# app.py - Secure, Queue-based Upload + Download

import os
import uuid
from pathlib import Path
from flask import Flask, render_template, request, session, redirect, url_for, send_file

app = Flask(__name__)
app.secret_key = 'your-secret-key-here'  # Change in production!

# Configurations
STATIC_DIR = Path("static", "uploads")
STATIC_DIR.mkdir(parents=True, exist_ok=True)

# In-memory queue (use Redis in real apps for scalability!)
UPLOAD_QUEUE = {}  # {session_id: {"in_progress": bool, "uuid": str, "confirmed": bool}}

@app.before_request
def setup_session():
    if 'user_id' not in session:
        session['user_id'] = str(uuid.uuid4())

@app.get("/")
def index():
    # Check if any upload is in progress (for other users)
    upload_in_progress = any(
        val["in_progress"] and not val["confirmed"]
        for val in UPLOAD_QUEUE.values()
    )
    return render_template("index.html", upload_in_progress=upload_in_progress)


@app.post("/upload")
def upload_chunk():
    # Ensure we're in a valid session
    user_id = session['user_id']

    if user_id in UPLOAD_QUEUE and UPLOAD_QUEUE[user_id]["in_progress"]:
        # If already uploading, reject
        return "Upload already in progress. Please wait.", 409

    try:
        file = request.files["file"]
        file_uuid = request.form["dzuuid"]
        filename = f"{file_uuid[:8]}_{secure_filename(file.filename)}"
        save_path = STATIC_DIR / filename
        chunk_index = int(request.form["dzchunkindex"])
        total_chunks = int(request.form["dztotalchunkcount"])
        total_size = int(request.form["dztotalfilesize"])
        byte_offset = int(request.form["dzchunkbyteoffset"])

        # Initialize upload for this user
        UPLOAD_QUEUE[user_id] = {
            "in_progress": True,
            "uuid": file_uuid,
            "filename": filename,
            "total_chunks": total_chunks,
            "total_size": total_size,
            "current_chunks": set(),
            "confirmed": False
        }

        # Create file or append
        with open(save_path, "ab") as f:
            f.seek(byte_offset)
            f.write(file.stream.read())

        # Track which chunks have been received
        UPLOAD_QUEUE[user_id]["current_chunks"].add(chunk_index)

        # Check if all chunks are uploaded
        if len(UPLOAD_QUEUE[user_id]["current_chunks"]) == total_chunks:
            # Final verification
            if os.path.getsize(save_path) != total_size:
                return "File size mismatch!", 500

            # Mark as complete but not yet confirmed
            UPLOAD_QUEUE[user_id]["in_progress"] = False
            UPLOAD_QUEUE[user_id]["confirmed"] = False

            # Optional: Clean up incomplete files later?
            return {"message": "Upload completed. Click 'Confirm & Download' to finalize."}, 200

        else:
            return {"message": f"Chunk {chunk_index} uploaded. Expected {total_chunks} total."}, 200

    except Exception as e:
        # Clean up if an error occurred
        if Path(save_path).exists():
            os.remove(save_path)
        if user_id in UPLOAD_QUEUE:
            del UPLOAD_QUEUE[user_id]
        return {"error": str(e)}, 500


@app.post("/confirm")
def confirm_upload():
    user_id = session['user_id']
    if user_id not in UPLOAD_QUEUE:
        return {"error": "No active upload found."}, 404

    if not UPLOAD_QUEUE[user_id]["in_progress"] and UPLOAD_QUEUE[user_id]["confirmed"]:
        return {"message": "Already confirmed!"}, 200

    # Finalize the upload
    UPLOAD_QUEUE[user_id]["confirmed"] = True
    UPLOAD_QUEUE[user_id]["in_progress"] = False  # cleanup

    return {"message": "Confirmed! File is ready for download."}, 200


@app.get("/download/<filename>")
def download_file(filename):
    user_id = session['user_id']
    # Check if this user owns the file and has confirmed it
    file_path = STATIC_DIR / filename

    if not file_path.exists():
        return "File not found.", 404

    # Fetch upload record for this user
    if user_id not in UPLOAD_QUEUE:
        return "No upload found. Cannot download.", 403

    if not UPLOAD_QUEUE[user_id].get("confirmed"):
        return "You haven't confirmed the upload yet.", 403

    # Optional: Verify filename matches confirmed UUID
    upload_data = UPLOAD_QUEUE[user_id]
    if upload_data["filename"] != filename:
        return "Unauthorized access.", 403

    return send_file(str(file_path), as_attachment=True, download_name=filename.split('_', 1)[1])
```

> 💡 Note: `secure_filename` helps prevent path traversal, but we’re still storing filenames based on client-provided names. For maximum safety, consider renaming with random name and mapping it via metadata JSON (optional future upgrade).

