from flask import Flask, render_template, request, jsonify
import os
from googletrans import Translator
import re
from flask_cors import CORS

# 환경 변수 로드
from dotenv import load_dotenv
load_dotenv()

app = Flask(__name__)
CORS(app)  # CORS 보안 설정 (필수)

# 기본 언어 설정 (한국어 → 영어)
translator = Translator()

# XSS 방지: 입력 텍스트 청소 함수
def sanitize_input(text):
    if not text:
        return ""
    # HTML 특수문자 인코딩
    return re.escape(text)

@app.route("/", methods=["GET", "POST"])
def home():
    result = None
    if request.method == "POST":
        user_text = request.form.get("text", "").strip()
        if not user_text:
            return render_template("index.html", error="문자를 입력해주세요.")

        # 입력 검증 및 처리
        sanitized_text = sanitize_input(user_text)

        try:
            # 번역 실행 (영어로)
            translation = translator.translate(sanitized_text, src='ko', dest='en')
            result = translation.text
        except Exception as e:
            return render_template("index.html", error=f"번역 중 오류 발생: {str(e)}")

    return render_template("index.html", result=result)

@app.route("/api/translate", methods=["POST"])
def api_translate():
    data = request.get_json()
    text = data.get("text", "").strip()

    if not text:
        return jsonify({"error": "텍스트가 비어 있습니다."}), 400

    try:
        translation = translator.translate(text, src='ko', dest='en')
        return jsonify({
            "original": text,
            "translated": translation.text,
            "source": "ko",
            "target": "en"
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


if __name__ == '__main__':
    # 보안 강화 옵션
    app.config['SESSION_COOKIE_SECURE'] = True
    app.config['SESSION_COOKIE_HTTPONLY'] = True
    app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'

    # 로컬 개발일 경우만 실행 가능
    app.run(host='127.0.0.1', port=5000, debug=False)
```

