#!/usr/bin/env python3

import os
import shutil
from flask import Flask, render_template, jsonify, request
from threading import Thread
import time

app = Flask(__name__)

# CONFIGURATION
SOURCE_DIR = "/path/to/your/videos"  # 👇 Changer par ton chemin
USB_MOUNT_POINT = "/media/usb"       # Doit être accessible
PROGRESS_FILE = "/tmp/copy_progress.json"  # Fichier temporaire pour partager les infos

# Vérification si le point de montage existe
if not os.path.exists(USB_MOUNT_POINT):
    raise FileNotFoundError(f"Le périphérique USB n'est pas monté sur {USB_MOUNT_POINT}")

# Initialisation des données de progression
def init_progress():
    return {"total": 0, "copied": 0, "percentage": 0, "status": "ready", "current_file": ""}

def save_progress(data):
    with open(PROGRESS_FILE, 'w') as f:
        import json
        json.dump(data, f)

def load_progress():
    if not os.path.exists(PROGRESS_FILE):
        return init_progress()
    try:
        with open(PROGRESS_FILE, 'r') as f:
            return json.load(f)
    except:
        return init_progress()

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/start_copy", methods=["POST"])
def start_copy():
    # Récupère les fichiers mp4
    mp4_files = [f for f in os.listdir(SOURCE_DIR) if f.lower().endswith(".mp4")]
    if not mp4_files:
        return jsonify({"error": "Aucun fichier MP4 trouvé dans le dossier source."}), 400

    progress_data = init_progress()
    progress_data["total"] = len(mp4_files)
    progress_data["status"] = "running"
    save_progress(progress_data)

    def do_copy():
        copied = 0
        total = len(mp4_files)

        for filename in mp4_files:
            src_path = os.path.join(SOURCE_DIR, filename)
            dst_path = os.path.join(USB_MOUNT_POINT, filename)

            try:
                # Copie le fichier
                shutil.copy2(src_path, dst_path)
                copied += 1

                # Mise à jour de la progression
                progress_data = {
                    "total": total,
                    "copied": copied,
                    "percentage": int((copied / total) * 100),
                    "status": "running",
                    "current_file": filename
                }
                save_progress(progress_data)

                # Pause très courte pour simuler un "changement visible"
                time.sleep(0.1)  # Supprime ou ajuste selon vitesse copie

            except Exception as e:
                progress_data = {
                    "total": total,
                    "copied": copied,
                    "percentage": int((copied / total) * 100),
                    "status": "error",
                    "current_file": filename,
                    "error": str(e)
                }
                save_progress(progress_data)
                break

        # Fin réussie
        final_data = {
            "total": total,
            "copied": copied,
            "percentage": 100,
            "status": "completed",
            "current_file": ""
        }
        save_progress(final_data)

    # Démarrage en thread pour ne pas bloquer le serveur
    thread = Thread(target=do_copy, daemon=True)
    thread.start()

    return jsonify({"message": "Copie démarrée.", "progress": load_progress()})

@app.route("/progress")
def get_progress():
    return jsonify(load_progress())

# Serveur statique pour les fichiers CSS/JS
@app.route("/static/<path:filename>")
def static_files(filename):
    return app.send_static_file(filename)

if __name__ == "__main__":
    # Crée le fichier de progression si besoin
    if not os.path.exists(PROGRESS_FILE):
        save_progress(init_progress())

    app.run(host="0.0.0.0", port=5000, debug=False)
```

