    const button = document.getElementById('startBtn');
    button.disabled = true;
    button.innerHTML = '<span class="spinner-border spinner-border-sm me-1" role="status"></span> Copie en cours...';

    fetch('/start_copy', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
    })
    .then(response => response.json())
    .then(data => {
        if (data.error) {
            alert(`Erreur : ${data.error}`);
            button.disabled = false;
            button.innerHTML = '💾 Lancer la copie';
            return;
