        // Démarrer la mise à jour de progression
        updateProgress();
    })
    .catch(err => {
        console.error(err);
        alert("Une erreur s'est produite.");
        button.disabled = false;
        button.innerHTML = '💾 Lancer la copie';
    });
}

// Met à jour la progression en continu
function updateProgress() {
    fetch('/progress')
    .then(response => response.json())
    .then(data => {
        const progressBar = document.getElementById('progressBar');
        const statusText = document.getElementById('statusText');
        const currentFileDiv = document.getElementById('currentFile');
        const errorTextDiv = document.getElementById('errorText');

        // Mise à jour de la barre
        progressBar.style.width = `${data.percentage}%`;
        progressBar.className = `progress-bar progress-bar-striped ${data.status === 'running' ? 'progress-bar-animated' : ''}`;

        // Mise à jour du texte
        statusText.textContent = data.status === 'completed' ? '✅ Copie terminée.' :
                                data.status === 'error' ? '❌ Erreur détectée.' :
                                data.status === 'ready' ? 'Prêt à copier...' : 'En cours...';

        // Afficher le fichier en cours
        currentFileDiv.textContent = data.current_file ? `(${data.current_file})` : '';

        // Gestion erreurs
        if (data.error) {
            errorTextDiv.classList.remove('d-none');
            errorTextDiv.textContent = `Erreur: ${data.error}`;
        } else {
            errorTextDiv.classList.add('d-none');
        }

        // Arret si fini
        if (data.percentage === 100) {
            setTimeout(() => {
                alert('Copie terminée ! Tous les fichiers ont été copiés.');
            }, 500);
            return;
        }

        // Répéter toutes les 500ms
        setTimeout(updateProgress, 500);
    })
    .catch(err => {
        console.error("Erreur de requête de progression :", err);
    });
}

// Charger la progression au démarrage
document.addEventListener("DOMContentLoaded", () => {
    updateProgress();
});
</script>

