# app.py
import os
import json
import uuid
from flask import Flask, render_template, request, jsonify, send_file
from scripts.generate_novel import (
    generate_outline,
    generate_character,
    generate_plot,
    generate_chapter,
    refine_chapter
)
from datetime import datetime

app = Flask(__name__)

# 存储用户会话（模拟内存存储；生产环境建议用 Redis / DB）
sessions = {}

# OpenAI API Key (从环境变量读取)
openai_api_key = os.getenv("OPENAI_API_KEY")

@app.route("/", methods=["GET"])
def index():
    return render_template("index.html")

@app.route("/api/generate", methods=["POST"])
def api_generate():
    data = request.json
    keyword = data.get("keyword", "").strip()

    if not keyword:
        return jsonify({"error": "Please provide a keyword"}), 400

    session_id = data.get("session_id")
    if not session_id:
        session_id = str(uuid.uuid4())
        sessions[session_id] = {
            "keyword": keyword,
            "outline": None,
            "character": None,
            "plot": None,
            "chapters": [],
            "current_chapter_index": 0
        }

    # 1. 自动生成大纲、角色、情节
    outline = generate_outline(keyword, openai_api_key)
    character = generate_character(keyword, openai_api_key)
    plot = generate_plot(keyword, openai_api_key)

    sessions[session_id]["outline"] = outline
    sessions[session_id]["character"] = character
    sessions[session_id]["plot"] = plot

    return jsonify({
        "session_id": session_id,
        "outline": outline,
        "character": character,
        "plot": plot
    })

@app.route("/api/rewrite", methods=["POST"])
def api_rewrite():
    data = request.json
    session_id = data.get("session_id")
    if session_id not in sessions:
        return jsonify({"error": "Session expired"}), 400

    # 重新生成大纲、角色、情节
    keyword = sessions[session_id]["keyword"]
    outline = generate_outline(keyword, openai_api_key)
    character = generate_character(keyword, openai_api_key)
    plot = generate_plot(keyword, openai_api_key)

    sessions[session_id]["outline"] = outline
    sessions[session_id]["character"] = character
    sessions[session_id]["plot"] = plot

    return jsonify({
        "outline": outline,
        "character": character,
        "plot": plot
    })

@app.route("/api/generate-chapter", methods=["POST"])
def api_generate_chapter():
    data = request.json
    session_id = data.get("session_id")
    style = data.get("style", "standard")
    new_plot = data.get("new_plot", "")

    if session_id not in sessions:
        return jsonify({"error": "Session expired"}), 400

    session = sessions[session_id]
    outline = session["outline"]
    character = session["character"]

    # 生成章节内容
    chapter_text = generate_chapter(
        outline=outline,
        character=character,
        plot=new_plot or session["plot"],
        style=style,
        api_key=openai_api_key
    )

    # 保存到当前会话
    current_chapter = {
        "index": len(session["chapters"]) + 1,
        "content": chapter_text,
        "title": f"第{len(session['chapters']) + 1}章：{new_plot[:20]}..." if new_plot else f"第{len(session['chapters']) + 1}章"
    }
    session["chapters"].append(current_chapter)

    return jsonify({
        "chapter": current_chapter,
        "session_id": session_id
    })

@app.route("/api/refine-chapter", methods=["POST"])
def api_refine_chapter():
    data = request.json
    session_id = data.get("session_id")
    chapter_index = data.get("chapter_index")
    feedback = data.get("feedback", "")

    if session_id not in sessions or chapter_index >= len(sessions[session_id]["chapters"]):
        return jsonify({"error": "Invalid chapter"}), 400

    chapter = sessions[session_id]["chapters"][chapter_index]
    refactored = refine_chapter(
        original=chapter["content"],
        feedback=feedback,
        api_key=openai_api_key
    )

    chapters = sessions[session_id]["chapters"]
    chapters[chapter_index]["content"] = refactored
    chapters[chapter_index]["feedback"] = feedback

    return jsonify({
        "refined_chapter": {"index": chapter_index, "content": refactored}
    })

@app.route("/api/download-chapter", methods=["POST"])
def download_chapter():
    data = request.json
    session_id = data.get("session_id")
    chapter_idx = data.get("chapter_index")
    filename = f"novel_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"

    session = sessions.get(session_id)
    if not session or chapter_idx >= len(session["chapters"]):
        return jsonify({"error": "Chapter not found"}), 404

    chapter = session["chapters"][chapter_idx]
    content = chapter["content"]
    filepath = f"downloads/{filename}"

    os.makedirs("downloads", exist_ok=True)
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(f"=== {chapter['title']} ===\n\n{content}\n\n")

    return send_file(filepath, as_attachment=True, download_name=filename)

@app.route("/api/get-progress", methods=["POST"])
def get_progress():
    data = request.json
    session_id = data.get("session_id")
    if session_id not in sessions:
        return jsonify({"error": "Session not found"}), 400

    session = sessions[session_id]
    progress = {
        "total_chapters": len(session["chapters"]),
        "outline": session["outline"],
        "character": session["character"],
        "last_plot": session["plot"]
    }
    return jsonify(progress)

if __name__ == "__main__":
    # 本地调试时启用
    app.run(debug=True, host="0.0.0.0", port=5000)
