```python
# scripts/generate_novel.py
import openai
from typing import Dict, List

openai.api_key = ""

def call_openai(prompt: str, model="gpt-4", max_tokens=1024, temperature=0.7) -> str:
    try:
        response = openai.ChatCompletion.create(
            model=model,
            messages=[{"role": "user", "content": prompt}],
            max_tokens=max_tokens,
            temperature=temperature,
            top_p=1,
            frequency_penalty=0,
            presence_penalty=0
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        print(f"API Error: {e}")
        return f"❌ 生成失败：{str(e)}"

# 1. 扩写大纲
def generate_outline(keyword: str, api_key: str) -> str:
    prompt = f"""
你是一名资深网络小说策划师，请根据以下关键词扩展出一个完整的小说大纲：
关键词：'{keyword}'
要求：
1. 包含世界观设定（背景时代、地点、社会结构）
2. 三幕式结构：起承转合
3. 主线剧情走向清晰，有冲突与高潮
4. 保持中文流畅，口语化易读
"""
    return call_openai(prompt, api_key=api_key)

# 2. 生成角色人设
def generate_character(keyword: str, api_key: str) -> str:
    prompt = f"""
请根据关键词 '{keyword}' 为核心，设计一位主角的人设。要求：
- 姓名、年龄、外貌特征
- 背景故事（原生家庭、成长经历）
- 性格特点（优点+弱点）
- 武力/天赋/特殊能力（如有）
- 成长弧光（如何改变？）
- 一句话标签（比如“废柴逆袭，一怒为红颜”）
请用简洁中文字描述。
"""
    return call_openai(prompt, api_key=api_key)

# 3. 扩写情节
def generate_plot(keyword: str, api_key: str) -> str:
    prompt = f"""
基于关键词 '{keyword}'，撰写一段详细的情节梗概，用于推动第一章节剧情发展。
要求：包含具体事件、人物互动、情绪转折点和悬念。
例如：主角被背叛→坠崖→觉醒异能→归来复仇...
保持网络小说风格：节奏快、有爽感、带反转。
"""
    return call_openai(prompt, api_key=api_key)

# 4. 生成小说章节
def generate_chapter(outline: str, character: str, plot: str, style: str, api_key: str) -> str:
    styles = {
        "standard": "标准网文风格：节奏明快，对话生动，带爽点。",
        "xuanhuan": "玄幻风：古风韵味，意境优美，多引用诗词典故。",
        "xianxia": "仙侠风：飘渺意境，修炼体系分明，台词诗意。",
        "dizi": "都市异能风：现代都市背景，轻松幽默，带吐槽。",
        "dark": "黑暗向：冷峻现实，人性挣扎，不完美结局。",
        "slice_of_life": "日常向：平淡温情，生活细节丰富，慢节奏。"
    }

    selected_style = styles.get(style, "标准网文风格")

    prompt = f"""
你是一位畅销网络小说作家，请根据以下信息创作一章小说正文（1500字左右），要求：
- 采用【{selected_style}】的写作风格
- 内容基于大纲：{outline}
- 角色设定：{character}
- 情节推进：{plot}
- 章节标题自拟，带有吸引力（如“血染长河”、“我重生了，但谁也没认出我”）
- 有具体场景描写、人物表情动作、内心独白
- 结尾留有悬念或反转
- 不要总结性语句，直接进入叙事
"""
    return call_openai(prompt, api_key=api_key)

# 5. 改写章节（基于用户反馈）
def refine_chapter(original: str, feedback: str, api_key: str) -> str:
    prompt = f"""
你是一位经验丰富的编辑，收到读者反馈如下：
反馈：{feedback}

原文如下：
{original}

请根据该反馈，优化改写以上段落，使其更符合读者期待。注意：
- 保留原有情节框架
- 修正语气、节奏、逻辑不通之处
- 提升爽感/代入感/合理性
- 输出全新修改版本
"""
    return call_openai(prompt, api_key=api_key)
