        $.post("/api/generate", { keyword: keyword }, function (res) {
          if (res.error) return alert(res.error);

          sessionId = res.session_id;
          $("#outlineText").text(res.outline || "");
          $("#characterText").text(res.character || "");
          $("#plotText").text(res.plot || "");

          $("#expandedContent").removeClass("d-none");
          $("#writingSection").removeClass("d-none");
          $("#progressInfo").text(`已生成内容 | Session ID: ${sessionId.substring(0,8)}`);
