      $("#startWriteBtn").on('click', function () {
        const style = $("#styleSelect").val();
        const newPlot = $("#newPlot").val();

        $.post("/api/generate-chapter", {
          session_id: sessionId,
          style: style,
          new_plot: newPlot
        }, function (res) {
          const chapter = res.chapter;
          $("#chapterContent").html(chapter.content.replace(/\n/g, "<br>"));
          $("#outputSection").removeClass("d-none");
          $("#progressInfo").text(`第${chapter.index}章已生成`);

          // 填充下载参数
          $("#downloadBtn").data("chapter-index", chapter.index);
        }).fail(function () {
          alert("章节生成失败");
        });
      });

      // Step 4: 反馈 & 重写
      $("#refineBtn").on('click', function () {
        $("#feedbackDiv").removeClass("d-none");
      });

      $("#cancelFeedbackBtn").on('click', function () {
        $("#feedbackDiv").addClass("d-none");
      });

      $("#submitFeedbackBtn").on('click', function () {
        const feedback = $("#feedbackInput").val();
        if (!feedback) return alert("请填写修改意见");

        $.post("/api/refine-chapter", {
          session_id: sessionId,
          chapter_index: $("#downloadBtn").data("chapter-index"),
          feedback: feedback
        }, function (res) {
          $("#chapterContent").html(res.refined_chapter.content.replace(/\n/g, "<br>"));
          alert("章节已根据反馈修改！");
          $("#feedbackDiv").addClass("d-none");
        });
      });

      // Step 5: 下载
      $("#downloadBtn").on('click', function () {
        const idx = $(this).data("chapter-index");
        $.post("/api/download-chapter", {
          session_id: sessionId,
          chapter_index: idx
        }).fail(function () {
          alert("下载失败");
        });
      });

