### 💻 Полный код для **Arduino Pro Mini (node sensor)**

```cpp
/*
 * =============== ARDUINO PRO MINI NODE SENSOR (DS18B20 + Digital Input) ===============
 * Author: SecurityResearcher
 * Device: Arduino Pro Mini 3.3V / 5V (16MHz) with DS18B20 and HC-12
 * Purpose: Read temperature from DS18B20, read digital input state, send via HC-12 to Orange Pi Zero
 * Data format: JSON-like string sent over serial (via SoftwareSerial to HC-12)
 *
 * 🔐 SAFETY NOTE (Security Researchers):
 *   - HC-12 uses unencrypted 433/470MHz RF — anyone within range can sniff data!
 *   - Never use for security-critical or private data without encryption.
 *   - Future improvement: Add AES-128 encryption + device authentication (e.g., unique ID).
 *
 * ================== PINOUT (Example) ==================
 * DS18B20 Sensor (1-Wire):
 *   - Data -> Pin 7 (digital pin)
 *   - VCC -> 5V
 *   - GND -> GND
 *
 * Digital Input (e.g., switch, sensor, button):
 *   - Signal -> Pin 2 (with pull-up resistor ~10kΩ)
 *
 * HC-12 Radio Module:
 *   - TXD -> Pin 3 (connected to HC-12 RX)
 *   - RXD -> Pin 4 (connected to HC-12 TX)
 *     ⚠️ Warning: Do NOT use UART pins (0,1) if you want to debug via USB programmer!
 *     Therefore, we use SoftwareSerial on pin 3 & 4.
 */

// === Includes === //
#include <OneWire.h>           // Library for DS18B20
#include <DallasTemperature.h> // Library for temperature reading
#include <SoftwareSerial.h>    // Use non-UART pins for HC-12

// === Hardware Configuration === //

#define ONE_WIRE_BUS 7             // Connect DS18B20 data to pin 7
#define DIGITAL_INPUT_PIN 2        // Digital input (e.g., door sensor, motion, etc.)
#define HC12_TX_PIN 3              // HC-12 TX → Arduino RX (use any two unused pins)
#define HC12_RX_PIN 4              // HC-12 RX → Arduino TX

// Create OneWire instance
OneWire oneWire(ONE_WIRE_BUS);

// Pass the oneWire reference to DallasTemperature library
DallasTemperature sensors(&oneWire);

// Create SoftwareSerial object for HC-12 (TX on pin 3, RX on pin 4)
SoftwareSerial hc12Serial(HC12_RX_PIN, HC12_TX_PIN); // RX, TX

// Constants for network communication
#define BAUD_RATE_HC12 9600         // Default baud rate for HC-12
#define SEND_INTERVAL_MS 5000       // Send every 5 seconds

// Variables to store sensor readings
float currentTemperature = 0.0;
int digitalInputState = 0;

// Device identifier (can be unique per node, e.g., MAC-like, but hardcoded now)
const char* DEVICE_ID = "NODE_01";  // This should be unique across nodes

// Timestamp to track last transmission
unsigned long lastSendTime = 0;

// === Setup Function === //
void setup() {
  // Initialize debug serial (for programming and debugging if needed)
  Serial.begin(9600);
  delay(1000); // Wait for serial monitor

  // Print startup message
  Serial.println("Initializing Arduino Pro Mini Sensor Node...");
  Serial.println("Device ID: " + String(DEVICE_ID));

  // Start DS18B20 sensor (note: requires pull-up resistor ~4.7kΩ on data line!)
  sensors.begin();

  // Check if at least one sensor is connected
  if (sensors.getDeviceCount() == 0) {
    Serial.println("❌ No DS18B20 found! Check wiring.");
  } else {
    Serial.print("✅ Found ");
    Serial.print(sensors.getDeviceCount());
    Serial.println(" DS18B20 sensor(s).");
  }

  // Initialize digital input pin as INPUT with internal pull-up
  pinMode(DIGITAL_INPUT_PIN, INPUT_PULLUP);  // State HIGH = open (e.g., door closed), LOW = closed (door open)
  Serial.print("Digital input pin ");
  Serial.print(DIGITAL_INPUT_PIN);
  Serial.println(" configured with internal pull-up.");

  // Initialize HC-12 communication via SoftwareSerial
  hc12Serial.begin(BAUD_RATE_HC12);
  Serial.print("HC-12 initialized on pins TX:");
  Serial.print(HC12_TX_PIN);
  Serial.print(", RX:");
  Serial.println(HC12_RX_PIN);
  Serial.println("Waiting for first readings...");

  lastSendTime = millis(); // Initialize timestamp
}

// === Loop Function === //
void loop() {
  unsigned long currentTime = millis();

  // Check if it's time to send data
  if (currentTime - lastSendTime >= SEND_INTERVAL_MS) {
    // Update digital input state
    digitalInputState = digitalRead(DIGITAL_INPUT_PIN);

    // Request temperature from DS18B20
    sensors.requestTemperatures();
    float temp = sensors.getTempCByIndex(0); // Get first sensor

    // Handle error case
    if (temp == DEVICE_DISCONNECTED_C) {
      Serial.println("❌ DS18B20 disconnected!");
      currentTemperature = -999.0; // Represent error
    } else {
      currentTemperature = temp;
    }

    // Prepare JSON-like packet for sending
    // Format example:
    // {"device":"NODE_01","temp":23.5,"digital":1}
    String packet = "{";
    packet += "\"device\":\"";
    packet += DEVICE_ID;
    packet += "\",\"temp\":";
    packet += String(currentTemperature, 1); // 1 decimal place
    packet += ",\"digital\":";
    packet += digitalInputState;
    packet += "}";

    // Debug: print raw packet
    Serial.print("Sending packet: ");
    Serial.println(packet);

    // Send via HC-12
    hc12Serial.println(packet);

    // Optional: wait a moment after sending (recommended by HC-12 datasheet)
    delay(100);

    // Update last send time
    lastSendTime = currentTime;

    // Additional: send test packet in case of debug mode
    // hc12Serial.println("{\"test\":\"OK\",\"ts\":");
    // hc12Serial.println(millis());
    // hc12Serial.println("}");
  }

  // Small delay to avoid busy-waiting
  delay(100);
}
```

