import React, { useState, useEffect } from 'react';
import WelcomePage from './pages/WelcomePage';
import Dashboard from './pages/Dashboard';
import TranslationCard from './components/TranslationCard';
import VoiceInput from './components/VoiceInput';
import { fetchTranslation } from '../services/apiService';

const App = () => {
  const [userInput, setUserInput] = useState('');
  const [aiOutput, setAiOutput] = useState('');
  const [isTranslating, setIsTranslating] = useState(false);
  const [activePage, setActivePage] = useState('welcome');
  const [userSpeech, setUserSpeech] = useState(null);

  const translateToDog = async (text) => {
    setIsTranslating(true);
    try {
      const response = await fetchTranslation({ text, direction: 'human_to_dog' });
      setAiOutput(response.translatedText);
    } catch (error) {
      console.error("Translation failed:", error);
      setAiOutput("Error: Could not translate. Try again later.");
    } finally {
      setIsTranslating(false);
    }
  };

  const handleTranslate = () => {
    if (!userInput.trim()) return;
    translateToDog(userInput);
  };

  const handleVoiceInput = (speechText) => {
    setUserInput(speechText);
    translateToDog(speechText);
  };

  // Start listening to the mic when active
  useEffect(() => {
    if (userSpeech && !isTranslating) {
      handleVoiceInput(userSpeech);
    }
  }, [userSpeech]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-100 to-pink-200">
      <header className="py-6 px-8 flex justify-between items-center shadow-md">
        <h1 className="text-3xl font-extrabold text-purple-700">🐶 BotDoggy</h1>
        <button
          onClick={() => setActivePage(activePage === 'welcome' ? 'dashboard' : 'welcome')}
          className="bg-purple-600 hover:bg-purple-700 text-white px-5 py-2 rounded-lg font-medium transition"
        >
          {activePage === 'welcome' ? 'Go to Translator' : 'Back to Home'}
        </button>
      </header>

      {activePage === 'welcome' ? (
        <WelcomePage onStart={() => setActivePage('dashboard')} />
      ) : (
        <Dashboard>
          <div className="max-w-4xl mx-auto p-6 space-y-8">
            <h2 className="text-2xl font-bold text-gray-800 text-center mb-4">Talk to Your Dog 💬</h2>

            <VoiceInput onSpeechResult={setUserSpeech} />

            <input
              type="text"
              placeholder="Type what you want to say to your dog..."
              value={userInput}
              onChange={(e) => setUserInput(e.target.value)}
              className="w-full p-4 border border-gray-300 rounded-lg text-lg focus:ring-2 focus:ring-purple-400 focus:border-transparent transition duration-200"
            />

            <button
              onClick={handleTranslate}
              disabled={isTranslating || !userInput.trim()}
              className="w-full bg-green-500 hover:bg-green-600 disabled:bg-gray-300 text-white font-bold py-4 rounded-lg transition mt-4"
            >
              {isTranslating ? 'Translating...' : '👉 Translate to Dog Talk!'}
            </button>

            <TranslationCard
              inputText={userInput}
              outputText={aiOutput}
              direction="human_to_dog"
            />
          </div>
        </Dashboard>
      )}
    </div>
  );
};

export default App;
