import { useEffect, useState } from 'react';

const VoiceInput = ({ onSpeechResult }) => {
  const [isListening, setIsListening] = useState(false);

  useEffect(() => {
    let recognition;

    if ('webkitSpeechRecognition' in window) {
      recognition = new webkitSpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;

      recognition.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        onSpeechResult(transcript);
        setIsListening(false);
      };

      recognition.onerror = (event) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);
      };
    }

    return () => {
      if (recognition) recognition.stop();
    };
  }, []);

  const toggleListening = () => {
    if (isListening) {
      if ('webkitSpeechRecognition' in window) {
        window.recognition?.stop();
      }
      setIsListening(false);
    } else {
      if ('webkitSpeechRecognition' in window) {
        window.recognition = new webkitSpeechRecognition();
        window.recognition.start();
      }
      setIsListening(true);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-4">
      <button
        onClick={toggleListening}
        className={`px-8 py-3 rounded-full font-semibold transition transform ${
          isListening
            ? 'bg-red-500 hover:bg-red-600 text-white scale-105'
            : 'bg-blue-500 hover:bg-blue-600 text-white'
        }`}
      >
        {isListening ? '⏹️ Stop Listening' : '🎤 Speak Now!'}
      </button>
      <p className="text-sm text-gray-600">
        {isListening ? 'Listening... Speak clearly!' : 'Click to enable microphone'}
      </p>
    </div>
  );
};

export default VoiceInput;
