import express from 'express';
import mongoose from 'mongoose';
import dotenv from 'dotenv';
import cors from 'cors';
import socketIo from 'socket.io';
import authRoutes from './routes/authRoutes';
import translationRoutes from './routes/translationRoutes';
import * as Sentry from '@sentry/node';
import { errorHandler } from './middleware/errorHandler';

dotenv.config();

const app = express();

// Initialize Sentry for Error Monitoring (Optional but Recommended)
Sentry.init({
  dsn: process.env.SENTRY_DSN,
  tracesSampleRate: 1.0,
  debug: false,
});

app.use(Sentry.Handlers.requestHandler());
app.use(cors());
app.use(express.json({ limit: '10mb' }));

// Routes
app.use('/api/auth', authRoutes);
app.use('/api/translate', translationRoutes);

// Health Check
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'OK', timestamp: new Date() });
});

// Catch All Unknown Routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Error Handling Middleware
app.use(Sentry.Handlers.errorHandler());

app.use(errorHandler);

// MongoDB Connection
mongoose.connect(process.env.MONGO_URI)
  .then(() => {
    console.log('✅ Connected to MongoDB');
  })
  .catch(err => {
    console.error('❌ MongoDB connection error:', err);
    process.exit(1);
  });

// Create and start server
const PORT = process.env.PORT || 5000;
const server = app.listen(PORT, () => {
  console.log(`🚀 BotDoggy Backend running on http://localhost:${PORT}`);
});

// Socket.IO for real-time updates (future proofing)
const io = socketIo(server, {
  cors: {
    origin: process.env.CLIENT_URL || "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

io.on('connection', (socket) => {
  console.log('📡 New client connected:', socket.id);

  socket.on('disconnect', () => {
    console.log('📉 Client disconnected:', socket.id);
  });

  socket.on('newTranslation', (data) => {
    console.log('💬 New translation request:', data);
    io.emit('updateTranslation', data); // Broadcast to all clients
  });
});

export { app, server, io };
