import fs from 'fs';
import path from 'path';
import { getResponseFromGPT } from '../ai-models/gpt_dog_translation';

// Simulate dog-to-human / human-to-dog mappings (replace with real AI training later)
const HUMAN_TO_DOG_MAP = {
  "I love you": "Wuff! Happy tail wagging!",
  "Good boy!": "Happy woof! Wiggles and lick!",
  "Time for dinner!": "Yummy food! Runnn!",
  "Stay": "Hmm, not moving… nose down.",
  "No": "Whine, whine… back off!",
  "Come here": "Ears up! Running fast!"
};

const DOG_TO_HUMAN_MAP = {
  "Woff!": "This smells interesting!",
  "Woof! Woof!": "Someone at the door!",
  "Ruff! Ruff!": "Protecting my territory!",
  "Whiney groan": "I'm bored, can we play?"
};

// Simple fallback mapping function (use real AI model in production!)
export const translateText = async (req, res) => {
  const { text, direction } = req.body;

  if (!text || !direction) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  try {
    let result;

    if (direction === 'human_to_dog') {
      // Use map lookup first
      let translation = HUMAN_TO_DOG_MAP[text.trim().toLowerCase()];
      if (!translation) {
        // Fallback to AI model
        const response = await getResponseFromGPT(text, 'human_to_dog');
        translation = response.generatedText;
      }
      result = translation;
    } else if (direction === 'dog_to_human') {
      let translation = DOG_TO_HUMAN_MAP[text.trim().toLowerCase()];
      if (!translation) {
        const response = await getResponseFromGPT(text, 'dog_to_human');
        translation = response.generatedText;
      }
      result = translation;
    }

    res.json({
      originalText: text,
      translatedText: result,
      direction: direction,
      timestamp: new Date().toISOString()
    });

  } catch (err) {
    console.error("Translation error:", err);
    return res.status(500).json({
      error: "Failed to translate text",
      details: err.message
    });
  }
};
