export const validateTranslationRequest = (req, res, next) => {
  const { text, direction } = req.body;

  if (!text || typeof text !== 'string' || text.length > 500) {
    return res.status(400).json({ error: 'Valid text (max 500 chars) is required' });
  }

  if (!['human_to_dog', 'dog_to_human'].includes(direction)) {
    return res.status(400).json({ error: 'Invalid direction. Must be human_to_dog or dog_to_human' });
  }

  next();
};
