# ai-models/gpt_dog_translation.py
"""
Fine-tuned GPT-based dog linguistics model wrapper.
Uses OpenAI API or local LLM (e.g., Mistral, Phi-3) for translation.
"""

import os
from openai import OpenAI
from typing import Dict, Optional

class DogTranslationModel:
    def __init__(self):
        self.client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
        self.model = os.getenv("DOG_TRANSLATION_MODEL", "gpt-4o-mini")

    def translate(self, text: str, direction: str) -> dict:
        """
        Translate between human and dog language.
        direction: 'human_to_dog' | 'dog_to_human'
        """
        system_prompt = {
            'human_to_dog': """You are Dr. Barksley, a world-renowned animal linguist who specializes in translating human emotional signals into dog language. 
            Dogs interpret tone, body movement, and intent more than words.  
            Convert human phrases into authentic dog expressions using barks, whines, tail wags, and behavior cues.
            Keep translations short and expressive (max 20 words).
            Example: "I love you" → "Happy wagging, wet nose, nuzzle!" """,

            'dog_to_human': """You are a translator decoding dog vocalizations and behaviors into understandable human phrases. 
            Interpret barks, whines, growls, and postures with emotion, urgency, and context.
            Be accurate, concise, and realistic (max 25 words).
            Example: "Wooof!" → "There's someone at the door! Need help!" """
        }

        try:
            response = self.client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": system_prompt[direction]},
