def get_mp4_files():
    try:
        files = [f for f in os.listdir(SOURCE_DIR) if f.lower().endswith(".mp4")]
        return sorted(files)
    except Exception as e:
        print(f"[ERROR] Cannot list files: {e}")
        return []

# Fonction pour mettre à jour le fichier de progression
def update_progress(completed, total, last_file=None):
    with open(PROGRESS_FILE, 'w') as f:
        f.write(f'{{"total_files": {total}, "completed_files": {completed}, "last_file": "{last_file or ""}", "status": "in-progress"}}')
    print(f"[INFO] Progress updated: {completed}/{total} | Last: {last_file}")

# Fonction pour lire le statut de progression
def read_progress():
    try:
        if not os.path.exists(PROGRESS_FILE):
            return {"total_files": 0, "completed_files": 0, "status": "idle"}

        with open(PROGRESS_FILE, 'r') as f:
            content = f.read().strip()
            if not content:
                return {"total_files": 0, "completed_files": 0, "status": "idle"}

        data = eval(content)  # Sécurité limitée : utilisez JSON en production
        if "status" not in data:
            data["status"] = "in-progress"
        return data
    except Exception as e:
        print(f"[ERROR] Unable to read progress: {e}")
        return {"total_files": 0, "completed_files": 0, "status": "error"}

# Route principale
@app.route("/")
