    return render_template_string(HTML_TEMPLATE)

# Route : Démarrer la copie
@app.route("/start_copy")
def start_copy():
    files = get_mp4_files()
    if not files:
        return jsonify({
            "status": "error",
            "message": "Aucun fichier MP4 trouvé."
        })

    # Vérifier si la clé USB est montée
    if not os.path.exists(USB_MOUNT_POINT):
        return jsonify({
            "status": "error",
            "message": f"Clé USB non montée à {USB_MOUNT_POINT}"
        })

    # Vider le fichier de progression
    try:
        with open(PROGRESS_FILE, 'w') as f:
            f.write(f'{{"total_files": {len(files)}, "completed_files": 0, "status": "in-progress"}}')
    except Exception as e:
        return jsonify({
            "status": "error",
            "message": f"Impossible d’initialiser le suivi : {e}"
        })

    # Lancer le copiage dans un thread séparé (simulé ici via déclenchement)
    # En réalité, on pourrait utiliser threading ou un worker
    def copy_worker():
