        for filename in files:
            source_path = os.path.join(SOURCE_DIR, filename)
            dest_path = os.path.join(USB_MOUNT_POINT, filename)

            try:
                shutil.copy2(source_path, dest_path)  # copie avec métadonnées
                copied_count += 1
                update_progress(copied_count, len(files), filename)

                # Ajout au journal
                with open(LOG_FILE, 'a') as log:
                    log.write(f"[{datetime.now().strftime('%H:%M:%S')}][COPIED] {filename}\n")

            except Exception as e:
                with open(LOG_FILE, 'a') as log:
                    log.write(f"[{datetime.now().strftime('%H:%M:%S')}][FAILED] {filename}: {e}\n")
                continue  # Passer au fichier suivant

