```c
#include <stdio.h>
#include <stdlib.h>

// 链表节点定义
typedef struct ListNode {
    int val;
    struct ListNode* next;
} ListNode;

// 函 数：合并两个升序链表，返回新链表头指针
ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
    // === 安全检查：输入合法性 ===
    if (list1 == NULL && list2 == NULL) {
        return NULL;  // 两边都为空，返回空
    }

    // 创建虚拟头结点（哨兵节点），简化逻辑，避免对 head 特殊处理
    ListNode* dummy = (ListNode*)malloc(sizeof(ListNode));
    if (dummy == NULL) {
        fprintf(stderr, "Memory allocation failed for dummy node.\n");
        exit(EXIT_FAILURE);
    }
    dummy->next = NULL;  // 初值设为空指针

    ListNode* current = dummy;  // 当前工作指针

    // 合并过程：逐个比较并移动
    while (list1 != NULL && list2 != NULL) {
        if (list1->val <= list2->val) {
            current->next = list1;
            list1 = list1->next;
        } else {
            current->next = list2;
            list2 = list2->next;
        }
        current = current->next;  // 移动 current 到下一个节点
    }

    // 处理剩余部分：链表可能不等长
    if (list1 != NULL) {
        current->next = list1;
    } else if (list2 != NULL) {
        current->next = list2;
    }

    // 取出真实头结点，释放 dummy 节点
    ListNode* mergedHead = dummy->next;
    free(dummy);  // 安全释放虚头节点

    return mergedHead;
}

// === 辅助函数：创建新节点 ===
ListNode* createNode(int val) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new node.\n");
        exit(EXIT_FAILURE);
    }
    node->val = val;
    node->next = NULL;
    return node;
}

// === 辅助函数：打印链表（用于测试）===
void printList(ListNode* head) {
    ListNode* curr = head;
    printf("List: ");
    while (curr != NULL) {
        printf("%d -> ", curr->val);
        curr = curr->next;
    }
    printf("null\n");
}

// === 辅助函数：释放链表内存 ===
void freeList(ListNode* head) {
    ListNode* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// === 测 试 用 例 ===
int main() {
    // 构造链表1: 1 -> 2 -> 4
    ListNode* l1 = createNode(1);
    l1->next = createNode(2);
    l1->next->next = createNode(4);

    // 构造链表2: 1 -> 3 -> 4
    ListNode* l2 = createNode(1);
    l2->next = createNode(3);
    l2->next->next = createNode(4);

    printf("Input:\n");
    printList(l1);
    printList(l2);

    ListNode* merged = mergeTwoLists(l1, l2);

    printf("Merged List: ");
    printList(merged);

    // 释放内存
    freeList(l1);
    freeList(l2);
    freeList(merged);

    return 0;
}
