                        } else if (strncmp(value, "pulse", val_len) == 0) {
                            rule.mode = MODE_PULSE;
                        } else {
                            return -1; // Неизвестный режим
                        }
                    } 1
                 } 
                 ptr++; // переходим дальше
            }

            // Проверка валидности
            if (rule.button >= BUTTON_COUNT || rule.relay >= RELAY_COUNT) {
                continue; // пропустить невалидное правило
            }

            rules[rule_count++] = rule;
            ptr++; // переход к следующему элементу
        } 
        else {
            ptr++;
        }
    }

    return rule_count;
}
```

