### ✔️ Пример: `parse_next_key_value()` (совместимо с mjson)

```c
int parse_next_key_value(const char** src, const char** key, int* klen, const char** value, int* vlen) {
    const char* p = *src;
    skip_whitespace(p);

    // Ожидаем: "ключ": "значение"
    if (*p != '"') return -1;
    p++;

    const char* start_key = p;

    while (*p && *p != '"') p++;
    if (!*p) return -1;
    *klen = p - start_key;
    *key = start_key;
    p++;

    skip_whitespace(p); // пропускаем : 

    if (*p != ':') return -1;
    p++;
    skip_whitespace(p);

    if (*p != '"') return -1;
    p++;
    const char* start_val = p;

    while (*p && *p != '"') p++;
    if (!*p) return -1;
    *vlen = p - start_val;
    *value = start_val;
    p++;

    // Возвращаем указатель после значения
    *src = p;
    return 0;
}

void skip_whitespace(const char* p) {
    while (*p == ' ' || *p == '\t' || *p == '\n') p++;
}
```

