#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>  // for sleep()

// 全局资源总量
struct Resource totalResource = {10, 15, 8};

// 进程数量
#define MAX_PROCESSES 5

// 限制最大运行次数（避免无限循环）
#define MAX_RUNS 50

// PCP 管理数组
PCB processes[MAX_PROCESSES];

// 就绪队列（链式队列或数组 + 指针）
int readyQueue[5], blockedQueue[5];
int readyCount = 0, blockedCount = 0;

// 当前正在运行的进程索引
int currentRunning = -1;

// 安全性检测函数
int isSafeState(int available[3]) {
    int work[3] = {available[0], available[1], available[2]};
    int finish[MAX_PROCESSES] = {0}; // 0:未完成
    int safeSeq[MAX_PROCESSES];
    int idx = 0;

    while (idx < MAX_PROCESSES) {
        int found = 0;
        for (int i = 0; i < MAX_PROCESSES; i++) {
            if (!finish[i]) {
                // 检查是否满足需求
                int canRun = 1;
                for (int j = 0; j < 3; j++) {
                    if (processes[i].need[j] > work[j]) {
                        canRun = 0;
                        break;
                    }
                }
                if (canRun) {
                    finish[i] = 1;
                    safeSeq[idx++] = i;
                    for (int j = 0; j < 3; j++) {
                        work[j] += processes[i].allocated[j];
                    }
                    found = 1;
                }
            }
        }
        if (!found) break;
    }

    return idx == MAX_PROCESSES;
}

// 打印当前状态
void printStatus(int step) {
    printf("\n--- Step %d ---\n", step);
    printf("正在运行的进程: ");
    if (currentRunning != -1) {
        printf("%s", processes[currentRunning].name);
    } else {
        printf("无");
    }
    printf("\n");

    printf("就绪队列 (W): ");
    for (int i = 0; i < readyCount; i++) {
        printf("%s ", processes[readyQueue[i]].name);
    }
    if (readyCount == 0) printf("空");
    printf("\n");

    printf("阻塞队列 (B): ");
    for (int i = 0; i < blockedCount; i++) {
        printf("%s ", processes[blockedQueue[i]].name);
    }
    if (blockedCount == 0) printf("空");
    printf("\n");

    printf("已完成进程 (F): ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == 3)
            printf("%s ", processes[i].name);
    }
    if (readyCount == 0 && blockedCount == 0) printf("空");
    printf("\n\n");

    printf("各进程 PCB 状况:\n");
    printf("进程名 | 最大需求 (A,B,C) | 已分配 | 还需 | 状态 | 时间片 \n");
    printf("-------|------------------|--------|------|------|--------\n");

    for (int i = 0; i < MAX_PROCESSES; i++) {
        printf("%-6s | %-15d | %-6d | %-4d |",
               processes[i].name,
               processes[i].maxDemand[0], processes[i].maxDemand[1], processes[i].maxDemand[2],
               processes[i].allocated[0], processes[i].allocated[1], processes[i].allocated[2],
               processes[i].need[0], processes[i].need[1], processes[i].need[2]);

        switch (processes[i].state) {
            case 0: printf(" W "); break;
            case 1: printf(" R "); break;
            case 2: printf(" B "); break;
            case 3: printf(" F "); break;
            default: printf(" ??"); break;
        }
        printf(" | %d\n", processes[i].timeRemaining);
    }
    printf("\n");
}

// 从就绪队列取下一个运行
int getNextProcess() {
    if (readyCount == 0) return -1;
    int next = readyQueue[0];
    // 移动队列
    for (int i = 0; i < readyCount - 1; i++) {
        readyQueue[i] = readyQueue[i + 1];
    }
    readyCount--;
    return next;
}

// 添加到就绪队列
void addToReady(int pid) {
    readyQueue[readyCount++] = pid;
}

// 添加到阻塞队列
void addToBlocked(int pid) {
    blockedQueue[blockedCount++] = pid;
}

// 从阻塞队列唤醒，并加入就绪
void wakeUpBlocked() {
    for (int i = 0; i < blockedCount; i++) {
        int pid = blockedQueue[i];
        int avail[3] = {totalResource.A - processes[pid].allocated[0],
                         totalResource.B - processes[pid].allocated[1],
                         totalResource.C - processes[pid].allocated[2]};
        int req[3] = {0, 0, 0};
        // 模拟请求（实际应从申请请求中读取，这里简化为测试阶段）
        // 在实际中可以调用 requestResource()
        // 这里简化：若能用，就唤醒
        if (isSafeState(avail)) {
            // 为了演示，我们认为可唤醒
            removeFromBlocked(pid);
            addToReady(pid);
        }
    }
}

// 从阻塞队列移除
void removeFromBlocked(int pid) {
    for (int i = 0; i < blockedCount; i++) {
        if (blockedQueue[i] == pid) {
            for (int j = i; j < blockedCount - 1; j++) {
                blockedQueue[j] = blockedQueue[j + 1];
            }
            blockedCount--;
            break;
        }
    }
}

// 初始化进程
void initProcesses() {
    char names[] = {'p', '1', '\0'};
    for (int i = 0; i < MAX_PROCESSES; i++) {
        snprintf(processes[i].name, sizeof(processes[i].name), "p%d", i + 1);
        // 随机最大需求（不超过总量）
        processes[i].maxDemand[0] = rand() % (totalResource.A / 2 + 1) + 1;
        processes[i].maxDemand[1] = rand() % (totalResource.B / 2 + 1) + 1;
        processes[i].maxDemand[2] = rand() % (totalResource.C / 2 + 1) + 1;

        // 初值已分配为0
        processes[i].allocated[0] = 0;
        processes[i].allocated[1] = 0;
        processes[i].allocated[2] = 0;

        // 计算还需
        processes[i].need[0] = processes[i].maxDemand[0];
        processes[i].need[1] = processes[i].maxDemand[1];
        processes[i].need[2] = processes[i].maxDemand[2];

        // 初态：就绪
        processes[i].state = 0;
        processes[i].timeRemaining = 1; // 给一个时间片
        addToReady(i);  // 添加到就绪队列
    }
}

// 分配资源（调用银行家算法）
int requestResource(int pid, int request[3]) {
    // 1. 检查请求是否超过需要
    for (int i = 0; i < 3; i++) {
        if (request[i] > processes[pid].need[i]) {
            printf("PID %s: 请求 (%d,%d,%d) 超过还需 (%d,%d,%d) → 拒绝。\n",
                   processes[pid].name,
                   request[0], request[1], request[2],
                   processes[pid].need[0], processes[pid].need[1], processes[pid].need[2]);
            return 0;
        }
    }

    // 2. 检查系统是否有足够资源
    int available[3] = {
        totalResource.A - processes[pid].allocated[0],
        totalResource.B - processes[pid].allocated[1],
        totalResource.C - processes[pid].allocated[2]
    };
    for (int i = 0; i < 3; i++) {
        if (request[i] > available[i]) {
            printf("PID %s: 系统资源不足 (%d) → 阻塞。\n", processes[pid].name, available[i]);
            return 0; // 不够，阻塞
        }
    }

    // 3. 预分配检查安全性
    int tempAlloc[3], tempNeed[3];
    memcpy(tempAlloc, processes[pid].allocated, 3 * sizeof(int));
    memcpy(tempNeed, processes[pid].need, 3 * sizeof(int));

    for (int i = 0; i < 3; i++) {
        tempAlloc[i] += request[i];
        tempNeed[i] -= request[i];
    }

    // 模拟预分配后，再做安全性检测
    int newAvailable[3] = {
        available[0] - request[0],
        available[1] - request[1],
        available[2] - request[2]
    };

    if (isSafeState(newAvailable)) {
        // 安全！分配成功
        for (int i = 0; i < 3; i++) {
            processes[pid].allocated[i] += request[i];
            processes[pid].need[i] -= request[i];
        }
        printf("PID %s: 成功分配资源 (%d,%d,%d)。\n", processes[pid].name, request[0], request[1], request[2]);
        return 1;
    } else {
        printf("PID %s: 预分配不安全 → 拒绝。\n", processes[pid].name);
        return 0;
    }
}

// 检查是否完成（需求为0）
int checkCompletion(int pid) {
    if (processes[pid].need[0] == 0 &&
        processes[pid].need[1] == 0 &&
        processes[pid].need[2] == 0) {
        return 1;
    }
    return 0;
}

// 释放资源 + 唤醒阻塞
void releaseResources(int pid) {
    printf("进程 %s 完成！释放资源。\n", processes[pid].name);
    for (int i = 0; i < 3; i++) {
        totalResource.A += processes[pid].allocated[i];
        totalResource.B += processes[pid].allocated[i];
        totalResource.C += processes[pid].allocated[i];
        // 清零
        processes[pid].allocated[i] = 0;
        processes[pid].need[i] = 0;
