// Load tasks from JSON file
void load_tasks_from_file() {
    FILE *file = fopen(DATA_FILE, "r");
    if (file == NULL) {
        // File doesn't exist yet - this is normal on first run
        return;
    }

    // Read file into buffer
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size > 100000) {  // Limit to 100KB to prevent memory exhaustion
        printf("⚠️ Warning: Todo file is too large (%ld bytes). Skipping load.\n", file_size);
        fclose(file);
        return;
    }

    char *buffer = (char*)malloc(file_size + 1);
    if (buffer == NULL) {
        printf("❌ Memory allocation failed while loading todo file.\n");
        fclose(file);
        return;
    }

    size_t read_size = fread(buffer, 1, file_size, file);
    buffer[read_size] = '\0';
    fclose(file);

    // Basic checks to ensure it's valid JSON
    if (read_size < 10 || 
        buffer[0] != '{' || 
        buffer[read_size - 1] != '}') {
        printf("⚠️ Warning: Todo file doesn't appear to be valid JSON. Skipping load.\n");
        free(buffer);
        return;
    }

    // Simple parsing - we're just looking for "tasks" array
    char *tasks_start = strstr(buffer, "\"tasks\": [");
    if (tasks_start == NULL) {
        printf("⚠️ Warning: Could not find tasks array in todo file. Skipping load.\n");
        free(buffer);
        return;
    }

    // Parse tasks (very basic)
    char *ptr = tasks_start + 10; // Skip "tasks": ["
    int task_id;
    char description[MAX_TASK_LEN];
    int completed;
    char created_at[20];
    char updated_at[20];

    while (ptr < buffer + file_size) {
        // Look for id: 
        if (sscanf(ptr, "  {\"id\": %d", &task_id) == 1) {
            // Look for description
            char temp[MAX_TASK_LEN];
            if (sscanf(ptr, "  {\"id\": %d,\"description\": \"%[^\"]\",", &task_id, temp) == 2) {
                strncpy(description, temp, sizeof(description) - 1);
                description[sizeof(description) - 1] = '\0';

                // Look for completed
                if (sscanf(ptr, "  {\"id\": %d,\"description\": \"%[^\"]\",\"completed\": %[^,],\"created_at\": \"%[^\"]\",\"updated_at\": \"%[^\"]\",", 
                           &task_id, temp, completed ? &completed : &completed, created_at, updated_at) == 5) {
                    // Create and add task
                    if (task_count < MAX_TASKS) {
                        Task t;
                        t.id = task_id;
                        strcpy(t.description, description);
                        t.completed = completed;
                        strcpy(t.created_at, created_at);
                        strcpy(t.updated_at, updated_at);
                        tasks[task_count++] = t;
                    }
                }
            }
        }

        // Move to next task
        ptr = strstr(ptr, "  {");
        if (ptr == NULL) {
