    printf("✅ Loaded %d tasks from %s\n", task_count, DATA_FILE);
}

// Secure gets implementation that limits input length
void secure_gets(char* buffer, int size) {
    if (buffer == NULL || size <= 0) {
        return;
    }

    // Clear buffer
    memset(buffer, 0, size);

    // Read input line by line
    if (fgets(buffer, size, stdin) == NULL) {
        buffer[0] = '\0';
        return;
    }

    // Remove newline character if present
    int len = strlen(buffer);
    if (len > 0 && buffer[len - 1] == '\n') {
        buffer[len - 1] = '\0';
    }
}

// Generate unique ID with randomness
int generate_unique_id() {
    // Use random ID to prevent predictability
    return (rand() % 90000) + 10000; // 10000-99999
}

// Format timestamp in ISO 8601 format
void format_timestamp(char* buffer, size_t size) {
    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);

    if (tm_info != NULL) {
        // Format: YYYY-MM-DD HH:MM:SS
        strftime(buffer, size, "%Y-%m-%d %H:%M:%S", tm_info);
    } else {
        // Fallback
        strncpy(buffer, "Unknown", size - 1);
        buffer[size - 1] = '\0';
    }
}

// Security Considerations:
// 1. Input validation (length, format)
// 2. Buffer overflow protection with fixed-size buffers and bounds checking
// 3. Memory management (safe allocation and cleanup)
// 4. Preventing format string attacks (using literal strings)
// 5. Proper error handling for file operations
// 6. Secure string handling (strcpy replaced with strncpy, memset)
// 7. Avoiding use of unsafe functions
// 8. Limiting data file size to prevent resource exhaustion
// 9. Random task ID generation to avoid predictability
// 10. Confirmations for destructive operations
```

## How to Compile and Run

```bash
# Compile with security flags
gcc -Wall -Wextra -Werror -Wextra -O2 -g -D_FORTIFY_SOURCE=2 -fstack-protector-strong todo.c -o todo

# Run the application
./todo
```

## Key Security Features

1. **Input Validation**: All user inputs are checked for length and content
2. **Buffer Overflow Protection**: All string operations use fixed-size buffers with length limits
3. **Memory Safety**: Proper initialization, cleanup, and bounds checking
4. **File Integrity**: Size limits on data file to prevent resource exhaustion
5. **Random IDs**: Task IDs are randomly generated to prevent enumeration attacks
6. **Error Handling**: All system calls have proper error checking
7. **No dangerous functions**: Avoids `gets`, `strcpy`, `sprintf`, etc. in favor of safer alternatives
8. **Confirmation prompts**: Prevent accidental data loss on deletion

This secure todo app demonstrates proper security practices while remaining functional and user-friendly.

