#include <stdio.h>
#include <stdlib.h>

// Structure to store number and its frequency
typedef struct {
    int num;
    int count;
} NumberCount;

// Function to find if number exists in array and update count
int findAndUpdate(NumberCount *arr, int size, int num) {
    for (int i = 0; i < size; i++) {
        if (arr[i].num == num) {
            arr[i].count++;
            return 1; // Found and updated
        }
    }
    return 0; // Not found
}

// Function to add new number to array
void addNumber(NumberCount *arr, int *size, int num) {
    arr[*size].num = num;
    arr[*size].count = 1;
    (*size)++;
}

int main() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Invalid input.\n");
        return 1;
    }

    // Dynamically allocate memory for list of numbers and counts
    NumberCount *counts = (NumberCount *)malloc(n * sizeof(NumberCount));
    if (!counts) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    int size = 0; // Current number of unique elements

    printf("Enter %d integers: ", n);
    for (int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);

        if (findAndUpdate(counts, size, num)) {
            continue; // Already exists, no need to add again
        } else {
            addNumber(counts, &size, num);
        }
    }

    // Display duplicate numbers (frequency > 1)
    printf("\n--- Duplicate Numbers ---\n");
    int foundDuplicate = 0;
    for (int i = 0; i < size; i++) {
        if (counts[i].count > 1) {
            printf("Number %d appears %d times\n", counts[i].num, counts[i].count);
            foundDuplicate = 1;
        }
    }

    if (!foundDuplicate) {
        printf("No repeated numbers found.\n");
    }

    // Cleanup
    free(counts);
    return 0;
}
