#include <stdint.h>
#include <stdio.h>

/**
 * @brief 统计32位无符号整数中二进制1的个数（汉明重量）
 * @param n: 32位无符号整数
 * @return 1的个数（0 ~ 32）
 *
 * 🔐 安全性设计：
 * - 使用固定宽度类型：uint32_t，避免平台差异
 * - 无符号右移，确保逻辑移位
 * - 无动态内存分配，无数组越界
 * - 恒定时间复杂度：最坏情况32次循环，但不依赖输入值
 * - 兼容任意编译器，无未定义行为
 */
uint8_t count_ones_32(uint32_t n) {
    uint8_t count = 0;
    while (n) {
        count += n & 1;  // 检查最低位是否为1
        n >>= 1;         // 无符号右移一位
    }
    return count;
}

// 🔥 优化版本：基于 Brian Kernighan 算法（更高效）
// 时间复杂度：O(ones)，其中 ones 为1的个数
uint8_t count_ones_32_bk(uint32_t n) {
    uint8_t count = 0;
    while (n) {
        n &= n - 1;  // 清除最低位的1
        count++;
    }
    return count;
}

// 💡 最佳性能版本（利用编译器内建函数）
// 注意：GCC/Clang 提供 __builtin_popcount，但需注意跨平台兼容性
inline uint8_t count_ones_builtin(uint32_t n) {
    return __builtin_popcount(n);
}

// ⚠️ 安全警告：__builtin_popcount 仅适用于 GCC/Clang
// 非标准函数，可能引发构建失败于 MSVC
```

