        fprintf(stderr, "Error: Both \"text\" and \"data\" entries must be present in source file.\n");
        return 1;
    }

    // Теперь загружаем базы из `data_file`
    struct base bases[MAX_BASES];
    int num_bases = 0;

    char **data_lines = read_file_lines(data_file, &num_bases);
    if (!data_lines) {
        fprintf(stderr, "Error reading data file: %s\n", data_file);
        return 1;
    }

    // Анализ строк вида `"base-a":"./a.db"`
    for (int i = 0; i < num_bases; i++) {
        char *line = data_lines[i];
        char base_name[MAX_LINE_LENGTH];
        char path_to_db[MAX_LINE_LENGTH];

        if (sscanf(line, "\"%[^\":]%*c\"%[^:\"]%*c\"", base_name, path_to_db) == 2) {
            bases[i].basename = strdup(base_name);
            bases[i].pathtobase = strdup(path_to_db);
        } else {
            fprintf(stderr, "Invalid format in data file line (%s)\n", line);
            free(data_lines[i]);
            continue;
        }
        free(data_lines[i]); // освободили строку – не нужна больше
    }
    free(data_lines);

    // Перезаписываем массив, оставляем только корректные базы
    int valid_bases = 0;
    for (int i = 0; i < num_bases; i++) {
        if (bases[i].basename && bases[i].pathtobase) {
            if (valid_bases != i) {
                bases[valid_bases] = bases[i];
            }
            valid_bases++;
        }
    }
    num_bases = valid_bases;

    // Шаг 3: читаем `text_file` и заменяем шаблоны
    char **text_lines = read_file_lines(text_file, &num_bases);
    if (!text_lines) {
        fprintf(stderr, "Error reading text file: %s\n", text_file);
        return 1;
    }

    char *result_output = NULL;
    for (int i = 0; i < num_bases; i++) {
        char *line = text_lines[i];
        char *temp_result = NULL;
        replace_placeholders(line, bases, num_bases, &temp_result);
        if (result_output && temp_result) {
            char *merged = malloc(strlen(result_output) + strlen(temp_result) + 2);
            if (!merged) {
                fprintf(stderr, "Memory error during merge.\n");
                exit(1);
            }
            strcpy(merged, result_output);
            strcat(merged, "\n");
            strcat(merged, temp_result);
            free(result_output);
            free(temp_result);
            result_output = merged;
        } else if (temp_result) {
            result_output = temp_result;
        }
        free(text_lines[i]);
    }
    free(text_lines);

    // Шаг 4: запросить имя выводного файла
    printf("Enter output file name: ");
    if (!fgets(out_file, sizeof(out_file), stdin)) {
        fprintf(stderr, "Error reading output file name.\n");
        exit(1);
    }
    len = strlen(out_file);
    if (len > 0 && out_file[len - 1] == '\n') {
        out_file[len - 1] = '\0';
    }

    // Запись результата
    FILE *outfile = fopen(out_file, "w");
    if (!outfile) {
        perror("Cannot write to output file");
        if (result_output) free(result_output);
        return 1;
    }

    fprintf(outfile, "%s\n", result_output ? result_output : "");
    fclose(outfile);

    // Очистка памяти
    if (result_output) free(result_output);

    for (int i = 0; i < num_bases; i++) {
        free(bases[i].basename);
        free(bases[i].pathtobase);
    }

    printf("Successfully processed and saved to %s\n", out_file);

    return 0;
}
