#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

// Target device – should be a camera or video capture device with DMA support
#define DEVICE_PATH "/dev/video0"

int main(int argc, char *argv[]) {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    __u32 nbufs = 4;
    void *mem_ptr = NULL;

    // Open video device
    fd = open(DEVICE_PATH, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open video device");
        return -1;
    }

    // Get capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);

    // Request buffers (will use DMA buffers internally)
    memset(&req, 0, sizeof(req));
    req.count = nbufs;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    printf("Allocated %u DMA buffers via mmap\n", req.count);

    // Query the first buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Map buffer into user space (actual DMA mapping via mmap)
    mem_ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (mem_ptr == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return -1;
