    for (int i = 0; i < 32; i++) {
        if (i % 16 == 0) printf("\n");
        printf("%02x ", ((unsigned char*)mem_ptr)[i]);
    }
    printf("\n");

    // Cleanup
    munmap(mem_ptr, buf.length);
    close(fd);

