## 🔐 Program C – UDP Broadcast avec Communication Entre Père et Fils

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/shm.h>
#include <sys/stat.h>
#include <time.h>

#define PORT 2346
#define BROADCAST_ADDR "255.255.255.255"
#define MAX_MESG_SIZE 256
#define MAX_ENTRIES 100
#define SHM_KEY 12345

// Structure pour stocker les informations d'envoyeur
typedef struct {
    char ip[16];
    int port;
} SenderInfo;

// Tableau partagé : liste des émetteurs ayant envoyé un message identique
typedef struct {
    SenderInfo tb[MAX_ENTRIES];
    int count;
    int updated; // Indicateur pour notifier le père que le tableau a été modifié
} SharedData;

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <chaine_a_envoyer>\n", argv[0]);
        exit(1);
    }

    char *target_string = argv[1];

    // Création de la mémoire partagée
    int shm_id = shmget(SHM_KEY, sizeof(SharedData), IPC_CREAT | 0666);
    if (shm_id == -1) {
        perror("shmget");
        exit(1);
    }

    // Attachement à la mémoire partagée
    SharedData *shared = (SharedData *)shmat(shm_id, NULL, 0);
    if (shared == (void*)-1) {
        perror("shmat");
        exit(1);
    }

    // Initialisation du tableau
    shared->count = 0;
    shared->updated = 0;

    // Création du socket UDP pour le fils
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(1);
    }

    // Activer l'option d'envoi en broadcast
    int broadcast_enable = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &broadcast_enable, sizeof(broadcast_enable)) < 0) {
        perror("setsockopt SO_BROADCAST");
        exit(1);
    }

    // Configuration de l'adresse du récepteur (fils écoute sur tout)
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY; // Ecoute sur tout interface

    if (bind(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Fork : création du processus enfant (fils)
    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        exit(1);
    }

    if (pid == 0) {
        // === Processus FILS ===
        printf("Fils en ecoute sur le port %d...\n", PORT);

        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        char buffer[MAX_MESG_SIZE];

        while (1) {
            ssize_t recv_len = recvfrom(sockfd, buffer, MAX_MESG_SIZE - 1, 0,
                                        (struct sockaddr*)&client_addr, &client_len);

            if (recv_len < 0) {
                continue; // Pas d'erreur grave, on continue
            }

            buffer[recv_len] = '\0';

            // Comparer le message reçu avec l'argument passé
            if (strcmp(buffer, target_string) == 0) {
                // Ajouter l'IP et le port à la liste
                if (shared->count < MAX_ENTRIES) {
                    strcpy(shared->tb[shared->count].ip, inet_ntoa(client_addr.sin_addr));
                    shared->tb[shared->count].port = ntohs(client_addr.sin_port);
                    shared->count++;
                    shared->updated = 1; // Marque comme mis à jour
                    printf("Message reçu identique ! Enregistré : %s:%d\n",
                           shared->tb[shared->count-1].ip, shared->tb[shared->count-1].port);
                }
            }
        }

        // Jamais atteint normalement
        shmdt((void*)shared);
        close(sockfd);
        exit(0);
    } else {
        // === Processus PERE ===
        printf("Père en envoi toutes les secondes sur le broadcast %s:%d...\n"
               "Toutes les 30 secondes, affichage du tableau.\n", BROADCAST_ADDR, PORT);

        // Création du socket d'envoi
        int send_sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (send_sock < 0) {
            perror("socket (envoi)");
            exit(1);
        }

        // Activer SO_BROADCAST
        if (setsockopt(send_sock, SOL_SOCKET, SO_BROADCAST, &broadcast_enable, sizeof(broadcast_enable)) < 0) {
            perror("setsockopt SO_BROADCAST (envoi)");
            exit(1);
        }

        // Adresse de broadcast
        struct sockaddr_in broadcast_addr;
        memset(&broadcast_addr, 0, sizeof(broadcast_addr));
        broadcast_addr.sin_family = AF_INET;
        broadcast_addr.sin_port = htons(PORT);
        inet_pton(AF_INET, BROADCAST_ADDR, &broadcast_addr.sin_addr);

        // Boucle infinie : envoie chaque seconde
        time_t start_time = time(NULL);
        int total_sleep = 0;

        while (1) {
            // Envoyer la chaîne
            if (sendto(send_sock, target_string, strlen(target_string), 0,
                       (struct sockaddr*)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
                perror("sendto");
            } else {
                printf("Envoi de '%s' à %s:%d\n", target_string, BROADCAST_ADDR, PORT);
            }

            sleep(1); // Chaque seconde

            total_sleep++;
            if (total_sleep % 30 == 0) {
                // Toutes les 30 secondes, afficher le tableau tb
                printf("\n=== VISUALISATION DU TABLEAU tb (mis à jour à %ld) ===\n", time(NULL));
                for (int i = 0; i < shared->count; i++) {
                    printf("[%d] %s:%d\n", i + 1, shared->tb[i].ip, shared->tb[i].port);
                }
                printf("=============================================\n\n");

                // Réinitialiser le flag (pour éviter de relire plusieurs fois)
                shared->updated = 0;
            }
        }

        // Nettoyage (jamais atteint si boucle infinie)
        close(send_sock);
        shmdt((void*)shared);
        shmctl(shm_id, IPC_RMID, NULL); // Supprime la mémoire partagée
        wait(NULL); // Attendre que le fils se termine (si nécessaire)
        exit(0);
    }

    return 0;
}
```

