### 🛠️ Код программы `call_graph.c`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FUNCTIONS 100
#define MAX_NAME_LEN 100
#define MAX_LINES 5000
#define MAX_LINE_LEN 256

// Для хранения дерева вызовов
typedef struct FunctionNode {
    char name[MAX_NAME_LEN];
    int call_count;
    struct FunctionNode* children[MAX_FUNCTIONS];
    int child_count;
} FunctionNode;

// Глобальные массивы
FunctionNode functions[MAX_FUNCTIONS];
int func_count = 0;
char line_buffer[MAX_LINE_LEN];

// Поиск функции по имени
FunctionNode* find_function(const char* name) {
    for (int i = 0; i < func_count; i++) {
        if (strcmp(functions[i].name, name) == 0) {
            return &functions[i];
        }
    }
    return NULL;
}

// Добавление вызова: вызвавшая функция вызывает другую
void add_call(const char* caller, const char* callee) {
    FunctionNode* c = find_function(caller);
    if (!c) return;

    FunctionNode* cal = find_function(callee);
    if (!cal) return;

    // Проверка, не добавлен ли уже этот вызов
    for (int i = 0; i < c->child_count; i++) {
        if (c->children[i] == cal) return;
    }

    if (c->child_count < MAX_FUNCTIONS - 1) {
        c->children[c->child_count++] = cal;
    }
}

// Выделение имени функции (то, что перед `(`)
int extract_function_name(char* line, char* buffer) {
    int len = strlen(line);
    int pos = 0;

    // Игнорируем пробелы с начала строки
    while (pos < len && isspace(line[pos])) pos++;

    // Пропускаем тип возврата (может быть длинным)
    while (pos < len && !isspace(line[pos]) && line[pos] != '(' && line[pos] != ')') pos++;

    // Пропускаем пробелы до имени
    while (pos < len && isspace(line[pos])) pos++;

    // Начало имени
    int start = pos;
    while (pos < len && isalnum(line[pos])) {
        pos++;
    }

    if (start >= pos) return 0;  // ничего не нашли

    strncpy(buffer, line + start, pos - start);
    buffer[pos - start] = '\0';

    return 1;
}

// Проверяет, есть ли в строке вызов функции (имя + ())
int detect_call(char* line, char* function_name) {
    int len = strlen(line);
    int i = 0;

    while (i < len - 1) {
        // Ищем начало имени
        while (i < len && !isalnum(line[i]) && line[i] != '_') i++;

        int start = i;

        while (i < len && (isalnum(line[i]) || line[i] == '_')) {
            i++;
        }

        if (i - start <= 0) break;

        char temp_name[MAX_NAME_LEN];
        strncpy(temp_name, line + start, i - start);
        temp_name[i - start] = '\0';

        // Проверяем, заканчивается ли на '('
        if (i < len && line[i] == '(') {
            // Если имя совпадает с функцией, то мы нашли вызов
            if (strcmp(temp_name, function_name) == 0) {
                return 1;
            }
        }
    }

    return 0;
}

// Загружает функцию (определение) в массив и создает узел
void register_function(const char* fname) {
    if (find_function(fname)) return;

    if (func_count >= MAX_FUNCTIONS - 1) {
        printf("Слишком много функций!\n");
        return;
    }

    strcpy(functions[func_count].name, fname);
    functions[func_count].child_count = 0;
    func_count++;
}

// Выводит дерево вызовов
void print_tree(FunctionNode* node, int depth) {
    if (!node) return;

    for (int i = 0; i < depth; i++) printf("  ");
    printf("%s\n", node->name);

    for (int i = 0; i < node->child_count; i++) {
        print_tree(node->children[i], depth + 1);
    }
}

int main() {
    FILE* file = fopen("test.txt", "r");
    if (!file) {
        perror("Ошибка открытия test.txt");
        return 1;
    }

    // Переменные для анализа
    int current_func_line_start = -1;
    char current_func_name[MAX_NAME_LEN] = "";

    while (fgets(line_buffer, MAX_LINE_LEN, file) != NULL) {
        // Удаляем перенос строки
        size_t len = strlen(line_buffer);
        if (len > 0 && line_buffer[len - 1] == '\n') {
            line_buffer[len - 1] = '\0';
            len--;
        }

        // Проверить наличие определения функции: <имя>(...
        char name_temp[MAX_NAME_LEN];
        if (extract_function_name(line_buffer, name_temp)) {
            // Проверяем, что это не прототип (например, если нет '{')
            if (strstr(line_buffer, "{") != NULL) {
                // Это определение функции
                register_function(name_temp);
                strncpy(current_func_name, name_temp, MAX_NAME_LEN - 1);
                current_func_name[MAX_NAME_LEN - 1] = '\0';
            }
        }

        // Теперь проверим: есть ли внутри вызовы других функций?
        if (strlen(current_func_name) > 0) {
            // Ищем вызовы функций в этой строке
            char temp_name[MAX_NAME_LEN];
            int i = 0;

            while (i < len) {
                // Начинаем поиск имени
                while (i < len && !isalnum(line_buffer[i]) && line_buffer[i] != '_') i++;
                int start = i;

                while (i < len && (isalnum(line_buffer[i]) || line_buffer[i] == '_')) {
                    i++;
                }

                if (i - start <= 0) continue;

                strncpy(temp_name, line_buffer + start, i - start);
                temp_name[i - start] = '\0';

                // Проверяем, есть ли после этого '('
                if (i < len && line_buffer[i] == '(') {
                    // Это вызов функции!
                    // Используем её имя (temp_name) как вызванную
                    if (strcmp(temp_name, current_func_name) != 0 && 
                        find_function(temp_name)) {  // вызов другой функции
                        add_call(current_func_name, temp_name);
                    }
                }
            }
        }
    }

    fclose(file);

    // Выводим дерево вызовов
    printf("\n=== ДЕРЕВО ВЫЗОВОВ ФУНКЦИЙ ===\n");

    if (func_count == 0) {
        printf("Нет найденных функций.\n");
        return 0;
    }

    // Ищем корневые функции (вызываемые, но не вызываемые другими)
    FunctionNode* root = NULL;
    int has_incoming[MAX_FUNCTIONS] = {0};

    // Отмечаем функции, которые вызывают другие
    for (int i = 0; i < func_count; i++) {
        for (int j = 0; j < functions[i].child_count; j++) {
            for (int k = 0; k < func_count; k++) {
                if (functions[k].name == functions[i].children[j]->name) {
                    has_incoming[k] = 1;
                }
            }
        }
    }

    // Ищем первую функцию, которая не вызывается ни одной другой (или любую как корень)
    // Если есть несколько — выведем одну, а остальные будут частью дерева
    for (int i = 0; i < func_count; i++) {
        if (!has_incoming[i]) {
            print_tree(&functions[i], 0);
            break;
        }
    }

    // Если корень не найден — просто начать с первой
    if (root == NULL) {
        print_tree(&functions[0], 0);
    }

    return 0;
}
```

