## ✅ Решение

```cpp
#include <stdio.h>
#include <conio.h>
#include <string.h>

using namespace std;

int main()
{
    const int MAX_LEN = 256;
    char input[MAX_LEN];
    char result[MAX_LEN];

    // Ввод строки
    printf("Введите строку: ");
    gets(input); // читаем строку с пробелами

    // Копируем строку в результирующую (будет отсортирована)
    strcpy(result, input);

    // Длина входной строки
    int len = strlen(input);

    // Указатель на начало слова в строке
    char *wordstart = result;
    char *wordend;
    char *current;

    // Подсчитаем количество слов, используя метод сканирования через цикл ассемблера
    // Используем стековый подход: выделим массив указателей на начало каждого слова
    // Но мы не можем использовать динамическую память (malloc), поэтому используем статическую область

    const int MAX_WORDS = 40; // максимум 40 слов
    char* word_ptr[MAX_WORDS];
    int word_count = 0;

    // Найдём все слова (разделители — пробелы, табуляции, символы конца строки)
    current = result;
    while (*current != '\0') {
        // Пропускаем пробелы
        while (*current == ' ' || *current == '\t' || *current == '\n' || *current == '\r') {
            current++;
        }
        if (*current == '\0') break;

        // Нашли начало слова
        word_ptr[word_count++] = current;
        // Теперь пропустим само слово
        while (*current != ' ' && *current != '\t' && *current != '\n' && *current != '\r' && *current != '\0') {
            current++;
        }
        // Последнее слово закрывается нулём
        if (*current != '\0') *current++ = '\0'; // заменяем разделитель на '\0'
    }

    // Теперь отсортируем указатели на слова по длине (алгоритм сортировки выбором)
    // Внешний цикл: проходим по всем элементам
    // Используем локальные переменные и регистры ассемблера

    _asm {
        pushad

        mov ecx, word_count   ; i = word_count
        cld                   ; направление чтения слева направо

        mov esi, 0            ; i = 0
    outer_loop:
        mov ebx, ecx          ; сохраняем текущее значение счетчика
        mov edx, esi          ; j = i
        mov edi, [word_ptr + esi*4] ; ptr_i = word_ptr[i]

        xor eax, eax          ; минимальная длина
        mov cl, 0x7f          ; кладём 127 в регистрах, чтобы сравнивать

    inner_loop:
        cmp edx, ebx          ; если (j >= count) => выйти
        jge end_inner

        mov edi, [word_ptr + edx*4]
        mov eax, edi
        push esi
        push edi
        call get_strlen       ; получить длину слова по указателю
        pop edi
        pop esi

        mov al, byte ptr [ebp + 8]  ; результат возвращён в [ebp+8]
        cmp al, cl              ; если текущая длина меньше, чем минимум — запоминаем
        jge skip_update_min     ; нет — пропускаем

        mov cl, al              ; cl = min_length
        mov ebp, edx            ; запомним индекс минимального слова

    skip_update_min:
        inc edx                 ; j++
        jmp inner_loop

    end_inner:
        ; Теперь поменяем слово в позиции "i" и минимальное слово
        cmp esi, ebp            ; если уже i == min_index — пропустить
        je next_iter

        ; swap word_ptr[esi] и word_ptr[ebp]
        mov eax, [word_ptr + esi*4]
        mov ebx, [word_ptr + ebp*4]
        mov [word_ptr + esi*4], ebx
        mov [word_ptr + ebp*4], eax

    next_iter:
        inc esi
        dec ecx
        jnz outer_loop

        popad
        ret
    }

    // Вывод отсортированной строки
    printf("\nОтсортированная строка по длине слов:\n");

    // Создаём новую строку для вывода
    char output_buffer[MAX_LEN];
    strcpy(output_buffer, "");
    char *output_ptr = output_buffer;

    for (int i = 0; i < word_count; ++i) {
        char* w = word_ptr[i];
        int l = strlen(w);
        strcpy(output_ptr, w);
        output_ptr += l;
        *output_ptr++ = ' ';
    }
    if (word_count > 0) output_ptr[-1] = '\0'; // убираем последний пробел
    else output_buffer[0] = '\0';

    puts(output_buffer);

    getch();
    return 0;
}

// ========================== Функция получения длины строки внутри ассемблера ==========================
// Она вызывается через `call get_strlen`, возвращает длину в `al`
// Использует `scasb`, `lodsb`, `inc` — только разрешённые команды
void get_strlen(char* str) {
    // Эта функция полностью написана на ассемблере
    _asm {
        push ebp
        mov ebp, esp
        push ebx
        push esi
        mov esi, eax          ; esi = указатель на строку
        xor ecx, ecx          ; ec = 0

    length_loop:
        lodsb                 ; загружаем байт в %al
        or al, al             ; проверяем на 0
        jz done               ; если достигнут 0 — выход
        inc ecx               ; увеличиваем счётчик
        jmp length_loop

    done:
        mov al, cl            ; возвращаем длину в %al
        pop esi
        pop ebx
        pop ebp
        ret
    }
}
```

