// Funkcja do obsługi semaforów
void handle_semaphore(int semid, int key, char action, const char* name) {
    struct sembuf op;

    // Inicjalizacja operacji na semaforze
    op.sem_num = 0;
    op.sem_op = (action == '1' || action == '2') ? -1 : 1;  // -1 = zabieranie, +1 = zwalnianie
    op.sem_flag = 0;

    printf("Proces %d [%s] %c (%s)\n", getpid(), name, action, 
           (action == '1' || action == '2') ? "zajmuje" : "zwalnia");

    if (semop(semid, &op, 1) == -1) {
        perror("semop");
        exit(1);
    }

    printf("Zasób %s został %s\n", name, (action == '1' || action == '2') ? "zajęty" : "zwolniony");
}

int main() {
