    // Tworzenie lub uzyskanie dostępu do semafora 1 i 2
    semid1 = semget(SEMAPHORE_KEY_1, 1, IPC_CREAT | 0666);
    semid2 = semget(SEMAPHORE_KEY_2, 1, IPC_CREAT | 0666);

    if (semid1 == -1 || semid2 == -1) {
        perror("semget");
        exit(1);
    }

    // Inicjalizacja semaforów na 1 (jeden dostęp)
    if (semctl(semid1, 0, SETVAL, 1) == -1) {
        perror("semctl (sem1)");
        exit(1);
    }
    if (semctl(semid2, 0, SETVAL, 1) == -1) {
        perror("semctl (sem2)");
        exit(1);
    }

    char action;
    printf("Proces %d uruchomiony.\n", getpid());
    printf("Instrukcje:\n");
    printf("1 – zajęcie semafora 1\n");
    printf("q – zwolnienie semafora 1\n");
    printf("2 – zajęcie semafora 2\n");
    printf("w – zwolnienie semafora 2\n");
    printf("Podaj akcję: ");

    while ((action = getchar()) != EOF) {
        getchar();  // pomin znak nowej linii

        switch (action) {
            case '1':
                handle_semaphore(semid1, SEMAPHORE_KEY_1, '1', "Semafor 1");
                break;
            case 'q':
