// Compara due prodotti per valore (costo * quantità) in ordine decrescente
int confronta_prodotti(const void *a, const void *b) {
    const Prodotto *p1 = (const Prodotto *)a;
    const Prodotto *p2 = (const Prodotto *)b;
    double val1 = p1->costo * p1->quantita;
    double val2 = p2->costo * p2->quantita;

    if (val1 > val2) return -1;
    if (val1 < val2) return 1;
    return 0;
}

// Esercizio 1: Lettura file magazzino
int leggi_magazzino(FILE *file_in, Prodotto magazzino[]) {
    int n_prodotti = 0;
    char buffer[1024];

    while (fgets(buffer, sizeof(buffer), file_in) && n_prodotti < MAX_PRODOTTI) {
        // Ignora linee vuote o commenti
        if (buffer[0] == '\n' || buffer[0] == '#' || buffer[0] == '\r')
            continue;

        char codice[MAX_CODICE_LEN];
        double costo;
        int quantita;

        // Parse della riga: codice, costo, quantità
        if (sscanf(buffer, "%s %lf %d", codice, &costo, &quantita) != 3) {
            fprintf(stderr, "Errore nel parsing della riga: %s\n", buffer);
            continue;
        }

        // Convalida codice
        if (strlen(codice) == 0 || strlen(codice) >= MAX_CODICE_LEN) {
            fprintf(stderr, "Codice prodotto non valido: %s\n", codice);
            continue;
        }

        // Copia il codice
        strcpy(magazzino[n_prodotti].codice, codice);
        magazzino[n_prodotti].costo = costo;
        magazzino[n_prodotti].quantita = quantita;

        n_prodotti++;
    }

    return n_prodotti;
}

// Esercizio 2: Controllo operazione aggiornamento
int controlla_aggiornamento(const char *codice, int variazione, const Prodotto magazzino[], int n_prodotti) {
    // Cerco il prodotto
    int idx = -1;
    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        return -1; // Prodotto non trovato
    }

    int nuova_quantita = magazzino[idx].quantita + variazione;

    // Verifica validità della variazione
    if (variazione < 0 && nuova_quantita < 0) {
        return -2; // Decremento troppo grande -> quantità negativa
    }

    if (nuova_quantita > MAX_QUANTITÀ) {
        return -2; // Incremento troppo grande -> oltre 10000
    }

    return 1; // Operazione consentita
}

// Esercizio 3: Aggiornamento e stampa magazzino
void aggiorna_e_stampa(Prodotto magazzino[], int n_prodotti, const char *codice, int variazione) {
    int idx = -1;
    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        printf("ERRORE: Prodotto '%s' non trovato.\n", codice);
        return;
    }

    // Calcoliamo valore iniziale e finale
    double valore_iniziale = 0.0;
    double valore_finale = 0.0;

    for (int i = 0; i < n_prodotti; i++) {
        valore_iniziale += magazzino[i].costo * magazzino[i].quantita;
    }

    magazzino[idx].quantita += variazione;

    for (int i = 0; i < n_prodotti; i++) {
        valore_finale += magazzino[i].costo * magazzino[i].quantita;
    }

    // Stampa a video
    printf("Operazione eseguita: '%s' + %d -> Quantità: %d\n", codice, variazione, magazzino[idx].quantita);
    printf("Valore magazzino prima: %.2f €\n", valore_iniziale);
    printf("Valore magazzino dopo:  %.2f €\n", valore_finale);
}

// Esercizio 4: Ordinamento e stampa su file
void stampa_ordinato_su_file(FILE *file_out, Prodotto magazzino[], int n_prodotti) {
    // Creiamo una copia temporanea per non modificare l'ordine originale
    Prodotto copia[MAX_PRODOTTI];
    memcpy(copia, magazzino, n_prodotti * sizeof(Prodotto));

    // Ordiniamo per valore decrescente
    qsort(copia, n_prodotti, sizeof(Prodotto), confronta_prodotti);

    // Scriviamo su file
    for (int i = 0; i < n_prodotti; i++) {
        fprintf(file_out, "%s %.2f %d\n",
                copia[i].codice,
                copia[i].costo,
                copia[i].quantita);
    }

    printf("Magazzino ordinato ed escrito su file con successo!\n");
}
