#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_VERTICES 20
#define INF INT_MAX

// 顶点数
int n;

// 邻接矩阵，表示图
int graph[MAX_VERTICES][MAX_VERTICES];

// 距离数组：D[i] 表示从 V0 到 Vi  的最短距离
int D[MAX_VERTICES];

// 标记是否已访问
int visited[MAX_VERTICES];

// 前驱数组：path[i] 表示到 i 顶点的最短路径上前一个顶点
int path[MAX_VERTICES];

// 函   1. 初始化图与数据结构
void initialize(int num_vertices) {
    n = num_vertices;
    // 初始化邻接矩阵为无穷大（即不可达）
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                graph[i][j] = 0;  // 自环为 0
            } 
            else {
                graph[i][j] = INF;
            }
        }
    }

    // 初始化 D[] 为从起点到各点的距离
    for (int i = 0; i < n; i++) {
        D[i] = graph[0][i];  // 假设所有边已存在（后面会改）
        path[i] = -1;        // 无前驱
    }

    // 初始化访问标记
    memset(visited, 0, sizeof(visited));
}

// 函   2. 找出尚未访问且距离最小的顶点
int findMinVertex() {
    int min = INF;
    int k = -1;
    for (int i = 0; i < n; i++) {
        if (!visited[i] && D[i] < min) {
            min = D[i];
            k = i;
        }
    }
    return k;
}

// 函   3. 更新邻接顶点的距离和路径
void updateDistances(int k) {
    for (int i = 0; i < n; i++) {
        // 只考虑与 Vk 相连且未访问的顶点
        if (!visited[i] && graph[k][i] != INF) {
            int new_dist = D[k] + graph[k][i];
            if (new_dist < D[i]) {
                D[i] = new_dist;
                path[i] = k;  // 记录路径：通过 k 到达 i
            }
        }
    }
}

// 函   4. Dijkstra 主函数
void dijkstra(int start) {
    initialize(n);  // ① 初始化

    // 标记起点已访问
    visited[start] = 1;

    // 每次都找当前未访问集合中距离最小的顶点
    for (int count = 0; count < n - 1; count++) {
        int k = findMinVertex();  // ② 求最小

        if (k == -1) {
            printf("Error: No reachable vertex found!\n");
            break;
        }

        visited[k] = 1;  // 标记为已访问

        updateDistances(k);  // ③  更新邻接点的 D[i] 与路径
    }
}

// 函   5. 输出最短路径
void printPath(int target) {
    if (target == 0) {
        printf("V0");
        return;
    }

    if (path[target] == -1) {
        printf("No path exists from V0 to V%d", target);
        return;
    }

    printPath(path[target]);
    printf(" -> V%d", target);
}

// 函   6. 打印结果
void printResult() {
    printf("\n");
    printf("============================================================\n");
    printf("              Dijkstra 最短路径计算结果                      \n");
    printf("============================================================\n");

    printf("源点:   V0\n");
    printf("%-8s %-12s %-12s\n", "顶点", "最短距离", "路径");

    for (int i = 0; i < n; i++) {
        printf("%-8s %-12d ", i == 0 ? "V0" : (char[5]){0}, D[i]);

        if (D[i] == INF) {
            printf("INF");
        } else {
            printPath(i);
        }
        printf("\n");
    }

    printf("============================================================\n");
}

// 函   7. 构建测试图（示例：带权有向图）
void buildGraph() {
    // 假设有 5 个顶点：0 ~ 4
    n = 5;

    // 以实例图为例：
    //       2
    //   5→  |   →3
    //  0   → 1 → 2 → 4
    //   3↓  1↑   ↑     ↑
    //      3     2     4
    //       ↓   ←2  →1
    //          3 ←--- 4

    // 设置边权
    graph[0][1] = 5;
    graph[0][2] = 3;
    graph[1][2] = 1;
    graph[1][3] = 3;
    graph[2][3] = 2;
    graph[2][4] = 4;
    graph[3][4] = 1;
    graph[4][2] = 2;

    // 剩下位置为无穷大（由 initialize 设置）

    printf("已构建图（共 %d 个顶点）:\n", n);
    printf("  顶点编号: 0, 1, 2, 3, 4.\n");
    printf("  详见邻接矩阵定义.\n");
}

// 8. 主函数
int main() {
    buildGraph();

    // 运行 Dijkstra 算法，从顶点 0 (V0) 出发
    dijkstra(0);

    // 输出结果
    printResult();

    return 0;
}
