For any real-world application:

```c
#include <stdio.h>
#include <string.h>
#include <stdint.h>

// Assume you're using OpenSSL for HMAC and SHA-512
#include <openssl/hmac.h>
#include <openssl/sha.h>

#define AES_128_KEY_SIZE 16
#define HMAC_SHA512_KEY_SIZE 64
#define DERIVED_KEY_LEN (AES_128_KEY_SIZE + HMAC_SHA512_KEY_SIZE)

// Function: Derive AES-128 + HMAC-SHA512 key using HKDF (secure replacement for X9.63)
int hkdf_derive_keys(const unsigned char *salt, size_t salt_len,
                      const unsigned char *ikm, size_t ikm_len,
                      const unsigned char *info, size_t info_len,
                      unsigned char *out_key_material) {
    // Step 1: Extract phase – derive a PRK from IKM using salt
    unsigned char prk[64];  // SHA-512 digest size
    unsigned int prk_len;

    HMAC(EVP_sha512(), salt, salt_len, ikm, ikm_len, prk, &prk_len);

    // Step 2: Expand phase – expand PRK into output keys
    unsigned char t[64];   // T buffer for intermediate values
    size_t offset = 0;
    unsigned char counter = 1;

    while (offset < DERIVED_KEY_LEN) {
        // Concatenate [info || counter]
        size_t input_len = info_len + 1;
        unsigned char input[input_len];
        memcpy(input, info, info_len);
        input[info_len] = counter;

        // HMAC( PRK, T || info || counter )
        HMAC(EVP_sha512(), prk, prk_len, input, input_len, t, &prk_len);

        // Copy up to remaining bytes into output
        size_t to_copy = (DERIVED_KEY_LEN - offset < prk_len) ? (DERIVED_KEY_LEN - offset) : prk_len;
        memcpy(out_key_material + offset, t, to_copy);
        offset += to_copy;
        counter++;
    }

    return 0; // Success
}

int main() {
