    unsigned char info[] = "Application: AES-HMAC Keys";

    // Allocate derived key buffer
    unsigned char derived_key_buffer[DERIVED_KEY_LEN];

    // Derive keys using HKDF (recommended)
    if (hkdf_derive_keys(salt, sizeof(salt),
                         password, strlen((char*)password),
                         info, sizeof(info) - 1,
                         derived_key_buffer) != 0) {
        fprintf(stderr, "HKDF derivation failed!\n");
        return -1;
    }

    // Split derived material:
    unsigned char aes_key[AES_128_KEY_SIZE];
    unsigned char hmac_key[HMAC_SHA512_KEY_SIZE];

    memcpy(aes_key, derived_key_buffer, AES_128_KEY_SIZE);
    memcpy(hmac_key, derived_key_buffer + AES_128_KEY_SIZE, HMAC_SHA512_KEY_SIZE);

    printf("AES-128 Key (16 bytes): ");
    for (int i = 0; i < AES_128_KEY_SIZE; i++) {
        printf("%02X", aes_key[i]);
    }
    printf("\n");

    printf("HMAC-SHA512 Key (64 bytes): ");
