    BiTQueue* q = malloc(sizeof(BiTQueue));
    q->front = q->rear = NULL;
    q->n = 0;
    return q;
}

void Push(BiTQueue* Q, BstNode* T) {
    QNode* node = malloc(sizeof(QNode));
    node->data = T;
    node->next = NULL;

    if (Q->front == NULL) {
        Q->front = Q->rear = node;
    } else {
        Q->rear->next = node;
        Q->rear = node;
