//   1 - бесконечно много решений (если система зависима)
//   2 - нет решений (если система противоречива)

int solve_system(int a, int b, int c, int d, double *x, double *y) {
    // Применяем метод подстановки:
    // Из второго уравнения:  =>  [1]  ->  'x = y + d'
    //
    // Подставляем в первое уравнение:
    //   a(y + d) + b y = c
    //   a*y + a*d + b*y = c
    //   (a + b) * y + a*d = c
    //   (a + b) * y = c - a*d

    // Коэффициент при "y"
    double coeff_y = a + b;

    // Правая часть уравнения для 'y'
    double rhs = c - a * d;

    if (coeff_y == 0) {
        // Если коэффициент при 'y' равен нулю, то возможны два случая:
        if (rhs == 0) {
            // Уравнение превращается в 0 = 0 → бесконечно много решений
            // Любая пара (x, y), где  х = у + d
            // Просто вернём, что есть бесконечно много решений.
            // Можно, например, вывести одно общее решение (например, пусть у = 0).
            *x = d;
            *y = 0;
            return 1; // Бесконечно много решений
        } else {
            // 0*y = отличное от нуля → нет решений
            return 2; // Нет решений
        }
    }

    // Находим 'y' из уравнения: y = rhs / coeff_y
    *y = rhs / coeff_y;

    // Находим 'x': x = y + d
    *x = *y + d;

    return 0; // Уникальное решение найдено
}

