#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Function to check if a number (as string) is k-good
bool is_k_good(const char* num_str, int k) {
    // Boolean array to track which digits (0 to k) have been seen
    bool seen[10] = {false};  // Index 0 to 9

    // Traverse each character in the string
    for (int i = 0; i < strlen(num_str); i++) {
        int digit = num_str[i] - '0';
        if (digit <= k) {
            seen[digit] = true;
        }
    }

    // Check if all digits from 0 to k are present
    for (int d = 0; d <= k; d++) {
        if (!seen[d]) {
            return false;
        }
    }

