/* cachecinv.c - Pull-based Cache Invalidation using CSIM20 */
/* Based on G. Cao, "A Scalable Low-Latency Cache Invalidation Strategy", MobiCom 2000 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

// CSIM20 Headers
#include "csim.h"

// Simulation Parameters
#define NUM_CLIENTS         5
#define DB_SIZE             500
#define CACHE_SIZE          100
#define DATA_ITEM_SIZE      1024    // bytes
#define BANDWIDTH           10000   // bits/sec -> 10 Kbps

#define HOT_START           1
#define HOT_END             50
#define HOT_ACCESS_PROB     0.8
#define HOT_UPDATE_PROB     0.33

// Events types
#define QUERY_EVENT         1
#define UPDATE_EVENT        2
#define CHECK_MSG_EVENT     3
#define REQUEST_MSG_EVENT   4
#define REPLY_MSG_EVENT     5

// Time Units in seconds
double T_QUERY_VALUES[] = {5, 10, 25, 50, 100};
double T_UPDATE_VALUES[] = {5, 10, 20, 100, 200};
int num_tq = 5;
int num_tu = 5;

// Global state
double total_queries = 0;
double cache_hits = 0;
double total_query_delay = 0.0;
double total_sent_bytes = 0.0;

// Structures
typedef struct {
    int item_id;
    double timestamp;
} cached_item_t;

typedef struct {
    int client_id;
    int item_id;
    int msg_type;            // 1: QUERY, 2: UPDATE, etc.
    double send_time, recv_time;
} event_t;

// Client structure
typedef struct {
    int id;
    cached_item_t cache[CACHE_SIZE];
    int cache_count;         // number of valid entries
    double last_updated[DB_SIZE + 1];  // last time item was verified via check
    int ref_count[CACHE_SIZE];
} client_t;

client_t clients[NUM_CLIENTS];

// Server info
int update_log[DB_SIZE + 1];  // tracks whether an update occurred
double server_last_update_time[DB_SIZE + 1];  // when was data last updated
int server_data[DB_SIZE + 1];  // actual value (not used, just for validation)
int total_updates = 0;

// Helpers
void init_simulation();
void start_client(int cid, double t);
void start_server(double t);
void generate_query(int cid, double t);
void generate_update(double t);
void send_check_msg(int cid, int item_id, double t);
void receive_request(int cid, int item_id, double t);
void send_reply(int cid, int item_id, double delay);
void handle_cache_hit(int cid, int item_id, double now, int is_valid);
void invalidate_cache(int cid, int item_id, double now);

// For statistical tracking
struct result_stats {
    double t_query, t_update;
    double avg_hit_ratio;
    double avg_query_delay;
    double total_bytes_transferred;
};

struct result_stats results[5][5];  // [tq][tu]
int result_idx = 0;

// Initialize simulation
void init_simulation() {
    srand(time(NULL));
    for (int i=0; i<NUM_CLIENTS; i++) {
        clients[i].id = i;
        clients[i].cache_count = 0;
        memset(clients[i].last_updated, 0, sizeof(clients[i].last_updated));
        memset(clients[i].ref_count, 0, sizeof(clients[i].ref_count));
    }
    memset(server_last_update_time, 0, sizeof(server_last_update_time));
    memset(update_log, 0, sizeof(update_log));
    memset(server_data, 0, sizeof(server_data));
    total_updates = 0;
}

// Find if item is in cache
int find_in_cache(int cid, int item_id) {
    for (int i = 0; i < clients[cid].cache_count; i++) {
        if (clients[cid].cache[i].item_id == item_id) {
            return i;
        }
    }
    return -1;
}

// LRU replacement: move item to front, evict oldest once full
void update_lru(int cid, int index) {
    // If not already in top, shift it up
    cached_item_t temp = clients[cid].cache[index];
    for (int i = index; i > 0; i--) {
        clients[cid].cache[i] = clients[cid].cache[i-1];
    }
    clients[cid].cache[0] = temp;
    // Ref count doesn't reflect here, but for simplicity we ignore it
}

void insert_into_cache(int cid, int item_id, double now) {
    if (clients[cid].cache_count >= CACHE_SIZE) {
        // Evict LRU (last element)
        for (int i = 1; i < CACHE_SIZE; i++) {
            clients[cid].cache[i-1] = clients[cid].cache[i];
        }
        clients[cid].cache_count--;
    }
    clients[cid].cache[clients[cid].cache_count].item_id = item_id;
    clients[cid].cache[clients[cid].cache_count].timestamp = now;
    clients[cid].cache_count++;
}

// Check if item is valid (based on timestamp vs latest server update)
int is_valid(int cid, int item_id) {
    double last_check = clients[cid].last_updated[item_id];
    double last_update = server_last_update_time[item_id];
    return (last_check >= last_update);
}

// Generate a query: pick item (hot or cold with prob)
void generate_query(int cid, double t) {
    // Decide whether hot or cold
    double p_hot = HOT_ACCESS_PROB;
    int is_hot = (rand() / (RAND_MAX + 1.0)) < p_hot ? 1 : 0;

    int item_id;
    if (is_hot) {
        item_id = rand() % (HOT_END - HOT_START + 1) + HOT_START;
    } else {
        item_id = rand() % (DB_SIZE - HOT_END) + HOT_END + 1;
    }

    int cache_index = find_in_cache(cid, item_id);
    double now = t;

    if (cache_index != -1) {
        // Cache hit
        cache_hits++;
        // Send check message
        event_t *ev = malloc(sizeof(event_t));
        ev->client_id = cid;
        ev->item_id = item_id;
        ev->msg_type = CHECK_MSG_EVENT;
        ev->send_time = now;
        schedule_event(CHECK_MSG_EVENT, now + 0.001, ev);  // slight delay
    } else {
        // Cache miss: request from server
        event_t *ev = malloc(sizeof(event_t));
        ev->client_id = cid;
        ev->item_id = item_id;
        ev->msg_type = REQUEST_MSG_EVENT;
        ev->send_time = now;
        schedule_event(REQUEST_MSG_EVENT, now + 0.001, ev);
    }

    total_queries++;

    // Schedule next query
    double inter_arrival = exponential_rand(T_QUERY_VALUES[result_idx % 5]);
    schedule_event(QUERY_EVENT, t + inter_arrival, NULL);
}

// Handle Check Message: validate and respond
void send_check_msg(int cid, int item_id, double t) {
    if (is_valid(cid, item_id)) {
        // Valid: confirm immediately
        handle_cache_hit(cid, item_id, t, 1);
        clients[cid].last_updated[item_id] = t;
    } else {
        // Invalid: request fresh copy
        event_t *ev = malloc(sizeof(event_t));
        ev->client_id = cid;
        ev->item_id = item_id;
        ev->msg_type = REQUEST_MSG_EVENT;
        ev->send_time = t;
        schedule_event(REQUEST_MSG_EVENT, t + 0.001, ev);
    }
}

// Handle Request Message: send server reply
void receive_request(int cid, int item_id, double t) {
    double data_size_bits = DATA_ITEM_SIZE * 8.0;
    double prop_delay = data_size_bits / BANDWIDTH;
    double send_time = t;
    double recv_time = t + prop_delay;

    clients[cid].last_updated[item_id] = server_last_update_time[item_id];
    insert_into_cache(cid, item_id, recv_time);

    total_sent_bytes += data_size_bits;
    total_query_delay += prop_delay;

    event_t *ev = malloc(sizeof(event_t));
    ev->client_id = cid;
    ev->item_id = item_id;
    ev->msg_type = REPLY_MSG_EVENT;
    ev->recv_time = recv_time;
    schedule_event(REPLY_MSG_EVENT, recv_time, ev);
}

// Handle Reply Message
void send_reply(int cid, int item_id, double delay) {
    // Only track delay from original query
    // But delay already measured in network delay
}

void handle_cache_hit(int cid, int item_id, double now, int is_valid) {
    // If valid, no extra action needed
    if (is_valid) {
        cache_hits++;
    }
    // Always record timestamp of valid check
    clients[cid].last_updated[item_id] = now;
}

// Server generates updates to hot items
void generate_update(double t) {
    int item_id = rand() % (HOT_END - HOT_START + 1) + HOT_START;
    double prob = (rand() / (RAND_MAX + 1.0));

    if (prob <= HOT_UPDATE_PROB) {
        total_updates++;
        server_last_update_time[item_id] = t;
        update_log[item_id]++;  // mark update

        // Invalidate all caches for this item
        for (int i = 0; i < NUM_CLIENTS; i++) {
            invalidate_cache(i, item_id, t);
        }
    }

    // Schedule next update
    double inter_arrival = exponential_rand(T_UPDATE_VALUES[result_idx % 5]);
    schedule_event(UPDATE_EVENT, t + inter_arrival, NULL);
}

void invalidate_cache(int cid, int item_id, double now) {
    int index = find_in_cache(cid, item_id);
    if (index != -1) {
        // Move to end? Or just remove?
        for (int i = index; i < clients[cid].cache_count - 1; i++) {
            clients[cid].cache[i] = clients[cid].cache[i+1];
        }
        clients[cid].cache_count--;
    }
    clients[cid].last_updated[item_id] = now; // mark as obsolete
}

// Main Simulation function
void sim() {
    // Run for fixed duration after warmup
    int warmup_duration = 1000;  // seconds
    int run_duration = 2000;     // seconds

    double current_time = 0.0;
    double final_time = warmup_duration + run_duration;

    printf("Starting simulation with T_query = %.1f, T_update = %.1f\n",
           T_QUERY_VALUES[result_idx % 5], T_UPDATE_VALUES[result_idx % 5]);

    // Start server and first events
    schedule_event(QUERY_EVENT, 0.0, NULL);
    schedule_event(UPDATE_EVENT, 0.0, NULL);

    // Primary simulation loop
    while ((current_time = get_next_event_time()) < final_time) {
        int event_type = get_event_type();

        if (event_type == QUERY_EVENT) {
            double t = get_event_time();
            // Distribute queries among clients
            int cid = (int)(floor(rand() / (RAND_MAX + 1.0) * NUM_CLIENTS));
            generate_query(cid, t);
        } else if (event_type == UPDATE_EVENT) {
            double t = get_event_time();
            generate_update(t);
        } else if (event_type == CHECK_MSG_EVENT) {
            event_t *ev = (event_t*)get_event_data();
            send_check_msg(ev->client_id, ev->item_id, ev->send_time);
            free(ev);
        } else if (event_type == REQUEST_MSG_EVENT) {
            event_t *ev = (event_t*)get_event_data();
            receive_request(ev->client_id, ev->item_id, ev->send_time);
            free(ev);
        } else if (event_type == REPLY_MSG_EVENT) {
            event_t *ev = (event_t*)get_event_data();
            send_reply(ev->client_id, ev->item_id, ev->recv_time);
            free(ev);
        }

        advance_time();
    }

    // Collect metrics after warmup
    double avg_hit_ratio = cache_hits / total_queries;
    double avg_delay = total_query_delay / total_queries;
    double total_bytes_kB = total_sent_bytes / 1000.0;

    // Store result
