// Параметры: массив столбца (размер 'rows'), длина столбца
int isNonDecreasing(int col[], int rows) {
    for (int i = 1; i < rows; i++) {
        if (col[i] < col[i - 1]) {
            return 0; // не неубывающая
        }
    }
    return 1; // неубывающая
