```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE_LENGTH 1024
#define HEX_PATTERN "0[xX][0-9a-fA-F]+"

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    // Компиляция регулярного выражения для шестнадцатеричных чисел
    regex_t regex;
    int ret = regcomp(&regex, HEX_PATTERN, REG_EXTENDED | REG_ICASE);
    if (ret != 0) {
        fprintf(stderr, "Failed to compile regex\n");
        fclose(file);
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    char *highlight_start = NULL;
    char *highlight_end = NULL;
    char *ptr = NULL;
    int offset = 0;

    while (fgets(line, sizeof(line), file)) {
        // Начинаем вывод с обычного текста
        printf("\033[0m"); // Сброс цвета

        // Ищем все совпадения в строке
        regmatch_t matches[1];
        ptr = line;
        offset = 0;

        while (regexec(&regex, ptr, 1, matches, 0) == 0) {
            // Устанавливаем позиции
            highlight_start = ptr + matches[0].rm_so;
            highlight_end = ptr + matches[0].rm_eo;

            // Печатаем текст до шестнадцатеричной части
            *highlight_start = '\0';
            printf("%s", ptr);

            // Подсвечиваем шестнадцатеричную константу
            printf("\033[1;33m"); // Желтый, жирный
            printf("%.*s", (int)(highlight_end - highlight_start), highlight_start);
            printf("\033[0m"); // Сброс цвета

            // Двигаемся дальше
