    int max_length = 1;
    int max_index = 0; // index where the longest chain ends

    // Initialize
    for (int i = 0; i < n; i++) {
        freq[i] = 1;
        prev[i] = -1; // no predecessor

        for (int j = 0; j < i; j++) {
