    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

// 音符索引映射：根据按键字母映射到 freq[] 索引
// 注意：键盘上 '1'~'9' 对应 freq[0]~freq[8]；'0' 对应 freq[9]；'A'~'D' 保留为控制键
unsigned char key_to_freq_idx(char key) {
    if (key >= '1' && key <= '9') {
        return key - '1';
    } else if (key == '0') {
        return 9;
    } else if (key == '*') {
        return 255; // 特殊控制键：录制开始/停止
    } else if (key == '#') {
        return 254; // 播放回放
    } else {
        return 255; // 无效键
    }
}

// 去抖延迟函数（10ms 去抖，可调整）
void delay_10ms(unsigned char cnt) {
    unsigned int i;
    while (cnt--) {
        for (i = 0; i < 1100; i++); // 约 10ms @ 12MHz
    }
}

char matrix_keypad_scan() {
    char key = 0;
    int i, j;
    unsigned char last_col = 0xFF;

    // 初始化：所有行拉高，列拉高（输入模式）
    row1 = 1; row2 = 1; row3 = 1; row4 = 1;
    col1 = 1; col2 = 1; col3 = 1; col4 = 1;

    // 低电平扫描：每行置低，检测列
    for (i = 0; i < ROWS; i++) {
        switch (i) {
            case 0: row1 = 0; break;
            case 1: row2 = 0; break;
            case 2: row3 = 0; break;
            case 3: row4 = 0; break;
        }

        delay_10ms(1); // 10ms 去抖延迟

        // 检测列状态
        for (j = 0; j < COLS; j++) {
            if (col1 == 0) {
                key = keymap[i][j];
                break;
            }
            if (col2 == 0) {
                key = keymap[i][j+1];
                break;
            }
            if (col3 == 0) {
                key = keymap[i][j+2];
                break;
            }
            if (col4 == 0) {
                key = keymap[i][j+3];
                break;
            }
        }

        // 如果检测到按键，等待释放（关键去抖）
        if (key != 0) {
            while (col1==0 || col2==0 || col3==0 || col4==0) {
