            }
            return key;
        }

        // 恢复列状态
        col1 = 1; col2 = 1; col3 = 1; col4 = 1;
    }

    return 0;
}

// 播放单个音符
void play_note(unsigned char idx, unsigned int duration) {
    if (idx >= 13) return;

    unsigned int val = Clk / freq[idx];
    if (freq[idx] == 0 || val > 0xFFFF) return;

    val = 0xFFFF - val;
    val_H = (val >> 8) & 0xFF;
    val_L = val & 0xFF;

    // 更新定时器初值
    TH0 = val_H;
    TL0 = val_L;

    // 播放持续时间（单位：10毫秒）
    unsigned int i;
    for (i = 0; i < duration; i++) {
        Delay(1); // 约10ms，实际调用 Delay(1) ≈ 10ms（需验证）
        // 检查是否需要停止播放
        if (key_scan(0) != KEY_UNPRESS) {
            break;
        }
    }
}

// 定时器 0 中断服务程序（更新：仅在播放/录制时才控制蜂鸣器）
void t0_isr() interrupt 1 {
    if (song_playing) {
        P00 = ~P00; // 方波输出
    } else {
        P00 = 1; // 关闭蜂鸣器
    }
    TH0 = val_H;
    TL0 = val_L;
}

// 录制音乐：将当前按键记录到 buffer
void record_key(char key) {
    unsigned char idx = key_to_freq_idx(key);

    if (idx == 255) return; // 无效键

    if (music_length >= 32) return; // 防止溢出

    if (idx == 255) return; // 暂不处理特殊键，待逻辑补充

    // 仅在录制模式下记录
    if (recording && idx < 13) {
        music_buffer[music_length] = idx;
        time_buffer[music_length] = 20; // 默认时长 200ms（20×10ms）
        music_length++;
    }
}

// 播放录制的音乐
void play_recorded_music() {
    if (music_length == 0) return;

    playback = 1;
    paused = 0;
    unsigned char i = 0;

    // 循环播放
    while (1) {
        // 如果按了 * 或 #，暂停或停止
        if (key_scan(0) != KEY_UNPRESS || paused) {
            while (key_scan(0) != KEY_UNPRESS) {
                delay_10ms(1);
            }
            if (!paused) {
                paused = 1; // 暂停
                song_playing = 0;
                continue;
            } else {
                paused = 0; // 继续
            }
        }

        if (paused) continue;

        if (i >= music_length) {
            // 播放结束，等待用户操作或自动重启
            delay_10ms(100); // 1秒静音
            i = 0; // 重新开始
        }

        play_note(music_buffer[i], time_buffer[i]);
        i++;
        // 支持中途停止
        if (key_scan(0) != KEY_UNPRESS) {
            playback = 0;
            break;
        }
    }

    playback = 0;
}

