            double a, b, result;

            if (is_empty(&result_stack)) {
                fprintf(stderr, "Ошибка: недостаточно операндов для операции '%c'.\n", op);
                exit(1);
            }

            // Сначала извлекаем B, потом A — потому что стек работает LIFO
            b = pop(&result_stack);
            if (is_empty(&result_stack)) {
                fprintf(stderr, "Ошибка: недостаточно операндов для операции '%c'.\n", op);
                exit(1);
            }
            a = pop(&result_stack);

            // Проверка на деление на ноль
            if (op == '/' && b == 0.0) {
                fprintf(stderr, "Ошибка: деление на ноль.\n");
                exit(1);
            }

            switch (op) {
                case '+': result = a + b; break;
                case '-': result = a - b; break;
                case '*': result = a * b; break;
                case '/': result = a / b; break;
                case '%': result = fmod(a, b); break;
                case '^': result = pow(a, b); break;
                default:
                    fprintf(stderr, "Неизвестная операция: %c\n", op);
                    exit(1);
