            if (isinf(result) || isnan(result)) {
                fprintf(stderr, "Ошибка: вычисление привело к бесконечности или NaN.\n");
                exit(1);
            }

            push(&result_stack, result);
        }
        token = strtok(NULL, " ");
    }

    // Должно остаться одно число
    if (is_empty(&result_stack) || !is_empty(&result_stack) && result_stack.top != 0) {
        fprintf(stderr, "Ошибка: неверный синтаксис выражения.\n");
        exit(1);
    }

    return peek(&result_stack);
}

// Главная функция калькулятора
