// SSTF 算法
void sstf(int tracks[], int n, int initial) {
    // 创建访问数组副本，用标记表示是否被访问
    int* temp = (int*)malloc(n * sizeof(int));
    int* visited = (int*)calloc(n, sizeof(int));
    if (!temp || !visited) {
        fprintf(stderr, "内存分配失败！\n");
        free(temp);
        free(visited);
        return;
    }
    memcpy(temp, tracks, n * sizeof(int));

    int totalSeek = 0;
    int current = initial;
    printf("调度顺序: %d", initial);

    for (int i = 0; i < n; i++) {
        int minSeek = INT_MAX;
        int nextTrack = -1;

        for (int j = 0; j < n; j++) {
            if (visited[j]) continue;
            int seek = abs(temp[j] - current);
            if (seek < minSeek) {
                minSeek = seek;
                nextTrack = j;
            }
        }

        if (nextTrack == -1) break;

        totalSeek += minSeek;
        current = temp[nextTrack];
        visited[nextTrack] = 1;
        printf(" -> %d", current);
    }
    printf("\n总寻道长度: %d\n", totalSeek);
    printf("平均寻道长度: %.2f\n", (double)totalSeek / n);

    free(temp);
    free(visited);
}

// SCAN 算法
void scan(int tracks[], int n, int initial, int direction) {
    // 分离当前磁头左右的请求
    int leftTracks[MAX_TRACKS], rightTracks[MAX_TRACKS];
    int leftCount = 0, rightCount = 0;

    for (int i = 0; i < n; i++) {
        if (tracks[i] < initial) {
            leftTracks[leftCount++] = tracks[i];
        } else if (tracks[i] > initial) {
            rightTracks[rightCount++] = tracks[i];
        }
    }

    // 对左右部分排序
    sortTracks(leftTracks, leftCount);
    sortTracks(rightTracks, rightCount);

    int totalSeek = 0;
    int current = initial;
    printf("调度顺序: %d", initial);

    // 优先处理方向上的轨道
    if (direction == 1) {
        // 先处理右侧（向上）
        for (int i = 0; i < rightCount; i++) {
            totalSeek += abs(rightTracks[i] - current);
            current = rightTracks[i];
            printf(" -> %d", current);
        }
        // 到达右端后，反向处理左侧（向下）
        totalSeek += (MAX_TRACKS - 1 - current);
        current = MAX_TRACKS - 1;
        printf(" -> %d (右端)", current);
        for (int i = leftCount - 1; i >= 0; i--) {
            totalSeek += abs(leftTracks[i] - current);
            current = leftTracks[i];
            printf(" -> %d", current);
        }
    } else {
        // 向下方向
        for (int i = leftCount - 1; i >= 0; i--) {
            totalSeek += abs(leftTracks[i] - current);
            current = leftTracks[i];
            printf(" -> %d", current);
        }
        // 到达左端后返回右端（向上）
        totalSeek += current;
        current = 0;
        printf(" -> %d (左端)", current);
        for (int i = 0; i < rightCount; i++) {
            totalSeek += abs(rightTracks[i] - current);
            current = rightTracks[i];
            printf(" -> %d", current);
        }
    }

    printf("\n总寻道长度: %d\n", totalSeek);
    printf("平均寻道长度: %.2f\n", (double)totalSeek / n);
}

// 简单快速排序（降序或升序）
void sortTracks(int tracks[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (tracks[j] > tracks[j + 1]) {
                int tmp = tracks[j];
                tracks[j] = tracks[j + 1];
                tracks[j + 1] = tmp;
            }
        }
    }
}

// 绝对值函数
int abs(int x) {
    return x < 0 ? -x : x;
}
