// call_tree.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LINE 1024
#define MAX_FUNCS 1000
#define MAX_NAME 64

// Структура для узла дерева вызовов
typedef struct Node {
    char name[MAX_NAME];
    struct Node* children[MAX_FUNCS]; // список вызываемых функций
    int child_count;
    struct Node* parent;
} Node;

// Глобальные массивы
Node nodes[MAX_FUNCS];
int node_count = 0;

// Хэш-мап: имя функции → индекс в массиве nodes
int func_index_map[256]; // простой кэш по первому символу, не оптимально, но работает для demo
void init_map() {
    for (int i = 0; i < 256; i++) func_index_map[i] = -1;
}

// Поиск функции по имени, возвращает индекс или -1
int find_or_add_node(const char* name) {
    // Поиск в уже существующих узлах
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i].name, name) == 0) {
            return i;
        }
    }

    // Добавление новой функции
    if (node_count >= MAX_FUNCS) {
        fprintf(stderr, "Ограничение на количество функций превышено.\n");
        return -1;
    }

    Node* new_node = &nodes[node_count++];
    strncpy(new_node->name, name, MAX_NAME - 1);
    new_node->name[MAX_NAME - 1] = '\0';
    new_node->child_count = 0;
    new_node->parent = NULL;

    // Обновляем хэш-мап
    func_index_map[(unsigned char)name[0]] = node_count - 1;

    return node_count - 1;
}

// Извлечение имени функции из строки `func(...)` или `func ( ... )`
// (поддержка пробелов, но не проверяет синтаксис полностью)
char* extract_func_name(const char* line, int start_pos) {
    char* buf = malloc(MAX_NAME);
    if (!buf) return NULL;

    int i = 0;
    int pos = start_pos;

    // Пропускаем пробелы
    while (isspace(line[pos])) pos++;

    // Читаем имя (буквы, цифры, подчёркивания)
    while (line[pos] && (isalnum(line[pos]) || line[pos] == '_')) {
        if (i >= MAX_NAME - 1) break;
        buf[i++] = line[pos++];
    }
    buf[i] = '\0';

    // Определяем, что это действительно функция: далее идёт '('
    while (line[pos] && isspace(line[pos])) pos++;
    if (line[pos] != '(') {
        free(buf);
        return NULL;
    }

    return buf;
}

// Построение дерева вызовов
void build_call_tree(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Не удалось открыть файл");
        exit(1);
    }

    char line[MAX_LINE];
    int line_num = 0;

    while (fgets(line, sizeof(line), fp)) {
        line_num++;

        // Ищем открывающую скобку, которая может следовать за именем функции
        for (int i = 0; line[i]; i++) {
            if (line[i] == '(') {
                // Проверяем, что перед ней есть символы, которые могут быть именем функции
                // и возвращаем позицию начала имени
                int start = i - 1;
                while (start >= 0 && (isalnum(line[start]) || line[start] == '_')) {
                    start--;
                }
                start++; // первый символ имени

                // Пропускаем возможные пробелы
                while (start < i && isspace(line[start])) start++;

                if (start >= i) continue;

                char* func_name = extract_func_name(line, start);
                if (!func_name) continue;

                // Находим или создаём узел для этой функции
                int parent_idx = find_or_add_node(func_name);
                free(func_name);
                if (parent_idx == -1) continue;

                // Теперь ищем *вызовы* внутри этой строки
                // Ищем имя, за которым следует '('
                for (int j = i + 1; line[j]; j++) {
                    if (line[j] == '(' && j > 0 && !isspace(line[j-1])) {
                        // Снова выясняем, может быть вызов функции
                        int call_start = j - 1;
                        while (call_start >= 0 && (isalnum(line[call_start]) || line[call_start] == '_')) {
                            call_start--;
                        }
                        call_start++;

                        // Пропускаем пробелы и проверяем, что это вызов
                        while (call_start < j && isspace(line[call_start])) call_start++;

                        if (call_start >= j) continue;

                        char* called_func = extract_func_name(line, call_start);
                        if (!called_func) continue;

                        // Ищем или создаём узел для вызываемой функции
                        int child_idx = find_or_add_node(called_func);
                        free(called_func);
                        if (child_idx == -1) continue;

                        // Если вызываемая функция ещё не была добавлена как дочерняя
                        bool found = false;
                        for (int k = 0; k < nodes[parent_idx].child_count; k++) {
                            if (nodes[parent_idx].children[k] == &nodes[child_idx]) {
                                found = true;
                                break;
                            }
                        }
                        if (!found && nodes[parent_idx].child_count < MAX_FUNCS) {
                            nodes[parent_idx].children[nodes[parent_idx].child_count] = &nodes[child_idx];
                            nodes[parent_idx].child_count++;
                            // Устанавливаем родителя (для обратной ссылки)
                            if (nodes[child_idx].parent == NULL) {
                                nodes[child_idx].parent = &nodes[parent_idx];
                            }
                        }
                    }
                }
            }
        }
    }

    fclose(fp);
}

// Рекурсивный вывод дерева вызовов с отступами
void print_call_tree(const Node* node, int depth) {
    if (!node) return;

    // Выводим текущий узел с отступом
    for (int i = 0; i < depth; i++) printf("  ");
    printf("%s\n", node->name);

    // Рекурсивно выводим дочерние
    for (int i = 0; i < node->child_count; i++) {
        print_call_tree(node->children[i], depth + 1);
    }
}

// Вывод дерева вызовов
void print_tree() {
    printf("\n=== Дерево вызовов функций ===\n");
    for (int i = 0; i < node_count; i++) {
        // Только корневые узлы (тех, у которых нет родителя)
        if (nodes[i].parent == NULL) {
            print_call_tree(&nodes[i], 0);
        }
    }
}

// Главная функция
int main() {
    init_map();
    build_call_tree("test.txt");
    print_tree();
    return 0;
}
