    *year = y;
    *month = m;
    *day = d;
    return 1;
}

// 增加/减少年、月、日（安全更新）
void adjust_date(int *year, int *month, int *day, int adjustment_type, int step) {
    switch (adjustment_type) {
        case 1: // 增加年
            *year += step;
            break;
        case 2: // 减少年
            *year -= step;
            break;
        case 3: // 增加月
