            break;
        case 6: // 减少日
            *day -= step;
            break;
        default:
            printf("无效操作类型\n");
            return;
    }

    // 循环进位/错位处理：例如 2025-13-01 => 2026-01-01
    while (*month > 12) {
        (*year)++;
        (*month) -= 12;
    }
    while (*month < 1) {
        (*year)--;
        (*month) += 12;
    }

    // 处理日的进位（如 2025-02-30 => 2025-03-02）
    while (*day > days_in_month(*year, *month)) {
        (*day) -= days_in_month(*year, *month);
        (*month)++;
        if (*month > 12) {
            (*year)++;
            (*month) = 1;
        }
    }
    while (*day < 1) {
        (*month)--;
        if (*month < 1) {
            (*year)--;
            (*month) = 12;
        }
        (*day) += days_in_month(*year, *month);
    }
