    int arr[MAX_SIZE];  // Mảng chứa tối đa 101 phần tử
    int n;              // Số lượng phần tử thực tế

    // ========== BƯỚC 1: Khai báo mảng và biến n ==========
    // Đã được định nghĩa ở trên: arr[MAX_SIZE], n

