            // Xóa buffer lỗi
            while (getchar() != '\n');
            continue;
        }

        if (n < 1 || n > MAX_SIZE) {
            printf("⚠️ Sai: So luong phai tu 1 den %d.\n", MAX_SIZE);
        }
    } while (n < 1 || n > MAX_SIZE);

    // ========== BƯỚC 3: Nhập phần tử mảng với kiểm tra ==========
    printf("Nhap %d phan tu nguyen:\n", n);
    for (int i = 0; i < n; i++) {
        printf("Phan tu thu %d: ", i + 1);
        if (scanf("%d", &arr[i]) != 1) {
            printf("⚠️ Loi nhap: Vui long nhap mot so nguyen.\n");
            // Dừng chương trình an toàn khi lỗi nghiêm trọng
            fprintf(stderr, "❌ Lỗi: Nhập dữ liệu không hợp lệ. Dừng chương trình.\n");
            exit(1);
        }
    }

    // ========== BƯỚC 4: Sắp xếp giảm dần (Bubble Sort lồng vòng for) ==========
    printf("\n--- SẮP XẾP GIẢM DẦN ---\n");
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (arr[j] < arr[j + 1]) {
                // Đổi chỗ
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    // ========== BƯỚC 5: Hiển thị mảng đã sắp xếp giảm dần ==========
    printf("Mang sau khi sap xep giam dan: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // ========== BƯỚC 6: Sắp xếp tăng dần (lặp lại logic với thay đổi điều kiện) ==========
    printf("\n--- SẮP XẾP TĂNG DẦN ---\n");
    // Khôi phục lại mảng ban đầu (nếu cần) → ta làm lại từ đầu
    // Nhưng ở đây ta sẽ làm lại sắp xếp tăng dần từ mảng ban đầu (giữ lại data gốc)

