    // Tuy nhiên, vì chỉ cần thực hiện một lần, ta có thể làm:

    // Khôi phục lại mảng ban đầu từ dữ liệu đã lưu (mảng gốc không thay đổi)
    // Nhưng ở đây ta sẽ làm: tạo một mảng sao chép để sắp xếp tăng dần
    int sorted_asc[MAX_SIZE];
    for (int i = 0; i < n; i++) {
        sorted_asc[i] = arr[i];  // Lấy lại dữ liệu từ lần sắp xếp giảm dần
    }

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (sorted_asc[j] > sorted_asc[j + 1]) {
                int temp = sorted_asc[j];
                sorted_asc[j] = sorted_asc[j + 1];
                sorted_asc[j + 1] = temp;
            }
        }
    }

    // Hiển thị mảng tăng dần
    printf("Mang sau khi sap xep tang dan: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", sorted_asc[i]);
    }
    printf("\n");

    printf("✅ Hoan thanh. Chuong trinh da chay thanh cong.\n");
    return 0;
}
