        if (scanf("%d", &temp) != 1) {
            fprintf(stderr, "输入错误：第 %d 个数不是有效整数\n", i + 1);
            return 1;
        }
        numbers[i] = (double)temp;
    }

    // Step 1: 计算平均值
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += numbers[i];
    }
    double mean = sum / n;

    // Step 2: 计算离均差平方和
    double sum_of_squares = 0.0;
    for (int i = 0; i < n; i++) {
        double diff = numbers[i] - mean;
        sum_of_squares += diff * diff;
