### ✅ **`election.c`**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_CANDIDATES 100
#define MAX_NAME_LENGTH 100
#define MAX_LINE_LENGTH 1000

// Structure pour stocker les candidats
typedef struct {
    char name[MAX_NAME_LENGTH];
    int votes;
} Candidate;

int main() {
    FILE *infile = fopen("votes.txt", "r");
    FILE *outfile = fopen("resultats.txt", "w");

    // Vérification de l'ouverture des fichiers
    if (!infile) {
        fprintf(stderr, "Erreur : impossible d'ouvrir votes.txt\n");
        return 1;
    }
    if (!outfile) {
        fprintf(stderr, "Erreur : impossible de créer resultats.txt\n");
        fclose(infile);
        return 1;
    }

    // Tableau des candidats
    Candidate candidates[MAX_CANDIDATES];
    int num_candidates = 0;
    char line[MAX_LINE_LENGTH];

    // Lire les noms des candidats
    while (fgets(line, sizeof(line), infile) && num_candidates < MAX_CANDIDATES) {
        // Supprimer le saut de ligne final
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
            len--;
        }
        if (len == 0) continue;  // Ligne vide ?

        strcpy(candidates[num_candidates].name, line);
        candidates[num_candidates].votes = 0;
        num_candidates++;
    }

    // Vérification qu'au moins un candidat existe
    if (num_candidates == 0) {
        fprintf(stderr, "Erreur : aucun candidat trouvé dans votes.txt\n");
        fclose(infile);
        fclose(outfile);
        return 1;
    }

    // Lire la ligne des votes
    if (!fgets(line, sizeof(line), infile)) {
        fprintf(stderr, "Erreur : pas de ligne de votes trouvée\n");
        fclose(infile);
        fclose(outfile);
        return 1;
    }

    // Supprimer saut de ligne
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\n') {
        line[len - 1] = '\0';
    }

    // Compteur de votes
    int total_votes = 0;
    int valid_votes = 0;
    int invalid_votes = 0;

    // Analyser les votes
    char *token = strtok(line, " \t\n");
    int vote;

    while (token != NULL) {
        if (sscanf(token, "%d", &vote) != 1) {
            fprintf(stderr, "Erreur : conversion invalide pour '%s'\n", token);
            token = strtok(NULL, " \t\n");
            continue;
        }

        total_votes++;

        // Vérification validité du vote
        if (vote < 1 || vote > num_candidates) {
            fprintf(outfile, "Vote invalide : %d\n", vote);
            invalid_votes++;
        } else {
            candidates[vote - 1].votes++;  // Convertir de 1-based à 0-based
            valid_votes++;
        }

        token = strtok(NULL, " \t\n");
    }

    // Écrire les résultats dans resultats.txt
    fprintf(outfile, "Nombre d'électeurs : %d\n", total_votes);
    fprintf(outfile, "Nombre de votes valides : %d\n", valid_votes);
    fprintf(outfile, "Nombre de votes annules : %d\n", invalid_votes);
    fprintf(outfile, "\nCandidat score\n");

    // Écrire les scores
    for (int i = 0; i < num_candidates; i++) {
        fprintf(outfile, "%s %d\n", candidates[i].name, candidates[i].votes);
    }

    // Trouver le maximum de votes
    int max_votes = -1;
    for (int i = 0; i < num_candidates; i++) {
        if (candidates[i].votes > max_votes) {
            max_votes = candidates[i].votes;
        }
    }

    // Écrire les gagnants
    fprintf(outfile, "\nLes gagnants:\n");
    int found_winner = 0;
    for (int i = 0; i < num_candidates; i++) {
        if (candidates[i].votes == max_votes) {
            fprintf(outfile, "%s\n", candidates[i].name);
            found_winner = 1;
        }
    }

    // Vérifier qu'un gagnant existe (au cas où il y a des votes nuls)
    if (!found_winner) {
        fprintf(outfile, "Aucun candidat n'a obtenu de votes.\n");
    }

    // Fermeture des fichiers
    fclose(infile);
    fclose(outfile);

    printf("Résultats écrits dans resultats.txt avec succès.\n");

    return 0;
}
