// 调整日期（自动处理越界、月/年滚动）
void adjust_date(int* year, int* month, int* day, int change_type, int delta) {
    switch (change_type) {
        case 0: // 年份调整
            *year += delta;
            break;
        case 1: // 月份调整
            *month += delta;
            while (*month > 12) { *month -= 12; (*year)++; }
            while (*month < 1) { *month += 12; (*year)--; }
            // 修正天数
            if (*day > days_in_month(*month, *year)) {
                *day = days_in_month(*month, *year);
            }
            break;
        case 2: // 日期调整
            *day += delta;
            while (*day <= 0) {
                (*month)--;
                if (*month < 1) {
                    *month = 12;
                    (*year)--;
                }
                *day += days_in_month(*month, *year);
            }
            while (*day > days_in_month(*month, *year)) {
                *day -= days_in_month(*month, *year);
                (*month)++;
                if (*month > 12) {
                    *month = 1;
                    (*year)++;
                }
            }
            break;
    }

    // 限制年份范围
    if (*year < MIN_YEAR) {
        fprintf(stderr, "⚠️  年份过低，已重置为 %d\n", MIN_YEAR);
        *year = MIN_YEAR;
    } else if (*year > MAX_YEAR) {
        fprintf(stderr, "⚠️  年份过高，已重置为 %d\n", MAX_YEAR);
        *year = MAX_YEAR;
    }

    printf("📅 日期已更新为：%04d-%02d-%02d\n", *year, *month, *day);
    print_calendar(*year, *month, *day);
}

// 设置系统时间（使用 settimeofday）
int set_system_time(int year, int month, int day) {
    struct tm timeinfo = {0};
    timeinfo.tm_year = year - 1900;
    timeinfo.tm_mon = month - 1;  // 0-11
    timeinfo.tm_mday = day;
    timeinfo.tm_hour = 0;
    timeinfo.tm_min = 0;
    timeinfo.tm_sec = 0;
    timeinfo.tm_isdst = -1;

    time_t timestamp = mktime(&timeinfo);
    if (timestamp == -1) {
        fprintf(stderr, "❌ 无法将时间转换为时间戳：非法日期（如2月30日）。\n");
        return -1;
    }

    struct timeval tv;
    tv.tv_sec = timestamp;
    tv.tv_usec = 0;

    if (settimeofday(&tv, NULL) == -1) {
        fprintf(stderr, "❌ settimeofday() 失败：errno=%d (%s)\n", errno, strerror(errno));
        return -1;
    }

    printf("✅ 系统时间成功设置为：%04d-%02d-%02d\n", year, month, day);
    return 0;
}

// 显示菜单
void show_menu() {
