        perror("Błąd podczas tworzenia socketu klienta");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Nieprawidłowy adres IP serwera\n");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    // Dane do wysłania – możesz zmienić w kodzie
    strcpy(message, "Jan Kowalski");

    printf("Wysyłanie danych: %s\n", message);

    // Wyślij dane do serwera
    if (sendto(client_fd, message, strlen(message), 0,
               (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Błąd podczas wysyłania");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    // Odbierz odpowiedź
    int len = sizeof(server_addr);
    int n = recvfrom(client_fd, response, BUFFER_SIZE - 1, 0,
                     (struct sockaddr *)&server_addr, &len);

