    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read <= 0) {
        perror("read");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    buffer[bytes_read] = '\0';
    printf("Otrzymano od serwera: %s\n", buffer);

    // Zamknięcie gniazda
    close(client_fd);

    return 0;
}
