```c
// encryption.c
#include "encryption.h"
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pkcs5.h>

// 从密码派生密钥（PBKDF2）
int derive_key(const char *password, const unsigned char *salt, int iterations,
                unsigned char *key, int key_len) {
    return PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), salt, SALT_SIZE,
                                    iterations, key_len, key);
}

// AES-256-CBC 加密
int encrypt_data(const unsigned char *plaintext, size_t plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char **ciphertext, size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return 0;

    int len = 0;
    int ciphertext_len = 0;

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto err;
    if (!EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) goto err;
    ciphertext_len += len;
    if (!EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len)) goto err;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    *ciphertext_len = ciphertext_len;
    return 1;

err:
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// AES-256-CBC 解密
int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char **plaintext, size_t *plaintext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return 0;

    int len = 0;
    int plaintext_len = 0;

    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto err;
    if (!EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) goto err;
    plaintext_len += len;
    if (!EVP_DecryptFinal_ex(ctx, *plaintext + len, &len)) goto err;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    *plaintext_len = plaintext_len;
    return 1;

err:
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// 生成随机盐值
void generate_salt(unsigned char *salt) {
    RAND_bytes(salt, SALT_SIZE);
}
