## 📚 主程序实现（diary.c）

```c
// diary.c
#include "diary.h"

DiarySystem system = {0};
PasswordData pwd_data;
FILE *diary_file = NULL;
const char *DATA_FILE = "diary.dat";
const char *PASS_FILE = "password.txt";

// 系统初始化
void initialize_system() {
    system.count = 0;
    system.sorted = 0;
    memset(&pwd_data, 0, sizeof(pwd_data));

    // 创建或加载密码文件
    FILE *fp = fopen(PASS_FILE, "r");
    if (!fp) {
        printf("首次运行，设置密码:\n");
        set_password();
        printf("密码已设置。\n");
    } else {
        fclose(fp);
    }

    // 加载日记
    load_diary();

    printf("日记系统已启动。\n");
}

// 加载加密日记
void load_diary() {
    diary_file = fopen(DATA_FILE, "rb");
    if (!diary_file) return;

    unsigned char header[16];
    fread(header, 1, 16, diary_file);

    // 检查魔数（防止损坏）
    if (memcmp(header, "DIARY_V1\0", 8) != 0) {
        fclose(diary_file);
        return;
    }

    unsigned char salt[SALT_SIZE];
    fread(salt, 1, SALT_SIZE, diary_file);

    unsigned char hash[32];
    fread(hash, 1, 32, diary_file);

    // 验证密码
    unsigned char derived_key[32];
    if (!derive_key("temp_pass", salt, 10000, derived_key, 32)) {
        fclose(diary_file);
        return;
    }

    if (memcmp(derived_key, hash, 32) != 0) {
        perror("密码验证失败");
        fclose(diary_file);
        return;
    }

    // 正式加载
    while (!feof(diary_file)) {
        unsigned char iv[IV_SIZE];
        if (fread(iv, 1, IV_SIZE, diary_file) != IV_SIZE) break;

        int entry_len;
        fread(&entry_len, 4, 1, diary_file);

        unsigned char *ciphertext = malloc(entry_len);
        if (fread(ciphertext, 1, entry_len, diary_file) != entry_len) {
            free(ciphertext);
            break;
        }

        unsigned char plaintext[2048];
        int plaintext_len;
        if (decrypt_data(ciphertext, entry_len, derived_key, iv, &plaintext, &plaintext_len)) {
            plaintext[plaintext_len] = '\0';

            // 解析 JSON 风格数据
            char *ptr = plaintext;
            if (sscanf(ptr, "%10s", system.entries[system.count].date) == 1) {
                ptr += 12;
                char *content = strchr(ptr, '\n');
                if (content) {
                    *content = '\0';
                    strncpy(system.entries[system.count].content, ptr, MAX_LINE_LENGTH * 2 - 1);
                    content++;
                    int k = 0;
                    while (k < MAX_KEYWORDS && (ptr = strtok(content, " \t\n")) != NULL) {
                        strncpy(system.entries[system.count].keywords[k++], ptr, MAX_KEY_LENGTH - 1);
                        content = NULL;
                    }
                    system.entries[system.count].keyword_count = k;
                    system.count++;
                }
            }
        }
        free(ciphertext);
        if (system.count >= MAX_RECORDS) break;
    }
    fclose(diary_file);
    system.sorted = 1;
}

// 保存日记
void save_diary() {
    FILE *fp = fopen(DATA_FILE, "wb");
    if (!fp) {
        perror("无法写入日记文件");
        return;
    }

    // 写入魔数
    fwrite("DIARY_V1\0", 1, 8, fp);

    // 写入盐值（仅保存原始 salt）
    fwrite(pwd_data.salt, 1, SALT_SIZE, fp);

    // 写入 hash（当前仅保存存储 hash，后续改用 derived key 加密）
    fwrite(pwd_data.hash, 1, 32, fp);

    // 写入所有条目
    for (int i = 0; i < system.count; i++) {
        unsigned char iv[IV_SIZE];
        RAND_bytes(iv, IV_SIZE);

        unsigned char plaintext[2048];
        int len = snprintf((char *)plaintext, sizeof(plaintext),
                           "%s\n%s", system.entries[i].date, system.entries[i].content);
        for (int j = 0; j < system.entries[i].keyword_count; j++) {
            len += snprintf((char *)(plaintext + len), sizeof(plaintext) - len, " %s", system.entries[i].keywords[j]);
        }

        unsigned char *ciphertext = NULL;
        size_t ciphertext_len = 0;
        unsigned char derived_key[32];
        derive_key("temp_pass", pwd_data.salt, 10000, derived_key, 32);

        if (encrypt_data(plaintext, strlen((char *)plaintext), derived_key, iv,
                         &ciphertext, &ciphertext_len)) {
            fwrite(iv, 1, IV_SIZE, fp);
            fwrite(&ciphertext_len, 4, 1, fp);
            fwrite(ciphertext, 1, ciphertext_len, fp);
            free(ciphertext);
        }
    }

    fclose(fp);
    printf("日记已保存。\n");
}

// 添加日记
void add_entry() {
    if (system.count >= MAX_RECORDS) {
        printf("日记已满，无法添加。\n");
        return;
    }

    DiaryEntry *e = &system.entries[system.count];
    system.sorted = 0;

    printf("输入日期 (YYYY-MM-DD): ");
    fgets(e->date, sizeof(e->date), stdin);
    e->date[strcspn(e->date, "\n")] = 0;

    if (strlen(e->date) != 10) {
        printf("无效日期格式。\n");
        return;
    }

    printf("输入内容: ");
    fgets(e->content, sizeof(e->content), stdin);
    e->content[strcspn(e->content, "\n")] = 0;

    printf("输入关键字 (空格分隔): ");
    char keywords_str[MAX_LINE_LENGTH];
    fgets(keywords_str, sizeof(keywords_str), stdin);
    keywords_str[strcspn(keywords_str, "\n")] = 0;

    char *token = strtok(keywords_str, " \t");
    e->keyword_count = 0;
    while (token && e->keyword_count < MAX_KEYWORDS) {
        strncpy(e->keywords[e->keyword_count++], token, MAX_KEY_LENGTH - 1);
        token = strtok(NULL, " \t");
    }

    system.count++;
    sort_entries_by_date();
    printf("日记已添加。\n");
}

// 修改日记
void modify_entry() {
    char date[11];
    printf("输入要修改的日期 (YYYY-MM-DD): ");
    fgets(date, sizeof(date), stdin);
    date[strcspn(date, "\n")] = 0;

    for (int i = 0; i < system.count; i++) {
        if (strcmp(system.entries[i].date, date) == 0) {
            printf("输入新内容: ");
            fgets(system.entries[i].content, sizeof(system.entries[i].content), stdin);
            system.entries[i].content[strcspn(system.entries[i].content, "\n")] = 0;

            printf("输入新关键字: ");
            char keywords_str[MAX_LINE_LENGTH];
            fgets(keywords_str, sizeof(keywords_str), stdin);
            keywords_str[strcspn(keywords_str, "\n")] = 0;
            char *token = strtok(keywords_str, " \t");
            system.entries[i].keyword_count = 0;
            while (token && system.entries[i].keyword_count < MAX_KEYWORDS) {
                strncpy(system.entries[i].keywords[system.entries[i].keyword_count++], token, MAX_KEY_LENGTH - 1);
                token = strtok(NULL, " \t");
            }

            sort_entries_by_date();
            printf("日记已更新。\n");
            return;
        }
    }
    printf("未找到该日期的日记。\n");
}

// 删除日记
void delete_entry() {
    char date[11];
    printf("输入要删除的日期 (YYYY-MM-DD): ");
    fgets(date, sizeof(date), stdin);
    date[strcspn(date, "\n")] = 0;

    for (int i = 0; i < system.count; i++) {
        if (strcmp(system.entries[i].date, date) == 0) {
            for (int j = i; j < system.count - 1; j++) {
                system.entries[j] = system.entries[j + 1];
            }
            system.count--;
            system.sorted = 0;
            printf("日记已删除。\n");
            return;
        }
    }
    printf("未找到该日期的日记。\n");
}

// 浏览日记（已按日期排序）
void browse_entries() {
    if (system.count == 0) {
        printf("暂无日记。\n");
        return;
    }

    if (!system.sorted) {
        sort_entries_by_date();
    }

    for (int i = 0; i < system.count; i++) {
        DiaryEntry *e = &system.entries[i];
        printf("\n=== %s ===\n", e->date);
        printf("内容: %s\n", e->content);
        printf("关键字: ");
        for (int j = 0; j < e->keyword_count; j++) {
            printf("%s ", e->keywords[j]);
        }
        printf("\n");
    }
}

// 按关键字搜索日记
void search_by_keyword() {
    char keyword[MAX_KEY_LENGTH];
    printf("输入关键字: ");
    fgets(keyword, sizeof(keyword), stdin);
    keyword[strcspn(keyword, "\n")] = 0;

    int found = 0;
    for (int i = 0; i < system.count; i++) {
        for (int j = 0; j < system.entries[i].keyword_count; j++) {
            if (strcmp(system.entries[i].keywords[j], keyword) == 0) {
                printf("\n[匹配] %s - %s\n", system.entries[i].date, system.entries[i].content);
                found = 1;
            }
        }
    }
    if (!found) {
        printf("未找到包含该关键字的日记。\n");
    }
}

// 设置密码（首次启动）
void set_password() {
    char password[MAX_PASSWORD_LENGTH];
    char confirm[MAX_PASSWORD_LENGTH];

    printf("请输入新密码: ");
    fgets(password, sizeof(password), stdin);
    password[strcspn(password, "\n")] = 0;

    printf("请确认密码: ");
    fgets(confirm, sizeof(confirm), stdin);
    confirm[strcspn(confirm, "\n")] = 0;

    if (strcmp(password, confirm) != 0) {
        printf("密码不一致。\n");
        exit(1);
    }

    generate_salt(pwd_data.salt);
    unsigned char derived_key[32];
    if (!derive_key(password, pwd_data.salt, 10000, derived_key, 32)) {
        perror("密钥派生失败");
        exit(1);
    }

    memcpy(pwd_data.hash, derived_key, 32);

    FILE *fp = fopen(PASS_FILE, "w");
    if (!fp) {
        perror("无法写入密码文件");
        exit(1);
    }
    fwrite(pwd_data.salt, 1, SALT_SIZE, fp);
    fwrite(pwd_data.hash, 1, 32, fp);
    fclose(fp);

    // 设置文件权限为私有（仅用户可读写）
    chmod(PASS_FILE, 0600);
    chmod(DATA_FILE, 0600);

    printf("密码已设置，文件已加密存储。\n");
}

// 修改密码
void change_password() {
    char old_password[MAX_PASSWORD_LENGTH];
    char new_password[MAX_PASSWORD_LENGTH];
    char confirm[MAX_PASSWORD_LENGTH];

    printf("请输入当前密码: ");
    fgets(old_password, sizeof(old_password), stdin);
    old_password[strcspn(old_password, "\n")] = 0;

    unsigned char derived_key[32];
    if (!derive_key(old_password, pwd_data.salt, 10000, derived_key, 32)) {
        printf("密码错误。\n");
        return;
    }

    if (memcmp(derived_key, pwd_data.hash, 32) != 0) {
        printf("密码不正确。\n");
        return;
    }

    printf("请输入新密码: ");
    fgets(new_password, sizeof(new_password), stdin);
    new_password[strcspn(new_password, "\n")] = 0;

    printf("请确认新密码: ");
    fgets(confirm, sizeof(confirm), stdin);
    confirm[strcspn(confirm, "\n")] = 0;

    if (strcmp(new_password, confirm) != 0) {
        printf("密码不一致。\n");
        return;
    }

    // 重新派生新密码
    unsigned char new_hash[32];
    derive_key(new_password, pwd_data.salt, 10000, new_hash, 32);

    memcpy(pwd_data.hash, new_hash, 32);

    FILE *fp = fopen(PASS_FILE, "w");
    if (!fp) {
        perror("无法写入密码文件");
        return;
    }

    fwrite(pwd_data.salt, 1, SALT_SIZE, fp);
    fwrite(pwd_data.hash, 1, 32, fp);
    fclose(fp);

    printf("密码已修改。\n");
}

// 日期比较（用于 qsort）
int compare_dates(const void *a, const void *b) {
    const DiaryEntry *e1 = (const DiaryEntry *)a;
    const DiaryEntry *e2 = (const DiaryEntry *)b;
    return strcmp(e1->date, e2->date);
}

// 排序日记（按日期升序）
void sort_entries_by_date() {
    qsort(system.entries, system.count, sizeof(DiaryEntry), compare_dates);
    system.sorted = 1;
}

// 清除内存敏感数据
void secure_zero_memory(void *ptr, size_t len) {
    volatile char *p = ptr;
    while (len--) *p++ = 0;
}

// 主菜单
void display_menu() {
    printf("\n====== 日记管理系统 ======\n");
    printf("1. 添加日记\n");
    printf("2. 修改日记\n");
