            if (should_swap) {
                Product t = temp_products[j];
                temp_products[j] = temp_products[j + 1];
                temp_products[j + 1] = t;
            }
        }
    }

    if (choice == 1 || choice == 2) {
        printf("\n--- 统计结果（按 %s 降序）---\n", choice == 1 ? "价格" : "库存");
