#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 256  // 最大字符串长度（防溢出）

// 通用字符排序函数（升序，按 ASCII）
void sort_string(char *str, int len) {
    for (int i = 0; i < len - 1; i++) {
        for (int j = i + 1; j < len; j++) {
            if (str[i] > str[j]) {
                char temp = str[i];
                str[i] = str[j];
                str[j] = temp;
            }
        }
    }
}

// 删除重复字符（基于已排序字符串）
int remove_duplicates(char *str, int len) {
    if (len == 0) return 0;

    int write_idx = 1;  // 当前写入位置
    for (int read_idx = 1; read_idx < len; read_idx++) {
        if (str[read_idx] != str[read_idx - 1]) {
            str[write_idx++] = str[read_idx];
        }
    }
    return write_idx;  // 返回唯一字符数量
}

// 安全地读取字符串（含长度限制）
int safe_gets(char *buf, int size) {
    if (fgets(buf, size, stdin) == NULL) {
        fprintf(stderr, "[ERROR] Failed to read input.\n");
        return -1;
    }

    // 移除换行符（如果存在）
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
        len--;
    }

    // 检查是否输入过长（防缓冲区溢出）
    if (len == size - 1) {
        fprintf(stderr, "[WARNING] Input too long, truncated.\n");
    }

    return len;
}

int main() {
    char str1[MAX_LEN], str2[MAX_LEN];
    char *merged;

    printf("请输入第一个字符串: ");
    int len1 = safe_gets(str1, MAX_LEN);
    if (len1 < 0) {
        return -1;
    }

    printf("请输入第二个字符串: ");
    int len2 = safe_gets(str2, MAX_LEN);
    if (len2 < 0) {
        return -1;
    }

    // 合并长度：两个字符串加终止符
    int total_len = len1 + len2 + 1;
    merged = (char *)calloc(total_len, sizeof(char));
    if (merged == NULL) {
        fprintf(stderr, "[ERROR] Memory allocation failed.\n");
        return -1;
    }

    // 合并字符串
    strcpy(merged, str1);
    strcat(merged, str2);

    // 步骤1: 分别对两个原始字符串排序（仅排序原串，不是合并后的）
    sort_string(str1, len1);
    sort_string(str2, len2);

    // 步骤2: 合并后整体排序
    sort_string(merged, len1 + len2);

    // 步骤3: 删除重复字符（合并后已排序，只需去重）
    int unique_len = remove_duplicates(merged, len1 + len2);

    // 输出结果
    printf("\n--- 结果 ---\n");
    printf("第一个字符串排序后: %s\n", str1);
    printf("第二个字符串排序后: %s\n", str2);
    printf("合并后并去重: %.*s\n", unique_len, merged);

    // 清理
    free(merged);
    return 0;
}
```

