// Function to parse a point string of the form "(fx, fy)"
int parse_point(const char *line, double *x, double *y) {
    // Regex pattern: ^\(([-+]?\d*\.?\d+),\s*([-+]?\d*\.?\d+)\)$
    // Matches: (12.34, -5.67), (0, 0), (-1.5, 2), etc.
    regex_t regex;
    int ret;
    regmatch_t matches[3];  // One for whole match, two for groups

    // Compile regex: ^\(([-+]?\d*\.?\d+),\s*([-+]?\d*\.?\d+)\)$
    ret = regcomp(&regex, "^\\((-?\\d*\\.?\\d+),\\s*(-?\\d*\\.?\\d+)\\)$", REG_EXTENDED);
    if (ret != 0) {
        return 0;  // Compilation failed
    }

    ret = regexec(&regex, line, 3, matches, 0);
    regfree(&regex);

    if (ret != 0) {
        return 0;  // No match
    }

    // Extract captured groups
    char x_str[256], y_str[256];
    strncpy(x_str, line + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so);
