    // Formula: Area = |(x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2)) / 2|
    double area = (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0;
    return fabs(area);
