bool safe_atoi(const char *str, long *result) {
    char *endptr;
    errno = 0;

    *result = strtol(str, &endptr, 10);

    // Check for conversion errors
    if (errno == ERANGE) {
        fprintf(stderr, "Error: Number is too large or too small to fit in a long.\n");
        return false;
    }

    // Check if entire string was consumed (no trailing characters)
