        return false;
    }

    // Optional: Check if the number is within a reasonable range
    // to avoid excessive computation (e.g., > 10^18 is impractical)
    if (*result > 1000000000000000000L) {
        fprintf(stderr, "Error: Number is too large (exceeds safe computation limits).\n");
        return false;
    }

