#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Structure d'un nœud de la liste
typedef struct Noeud {
    char* mot;
    struct Noeud* precedent;
    struct Noeud* suivant;
} Noeud;

// Structure de la liste
typedef struct Liste {
    Noeud* debut;
    Noeud* fin;
    int taille;
} Liste;
```

---

### ✅ Fonction `ajoutMOT` : Ajout en ordre alphabétique

```c
// Fonction d'ajout d'un mot dans la liste triée (ordre alphabétique)
int ajoutMOT(Liste* liste, const char* mot) {
    // Vérification des paramètres d'entrée
    if (!liste || !mot) {
        fprintf(stderr, "[ERREUR] Paramètre invalide : liste ou mot null.\n");
        return -1; // Échec
    }

    // Copie du mot pour éviter le pointeur vers une chaîne temporaire
    char* copie_mot = strdup(mot);
    if (!copie_mot) {
        fprintf(stderr, "[ERREUR] Échec de l'allocation mémoire pour le mot.\n");
        return -1; // Échec
    }

    // Créer le nouvel nœud
    Noeud* nouveau = (Noeud*)malloc(sizeof(Noeud));
    if (!nouveau) {
        fprintf(stderr, "[ERREUR] Échec de l'allocation mémoire pour le nœud.\n");
        free(copie_mot); // Nettoyage en cas d'échec
        return -1;
    }

    nouveau->mot = copie_mot;
    nouveau->precedent = NULL;
    nouveau->suivant = NULL;

    // Cas 1 : Liste vide
    if (!liste->debut) {
        liste->debut = nouveau;
        liste->fin = nouveau;
        liste->taille = 1;
        return 0; // Succès
    }

    // Cas 2 : Insérer au début (le mot est plus petit que le premier)
    int comparaison = strcasecmp(nouveau->mot, liste->debut->mot);
    if (comparaison < 0) {
        nouveau->suivant = liste->debut;
        liste->debut->precedent = nouveau;
        liste->debut = nouveau;
        liste->taille++;
        return 0;
    }

    // Cas 3 : Insérer au milieu ou à la fin
    Noeud* courant = liste->debut;
    while (courant->suivant && strcasecmp(nouveau->mot, courant->suivant->mot) > 0) {
        courant = courant->suivant;
    }

    // Insérer après courant
    nouveau->suivant = courant->suivant;
    nouveau->precedent = courant;

    if (courant->suivant) {
        courant->suivant->precedent = nouveau;
    } else {
        // Si courant est la dernière, on met à jour la fin
        liste->fin = nouveau;
    }

    courant->suivant = nouveau;
    liste->taille++;

    return 0; // Succès
}
```

---

### 🛡️ Sécurité & Bonnes Pratiques Appliquées

- ✅ **Vérification des pointeurs** (`liste`, `mot`) → évite le *null pointer dereference*.
- ✅ **Copie du mot** via `strdup` → évite les pointeurs vers des chaînes temporaires.
- ✅ **Gestion des erreurs d’allocation mémoire** → libération en cas d’échec.
