#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#define MAX_NODES 30
#define MAX_EDGES 1000
#define UNVISITED -1
#define VISITING -2
#define VISITED 1

int N; // number of nodes
int adj[MAX_NODES][MAX_NODES];   // adjacency matrix
bool is_cycle_node[MAX_NODES];   // is this node in a cycle?
bool reachable[MAX_NODES][MAX_NODES]; // reachable[i][j] = true if j reachable from i

// DFS to detect cycles (back edge)
int visited[MAX_NODES];
int dfs_time = 0;
int rec_stack[MAX_NODES];  // for recursion stack
int rec_stack_size = 0;

void dfs_cycle(int u) {
    visited[u] = VISITING;
    rec_stack[rec_stack_size++] = u;

    for (int v = 0; v < N; v++) {
        if (adj[u][v]) {
            if (visited[v] == VISITING) {
                // Found back edge → cycle
                for (int i = 0; i < rec_stack_size; i++) {
                    if (rec_stack[i] == v) {
                        // Mark all nodes from v onwards in recursion stack as in cycle
                        for (int j = i; j < rec_stack_size; j++) {
                            is_cycle_node[rec_stack[j]] = true;
                        }
                    }
                }
            } else if (visited[v] == UNVISITED) {
                dfs_cycle(v);
            }
        }
    }

    rec_stack_size--;
    visited[u] = VISITED;
}

// BFS to compute reachability
void bfs_reachable(int start) {
    bool in_queue[MAX_NODES] = {0};
    int queue[MAX_NODES];
    int front = 0, rear = 0;

    queue[rear++] = start;
    in_queue[start] = true;

    while (front < rear) {
        int u = queue[front++];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && !in_queue[v]) {
                in_queue[v] = true;
                queue[rear++] = v;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        reachable[start][i] = in_queue[i];
    }
}

// Check if path from i to j goes through cycle
bool goes_through_cycle(int i, int j) {
    if (!reachable[i][j]) return false;

    // If any node on the path from i to j is a cycle node?
    // We use BFS from i to see if we can reach j through a cycle node
    bool seen[MAX_NODES] = {0};
    int q[MAX_NODES];
    int f = 0, r = 0;

    for (int k = 0; k < N; k++) {
        if (is_cycle_node[k]) {
            if (reachable[i][k] && reachable[k][j]) {
                return true;
            }
        }
    }
    return false;
}

// Count number of simple paths from i to j in DAG using topo + DP
int count_paths_dag(int i, int j) {
    // Find all nodes reachable from i
    bool in_component[MAX_NODES] = {0};
    int queue[MAX_NODES];
    int front = 0, rear = 0;
    queue[rear++] = i;
    in_component[i] = true;

    while (front < rear) {
        int u = queue[front++];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && !in_component[v]) {
                if (reachable[i][v]) { // only in component reachable from i
                    in_component[v] = true;
                    queue[rear++] = v;
                }
            }
        }
    }

    // Now build the DAG subgraph: only nodes in_component, and edges with both ends in
    int nodes[MAX_NODES];
    int node_count = 0;
    for (int k = 0; k < N; k++) {
        if (in_component[k]) {
            nodes[node_count++] = k;
        }
    }

    // Create local indegree and adjacency for DAG
    int indegree[MAX_NODES] = {0};
    int local_adj[MAX_NODES][MAX_NODES] = {0};

    for (int k = 0; k < node_count; k++) {
        int u = nodes[k];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && in_component[v]) {
                local_adj[k][v] = 1;
                indegree[k]++; // no, indegree per v
            }
        }
    }

    // Recompute indegree for nodes
    int deg[MAX_NODES] = {0};
    for (int k = 0; k < node_count; k++) {
        int u = nodes[k];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && in_component[v]) {
                int idx_v = -1;
                for (int w = 0; w < node_count; w++) {
                    if (nodes[w] == v) {
                        idx_v = w;
                        break;
                    }
                }
                if (idx_v != -1) {
                    deg[idx_v]++;
                }
            }
        }
    }

    // Topological sort
    int topo[MAX_NODES];
    int t_count = 0;
    int q2[MAX_NODES];
    int f2 = 0, r2 = 0;

    for (int k = 0; k < node_count; k++) {
        int u = nodes[k];
        if (deg[k] == 0) {
            q2[r2++] = k;
        }
    }

    while (f2 < r2) {
        int u_idx = q2[f2++];
        topo[t_count++] = u_idx;
        int u = nodes[u_idx];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && in_component[v]) {
                int v_idx = -1;
                for (int w = 0; w < node_count; w++) {
                    if (nodes[w] == v) {
                        v_idx = w;
                        break;
                    }
                }
                if (v_idx != -1) {
                    deg[v_idx]--;
                    if (deg[v_idx] == 0) {
                        q2[r2++] = v_idx;
                    }
                }
            }
        }
    }

    // DP: dp[i] = number of paths from nodes[i] to j
    int dp[MAX_NODES] = {0};
    int target_idx = -1;
    for (int k = 0; k < node_count; k++) {
        if (nodes[k] == j) {
            target_idx = k;
            dp[k] = 1;
            break;
        }
    }

    if (target_idx == -1) return 0;

    // Process in reverse topological order
    for (int i = t_count - 1; i >= 0; i--) {
        int u_idx = topo[i];
        int u = nodes[u_idx];
        for (int v = 0; v < N; v++) {
            if (adj[u][v] && in_component[v]) {
                int v_idx = -1;
                for (int w = 0; w < node_count; w++) {
                    if (nodes[w] == v) {
                        v_idx = w;
                        break;
                    }
                }
                if (v_idx != -1) {
                    dp[u_idx] += dp[v_idx];
                }
            }
        }
    }

    // Find dp index for i
    for (int k = 0; k < node_count; k++) {
        if (nodes[k] == i) {
            return dp[k];
        }
    }
    return 0;
}

// Read input
int read_city(int case_num) {
    int M;
    if (scanf("%d", &M) != 1) return 0;

    // Initialize
    memset(adj, 0, sizeof(adj));
    memset(reachable, 0, sizeof(reachable));
    memset(is_cycle_node, 0, sizeof(is_cycle_node));
    N = 0;

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u][v] = 1;
        if (u > N) N = u;
        if (v > N) N = v;
    }
    N += 1; // nodes from 0 to N-1

    // Step 1: detect cycle nodes
    memset(visited, UNVISITED, sizeof(visited));
    for (int i = 0; i < N; i++) {
        if (visited[i] == UNVISITED) {
            dfs_cycle(i);
        }
    }

    // Step 2: compute reachability
    for (int i = 0; i < N; i++) {
        bfs_reachable(i);
    }

    // Output matrix
    printf("matrix for city %d\n", case_num);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (!reachable[i][j]) {
                printf("0");
            } else if (goes_through_cycle(i, j)) {
                printf("-1");
            } else {
                // Count simple paths in DAG
                int cnt = count_paths_dag(i, j);
                printf("%d", cnt);
            }
            if (j < N - 1) printf(" ");
        }
        printf("\n");
    }

    return 1;
}

int main() {
    int case_num = 0;
    while (read_city(case_num)) {
        case_num++;
    }
    return 0;
}
