        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    printf("Các số nguyên tố <= %d:\n", n);
    int count = 0;
    for (int i = 2; i <= n; i++) {
        if (isPrime[i]) {
            printf("%d ", i);
            count++;
            if (count % 10 == 0) printf("\n");
        }
    }
    printf("\nTổng cộng: %d số nguyên tố.\n", count);

    free(isPrime);
}
```

