// Синхронизация: мьютекс для записи
HANDLE hMutexWrite = NULL;

// Функция загрузки данных из файла
bool LoadEmployees() {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cout << "Файл " << filename << " не найден. Создаём новый." << std::endl;
        // Создаём файл с примерами
        std::ofstream create_file(filename, std::ios::binary);
