        employee e2 = {2, "Petr", 38.0};
        employee e3 = {3, "Anna", 42.0};
        create_file.write((char*)&e1, sizeof(e1));
        create_file.write((char*)&e2, sizeof(e2));
        create_file.write((char*)&e3, sizeof(e3));
        create_file.close();
        return false;
    }

    employees.clear();
    employee emp;
    while (file.read((char*)&emp, sizeof(emp))) {
        employees.push_back(emp);
    }
    file.close();

    std::cout << "\n=== Данные из файла ===\n";
    for (const auto& e : employees) {
        std::cout << "ID: " << e.num << ", Имя: " << e.name << ", Часы: " << e.hours << std::endl;
    }
    return true;
}

// Функция сохранения в файл
