        // Запись: копируем данные
        memcpy(buffer + 5, data, sizeof(employee));
    }

    DWORD bytesWritten;
    if (!WriteFile(hPipe, buffer, 5 + (op == 1 ? sizeof(employee) : 0), &bytesWritten, NULL)) {
        std::cerr << "Ошибка отправки запроса" << std::endl;
        CloseHandle(hPipe);
        return false;
    }

