### 1️⃣ 内核模块（`mmap_kern.c`）

```c
// mmap_kern.c
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/mm.h>
#include <linux/slab.h>
#include <linux/ioctl.h>

#define DEVICE_NAME "mmap_dev"
#define MAGIC 'm'
#define IOCTL_MMAP _IOR(MAGIC, 0, unsigned long)

static struct class *mmap_class;
static struct device *mmap_device;
static void *shared_buffer;
static size_t buffer_size = 4096;

static int mmap_open(struct inode *inode, struct file *file) {
    return 0;
}

static int mmap_release(struct inode *inode, struct file *file) {
    return 0;
}

// 提供 mmap 映射处理函数
static int mmap_mmap(struct file *file, struct vm_area_struct *vma) {
    unsigned long size = vma->vm_end - vma->vm_start;

    if (size > buffer_size) {
        printk(KERN_ERR "mmap: requested size too large\n");
        return -EINVAL;
    }

    // 映射物理页 —— 保留用户页以供共享
    if (remap_pfn_range(vma, vma->vm_start, virt_to_phys(shared_buffer) >> PAGE_SHIFT,
                        size, vma->vm_page_prot)) {
        printk(KERN_ERR "mmap: remap_pfn_range failed\n");
        return -EAGAIN;
    }

    // 清除 VM_LOCKED 以避免页面锁死（安全考虑）
    vma->vm_flags &= ~VM_LOCKED;
    vma->vm_flags |= VM_DONTEXPAND | VM_DONTDUMP;

    printk(KERN_INFO "mmap: successfully mapped %zu bytes at %p\n", size, shared_buffer);

    return 0;
}

// ioctl 处理：通知内核准备映射
static long mmap_ioctl(struct file *file, unsigned int cmd, unsigned long arg) {
    switch (cmd) {
    case IOCTL_MMAP:
        printk(KERN_INFO "ioctl: mmap requested via ioctl\n");
        return 0;
    default:
        return -ENOTTY;
    }
}

static struct file_operations fops = {
    .open = mmap_open,
    .release = mmap_release,
    .unlocked_ioctl = mmap_ioctl,
    .mmap = mmap_mmap,
};

static int __init mmap_init(void) {
    int major;
    dev_t devno;

    // 分配设备号
    major = register_chrdev(0, DEVICE_NAME, &fops);
    if (major < 0) {
        printk(KERN_ERR "mmap: failed to register device\n");
        return major;
    }

    // 创建 class 与 device
    mmap_class = class_create(THIS_MODULE, DEVICE_NAME);
    if (IS_ERR(mmap_class)) {
        unregister_chrdev(major, DEVICE_NAME);
        return PTR_ERR(mmap_class);
    }

    devno = MKDEV(major, 0);
    mmap_device = device_create(mmap_class, NULL, devno, NULL, DEVICE_NAME);
    if (IS_ERR(mmap_device)) {
        class_destroy(mmap_class);
        unregister_chrdev(major, DEVICE_NAME);
        return PTR_ERR(mmap_device);
    }

    // 分配共享内存
    shared_buffer = kmalloc(buffer_size, GFP_KERNEL);
    if (!shared_buffer) {
        device_destroy(mmap_class, devno);
        class_destroy(mmap_class);
        unregister_chrdev(major, DEVICE_NAME);
        return -ENOMEM;
    }

    memset(shared_buffer, 0, buffer_size);
    printk(KERN_INFO "mmap: kernel module loaded. Shared buffer at %p\n", shared_buffer);
    return 0;
}

static void __exit mmap_exit(void) {
    device_destroy(mmap_class, MKDEV(0, 0));
    class_destroy(mmap_class);
    unregister_chrdev(major, DEVICE_NAME);
    kfree(shared_buffer);
    printk(KERN_INFO "mmap: module unloaded\n");
}

module_init(mmap_init);
module_exit(mmap_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Security Researcher");
MODULE_DESCRIPTION("Example: Userspace-Kernel mmap communication via ioctl");
```

