### 2️⃣ 用户空间测试程序（`mmap_user.c`）

```c
// mmap_user.c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <string.h>
#include <errno.h>

#define DEVICE_PATH "/dev/mmap_dev"
#define MAGIC 'm'
#define IOCTL_MMAP _IOR(MAGIC, 0, unsigned long)

int main(void) {
    int fd;
    void *mapped_addr;
    size_t size = 4096;

    // 打开设备节点
    fd = open(DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // 向内核发送 ioctl 通知映射
    if (ioctl(fd, IOCTL_MMAP, 0) < 0) {
        perror("ioctl");
        close(fd);
        exit(1);
    }

    // 执行 mmap 映射
    mapped_addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_addr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(1);
    }

    // 写入测试数据
    memset(mapped_addr, 'A', 100);
    printf("Wrote 'A' to shared memory: %.*s\n", 100, (char *)mapped_addr);

    // 读取验证
    printf("Read back: %.*s\n", 100, (char *)mapped_addr);

    // 同步并释放
    msync(mapped_addr, size, MS_SYNC);
    munmap(mapped_addr, size);
    close(fd);

    printf("Mmap communication completed successfully.\n");
    return 0;
}
```

