#define PORT         8080
#define MAX_CLIENTS  100
#define BUFFER_SIZE  1024

// Функция для установки сокета в неблокирующий режим
void set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags == -1) {
        perror("fcntl GETFL");
        exit(EXIT_FAILURE);
    }
    if (fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) {
        perror("fcntl SETFL");
        exit(EXIT_FAILURE);
    }
}

