    if (listen(server_fd, 10) == -1) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Сервер запущен на порту %d. Ожидание подключений...\n", PORT);

    // Массив дескрипторов клиентов
    int client_fds[MAX_CLIENTS];
    int client_count = 0;

    // Инициализация массива клиентов пустыми значениями
