    while (1) {
        // Копируем исходные наборы дескрипторов для select
        FD_ZERO(&read_fds);
        FD_ZERO(&write_fds);

        // Добавляем серверный сокет в набор чтения
        FD_SET(server_fd, &read_fds);

        // Добавляем клиентские сокеты в набор чтения и записи
        for (int i = 0; i < client_count; i++) {
            if (client_fds[i] != -1) {
                FD_SET(client_fds[i], &read_fds);
                FD_SET(client_fds[i], &write_fds);  // Запись тоже проверяем, но не обязательно
                if (client_fds[i] > max_fd) {
                    max_fd = client_fds[i];
                }
            }
        }

        // Ожидание событий
        int activity = select(max_fd + 1, &read_fds, &write_fds, NULL, NULL);
        if (activity < 0) {
            perror("select");
            continue;
        }

        // Проверяем, есть ли новое подключение на серверном сокете
        if (FD_ISSET(server_fd, &read_fds)) {
            client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
            if (client_fd == -1) {
                perror("accept");
                continue;
            }

            // Устанавливаем неблокирующий режим
            set_nonblocking(client_fd);

            // Добавляем клиента в массив
            bool found = false;
            for (int i = 0; i < MAX_CLIENTS; i++) {
                if (client_fds[i] == -1) {
                    client_fds[i] = client_fd;
                    client_count++;
                    printf("Новое подключение от %s:%d (fd=%d)\n", 
                           inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port), client_fd);
                    found = true;
                    break;
                }
            }

            if (!found) {
                fprintf(stderr, "Превышено максимальное количество клиентов (%d)\n", MAX_CLIENTS);
                close(client_fd);
            }
        }

        // Обрабатываем данные от клиентов
        for (int i = 0; i < client_count; i++) {
            int fd = client_fds[i];
            if (fd == -1) continue;

            if (FD_ISSET(fd, &read_fds)) {
                char buffer[BUFFER_SIZE];
                ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE - 1);
                if (bytes_read == 0) {
                    // Клиент отключился
                    printf("Клиент (fd=%d) отключился\n", fd);
                    close(fd);
                    client_fds[i] = -1;
                } else if (bytes_read > 0) {
                    buffer[bytes_read] = '\0';
                    printf("Получено от клиента (fd=%d): %s", fd, buffer);

                    // Отправляем обратно
                    if (write(fd, buffer, bytes_read) < 0) {
                        fprintf(stderr, "Ошибка записи на fd=%d\n", fd);
                        close(fd);
                        client_fds[i] = -1;
                    }
                } else {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        fprintf(stderr, "Ошибка чтения с fd=%d: %s\n", fd, strerror(errno));
                        close(fd);
                        client_fds[i] = -1;
                    }
                }
            }
        }
    }

    // Не достигается в нормальном потоке, но для безопасности
    close(server_fd);
    return 0;
}
