// 判断是否为闰年
int is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 获取某年某月的天数
int days_in_month(int year, int month) {
    if (month < 1 || month > 12) return 0;
    int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && is_leap_year(year)) {
        return 29;
    }
    return days[month];
}

// 打印日期（YYYY-MM-DD 格式）
void print_date(int year, int month, int day) {
    printf("%04d-%02d-%02d", year, month, day);
}

// 验证日期是否合法
int valid_date(int year, int month, int day) {
    if (year < MIN_YEAR || year > MAX_YEAR) return 0;
    if (month < 1 || month > 12) return 0;
    if (day < 1 || day > days_in_month(year, month)) return 0;
    return 1;
}

// 处理日期增减（支持 ±年/±月/±日）
void adjust_date(int *year, int *month, int *day, int mode) {
    int old_year = *year;
    int old_month = *month;
    int old_day = *day;

    // 使用 long 防止溢出
    long y = (long)*year;
    long m = (long)*month;
    long d = (long)*day;

    switch (mode) {
        case 1: // 增加年
            if (y + 1 > MAX_YEAR) {
                printf("警告：年份已达到最大值 %d，无法增加。\n", MAX_YEAR);
                return;
            }
            y += 1;
            break;
        case 2: // 减少年
            if (y - 1 < MIN_YEAR) {
                printf("警告：年份已达到最小值 %d，无法减少。\n", MIN_YEAR);
                return;
            }
            y -= 1;
            break;
        case 3: // 增加月
            if (m + 1 > 12) {
                y += 1;
                m = 1;
            } else {
                m += 1;
            }
            break;
        case 4: // 减少月
            if (m - 1 < 1) {
                y -= 1;
                m = 12;
            } else {
                m -= 1;
            }
            break;
        case 5: // 增加日
            if (d + 1 > days_in_month(y, m)) {
                // 跨日
                d = 1;
                if (m == 12) {
                    m = 1;
                    y += 1;
                } else {
                    m += 1;
                }
            } else {
                d += 1;
            }
            break;
        case 6: // 减少日
            if (d - 1 < 1) {
                // 跨日
                if (m == 1) {
                    m = 12;
                    y -= 1;
                } else {
                    m -= 1;
                }
                d = days_in_month(y, m);
            } else {
                d -= 1;
            }
            break;
        default:
            return;
    }

    // 溢出保护
    if (y < MIN_YEAR || y > MAX_YEAR) {
        printf("日期调整导致年份超出范围 %d~%d，已恢复。\n", MIN_YEAR, MAX_YEAR);
        *year = old_year;
        *month = old_month;
        *day = old_day;
        return;
    }

    *year = (int)y;
    *month = (int)m;
    *day = (int)d;

    printf("日期已成功调整。\n");
}

// 重置为初始时间
void reset_date(int *year, int *month, int *day, int init_year, int init_month, int init_day) {
    *year = init_year;
    *month = init_month;
    *day = init_day;
    printf("已重置为初始时间 %d-%02d-%02d。\n", init_year, init_month, init_day);
}

// 显示菜单
void display_menu() {
    printf("\n=== 菜单 ===\n");
    printf("1. 增加年份\n");
    printf("2. 减少年份\n");
    printf("3. 增加月份\n");
    printf("4. 减少月份\n");
    printf("5. 增加日期\n");
    printf("6. 减少日期\n");
    printf("7. 重置为初始时间\n");
    printf("8. 退出程序（实际是循环中断）\n");
}
