int isValidInput(const char *str, int *n) {
    if (str == NULL || *str == '\0') return 0;

    int i = 0;
    while (str[i] != '\0') {
        if (!isdigit(str[i])) return 0;
        i++;
    }

    *n = atoi(str);
    if (*n < 1) return 0;
    if (*n > 22) { // Безопасная граница: F(22) = 3 * 21! ~ 5.1e19 > 2^64
        return 0;
    }
    return 1;
}

// Вычисление F(n) = 3 * (n-1)!
unsigned long long F(int n) {
    if (n == 1) return 3;

    unsigned long long result = 3; // F(1) = 3
    for (int i = 2; i <= n; i++) {
        result *= (i - 1);
        // Проверка на переполнение
        if (result == 0) {
            fprintf(stderr, "Error: Overflow detected at F(%d)\n", i);
            exit(1);
        }
    }
    return result;
}

int main() {
