    char input[10];

    sem1 = sem_open(SEM1_NAME, O_CREAT, 0666, 1);
    sem2 = sem_open(SEM2_NAME, O_CREAT, 0666, 1);

    if (sem1 == SEM_FAILED || sem2 == SEM_FAILED) {
        perror("sem_open failed");
        exit(1);
    }

    printf("=== Deadlock Demo: Instancja %d ===\n", getpid());
    printf("1 -> zablokuj sem1, potem sem2\n");
    printf("2 -> zablokuj sem2, potem sem1\n");
    printf("Wciśnij: ");

