        if (input[0] == '1') {
            printf("Instancja %d: Zajmuję sem1...\n", getpid());
            sem_wait(sem1);

            printf("Instancja %d: Zajmuję sem2...\n", getpid());
            sem_wait(sem2);

            printf("Instancja %d: Wszystko zablokowane!\n", getpid());
            sleep(5); // symulacja pracy
            printf("Od blokowania: sem2 -> sem1...\n");

            sem_post(sem2);
            sem_post(sem1);
            printf("Zwolnione oba semafory.\n");
