            sem_wait(sem1);

            printf("Instancja %d: Udało się! (nie powinno sie wydarzyć)\n", getpid());
            sleep(5);

            sem_post(sem1);
            sem_post(sem2);
            printf("Zwolnione oba semafory.\n");
        }
        else {
            printf("Użyj: 1 lub 2\n");
        }

        printf("Wciśnij: ");
    }

    sem_close(sem1);
    sem_close(sem2);
    sem_unlink(SEM1_NAME);
    sem_unlink(SEM2_NAME);

    return 0;
}
```

