## 📄 3. `main.c` —— 安全增强型 WebSocket 客户端

```c
// main.c
#define LWS_PLUGIN_STATIC
#include <libwebsockets.h>
#include <libuv.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// 固定配置
#define WS_URI "wss://echo.websocket.org"  // 测试用（真实场景替换）
// #定义为可从环境变量获取，防止硬编码
#define CONNECT_TIMEOUT_SEC 10
#define PING_INTERVAL_SEC 30

// 全局状态结构
struct client_data {
    struct lws *wsi;
    uv_timer_t timer;
    int connected;
    char *url;
    int close_reason;
};

static void on_timeout(uv_timer_t* handle);
static int callback_webkit(struct lws *wsi, enum lws_callback_reasons reason,
                          void *user, void *in, size_t len);

// 安全函数：验证服务器证书（生产环境应加载可信CA，禁用证书验证仅用于测试）
static int verify_certificate_callback(const char *cert_pem, const char *hostname, int verify_depth) {
    // 【安全研究重点】
    // 实际场景中：应该检查 cert_chain 有效性，签名是否由可信 CA 签发
    // 此处仅为演示，建议在正式部署中启用完整链验证

    printf("[Security] Validating certificate for host: %s\n", hostname);

    // 基础检查：不可信证书拒绝
    if (!cert_pem || strlen(cert_pem) == 0) {
        fprintf(stderr, "[SECURITY ERROR] Empty certificate received.\n");
        return 1;
    }

    // 严禁在生产环境中使用以下行！
    // return 0; // <-- 允许任何证书（仅限测试）
    // 正确做法：使用 CA bundle 进行验证

    return 0; // 临时允许（示例用）
}

// === 重要：自定义认证逻辑（模拟 JWT Token 握手阶段）===
static int add_auth_headers(struct lws *wsi, void *user, const char *path) {
    // 可在握手前添加认证头（防御未授权访问）
    const char *auth_token = getenv("WS_AUTH_TOKEN"); // 从环境变量读取，避免硬编码

    if (auth_token && strlen(auth_token) > 0) {
        lws_add_http_header_by_name(wsi, "Authorization",
                                  (unsigned char*)auth_token, strlen(auth_token));
        printf("[Auth] Added token header: %s\n", auth_token);
    } else {
        fprintf(stderr, "[WARNING] No auth token provided. Consider setting WS_AUTH_TOKEN.\n");
    }
    return 0;
}

// 定时器：发送心跳（防止连接被中间设备断开）
static void on_timeout(uv_timer_t* handle) {
    struct client_data *data = (struct client_data*)handle->data;

    if (data->wsi) {
        lws_callback_on_writable(data->wsi);  // 触发发送心跳
    } 
    // 也可在协议层设置自动心跳
}

// WebSocket 回调函数
static int callback_webkit(struct lws *wsi, enum lws_callback_reasons reason,
                          void *user, void *in, size_t len) {

    struct client_data *data = (struct client_data *)user;

    switch(reason) {
        case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
            fprintf(stderr, "[ERROR] Connection error: %s\n", (char*)in ? (char*)in : "Unknown");
            data->close_reason = 1;
            break;

        case LWS_CALLBACK_Client_ESTABLISHED:
            printf("[INFO] Connected to server.\n");
            data->connected = 1;
            // 仅一次触发心跳定时器
            if (data->timer.data == NULL) {
                uv_timer_init(&data->uv_loop, &data->timer);
                data->timer.data = data;
                uv_timer_start(&data->timer, on_timeout, PING_INTERVAL_SEC * 1000, PING_INTERVAL_SEC * 1000);
            }
            break;

        case LWS_CALLBACK_CLIENT_RECEIVE:
            printf("[DATA] Received: %s\n", (char*)in);
            // 可增加内容过滤（防恶意脚本注入）
            break;

        case LWS_CALLBACK_CLIENT_WRITEABLE:
            // 心跳包：可发空帧或特定数据
            if (data->connected) {
                const char *ping_msg = "ping";
                lws_write(wsi, (unsigned char*)ping_msg, strlen(ping_msg), LWS_WRITE_TEXT);
            }
            break;

        case LWS_CALLBACK_CLOSED:
            printf("[INFO] Connection closed.\n");
            data->connected = 0;
            uv_timer_stop(&data->timer);
            break;

        case LWS_CALLBACK_CLIENT_APPEND_HEADERS:
            add_auth_headers(wsi, user, NULL);
            break;

        default:
            break;
    }

    return 0;
}

// 创建并启动客户端
int start_websocket_client(const char* url) {
    struct lws_context_creation_info info = {0};
    struct client_data *client_data = calloc(1, sizeof(*client_data));
    if (!client_data) {
        perror("calloc failed");
        return -1;
    }

    client_data->url = strdup(url);
    client_data->connected = 0;
    client_data->wsi = NULL;

    // 【关键配置项：安全性强化】
    info.port = CONTEXT_PORT_NO_LISTEN;
    info.protocols = (struct lws_protocols[]){
        {
            "default",
            callback_webkit,
            0,
            0,
            0,
            client_data,
            0
        },
        {NULL, NULL, 0, 0, 0, NULL, 0}
    };
    info.gid = -1;
    info.uid = -1;

    // SSL/TLS 配置（重要！)
    info.ssl_cert_filepath = NULL;     // 从系统信任库中读取证书
    info.ssl_private_key_filepath = NULL;
    info.client_ssl_ca_filepath = "/etc/ssl/certs/ca-certificates.crt";  // 推荐指定路径
    info.insecure_skip_verify = 0;   // 禁用跳过证书验证，除非明确需要

    // 自定义证书验证回调（高保真安全控制）
    info.psk = NULL;                 // PSK 不适用
    info.cert_mode = 0;              // 通常默认
    info.ietf_version = 13;          // WebSocket RFC 6455

    // 支持代理？可在此处添加
    info.options = LWS_SERVER_OPTION_DO_SSL_GLOBAL_INIT | LWS_SERVER_OPTION_ENABLE_HTTP_BASIC_AUTH;

    // 启动 libwebsockets context
    struct lws_context *context = lws_create_context(&info);
    if (!context) {
        fprintf(stderr, "[FAIL] Failed to create lws context\n");
        free(client_data->url);
        free(client_data);
        return -1;
    }

    // 启动客户端连接
    client_data->wsi = lws_client_connect(context, url, "wss", NULL, NULL, NULL, callback_webkit, client_data, CONNECT_TIMEOUT_SEC * 1000);

    if (!client_data->wsi) {
        fprintf(stderr, "[FAIL] Failed to connect to: %s\n", url);
        lws_context_destroy(context);
        free(client_data->url);
        free(client_data);
        return -1;
    }

    // 事件循环主循环（由 LWS 调用，内部包含其自己的事件轮询）

    while (lws_service(context, 0) != -1) {
        // 模拟周期性检查或日志打印
        usleep(10000); // 减少负载，不占用太多资源
    }

    // 清理
    uv_timer_stop(&client_data->timer);
    lws_context_destroy(context);
    free(client_data->url);
    free(client_data);

    return 0;
}

// 主函数入口
int main(int argc, char **argv) {

    // 【安全研究提示】：不要硬编码凭据（已按需通过环境变量传递）

    const char *url = WS_URI;

    if (argc > 1) {
        url = argv[1];
    }

    printf("[SECURITY RESEARCHER] Starting secure WebSocket client to: %s\n", url);

    int ret = start_websocket_client(url);

    if (ret != 0) {
        fprintf(stderr, "[FINAL] Client exited with error code %d\n", ret);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

