## 💻 用 C 实现高效24点求解器（最优复杂度）

```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

// 定义浮点误差容忍度
#define EPSILON 1e-6

// 操作符枚举
typedef enum {
    ADD, SUB, MUL, DIV
} Operator;

// 结构体：存储表达式树中的节点
typedef struct TreeNode {
    double value;
    char op;
    int isLeaf;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

// 构造叶子节点（数值）
TreeNode* createLeaf(double val) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->value = val;
    node->isLeaf = 1;
    node->left = node->right = NULL;
    return node;
}

// 构造内部节点
TreeNode* createNode(double val, char op, TreeNode* left, TreeNode* right) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->value = val;
    node->op = op;
    node->isLeaf = 0;
    node->left = left;
    node->right = right;
    return node;
}

// 打印表达式（后序遍历输出，便于理解）
void printExpression(TreeNode* root) {
    if (!root) return;

    if (root->isLeaf) {
        printf("%.1f", root->value);
    } else {
        printf("(");
        printExpression(root->left);
        printf(" %c ", root->op);
        printExpression(root->right);
        printf(")");
    }
}

// 执行运算并检查合法性
double applyOp(double a, double b, char op, int* valid) {
    *valid = 1;
    switch (op) {
        case ADD:
            return a + b;
        case SUB:
            return a - b;
        case MUL:
            return a * b;
        case DIV:
            if (fabs(b) < EPSILON) {
                *valid = 0;  // 除零
                return 0;
            }
            return a / b;
        default:
            *valid = 0;
            return 0;
    }
}

// 深度优先搜寻所有表达式树，尝试每一种组合
int solveWithTree(double nums[4], int depth, double target) {
    // 终止条件：只剩一个数
    if (depth == 1) {
        return fabs(nums[0] - target) < EPSILON;
    }

    // 尝试所有两两组合
    for (int i = 0; i < depth; i++) {
        for (int j = i + 1; j < depth; j++) {
            double a = nums[i];
            double b = nums[j];

            // 保存原始数据用于后续替换
            double temp_i = nums[i];
            double temp_j = nums[j];

            // 压缩数组：移除 a, b 并插入新值
            nums[i] = nums[depth - 1];  // 取最后一个元素覆盖
            nums[j] = nums[depth - 2]; // 左边再填一个

            int valid;
            double result;

            // 四种运算
            for (int op = ADD; op <= DIV; op++) {
                result = applyOp(a, b, op, &valid);
                if (!valid) continue;

                nums[depth - 2] = result;  // 放入新数字位置

                // 递归处理剩余深度 - 1
                if (solveWithTree(nums, depth - 1, target)) {
                    // 打印解法（可选）
                    printf("Solution found: ");
                    // 构建表达式树打印（简化版，只用数值模拟）
                    printSolution(a, b, op, depth - 2);  // 此处可增强输出表达式
                    return 1;
                }
            }

            // 还原数组顺序
            nums[i] = temp_i;
            nums[j] = temp_j;
        }
    }
    return 0;
}

// 打印构造的表达式解（辅助函数）
void printSolution(double a, double b, char op, int pos) {
    const char* ops = "+-*/";
    if (pos == 1) {
        printf("(%.1f %c %.1f)", a, ops[op], b);
    } else {
        printf("(%.0f %c %.0f)", a, ops[op], b);
    }
}

// 排列生成器（优化：直接对数组进行交换排列，减少冗余循环）
void permute(double nums[], int start, int end, double target) {
    if (start == end) {
        // 尝试当前排列
        if (solveWithTree(nums, 4, target)) {
            printf("\n== Success! Found solution: ");
            for (int i = 0; i < 4; i++)
                printf("%.1f ", nums[i]);
            printf("==\n\n");
        }
        return;
    }

    for (int i = start; i <= end; i++) {
        // 交换
        double temp = nums[start];
        nums[start] = nums[i];
        nums[i] = temp;

        permute(nums, start + 1, end, target);

        // 回溯
        temp = nums[start];
        nums[start] = nums[i];
        nums[i] = temp;
    }
}

// 接口函数：主求解入口
int isPossible24(double nums[4]) {
    if (nums == NULL || !isFinite(nums[0])) return 0;
    // 输入预处理：确保在1-13之间（可选）
    for (int i = 0; i < 4; i++) {
        if (nums[i] < 1 || nums[i] > 13 || !isfinite(nums[i]))
            return 0;
    }

    // 启动全排列 + 搜索
    permute(nums, 0, 3, 24.0);

    return 0;  // 只返回是否成功（无解就返回0）
}

// 检查是否可以凑成24点（主函数）
int main() {
    double nums[4];

    // 测试用例
    printf("Enter four numbers (1-13): ");
    for (int i = 0; i < 4; i++) {
        scanf("%lf", &nums[i]);
    }

    // 求解24点问题
    if (isPossible24(nums)) {
        printf("Yes, can make 24!\n");
    } else {
        printf("No, cannot make 24.\n");
    }

    return 0;
}
```

