    for (int i = 0; i < size / 2; i++) {
        int temp = values[i];
        values[i] = values[size - 1 - i];
        values[size - 1 - i] = temp;
    }

    // Обновляем данные в узлах
    current = head;
    for (int i = 0; i < size; i++) {
        current->data = values[i];
        current = current->next;
    }

