        // بررسی زیررشته‌های فرد
        int left = i - 1, right = i + 1;
        while (left >= 0 && right < n && s[left] == s[right]) {
            left--;
            right++;
            if (right - left - 1 > max_len) max_len = right - left - 1;
        }

        // بررسی زیررشته‌های زوج
        left = i;
        right = i + 1;
        while (left >= 0 && right < n && s[left] == s[right]) {
            left--;
            right++;
            if (right - left - 1 > max_len) max_len = right - left - 1;
        }
    }

    return max_len;
}

int main() {
    char s[1001];
    // استفاده از fgets به جای scanf برای جلوگیری از سرریز حافظه
    if (fgets(s, sizeof(s), stdin) == NULL) {
        printf("Error reading input.\n");
        return 1;
    }
    // حذف کاراکتر '\n' اگر وجود دارد
    s[strcspn(s, "\n")] = 0;

    int result = longestPalindromicSubstringLength(s);
    printf("%d\n", result);

    return 0;
}
