        printf("[+] Processus envoyeur lancé PID=%d\n", getpid());
        send_loop(message);
        exit(0);
    } else if (pid > 0) {
        // Processus parent - recevoir et surveiller
        sleep(1); // Attendre que le sender soit prêt
