                                   (struct sockaddr*)&sender_addr, &addrlen);
        if (received < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom failed");
            continue;
        }

        buffer[received] = '\0';
        char sender_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &sender_addr.sin_addr, sender_ip, INET_ADDRSTRLEN);

        // Comparaison avec le message attendu
        if (strcmp(buffer, message) == 0) {
            pthread_mutex_lock(&mutex);
            if (source_count < MAX_RECORDED_SOURCES) {
                strcpy(recorded_sources[source_count].ip, sender_ip);
                recorded_sources[source_count].port = ntohs(sender_addr.sin_port);
                recorded_sources[source_count].timestamp = time(NULL);
                source_count++;
                printf("[+] Nouveau correspondant détecté :\n");
                printf("    IP: %s  Port: %d\n", sender_ip, ntohs(sender_addr.sin_port));
            } else {
                printf("[-] Tableau de sources plein ! (%d entrées max)\n", MAX_RECORDED_SOURCES);
            }
            pthread_mutex_unlock(&mutex);
        }

        // Affichage toutes les 30 secondes
        time_t now = time(NULL);
        if (now - last_display >= INTERVAL_DISPLAY_SEC) {
            display_sources();
            last_display = now;
        }
    }

    close(sock);
    printf("[RECV] Récepteur arrêté.\n");
