               i + 1,
               recorded_sources[i].ip,
               recorded_sources[i].port,
               time_str);
    }

    if (source_count == 0) {
        printf("Aucun message correspondant reçu.\n");
    }

    printf("--------------------------------------------------------------------------------\n");
    pthread_mutex_unlock(&mutex);
}
