// Стандартный ряд Е12 (все значения в Омах)
static const double E12[] = {1.0, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2};
#define E12_SIZE 12

// Максимальная размерность "количество" резисторов в одном типе
#define MAX_COMBINATION 4

// Функция для определения типа разрядности и получения массива значений для этого диапазона
void get_resistors_for_range(double target, double values[], int *size) {
    double min_val = 1.0;
    double max_val = 1e6; // до 1 МОм

    if (target <= max_val && target >= min_val) {
        for (int i = 0; i < E12_SIZE; i++) {
            values[i] = E12[i];
        }
        *size = E12_SIZE;
    } else {
        // Попробуем масштабировать
        for (int i = 0; i < E12_SIZE; i++) {
            values[i] = E12[i] * 1e-1; // 0.1
        }
        *size = E12_SIZE;
    }
}

// Последовательное соединение (суммируем)
double series(double r1, double r2) {
    return r1 + r2;
}

// Параллельное соединение (обратное)
double parallel(double r1, double r2) {
    return (r1 * r2) / (r1 + r2);
}

// Находим лучшую комбинацию из двух одинаковых резисторов (например, 2*5.1)
void find_best_same(double target, double *best_diff, double *best_val, char *best_str) {
    double candidates[MAX_COMBINATION];
    int count = 0;

    // Получаем базовые номиналы
    get_resistors_for_range(target, candidates, &count);

    for (int i = 0; i < count; i++) {
        double val = candidates[i];
        double two_series = 2 * val;
        double two_parallel = (val * val) / (2 * val); // val / 2

        double diff_series = fabs(two_series - target);
        double diff_parallel = fabs(two_parallel - target);

        if (diff_series < *best_diff) {
            *best_diff = diff_series;
            *best_val = two_series;
            sprintf(best_str, "2*%.1fОм", val);
        }

        if (diff_parallel < *best_diff) {
            *best_diff = diff_parallel;
            *best_val = two_parallel;
            sprintf(best_str, "2*%.1fОм (пар.)", val);
        }
    }
}

