```c
#include <stdio.h>
#include <stdlib.h>

// Функция для нахождения НОД (алгоритм Евклида)
int gcd(int a, int b) {
    a = abs(a); // Приводим к положительному значению
    b = abs(b);
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Функция для нахождения НОК двух чисел
int nok2(int a, int b) {
    return (a * b) / gcd(a, b);
}

int main() {
    int A, B, C, D;

    // Ввод данных с клавиатуры
    printf("A:");
    scanf("%d", &A);
    printf("B:");
    scanf("%d", &B);
    printf("C:");
    scanf("%d", &C);
    printf("D:");
    scanf("%d", &D);

    // Вывод НОК для каждой пары
    printf("NOK(A,B): %d\n", nok2(A, B));
    printf("NOK(A,C): %d\n", nok2(A, C));
    printf("NOK(A,D): %d\n", nok2(A, D));

    return 0;
}
