// Calculatrice.java
public class Calculatrice {

    // Méthode pour effectuer une opération arithmétique simple : +, -, *, /
    public static double calculer(String operation) throws IllegalArgumentException {
        if (operation == null || operation.trim().isEmpty()) {
            throw new IllegalArgumentException("Opération vide");
        }

        String[] parts = operation.trim().split("\\s+");

        if (parts.length != 3) {
            throw new IllegalArgumentException("Format incorrect : usage: <nombre1> <opérateur> <nombre2>");
        }

        double a;
        double b;
        String op = parts[1];

        try {
            a = Double.parseDouble(parts[0]);
            b = Double.parseDouble(parts[2]);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Arguments non numériques valides");
        }

        switch (op) {
            case "+":
                return a + b;
            case "-":
                return a - b;
            case "*":
                return a * b;
            case "/":
                if (b == 0) {
                    throw new ArithmeticException("Division par zéro");
                }
                return a / b;
            default:
                throw new IllegalArgumentException("Opérateur non supporté: " + op);
        }
    }
}
```

