        ServerSocket serverSocket = null;
        Socket clientSocket = null;
        BufferedReader in = null;
        PrintWriter out = null;

        try {
            serverSocket = new ServerSocket(PORT);
            logger.info("Serveur lancé sur le port " + PORT);

            while (true) {
                clientSocket = serverSocket.accept();
                logger.info("Nouveau client connecté: " + clientSocket.getInetAddress());

                in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                out = new PrintWriter(clientSocket.getOutputStream(), true);

                String request = in.readLine();

                if (request == null || request.trim().isEmpty()) {
                    out.println("Erreur: Aucune requête reçue.");
                    continue;
                }

                try {
                    double result = Calculatrice.calculer(request);
                    out.println("Résultat: " + result);
                } catch (Exception e) {
                    out.println("Erreur: " + e.getMessage());
                }

                // Fermeture sécurisée après traitement
                in.close();
                out.close();
                clientSocket.close();
            }

        } catch (IOException e) {
            logger.log(Level.SEVERE, "Erreur serveur: ", e);
        } finally {
