# 🔐 Step 3: JWT Utility Service (With Session-Aware Claims)

```java
// JwtService.java
@Component
@RequiredArgsConstructor
public class JwtService {

    private final Environment env;
    private final String jwtKey;

    public JwtService(Environment env) {
        this.env = env;
        this.jwtKey = env.getProperty("jwt.secret");
    }

    public String generateToken(UserDetails userDetails, String sessionId) {
        return Jwts.builder()
                .setSubject(userDetails.getUsername())
                .claim("roles", userDetails.getAuthorities().stream()
                        .map(GrantedAuthority::getAuthority)
                        .collect(Collectors.toList()))
                .claim("jti", sessionId)
                .claim("iat", System.currentTimeMillis())
                .claim("exp", System.currentTimeMillis() + getExpirationTimeMillis())
                .signWith(getSigningKey(), SignatureAlgorithm.HS256)
                .compact();
    }

    public String generateRefreshToken(String username, String sessionId) {
        return Jwts.builder()
                .setSubject(username)
                .claim("jti", sessionId)
                .claim("type", "refresh")
                .claim("exp", System.currentTimeMillis() + getRefreshExpirationTimeMillis())
                .signWith(getSigningKey(), SignatureAlgorithm.HS256)
                .compact();
    }

    public boolean isValidToken(String token, UserDetails userDetails) {
        try {
            final String username = getUsernameFromToken(token);
            final String jti = getJtiFromToken(token);

            // Check if token is revoked
            if (isTokenRevoked(jti)) {
                return false;
            }

            return username.equals(userDetails.getUsername())
                    && !isTokenExpired(token)
                    && !isTokenRevoked(jti);
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isTokenRevoked(String jti) {
        return RedisTemplate.opsForValue().get("revoked:jti:" + jti) != null;
    }

    public void revokeTokenByJti(String jti) {
        String key = "revoked:jti:" + jti;
        String value = "REVOKED";
        redisTemplate.opsForValue().set(key, value, Duration.ofDays(7)); // keep for traceability
    }

    public void revokeAllTokensByUser(String username) {
        List<String> sessionIds = redisTemplate.opsForList().range("user:sessions:" + username, 0, -1);
        if (sessionIds != null) {
            for (String sid : sessionIds) {
                revokeTokenByJti(sid);
            }
            redisTemplate.delete("user:sessions:" + username); // clear list
        }
    }

    public void addSessionToUser(String username, String sessionId) {
        redisTemplate.opsForList().rightPush("user:sessions:" + username, sessionId);
    }

    public void removeSessionFromUser(String username, String sessionId) {
        redisTemplate.opsForList().remove("user:sessions:" + username, 1, sessionId);
    }

    public List<String> getUserSessions(String username) {
        return redisTemplate.opsForList().range("user:sessions:" + username, 0, -1);
    }

    public String getUsernameFromToken(String token) {
        return extractClaims(token).getSubject();
    }

    public String getJtiFromToken(String token) {
        return extractClaims(token).get("jti", String.class);
    }

    private Claims extractClaims(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(getSigningKey())
                .build()
                .parseClaimsJws(token)
                .getBody();
    }

    private Date getExpirationDate(String token) {
        return extractClaims(token).getExpiration();
    }

    private boolean isTokenExpired(String token) {
        return extractClaims(token).getExpiration().before(new Date());
    }

    public String getClaimFromToken(String token, Function<Claims, Object> claimResolver) {
        return claimResolver.apply(extractClaims(token));
    }

    private Key getSigningKey() {
        byte[] keyBytes = Decoders.BASE64.decode(jwtKey);
        return Keys.hmacShaKeyFor(keyBytes);
    }

    private long getExpirationTimeMillis() {
        return Long.parseLong(env.getProperty("jwt.expiration-milliseconds"));
    }

    private long getRefreshExpirationTimeMillis() {
        return Long.parseLong(env.getProperty("jwt.refresh-expiration-milliseconds"));
    }

    @Resource
    private RedisTemplate<String, Object> redisTemplate;
}
```

