```java
// AuthController.java
@RestController
@RequestMapping("/api/auth")
@AllArgsConstructor
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final JwtService jwtService;
    private final UserDetailsService userDetailsService;
    private final ObjectMapper objectMapper;

    @PostMapping("/login")
    public ResponseEntity<Map<String, String>> authenticateUser(@Valid @RequestBody LoginRequest loginRequest) {
        try {
            authenticationManager.authenticate(
                    new UsernamePasswordAuthenticationToken(loginRequest.getUsername(), loginRequest.getPassword())
            );

            final UserDetails userDetails = userDetailsService.loadUserByUsername(loginRequest.getUsername());

            // Generate unique session ID for this login
            String sessionId = UUID.randomUUID().toString();

            // Build JWT
            String accessToken = jwtService.generateToken(userDetails, sessionId);
            String refreshToken = jwtService.generateRefreshToken(loginRequest.getUsername(), sessionId);

            // Store session ID per user
            jwtService.addSessionToUser(loginRequest.getUsername(), sessionId);

            // Return both tokens
            Map<String, String> tokens = new HashMap<>();
            tokens.put("access_token", accessToken);
            tokens.put("refresh_token", refreshToken);

            return ResponseEntity.ok(tokens);
        } catch (BadCredentialsException ex) {
            Map<String, String> errorMap = new HashMap<>();
            errorMap.put("error", "Invalid credentials");
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(errorMap);
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<Void> logout(HttpServletRequest request) {
        final String authHeader = request.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.badRequest().build();
        }

        // Extract JTI and invalidate
        String jwt = authHeader.substring(7);
        String jti = jwtService.getJtiFromToken(jwt);

        jwtService.revokeTokenByJti(jti);

        // Remove session ID from user's session list
        String username = jwtService.getUsernameFromToken(jwt);
        jwtService.removeSessionFromUser(username, jti);

        return ResponseEntity.noContent().build();
    }

    @PostMapping("/logout-all")
    public ResponseEntity<Void> logoutAll(HttpServletRequest request) {
        final String authHeader = request.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.badRequest().build();
        }

        String jwt = authHeader.substring(7);
        String username = jwtService.getUsernameFromToken(jwt);

        jwtService.revokeAllTokensByUser(username);

        return ResponseEntity.noContent().build();
    }

    @PostMapping("/refresh")
    public ResponseEntity<Map<String, String>> refreshAccessToken(@RequestBody RefreshTokenRequest request) {
        String username = jwtService.getUsernameFromToken(request.getRefreshToken());

        if (username == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        if (!jwtService.isValidToken(request.getRefreshToken(), userDetailsService.loadUserByUsername(username))) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        // Regenerate new access token linked to same user/session
        String newAccessToken = jwtService.generateToken(userDetailsService.loadUserByUsername(username), 
                jwtService.getJtiFromToken(request.getRefreshToken()));

        Map<String, String> tokens = new HashMap<>();
        tokens.put("access_token", newAccessToken);
        return ResponseEntity.ok(tokens);
    }
}

