### 1. `utils/MessageProtocol.java` —— 消息协议定义（含安全字段）

```java
package utils;

import java.io.Serializable;
import java.util.Date;

public class MessageProtocol implements Serializable {
    public static final String MSG_TYPE_TEXT = "TEXT";
    public static final String MSG_TYPE_IMAGE = "IMAGE";
    public static final String MSG_TYPE_FILE = "FILE";
    public static final String MSG_TYPE_REQUEST_CONNECT = "CONNECT_REQ";
    public static final String MSG_TYPE_ACCEPT = "ACCEPT";
    public static final String MSG_TYPE_REJECT = "REJECT";
    public static final String MSG_TYPE_HEARTBEAT = "HEARTBEAT";

    private String type;          // 消息类型
    private String senderId;      // 发送者（用户或客服）
    private String receiverId;    // 接收者
    private String content;       // 内容（文本或文件路径）
    private byte[] fileData;      // 二进制文件内容（图像/文件）
    private String fileName;      // 附件名
    private long timestamp;
    private String hmac;          // HMAC-SHA256签名（用于防篡改）

    // 构造函数
    public MessageProtocol(String type, String senderId, String receiverId,
                           String content, byte[] fileData, String fileName) {
        this.type = type;
        this.senderId = senderId;
        this.receiverId = receiverId;
        this.content = content;
        this.fileData = fileData;
        this.fileName = fileName;
        this.timestamp = System.currentTimeMillis();
    }

    // getter/setter...
    public String getType() { return type; }
    public void setType(String type) { this.type = type; }

    public String getSenderId() { return senderId; }
    public void setSenderId(String senderId) { this.senderId = senderId; }

    public String getReceiverId() { return receiverId; }
    public void setReceiverId(String receiverId) { this.receiverId = receiverId; }

    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }

    public byte[] getFileData() { return fileData; }
    public void setFileData(byte[] fileData) { this.fileData = fileData; }

    public String getFileName() { return fileName; }
    public void setFileName(String fileName) { this.fileName = fileName; }

    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }

    public String getHmac() { return hmac; }
    public void setHmac(String hmac) { this.hmac = hmac; }

    // 生成HMAC签名（使用密钥）
    public void sign(String secretKey) {
        String message = type + "|" + senderId + "|" + receiverId + "|" +
                         content + "|" + fileName + "|" + timestamp;
        this.hmac = CryptoUtil.hmacSign(message, secretKey);
    }

    // 验证HMAC完整性
    public boolean verify(String secretKey) {
        if (hmac == null) return false;
        String message = type + "|" + senderId + "|" + receiverId + "|" +
                         content + "|" + fileName + "|" + timestamp;
        return CryptoUtil.hmacVerify(message, hmac, secretKey);
    }

    @Override
    public String toString() {
        return "[MSG] " + type + " from " + senderId + " to " + receiverId + 
               " at " + new Date(timestamp) + " (" + (content != null ? content.length() : 0) + " chars)";
    }
}
