### 2. `utils/CryptoUtil.java` —— 加解密与摘要工具

```java
package utils;

import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

public class CryptoUtil {

    private static final String AES_ALGORITHM = "AES";
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final String SECRET_KEY = "MySecretPassword123"; // 应从配置读取或随机生成

    // 自动生成对称密钥（仅示例）
    public static SecretKey generateAesKey() throws Exception {
        KeyGenerator kgen = KeyGenerator.getInstance(AES_ALGORITHM);
        kgen.init(128, SecureRandom.getInstanceStrong());
        return kgen.generateKey();
    }

    // 加密消息（使用AES）
    public static byte[] encrypt(byte[] data, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return cipher.doFinal(data);
    }

    // 解密消息
    public static byte[] decrypt(byte[] encryptedData, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, key);
        return cipher.doFinal(encryptedData);
    }

    // 生成HMAC-SHA256签名
    public static String hmacSign(String message, String secretKey) {
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance(HMAC_ALGORITHM);
            javax.crypto.spec.SecretKeySpec signingKey =
                new javax.crypto.spec.SecretKeySpec(secretKey.getBytes(), HMAC_ALGORITHM);
            mac.init(signingKey);
            byte[] rawHmac = mac.doFinal(message.getBytes());
            return Base64.getEncoder().encodeToString(rawHmac);
        } catch (Exception e) {
            throw new RuntimeException("HMAC sign failed", e);
        }
    }

    // 验证HMAC
    public static boolean hmacVerify(String message, String receivedHmac, String secretKey) {
        String expectedHmac = hmacSign(message, secretKey);
        return expectedHmac.equals(receivedHmac);
    }

    // SHA-256摘要（用于校验文件完整性，可选）
    public static String sha256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(input.getBytes());
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
