```java
package utils;

import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

public class FileStorage {

    private static final String RECORDS_DIR = "data/chat_records/";
    private static final String LOG_FORMAT = "[%s] %s: %s%n";

    // 初始化目录
    public static void init() {
        try {
            Files.createDirectories(Paths.get(RECORDS_DIR));
        } catch (Exception e) {
            throw new RuntimeException("Failed to create chat records directory", e);
        }
    }

    // 保存聊天记录到文件（按userId命名）
    public static void saveChatLog(String userId, String messageStr) {
        String filename = RECORDS_DIR + userId + ".log";
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filename, true))) {
            writer.write(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")) + " | " + messageStr);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Cannot write chat log: " + e.getMessage());
        }
    }

    // 读取聊天记录
    public static String loadChatLog(String userId) {
        String filename = RECORDS_DIR + userId + ".log";
        StringBuilder sb = new StringBuilder();

        File f = new File(filename);
        if (!f.exists()) return "";

        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
        } catch (IOException e) {
            System.err.println("Error reading chat log: " + e.getMessage());
        }
        return sb.toString();
    }

    // 安全验证路径（防止路径遍历攻击）
    public static boolean isValidPath(String path) {
        String normalized = path.replace('\\', '/').replaceAll("/+", "/");
        return normalized.startsWith(RECORDS_DIR) &&
               !normalized.contains("..") &&
               !normalized.contains("/") && // 不允许上级目录
               normalized.length() < 100;
    }

    // 验证文件是否为图片或合法文件类型（增强安全性）
    public static boolean isAllowedFileType(String fileName) {
        String ext = fileName.toLowerCase().substring(fileName.lastIndexOf('.') + 1);
        return Set.of("jpg", "jpeg", "png", "gif", "pdf", "txt", "docx").contains(ext);
    }

    // 获取完整路径（严格限制）
    public static String getRecordFilePath(String userId) {
        String safePath = RECORDS_DIR + userId + ".log";
        if (!isValidPath(safePath)) {
            throw new SecurityException("Invalid user ID or path traversal attempt: " + userId);
        }
        return safePath;
    }
}
