### 4. `client/UserClient.java` —— 用户端客户端

```java
package client;

import utils.*;
import java.io.*;
import java.net.Socket;
import java.util.Scanner;

public class UserClient {
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private Scanner sc = new Scanner(System.in);
    private String userId;
    private boolean isConnected = false;

    public UserClient(String host, int port, String userId) throws IOException {
        this.userId = userId;
        socket = new Socket(host, port);
        out = new ObjectOutputStream(socket.getOutputStream());
        in = new ObjectInputStream(socket.getInputStream());
        this.isConnected = true;
    }

    public void startCommunication() {
        System.out.println("✅ Connected to customer service server.");

        // 向服务器发送连接请求
        MessageProtocol req = new MessageProtocol(
            MessageProtocol.MSG_TYPE_REQUEST_CONNECT,
            userId, "admin", "",
            null, null
        );
        req.sign("MySecretPassword123");
        sendMessage(req);

        // 循环接收响应
        Thread responseChecker = new Thread(() -> {
            try {
                while (isConnected) {
                    MessageProtocol msg = (MessageProtocol) in.readObject();
                    if (msg.verify("MySecretPassword123")) {
                        processMessage(msg);
                    }
                }
            } catch (Exception e) {
                System.err.println("Connection lost: " + e.getMessage());
                isConnected = false;
            }
        });
        responseChecker.start();

        // 发送输入
        while (isConnected) {
            System.out.print("You: ");
            String input = sc.nextLine();

            if (input.equalsIgnoreCase("exit")) {
                break;
            } else if (input.startsWith("upload ")) {
                uploadFile(input.substring(7));
            } else {
                sendTextMessage(input);
            }
        }

        disconnect();
    }

    private void sendTextMessage(String text) {
        MessageProtocol msg = new MessageProtocol(
            MessageProtocol.MSG_TYPE_TEXT,
            userId, "admin", text,
            null, null
        );
        msg.sign("MySecretPassword123");
        sendMessage(msg);
    }

    private void uploadFile(String filePath) {
        File f = new File(filePath);
        if (!f.exists() || !FileStorage.isAllowedFileType(f.getName())) {
            System.out.println("🚫 Invalid or blocked file.");
            return;
        }

        try {
            byte[] data = Files.readAllBytes(f.toPath());
            MessageProtocol msg = new MessageProtocol(
                MessageProtocol.MSG_TYPE_FILE,
                userId, "admin", "file uploaded",
                data, f.getName()
            );
            msg.sign("MySecretPassword123");
            sendMessage(msg);
            System.out.println("📤 File sent: " + f.getName());
        } catch (Exception e) {
            System.err.println("Failed to send file: " + e.getMessage());
        }
    }

    private void sendMessage(MessageProtocol msg) {
        try {
            out.writeObject(msg);
            out.flush();
        } catch (IOException e) {
            System.err.println("Send error: " + e.getMessage());
            isConnected = false;
        }
    }

    private void processMessage(MessageProtocol msg) {
        switch (msg.getType()) {
            case MessageProtocol.MSG_TYPE_ACCEPT:
                System.out.println("🎉 Service connected! You can now chat.");
                // 读取历史记录
                String history = FileStorage.loadChatLog(userId);
                if (!history.isEmpty()) {
                    System.out.println("\n📜 Previous messages:");
                    System.out.println(history);
                }
                break;

            case MessageProtocol.MSG_TYPE_REJECT:
                System.out.println("❌ Service rejected the request.");
                break;

            case MessageProtocol.MSG_TYPE_TEXT:
                System.out.println("💬 " + msg.getSenderId() + ": " + msg.getContent());
                // 保存至本地
                FileStorage.saveChatLog(userId, msg.getContent());
                break;

            case MessageProtocol.MSG_TYPE_IMAGE:
                System.out.println("🖼️ Received image from admin");
                // 也可添加临时保存逻辑
                break;

            case MessageProtocol.MSG_TYPE_FILE:
                saveReceivedFile(msg.getFileName(), msg.getFileData());
                break;

            default:
                System.out.println("Unknown message: " + msg);
        }
    }

    private void saveReceivedFile(String filename, byte[] data) {
        try (FileOutputStream fos = new FileOutputStream("downloads/" + filename)) {
            fos.write(data);
            System.out.println("📁 Saved file: downloads/" + filename);
        } catch (IOException e) {
            System.err.println("Could not save file: " + e.getMessage());
        }
    }

    private void disconnect() {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
            isConnected = false;
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length < 3) {
            System.err.println("Usage: java UserClient <host> <port> <userId>");
            return;
        }

        String host = args[0];
        int port = Integer.parseInt(args[1]);
        String userId = args[2];

        FileStorage.init();  // 确保本地目录准备就绪

        try (UserClient client = new UserClient(host, port, userId)) {
            client.startCommunication();
        } catch (IOException e) {
            System.err.println("Connection failed: " + e.getMessage());
        }
    }
}
