public class CustomerServiceServer {
    private ServerSocket serverSocket;
    private ExecutorService threadPool;
    private final String SECRET_KEY = "MySecretPassword123";

    public CustomerServiceServer(int port) {
        try {
            serverSocket = new ServerSocket(port);
            threadPool = Executors.newFixedThreadPool(10); // 支持10个并发连接
        } catch (IOException e) {
            throw new RuntimeException("Failed to start server on port " + port, e);
        }
    }

    public void start() {
        System.out.println("🚀 Customer service server started on port " + serverSocket.getLocalPort());

        while (true) {
            try {
                Socket clientSocket = serverSocket.accept();
                System.out.println("📥 New connection from: " + clientSocket.getInetAddress());

                threadPool.submit(new ChatHandler(clientSocket, SECRET_KEY));

            } catch (IOException e) {
                System.err.println("Accept error: " + e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        int port = 8080;
        if (args.length > 0) port = Integer.parseInt(args[0]);

        CustomerServiceServer server = new CustomerServiceServer(port);
        server.start();
    }
