### 6. `server/ChatHandler.java` —— 单人服务线程类（处理连接）

```java
package server;

import utils.*;
import java.io.*;
import java.net.Socket;
import java.util.concurrent.atomic.AtomicBoolean;

public class ChatHandler implements Runnable {
    private Socket clientSocket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String clientId;
    private AtomicBoolean active = new AtomicBoolean(true);

    private final String SECRET_KEY;

    public ChatHandler(Socket socket, String secretKey) {
        this.clientSocket = socket;
        this.SECRET_KEY = secretKey;
    }

    @Override
    public void run() {
        try {
            in = new ObjectInputStream(clientSocket.getInputStream());
            out = new ObjectOutputStream(clientSocket.getOutputStream());

            // 读取第一个消息：请求连接
            MessageProtocol firstMsg = (MessageProtocol) in.readObject();
            if (firstMsg.verify(SECRET_KEY)) {
                clientId = firstMsg.getSenderId();
                System.out.printf("🔔 New request from user: %s%n", clientId);

                // 弹出提示（模拟客户端UI提示）
                System.out.println("❓ Would you like to accept this request? (y/n)");

                // 模拟人工判断（实际应接入GUI）
                boolean accepted = askForAcceptance();
                MessageProtocol resp = accepted ?
                    new MessageProtocol(MessageProtocol.MSG_TYPE_ACCEPT, "admin", clientId, "accepted", null, null)
                    : new MessageProtocol(MessageProtocol.MSG_TYPE_REJECT, "admin", clientId, "rejected", null, null);

                resp.sign(SECRET_KEY);
                out.writeObject(resp);
                out.flush();
                if (!accepted) return;
            }

            // 开始持续对话
            while (active.get() && !clientSocket.isClosed()) {
                MessageProtocol msg = (MessageProtocol) in.readObject();
                if (msg.verify(SECRET_KEY)) {
                    handleIncomingMessage(msg);
                }
            }

        } catch (Exception e) {
            System.err.println("Session ended with user " + clientId + ": " + e.getMessage());
        } finally {
            close();
        }
    }

    private boolean askForAcceptance() {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine().trim();
        return input.equalsIgnoreCase("y") || input.equalsIgnoreCase("yes");
    }

    private void handleIncomingMessage(MessageProtocol msg) {
        switch (msg.getType()) {
            case MessageProtocol.MSG_TYPE_TEXT:
                System.out.printf("👤 %s said: %s%n", msg.getSenderId(), msg.getContent());
                // 回复给用户
                MessageProtocol reply = new MessageProtocol("TEXT", "admin", msg.getSenderId(),
                        "Thanks for your message.", null, null);
                reply.sign(SECRET_KEY);
                sendMessage(reply);
                FileStorage.saveChatLog(msg.getSenderId(), msg.getContent());
                break;

            case MessageProtocol.MSG_TYPE_FILE:
                saveUpload(msg);
                MessageProtocol ack = new MessageProtocol("TEXT", "admin", msg.getSenderId(),
                        "File received.", null, null);
                ack.sign(SECRET_KEY);
                sendMessage(ack);
                break;

            default:
                System.out.println("⚠️ Unhandled message type: " + msg.getType());
        }
    }

    private void saveUpload(MessageProtocol msg) {
        try (FileOutputStream fos = new FileOutputStream("uploads/" + msg.getFileName())) {
            fos.write(msg.getFileData());
            System.out.println("📁 Received file: " + msg.getFileName());
        } catch (Exception e) {
            System.err.println("Cannot save uploaded file: " + e.getMessage());
        }
    }

    private void sendMessage(MessageProtocol msg) {
        try {
            out.writeObject(msg);
            out.flush();
        } catch (IOException e) {
            System.err.println("Send failed: " + e.getMessage());
            active.set(false);
        }
    }

    private void close() {
        try {
            in.close();
            out.close();
            clientSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        active.set(false);
    }
}
