```java
import java.io.IOException;
import java.util.*;
import java.util.stream.Collectors;

public class TradeAnalyzer {

    private final List<Marketplace> marketplaces;
    private final Map<Skin, Map<String, Double>> priceCache; // key: skinName -> marketName -> price

    public TradeAnalyzer() {
        this.marketplaces = Arrays.asList(
            new BitSkinsMarketplace(),
            new CsgoTMMarketplace(),
            new CstradeMarketplace(),
            new Buff163Marketplace(),
            new CsgoEmpireMarketplace(),
            new SwapGGMarketplace(),
            new CSGOExoMarketplace(),
            new LootFarmMarketplace(),
            new SkinPortMarketplace(),
            new CSGOTraderMarketplace(),
            new CSMoneyMarketplace()
        );

        this.priceCache = new HashMap<>();
    }

    /**
     * Parse le JSON brut et met à jour le cache
     */
    public void loadPricesFromJson(String json) {
        // Utilise Jackson ou Gson pour parser le JSON
        ObjectMapper mapper = new ObjectMapper();
        try {
            JsonNode root = mapper.readValue(json, JsonNode.class);

            for (JsonNode entryNode : root) {
                String displayName = entryNode.fieldNames().next();
                if (displayName.startsWith("\u2605 ")) {
                    displayName = displayName.substring(3); // Supprime l'emoji
                }

                // Extraction du nom, rareté, portefeuille
                Skin skin = parseSkin(displayName);

                // Créer map de prix pour ce skin
                Map<String, Double> pricesForSkin = new HashMap<>();

                // Parcourir chaque marketplace
                for (Marketplace m : marketplaces) {
                    if (isPriceAvailable(entryNode, m.getName())) {
                        double price = extractPrice(entryNode, m.getName());
                        pricesForSkin.put(m.getName(), price);
                    }
                }

                // Ajouter au cache
                priceCache.put(skin, pricesForSkin);
            }

        } catch (IOException e) {
            throw new RuntimeException("Error parsing JSON", e);
        }
    }

    /**
     * Retourne toutes les opportunités de trade profitable
     */
    public List<TradingOpportunity> findBestTrades(double minProfit = 5.0) {
        List<TradingOpportunity> opportunities = new ArrayList<>();

        for (Map.Entry<Skin, Map<String, Double>> entry : priceCache.entrySet()) {
            Skin skin = entry.getKey();
            Map<String, Double> prices = entry.getValue();

            List<Double> validPrices = prices.values().stream()
                .filter(p -> p > 0)
                .sorted()
                .collect(Collectors.toList());

            if (validPrices.size() < 2) continue;

            double minPrice = validPrices.get(0);
            double maxPrice = validPrices.get(validPrices.size() - 1);

            // On veut "acheter bas, vendre haut"
            // Tous les couple (buy, sell) où buy < sell
            for (Marketplace buyMkt : marketplaces) {
                if (!prices.containsKey(buyMkt.getName())) continue;
                double buyPrice = prices.get(buyMkt.getName());

                for (Marketplace sellMkt : marketplaces) {
                    if (!prices.containsKey(sellMkt.getName()) || sellMkt == buyMkt) continue;
                    double sellPrice = prices.get(sellMkt.getName());

                    if (sellPrice <= buyPrice) continue;

                    double profit = sellPrice - buyPrice;
                    double profitPct = (profit / buyPrice) * 100;

                    if (profitPct >= minProfit) {
                        opportunities.add(new TradingOpportunity(skin, buyMkt, sellMkt, buyPrice, sellPrice));
                    }
                }
            }
        }

        // Tri par profit décroissant
        return opportunities.stream()
                .sorted(Comparator.comparing(TradingOpportunity::getProfit).reversed())
                .collect(Collectors.toList());
    }

    private Skin parseSkin(String displayName) {
        // Regex pour extraire : "Knife | Wear"
        // Ex: "M9 Bayonet | Damascus Steel (Factory New)"
        String[] parts = displayName.trim().split("\\|", 2);
        String name = parts[0].trim();
        String wearRaw = parts[1].trim();

        // Extraire wear et rarity (peut-être difficile sans DB)
        // Simplification ici : on assume que le wear est entre parenthèses
        String wear = ""; // placeholder
        if (wearRaw.contains("(") && wearRaw.contains(")")) {
            int start = wearRaw.indexOf('(') + 1;
            int end = wearRaw.indexOf(')');
            wear = wearRaw.substring(start, end);
        }

        // Simple extraction pour le moment
        // En production, utilisez une base de données (ex: [CSGO Skin Database](https://www.csgostatic.com/))
        return new Skin(name, "Rare", wear);
    }

    private boolean isPriceAvailable(JsonNode node, String marketName) {
        return node.get(marketName) != null && !node.get(marketName).isNull();
    }

    private double extractPrice(JsonNode node, String marketName) {
        JsonNode marketNode = node.get(marketName);
        if (marketNode.isObject()) {
            if (marketNode.has("price")) {
                return marketNode.get("price").asDouble();
            } else if (marketNode.has("starting_at") && marketNode.get("starting_at").has("price")) {
                return marketNode.get("starting_at").get("price").asDouble();
            } else if (marketNode.has("highest_order") && marketNode.get("highest_order").has("price")) {
                return marketNode.get("highest_order").get("price").asDouble(); // ou lowest?
            }
            // D'autres champs selon la source
        } else if (marketNode.isNumberNode()) {
            return marketNode.asDouble();
        }
        return -1.0;
    }

    // Méthodes utilitaires pour affichage
    public void printTopOpportunities(int topN) {
        List<TradingOpportunity> opportunities = findBestTrades(5.0); // Min 5% de profit
        System.out.println("\n🔥 TOP " + Math.min(topN, opportunities.size()) + " OPPORTUNITÉS DE TRADING 🔥");
        opportunities.stream().limit(topN).forEach(System.out::println);
    }
}
```

