## ✅ 正确且安全的实现方式（推荐）

```java
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

public class LatestRecordRetriever {

    // 假设 LogEntry 时序类
    public static class LogEntry {
        private String id;
        private String message;
        private LocalDateTime timestamp;

        // 构造函数、getter、setter
        public LogEntry(String id, String message, LocalDateTime timestamp) {
            this.id = id;
            this.message = message;
            this.timestamp = timestamp;
        }

        public LocalDateTime getTimestamp() { return timestamp; }
        public String getId() { return id; }
        public String getMessage() { return message; }

        @Override
        public String toString() {
            return "LogEntry{id='" + id + "', message='" + message + "', timestamp=" + timestamp + "}";
        }
    }

    public static LogEntry getLatestEntry(List<LogEntry> logs) {
        // 安全性检查：空值防护
        if (logs == null || logs.isEmpty()) {
            return null; // 可选：抛出异常或返回 Optional.empty()
        }

        return logs.stream()
                   .max(Comparator.comparing(LogEntry::getTimestamp)) // 升序比较，max 返回最新
                   .orElse(null); // 防止空指针，建议用 Optional 保持安全性
    }

    // 或者使用明确的降序排序方式（更显式）
    public static Optional<LogEntry> getLatestEntryWithSort(List<LogEntry> logs) {
        if (logs == null || logs.isEmpty()) {
            return Optional.empty();
        }

        return logs.stream()
                   .sorted(Comparator.comparing(LogEntry::getTimestamp).reversed())
                   .findFirst();
    }

    // 测试主方法
    public static void main(String[] args) {
        List<LogEntry> logs = Arrays.asList(
            new LogEntry("1", "User login failed", LocalDateTime.of(2024, 6, 5, 10, 30)),
            new LogEntry("2", "System started", LocalDateTime.of(2024, 6, 5, 9, 15)),
            new LogEntry("3", "Failed auth attempt", LocalDateTime.of(2024, 6, 5, 10, 50))
        );

        LogEntry latest = getLatestEntry(logs);
        System.out.println("Latest record: " + latest);

        // 安全地处理可能为空的情况
        Optional<LogEntry> latestOpt = getLatestEntryWithSort(logs);
        latestOpt.ifPresent(System.out::println);
    }
}
```

