import java.io.FileNotFoundException;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class JiraXmlParser {

    // Define patterns for potential sensitive content (basic)
    private static final Pattern SENSITIVE_PATTERNS = Pattern.compile(
        "password|passwd|secret|api_key|token|credential|login|key|jwt|auth|admin|root|sudo",
        Pattern.CASE_INSENSITIVE
    );

    private static final String[] SECURITY_LABEL_FIELDS = {
        "Security Risk Level",
        "Issue Security Level",
        "Confidentiality",
        "Data Sensitivity"
    };

    private static final Map<String, String> fieldMap = new HashMap<>();

    static {
        // Optional: map custom field names if known
        fieldMap.put("customfield_10001", "Security Risk Level");
        fieldMap.put("customfield_10002", "Confidentiality");
        // Extend as needed
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: java JiraXmlParser <path-to-jira-export.xml>");
            System.exit(1);
        }

        String filePath = args[0];
        File file = new File(filePath);

        if (!file.exists() || !file.canRead()) {
            System.err.println("Error: Cannot read file at " + filePath);
            System.exit(1);
