    private static void parseJiraExport(File inputFile) throws XMLStreamException {
        XMLEventReader eventReader = XMLOutputFactory.newFactory().createXMLEventReader(new FileInputStream(inputFile));

        boolean inIssue = false;
        boolean inCustomField = false;
        boolean inDescription = false;
        boolean inComment = false;
        boolean processingSummary = false;

        StringBuilder currentText = new StringBuilder();
        String currentElement = "";
        String issueKey = null;
        String summary = null;
        String description = null;
        String reporter = null;
        String assignee = null;
        String createdDate = null;
        String updatedDate = null;
        String dueDate = null;
        String securityLevel = null;
        String attachmentUrl = null;
        String commentText = null;

        int issueCount = 0;

        while (eventReader.hasNext()) {
            XMLEvent event = eventReader.nextEvent();

            switch (event.getEventType()) {
                case XMLEvent.START_ELEMENT:
                    currentElement = event.asStartElement().getName().getLocalPart();

                    if ("issue".equals(currentElement)) {
                        inIssue = true;
                        issueKey = getAttributeValue(event.asStartElement(), "key");
