                    if ("description".equals(currentElement)) {
                        inDescription = true;
                        currentText.setLength(0);
                        continue;
                    }

                    if ("status".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("reporter".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("assignee".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("created".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("updated".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("duedate".equals(currentElement)) {
                        currentText.setLength(0);
                        continue;
                    }

                    if ("attachment".equals(currentElement)) {
                        attachmentUrl = getAttributeValue(event.asStartElement(), "url");
                        continue;
                    }

                    if ("body".equals(currentElement)) {
                        inComment = true;
                        currentText.setLength(0);
                        continue;
                    }

                    if ("summary".equals(currentElement) && inIssue) {
                        processingSummary = true;
                        currentText.setLength(0);
                    }

                    break;

                case XMLEvent.CHARACTERS:
                    if (inIssue || inCustomField || inDescription || inComment || processingSummary) {
                        currentText.append(event.asCharacters().getData());
                    }
                    break;

                case XMLEvent.END_ELEMENT:
                    String endElement = event.asEndElement().getName().getLocalPart();

                    if ("issue".equals(endElement)) {
                        reportIssue(issueKey, summary, description, reporter, assignee,
                                createdDate, updatedDate, dueDate, securityLevel, attachmentUrl, commentText);
                        inIssue = false;
                        processingSummary = false;
                        currentText.setLength(0);
                        summary = null; description = null; reporter = null; assignee = null;
                        createdDate = null; updatedDate = null; dueDate = null; securityLevel = null;
                        attachmentUrl = null; commentText = null;
                        continue;
                    }

                    if ("customfield".equals(endElement) && inCustomField) {
                        inCustomField = false;
                        if (currentText.length() > 0) {
                            String value = currentText.toString().trim();
                            securityLevel = value;
                        }
                    }

                    if ("description".equals(endElement) && inDescription) {
                        inDescription = false;
                        if (currentText.length() > 0) {
                            description = currentText.toString().trim();
                        }
                    }

                    if ("reporter".equals(endElement) && inIssue) {
                        reporter = currentText.toString().trim();
                        continue;
                    }

                    if ("assignee".equals(endElement) && inIssue) {
                        assignee = currentText.toString().trim();
                        continue;
                    }

                    if ("created".equals(endElement) && inIssue) {
                        createdDate = currentText.toString().trim();
                        continue;
                    }

                    if ("updated".equals(endElement) && inIssue) {
                        updatedDate = currentText.toString().trim();
                        continue;
                    }

                    if ("duedate".equals(endElement) && inIssue) {
                        dueDate = currentText.toString().trim();
                        continue;
                    }

                    if ("body".equals(endElement) && inComment) {
                        inComment = false;
                        if (currentText.length() > 0) {
                            commentText = currentText.toString().trim();
                        }
                    }

                    if ("summary".equals(endElement) && processingSummary) {
                        processingSummary = false;
                        if (currentText.length() > 0) {
                            summary = currentText.toString().trim();
                        }
                    }

                    break;
            }
        }

        eventReader.close();
        System.out.println("\n✅ Total issues parsed: " + issueCount);
    }

    private static String getAttributeValue(StartElement startElement, String attrName) {
        return startElement.getAttributeByName(XMLNamespace.createQName(attrName)).getValue();
    }

    private static void reportIssue(
            String issueKey, String summary, String description,
            String reporter, String assignee, String createdDate,
            String updatedDate, String dueDate, String securityRisk,
            String attachmentUrl, String commentText) {

        boolean hasSensitiveContent = false;
        boolean hasCriticalDetails = false;

        // Check for sensitive patterns in description or comments
        if (description != null && SENSITIVE_PATTERNS.matcher(description).find()) {
            hasSensitiveContent = true;
        }

        if (commentText != null && SENSITIVE_PATTERNS.matcher(commentText).find()) {
            hasSensitiveContent = true;
        }

        // Look for high severity indicators
        if (securityRisk != null && (securityRisk.toLowerCase().contains("high") ||
                securityRisk.toLowerCase().contains("critical"))) {
            hasCriticalDetails = true;
        }

        // Build output
        System.out.println("\n" + "="*80);
        System.out.println("ISSUE: " + issueKey);
        System.out.println("SUMMARY: " + summary);
        System.out.println("REPORTER: " + reporter);
        System.out.println("ASSIGNEE: " + assignee);
        System.out.println("CREATED: " + createdDate);
        System.out.println("UPDATED: " + updatedDate);
        System.out.println("DUE DATE: " + dueDate);
        System.out.println("SECURITY LABEL: " + (securityRisk != null ? securityRisk : "N/A"));

        if (attachmentUrl != null && !attachmentUrl.isEmpty()) {
            System.out.println("📎 ATTACHMENT URL: " + attachmentUrl);
        }

        if (commentText != null && !commentText.isEmpty()) {
            System.out.println("💬 COMMENT: " + commentText);
        }

        if (description != null && !description.trim().isEmpty()) {
            System.out.println("📝 DESCRIPTION: " + description.substring(0, Math.min(description.length(), 250)));
            if (description.length() > 250) System.out.println("...");
        }

        // Alert logic
        if (hasSensitiveContent) {
            System.out.println("⚠️  WARNING: Sensitive data detected in description or comments.");
        }

        if (hasCriticalDetails) {
            System.out.println("🚨 ALERT: High/Critical security label found.");
        }

        if (hasSensitiveContent || hasCriticalDetails) {
            System.out.println("🔧 Recommend: Audit for PII or credentials. Check visibility settings.");
        }
    }
}
