                // 验证是否完成且无额外数据
                if (size != 0) throw new IOException("Incomplete transmission");

            } catch (SecurityException e) {
                // 黑名单记录或断开连接
                System.err.println("Security violation: " + e.getMessage());
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

