import java.util.ArrayList;
import java.util.List;

// Point class to represent a coordinate point
public class Point {
    public double x, y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return String.format("(%.2f, %.2f)", x, y);
    }
}

public class TrailSmoothingUtils {

    /**
     * Applies multiple iterations of 5-point moving average smoothing on the trail points.
     *
     * @param points List of Point objects (must not be null)
     * @param iterations Number of times to apply smoothing
     * @return New list of smoothed points
     * @throws IllegalArgumentException if points is null or has fewer than 5 points
     */
    public static List<Point> fittingTrailsMultiple(List<Point> points, int iterations) {
        if (points == null || points.isEmpty()) {
            throw new IllegalArgumentException("Points cannot be null or empty");
        }
        if (points.size() < 5) {
            throw new IllegalArgumentException("At least 5 points are required for 5-point averaging");
        }

        List<Point> newPoints = new ArrayList<>(points); // Start with original

        for (int i = 0; i < iterations; i++) {
            newPoints = fittingTrails(newPoints);
        }

        return newPoints;
    }

    /**
     * Smooths the list of points using 5-point moving average for interior points.
     * Edge points remain unchanged.
     *
     * @param points List of Point objects
     * @return New list of smoothed points
     */
    private static List<Point> fittingTrails(List<Point> points) {
        List<Point> newPoints = new ArrayList<>();

        for (int i = 0; i < points.size(); i++) {
            if (i >= 2 && i <= points.size() - 3) { // i in [2, n-3] → 5-point window valid
                Point avgPoint = pointsAvg(points, i);
                newPoints.add(avgPoint);
            } else {
                // Keep edge points unchanged
                newPoints.add(points.get(i));
            }
        }

        return newPoints;
    }

    /**
     * Computes the average of 5 consecutive points centered at index i.
     *
     * @param points List of points
     * @param index Center index (i)
     * @return A new Point containing the averaged (x, y) values
     */
    private static Point pointsAvg(List<Point> points, int index) {
        double sumX = 0, sumY = 0;
        int start = index - 2;
        int end = index + 2;

        for (int j = start; j <= end; j++) {
            sumX += points.get(j).x;
            sumY += points.get(j).y;
        }

        double avgX = sumX / 5.0;
        double avgY = sumY / 5.0;

        return new Point(avgX, avgY);
    }

    // Example usage
    public static void main(String[] args) {
        List<Point> trailPoints = new ArrayList<>();
        trailPoints.add(new Point(0, 0));
        trailPoints.add(new Point(1, 1));
        trailPoints.add(new Point(2, 0));
        trailPoints.add(new Point(3, 1));
        trailPoints.add(new Point(4, 0));
        trailPoints.add(new Point(5, 1));
        trailPoints.add(new Point(6, 0));

        List<Point> smoothed = fittingTrailsMultiple(trailPoints, 3);
        System.out.println("Smoothed points: " + smoothed);
    }
}
