public class EncryptedChatLog {
    private static final SecretKeySpec KEY = new SecretKeySpec("your-aes-key-here".getBytes(), "AES");
    private static final Mac HMAC = Mac.getInstance("HmacSHA256");

    public void saveMessage(String userId, String message) throws Exception {
        DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
        String timestamp = LocalDateTime.now().format(fmt);
        String entry = timestamp + " | " + message;

