        Path path = Paths.get("logs/" + userId + ".log");
        if (!Files.exists(path)) return history;

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(path.toFile()))) {
            // 读取并验证 MAC
            byte[] iv = (byte[]) ois.readObject();
            byte[] encrypted = (byte[]) ois.readObject();
            byte[] expectedMac = (byte[]) ois.readObject();

            // 验证 MAC
            HMAC.init(KEY);
            byte[] actualMac = HMAC.doFinal(encrypted);
            if (!Arrays.equals(actualMac, expectedMac)) {
                throw new SecurityException("聊天记录被篡改！");
            }

            // 解密
            Cipher cipher = Cipher.getInstance("AES");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.DECRYPT_MODE, KEY, ivSpec);
            String decrypted = new String(cipher.doFinal(encrypted));

            history.add(decrypted);
        }
        return history;
    }
}
