### ✅ Secure Java Code: Randomly Select 10 Words from a File

```java
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.SecureRandom;
import java.util.*;

public class SecureWordSelector {

    // Define a custom exception for better clarity
    public static class WordSelectionException extends Exception {
        public WordSelectionException(String message) {
            super(message);
        }

        public WordSelectionException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    private static final SecureRandom secureRandom = new SecureRandom();
    private static final int WORD_COUNT_TO_SELECT = 10;

    /**
     * Selects 10 unique random words from a text file.
     *
     * @param filePath path to the input text file
     * @return list of 10 randomly selected words (unique)
     * @throws WordSelectionException if an error occurs during file reading or processing
     */
    public static List<String> selectRandomWords(String filePath) throws WordSelectionException {
        // Validate input
        if (filePath == null || filePath.trim().isEmpty()) {
            throw new WordSelectionException("File path cannot be null or empty.");
        }

        // Resolve and sanitize path using Path.get() with normalization
        Path path = Paths.get(filePath).toAbsolutePath().normalize();

        // Ensure the path is within a safe directory (optional but recommended for security)
        // Example: restrict to project's data directory
        Path baseDir = Paths.get(System.getProperty("user.dir")).toAbsolutePath().normalize();
        if (!path.startsWith(baseDir)) {
            throw new WordSelectionException("File path must be within the application's root directory.");
        }

        // Verify file exists and is readable
        if (!Files.exists(path)) {
            throw new WordSelectionException("File does not exist: " + filePath);
        }

        if (!Files.isReadable(path)) {
            throw new WordSelectionException("File is not readable: " + filePath);
        }

        // Read entire file into memory
        try {
            byte[] fileBytes = Files.readAllBytes(path);

            // Decode as UTF-8 to avoid encoding-related security issues
            String content = new String(fileBytes, StandardCharsets.UTF_8);

            // Split by whitespace (space, newline, tab, etc.) using regex
            // This handles multiple separators safely
            String[] rawWords = content.trim().split("\\s+");

            // Filter out empty or whitespace-only entries
            List<String> validWords = new ArrayList<>();
            for (String word : rawWords) {
                if (word != null && !word.trim().isEmpty()) {
                    validWords.add(word.trim());
                }
            }

            // Check if we have enough words
            if (validWords.size() < WORD_COUNT_TO_SELECT) {
                throw new WordSelectionException(
                    String.format("Not enough words in file (found %d, need at least %d).", 
                                  validWords.size(), WORD_COUNT_TO_SELECT));
            }

            // Use SecureRandom to select 10 random indices without collision
            Set<Integer> selectedIndices = new HashSet<>();
            List<String> selectedWords = new ArrayList<>();

            while (selectedIndices.size() < WORD_COUNT_TO_SELECT) {
                int index = secureRandom.nextInt(validWords.size());

                // Avoid duplicate picks via set
                if (selectedIndices.add(index)) {
                    selectedWords.add(validWords.get(index));
                }
            }

            return selectedWords;

        } catch (IOException e) {
            throw new WordSelectionException("Error reading or processing file: " + filePath, e);
        }
    }

    /**
     * Main method for testing the functionality.
     * Intended for demonstration only.
     */
    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: java SecureWordSelector <file-path>");
            System.exit(1);
        }

        try {
            List<String> words = selectRandomWords(args[0]);

            System.out.println("Selected " + WORD_COUNT_TO_SELECT + " random words:");
            words.forEach(System.out::println);

        } catch (WordSelectionException e) {
            System.err.println("ERROR: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }
}
```

