// src/main/java/com/example/androidnetworking/MainActivity.java

package com.example.androidnetworking;

import android.Manifest;
import android.app.Activity;
import android.content.pm.PackageManager;
import android.os.Bundle;
import android.util.Log;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;

public class MainActivity extends AppCompatActivity {

    private static final String TAG = "MainActivity";
    private static final int REQUEST_PERMISSIONS = 1001;

    private NetworkConnection networkConnection;
    private Thread networkThread;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        Log.d(TAG, "MainActivity started.");

        // Request required permissions at runtime
        if (checkPermissions()) {
            startNetworkConnection();
        } else {
            requestPermissions();
        }
    }

    private boolean checkPermissions() {
        return ActivityCompat.checkSelfPermission(this, Manifest.permission.INTERNET) == PackageManager.PERMISSION_GRANTED;
    }

    private void requestPermissions() {
        ActivityCompat.requestPermissions(this,
                new String[]{Manifest.permission.INTERNET},
                REQUEST_PERMISSIONS);
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == REQUEST_PERMISSIONS) {
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                Log.d(TAG, "Internet permission granted. Starting connection...");
                startNetworkConnection();
            } else {
                Log.e(TAG, "Internet permission denied. Cannot connect.");
            }
        }
    }

    private void startNetworkConnection() {
        networkConnection = new NetworkConnection();

        // Start networking in a separate thread
        networkThread = new Thread(networkConnection, "NetworkConnectionThread");
        networkThread.start();

        Log.d(TAG, "Network connection initiated in background thread.");
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (networkThread != null && networkThread.isAlive()) {
            networkConnection.disconnect();
            try {
                networkThread.join(5000); // Wait up to 5 seconds for safe exit
            } catch (InterruptedException e) {
                Log.e(TAG, "Interrupted while waiting for network thread shutdown");
                Thread.currentThread().interrupt();
            }
        }
        Log.d(TAG, "MainActivity destroyed.");
    }
}
```

