import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class TCPPacketServer {
    private static int port = 1024;
    private static ExecutorService pool = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("--Waiting for client request. New clients pop up!--");

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("Server: Hello");

                pool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static class ClientHandler implements Runnable {
        private final Socket clientSocket;

        public ClientHandler(Socket socket) {
            this.clientSocket = socket;
        }

        @Override
        public void run() {
            try (
                BufferedReader br = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                PrintStream ps = new PrintStream(clientSocket.getOutputStream())
            ) {

                int serialNo = 1; // Start at 1, increment on each packet

                String line;
                while ((line = br.readLine()) != null && !line.trim().equals("CLOSE")) {
                    // Parse input: expect format "serialNo:data"
                    if (line.contains(":")) {
                        String[] parts = line.split(":", 2);
                        try {
                            int receivedSerial = Integer.parseInt(parts[0]);
                            String receivedData = parts[1];
                            System.out.println("FROM CLIENT " + clientSocket.getRemoteSocketAddress() + ": Packet SerialNo#" + receivedSerial + " is received with data: " + receivedData);

                            // Send ACK immediately
                            ps.println("ACK");
                            ps.flush();

                            // Now receive next message from client (to be converted to uppercase)
                            String userInput = br.readLine();
                            if (userInput == null || userInput.trim().equals("CLOSE")) {
                                break;
                            }

                            // Convert to uppercase and send back
                            String response = userInput.toUpperCase();
                            ps.println("FROM SERVER: " + response);
                            ps.flush();

                            // Increment serial number for next packet
                            serialNo++;

                        } catch (NumberFormatException e) {
                            ps.println("ERROR: Invalid serial number format.");
                            ps.flush();
                        }
                    } else {
                        ps.println("ERROR: Invalid packet format. Expected 'serialNo:data'");
                        ps.flush();
                    }
                }

                System.out.println("Server: Connection closed by client.");
            } catch (IOException e) {
                System.err.println("Client handler error: " + e.getMessage());
            }
        }
    }
}
