import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

/**
 * Secure Password Hasher using PBKDF2 with salt.
 * Designed for portfolio to showcase security best practices in Java.
 */
public class SecurePasswordHasher {

    private static final int HASH_LENGTH = 32;       // 256 bits
    private static final int ITERATIONS = 10000;     // Recommended for security
    private static final String ALGORITHM = "PBKDF2WithHmacSHA256";
    private static final SecureRandom random = new SecureRandom();

    /**
     * Generates a random salt and returns the hash of password with salt.
     * @param password User's password
     * @return String in format: salt:hash (Base64-encoded)
     */
    public static String hashPassword(String password) {
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be null or empty");
        }

        byte[] salt = new byte[16]; // 128 bits
        random.nextBytes(salt);

        byte[] hash = deriveKey(password.toCharArray(), salt, ITERATIONS, HASH_LENGTH);

        String saltBase64 = Base64.getEncoder().encodeToString(salt);
        String hashBase64 = Base64.getEncoder().encodeToString(hash);

        return saltBase64 + ":" + hashBase64;
    }

    /**
     * Verifies if provided password matches the stored hash (format: salt:hash).
     * @param password The password to verify
     * @param storedHash The stored hash in format: salt:hash
     * @return true if match, false otherwise
     */
    public static boolean verifyPassword(String password, String storedHash) {
        if (password == null || storedHash == null || storedHash.isEmpty()) {
            return false;
        }

        try {
            String[] parts = storedHash.split(":", 2);
            if (parts.length != 2) return false;

            byte[] salt = Base64.getDecoder().decode(parts[0]);
            byte[] storedHashBytes = Base64.getDecoder().decode(parts[1]);

            byte[] testHash = deriveKey(password.toCharArray(), salt, ITERATIONS, HASH_LENGTH);

            return java.util.Arrays.equals(testHash, storedHashBytes);
        } catch (Exception e) {
            // Fail securely: don't reveal details about storage format
            return false;
        }
    }

    /**
     * Derives key using PBKDF2.
     */
    private static byte[] deriveKey(char[] password, byte[] salt, int iterations, int length) {
        try {
            PBEKeySpec spec = new PBEKeySpec(password, salt, iterations, length * 8);
            SecretKeyFactory factory = SecretKeyFactory.getInstance(ALGORITHM);
            return factory.generateSecret(spec).getEncoded();
        } catch (Exception e) {
            throw new RuntimeException("Failed to derive key", e);
        }
    }

    // === Demo Usage ===
    public static void main(String[] args) {
        String password = "MySuperSecurePassw0rd!";

        System.out.println("🔐 Original password: " + password);

        // Hash password
        String hashed = hashPassword(password);
        System.out.println("✅ Hashed (salt:hash): " + hashed);

        // Verify
        boolean valid = verifyPassword("MySuperSecurePassw0rd!", hashed);
        System.out.println("✅ Correct password verification: " + valid);

        boolean invalid = verifyPassword("wrongpass", hashed);
        System.out.println("❌ Wrong password verification: " + invalid);

        // Safety demo: trying to crack via brute-force is hard
        System.out.println("\n🔒 This implementation prevents common attacks:");
        System.out.println("   • Uses salt to prevent rainbow tables");
        System.out.println("   • Slow hashing (10k iterations)");
        System.out.println("   • Returns false silently on error (no info leakage)");
    }
}
```

