#include <iostream>
#include <vector>
#include <omp.h>
#include <sys/time.h>
#include <algorithm>

using namespace std;

// Function to get current time in microseconds
long long gettimeofday_us() {
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    return tv.tv_sec * 1000000LL + tv.tv_usec;
}

// Serial Sieve of Eratosthenes
void sieve_serial(int n, vector<bool>& is_prime) {
    is_prime.assign(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= n; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += i) {
                is_prime[j] = false;
            }
        }
    }
}

// Parallel Sieve of Eratosthenes using OpenMP (work distribution by index ranges)
void sieve_parallel(int n, vector<bool>& is_prime, int num_threads) {
    is_prime.assign(n + 1, true);
    is_prime[0] = is_prime[1] = false;

    int sqrt_n = static_cast<int>(sqrt(n));
    #pragma omp parallel num_threads(num_threads)
    {
        int tid = omp_get_thread_num();
        int total_threads = omp_get_num_threads();
        int start = 2 + tid * (sqrt_n - 1) / total_threads;
        int end = (tid == total_threads - 1) ? sqrt_n : (tid + 1) * (sqrt_n - 1) / total_threads;

        // Only odd primes needed from start to end
        for (int i = max(2, start); i <= end; ++i) {
            if (is_prime[i]) {
                #pragma omp critical
                {
                    // Ensure we only mark multiples starting from i*i
                    // But do it safely within the critical section
                    for (int j = i * i; j <= n; j += i) {
                        is_prime[j] = false;
                    }
                }
            }
        }
    }
}

// Count number of primes found (only for verification)
int count_primes(const vector<bool>& is_prime) {
    return accumulate(is_prime.begin(), is_prime.end(), 0);
}

int main() {
    const int N = 10000000; // 10 million
    const int trials = 3; // Run multiple times to average
    vector<bool> is_prime;

    // Output file header
    cout << "N = " << N << endl;
    cout << "Threads\tTime(s)\tSpeedup" << endl;

    // Test for each thread count
    int thread_counts[] = {1, 2, 4, 6, 8, 10, 12, 14, 16};
    int num_threads_list = sizeof(thread_counts) / sizeof(thread_counts[0]);

    for (int t_idx = 0; t_idx < num_threads_list; ++t_idx) {
        int num_threads = thread_counts[t_idx];
        long long total_time = 0;

