package com.security.h264;

import org.bytedeco.ffmpeg.avcodec.*;
import org.bytedeco.ffmpeg.avformat.*;
import org.bytedeco.ffmpeg.avutil.*;
import org.bytedeco.javacv.*;
import org.bytedeco.javacv.Frame;
import static org.bytedeco.ffmpeg.global.avcodec.*;
import static org.bytedeco.ffmpeg.global.avformat.*;
import static org.bytedeco.ffmpeg.global.avutil.*;

import java.io.*;
import java.net.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

public class SecureH264StreamerServer {

    private static final int PORT = 8554;
    private static final int MAX_FRAME_SIZE = 1024 * 1024;      // 1MB max frame
    private static final int MAX_CONCURRENT_CONNECTIONS = 5;
    private static final int FRAME_RATE = 25;
    private static final int TIMEOUT_SECONDS = 30;

    private final ServerSocket serverSocket;
    private final AtomicInteger connectionCount = new AtomicInteger(0);
    private final AtomicBoolean running = new AtomicBoolean(true);

    public SecureH264StreamerServer() throws IOException {
        this.serverSocket = new ServerSocket(PORT);
        this.serverSocket.setSoTimeout(TIMEOUT_SECONDS * 1000); // 超时断开
    }

    public void start() {
        System.out.println("🟢 H.264 Stream Server listening on port " + PORT);

        while (running.get()) {
            try {
                // 限制并发连接
                if (connectionCount.get() >= MAX_CONCURRENT_CONNECTIONS) {
                    System.out.println("⚠️  Max concurrent connections reached. Dropping connection.");
                    serverSocket.setSoTimeout(1000); // 快速丢弃
                    continue;
                }

                Socket clientSocket = serverSocket.accept();
                connectionCount.incrementAndGet();
                System.out.println("✅ New client connected: " + clientSocket.getInetAddress());

                // 启动新线程处理客户端
                new Thread(new VideoReceiver(clientSocket)).start();

            } catch (SocketTimeoutException e) {
                // 无客户端连接超时，继续监听
                continue;
            } catch (Exception e) {
                System.err.println("❌ Unexpected error: " + e.getMessage());
                e.printStackTrace();
            }
        }
    }

    // 安全接收并解码 H.264 数据
    private static class VideoReceiver implements Runnable {
        private final Socket socket;
        private final DataInputStream in;
        private final FrameRecorder recorder;
        private final AtomicBoolean running = new AtomicBoolean(true);

        public VideoReceiver(Socket socket) throws IOException {
            this.socket = socket;
            this.in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
            this.recorder = new FrameRecorder("output.avi", 640, 480);
            this.recorder.setFormat("avi");
            this.recorder.setFrameRate(FRAME_RATE);
            this.recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
            this.recorder.setVideoOption("preset", "superfast");

            try {
                recorder.start();
            } catch (Exception e) {
                System.err.println("🔴 Failed to start recorder: " + e.getMessage());
                throw e;
            }
        }

        @Override
        public void run() {
            try {
                byte[] buffer = new byte[1024 * 1024]; // 1MB buffer
                int bytesRead;

                while (running.get() && socket.isConnected() && !socket.isClosed()) {
                    // 安全读取：读取固定长度前导头（4字节：NALU长度）
                    int header = readInt(in, 4, 10000); // 10秒超时
                    if (header == -1) break;

                    if (header > MAX_FRAME_SIZE || header < 1) {
                        System.err.println("⚠️  Invalid H.264 frame size: " + header);
                        continue; // 跳过非法帧
                    }

                    // 读取实际帧数据
                    bytesRead = in.read(buffer, 0, header);
                    if (bytesRead != header) {
                        System.err.println("⚠️  Frame read incomplete: expected " + header + ", got " + bytesRead);
                        continue;
                    }

                    // 安全性检查：确认是否为 H.264 NALU（0x00000001 或 0x000001）
                    if (!isValidH264NALU(buffer, bytesRead)) {
                        System.err.println("⚠️  Invalid H.264 NALU detected, skipping.");
                        continue;
                    }

                    // 创建帧
                    Frame frame = new Frame();
                    frame.image = new byte[bytesRead];
                    System.arraycopy(buffer, 0, frame.image, 0, bytesRead);

                    // 发送给记录器（将 H.264 裸流编码为视频）
                    if (recorder != null) {
                        recorder.record(frame);
                    }

                    // 限制速率（防止 DoS）
                    Thread.sleep(1000 / FRAME_RATE);
                }

            } catch (Exception e) {
                System.err.println("🔴 Error processing stream: " + e.getMessage());
                e.printStackTrace();
            } finally {
                closeResources();
            }
        }

        private boolean isValidH264NALU(byte[] data, int len) {
            // 检查是否有 NALU 分隔符（0x00000001 或 0x000001）
            if (len < 4) return false;

            if ((data[0] == 0 && data[1] == 0 && data[2] == 0 && data[3] == 1) ||
                (data[0] == 0 && data[1] == 0 && data[2] == 1)) {
                return true;
            }

            // 更严格的检查：判断 NALU 头（第 4 字节）是否为有效类型
            int nalType = (data[0] & 0x1F);
            return nalType >= 1 && nalType <= 23; // 有效 H.264 NALU 类型
        }

        private int readInt(DataInputStream in, int expectedLen, int timeoutMs) throws IOException {
            int total = 0;
            long start = System.currentTimeMillis();
            while (System.currentTimeMillis() - start < timeoutMs) {
                try {
                    int b = in.read();
                    if (b == -1) return -1;
                    total = (total << 8) | b;
                    if (total == 0xFFFFFFFF) {
                        return -1; // 避免全1
                    }
                    if (total >> (8 * (expectedLen - 1)) != 0) {
                        return total; // 已读够
                    }
                } catch (IOException e) {
                    Thread.sleep(100);
                    continue;
                }
            }
            return -1; // 超时
        }

        private void closeResources() {
            try {
                if (recorder != null) {
                    recorder.stop();
                    recorder.release();
                }
                if (in != null) in.close();
                if (socket != null && !socket.isClosed()) {
                    socket.close();
                }
            } catch (Exception e) {
                System.err.println("⚠️  Error closing resource: " + e.getMessage());
            } finally {
                int current = connectionCount.decrementAndGet();
                System.out.println("🔴 Client disconnected. Active connections: " + current);
            }
        }
    }

    public static void main(String[] args) {
        try {
            SecureH264StreamerServer server = new SecureH264StreamerServer();
            server.start();
        } catch (Exception e) {
            System.err.println("❌ Failed to start server: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
```

