```java
package com.secure.app.model;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Objects;

/**
 * Secure, immutable representation of a date and time with timezone awareness.
 * Designed to prevent manipulation and timezone-related security bugs.
 */
public final class SecureDateTime {

    private final ZonedDateTime dateTime;

    // Private constructor to enforce immutability and validation
    private SecureDateTime(ZonedDateTime dateTime) {
        this.dateTime = Objects.requireNonNull(dateTime, "DateTime cannot be null");
    }

    /**
     * Creates a SecureDateTime from an ISO-8601 formatted string.
     * Uses UTC with Zulu time (best for security logs and timestamps).
     *
     * @param isoString ISO-8601 formatted string (e.g., "2025-04-05T10:30:00Z")
     * @return new SecureDateTime instance
     * @throws IllegalArgumentException if string is invalid or malformed
     */
    public static SecureDateTime fromIsoString(String isoString) {
        if (isoString == null || isoString.trim().isEmpty()) {
            throw new IllegalArgumentException("ISO string must not be null or empty");
        }

        try {
            // Parse with strict validation
            Instant instant = Instant.from(DateTimeFormatter.ISO_INSTANT.parse(isoString.trim()));
            ZonedDateTime zoned = instant.atZone(ZoneOffset.UTC); // Explicitly UTC
            return new SecureDateTime(zoned);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid ISO 8601 timestamp: " + isoString, e);
        }
    }

    /**
     * Creates a SecureDateTime from a ZonedDateTime (e.g., user-local time).
     *
     * @param zonedDateTime the time with timezone
     * @return a new SecureDateTime instance
     * @throws IllegalArgumentException if zonedDateTime is null or invalid
     */
    public static SecureDateTime fromZonedDateTime(ZonedDateTime zonedDateTime) {
        if (zonedDateTime == null) {
            throw new IllegalArgumentException("ZonedDateTime cannot be null");
        }
        // Ensure the time is normalized (e.g., no invalid times due to DST)
        return new SecureDateTime(zonedDateTime.withZoneSameInstant(ZoneOffset.UTC));
    }

    /**
     * Creates a SecureDateTime from a LocalDateTime in a given zone (used for local inputs).
     *
     * @param localDateTime local date-time (without timezone)
     * @param zoneId timezone to interpret the local time in
     * @return new SecureDateTime in UTC
     * @throws IllegalArgumentException if inputs are null or invalid
     */
    public static SecureDateTime fromLocalDateTime(LocalDateTime localDateTime, ZoneId zoneId) {
        if (localDateTime == null || zoneId == null) {
            throw new IllegalArgumentException("LocalDateTime and ZoneId cannot be null");
        }
        ZonedDateTime zonedDateTime = localDateTime.atZone(zoneId);
        return new SecureDateTime(zonedDateTime.withZoneSameInstant(ZoneOffset.UTC));
    }

    // Getters (no setters!)
    public ZonedDateTime getDateTime() {
        return dateTime; // Return defensive copy if needed, but ZonedDateTime is effectively immutable
    }

    public Instant toInstant() {
        return dateTime.toInstant();
    }

    public String toIsoString() {
        return dateTime.format(DateTimeFormatter.ISO_INSTANT); // Outputs like 2025-04-05T10:30:00Z
    }

    public ZoneId getZoneId() {
        return dateTime.getZone();
    }

    // Compare with another SecureDateTime
    public boolean isBefore(SecureDateTime other) {
        return this.dateTime.isBefore(other.dateTime);
    }

    public boolean isAfter(SecureDateTime other) {
        return this.dateTime.isAfter(other.dateTime);
    }

    public boolean isEqual(SecureDateTime other) {
        return this.dateTime.equals(other.dateTime);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        SecureDateTime that = (SecureDateTime) o;
        return dateTime.equals(that.dateTime);
    }

    @Override
    public int hashCode() {
        return Objects.hash(dateTime);
    }

    @Override
    public String toString() {
        return "SecureDateTime{" +
                "dateTime=" + toIsoString() +
                ", zone=" + getZoneId() +
                '}';
    }
}
```

