            List<Article> articles = new ArrayList<>();

            for (Element item : newsItems) {
                String title = item.select("a[href]").text().trim();
                String link = BASE_URL + item.select("a[href]").first().attr("href");
                String publishTime = item.select("span.time").text().trim(); // 例如：2024年12月3日

