    );

    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB

    public String storeFile(MultipartFile file) throws IOException {
        // 1. Валидация
        validateFile(file);

        // 2. Генерация безопасного имени
        String fileName = generateSafeFileName(file.getOriginalFilename());

        Path filePath = Paths.get(uploadPath, fileName).toAbsolutePath().normalize();

        // 3. Предотвращение path traversal
        if (!filePath.startsWith(Paths.get(uploadPath).toAbsolutePath())) {
            throw new SecurityException("Недопустимый путь: " + filePath);
        }

        // 4. Сохранение файла
        Files.copy(file.getInputStream(), filePath, StandardCopyOption.REPLACE_EXISTING);

        return fileName;
    }

    private void validateFile(MultipartFile file) {
        if (file.isEmpty()) {
            throw new IllegalArgumentException("Файл не может быть пустым");
        }

        if (file.getSize() > MAX_FILE_SIZE) {
            throw new IllegalArgumentException("Файл слишком большой (максимум 10MB)");
        }

        String originalFileName = file.getOriginalFilename();
        if (originalFileName == null) {
            throw new IllegalArgumentException("Имя файла не указано");
        }

        String extension = getFileExtension(originalFileName).toLowerCase();
        if (!ALLOWED_EXTENSIONS.contains(extension)) {
            throw new IllegalArgumentException("Недопустимое расширение файла: " + extension);
        }

        // Проверка MIME типа (важно!)
        String contentType = file.getContentType();
        if (contentType == null || !contentType.startsWith("image/") && !contentType.startsWith("application/")) {
            throw new IllegalArgumentException("Недопустимый тип содержимого: " + contentType);
        }
    }

    private String generateSafeFileName(String originalFileName) {
        String extension = getFileExtension(originalFileName);
        String baseName = originalFileName.substring(0, originalFileName.lastIndexOf('.'));
        return UUID.randomUUID().toString() + "." + extension;
    }

    private String getFileExtension(String fileName) {
        int lastDotIndex = fileName.lastIndexOf('.');
        if (lastDotIndex == -1) {
            throw new IllegalArgumentException("Файл должен иметь расширение");
        }
        return fileName.substring(lastDotIndex + 1);
    }
}
```

