### 5. Контроллер для загрузки (`FileUploadController.java`)

```java
@RestController
@RequestMapping("/api/files")
@PreAuthorize("hasRole('USER')")
public class FileUploadController {

    private final FileStorageService fileStorageService;

    public FileUploadController(FileStorageService fileStorageService) {
        this.fileStorageService = fileStorageService;
    }

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        try {
            String fileName = fileStorageService.storeFile(file);
            return ResponseEntity.ok("Файл загружен: " + fileName);
        } catch (Exception e) {
            return ResponseEntity.badRequest().body("Ошибка загрузки: " + e.getMessage());
        }
    }

    @GetMapping("/download/{fileName}")
    public ResponseEntity<Resource> downloadFile(@PathVariable String fileName) {
        Path filePath = Paths.get(getUploadDir(), fileName).toAbsolutePath().normalize();

        if (!filePath.startsWith(getUploadDir())) {
            return ResponseEntity.badRequest().build();
        }

        Resource resource = new UrlResource(filePath.toUri());

        if (resource.exists()) {
            return ResponseEntity.ok()
                    .contentType(MediaType.APPLICATION_OCTET_STREAM)
                    .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + fileName + "\"")
                    .body(resource);
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    private String getUploadDir() {
        return System.getProperty("java.io.tmpdir") + "/uploads";
    }
}
```

