```java
// src/main/java/com/example/admin/service/impl/AdminServiceImpl.java
package com.example.admin.service.impl;

import com.example.admin.entity.Admin;
import com.example.admin.mapper.AdminMapper;
import com.example.admin.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;

@Service
@Transactional
public class AdminServiceImpl implements AdminService {

    @Autowired
    private AdminMapper adminMapper;

    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder();

    // 登录成功后调用
    @Override
    public void loginSuccess(String username) {
        adminMapper.resetLoginFailedCount(username);
    }

    // 登录失败后调用
    @Override
    public void loginFailed(String username) {
        Admin admin = adminMapper.findByUsername(username);
        if (admin == null) return;

        // 防暴力破解：5次失败后锁定10分钟
        if (admin.getLoginFailedCount() >= 5) {
            adminMapper.setLockedStatus(username, true);
            adminMapper.updateLastLoginFailedTime(username, Instant.now().toEpochMilli());
            return;
        }

        // 递增失败次数
        adminMapper.updateLoginFailedCount(username);
    }

    // 验证用户名密码
    @Override
    public boolean authenticate(String username, String password) {
        Admin admin = adminMapper.findByUsername(username);
        if (admin == null) {
            loginFailed(username);
            return false;
        }

        // 检查是否被锁定
        if (admin.getLocked()) {
            // 检查是否超过锁定时间（例如10分钟）
            long now = Instant.now().toEpochMilli();
            if (now - admin.getLastLoginFailedTime() >= 10 * 60 * 1000) {
                // 解锁
                adminMapper.setLockedStatus(username, false);
                adminMapper.resetLoginFailedCount(username);
            } else {
                return false; // 仍处于锁定状态
            }
        }

        boolean matches = encoder.matches(password, admin.getPassword());

        if (matches) {
            loginSuccess(username);
            return true;
        } else {
            loginFailed(username);
            return false;
        }
    }
}
