// src/main/java/com/example/admin/controller/AdminController.java
package com.example.admin.controller;

import com.example.admin.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.HttpSession;
import java.util.HashMap;
import java.util.Map;

@Controller
@RequestMapping("/admin")
public class AdminController {

    @Autowired
    private AdminService adminService;

    @GetMapping("/login")
    public String showLogin() {
        return "admin/login"; // JSP 页面
    }

    @PostMapping("/login")
    @ResponseBody
    public ResponseEntity<Map<String, Object>> login(
            @RequestParam String username,
            @RequestParam String password,
            HttpSession session) {

        Map<String, Object> result = new HashMap<>();

        // 输入验证（防止SQL注入/XSS）
        if (username == null || username.trim().isEmpty() ||
            password == null || password.trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "用户名或密码不能为空");
            return ResponseEntity.badRequest().body(result);
        }

        // 严格校验：只接受字母数字下划线，防止注入
        if (!username.matches("^[a-zA-Z0-9_]+$")) {
            result.put("success", false);
            result.put("message", "用户名非法");
            return ResponseEntity.badRequest().body(result);
        }

        // 尝试登录
        boolean success = adminService.authenticate(username, password);

        if (success) {
            session.setAttribute("admin", username);
            result.put("success", true);
            result.put("message", "登录成功");
            return ResponseEntity.ok(result);
        } else {
            result.put("success", false);
            result.put("message", "用户名或密码错误");
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(result);
        }
    }

    @GetMapping("/dashboard")
    public String dashboard(HttpSession session) {
        if (session.getAttribute("admin") == null) {
            return "redirect:/admin/login";
        }
        return "admin/dashboard";
    }

    @GetMapping("/logout")
    public String logout(HttpSession session) {
        session.invalidate();
        return "redirect:/admin/login";
    }
}
