                    for (WatchEvent<?> event : key.pollEvents()) {
                        Path path = (Path) event.context();
                        Path fullPath = key.watchable().resolve(path);

                        String eventType = event.kind().name();
                        LOG.info("File event: " + eventType + " -> " + fullPath);

                        switch (eventType) {
                            case "ENTRY_CREATE":
                                handleCreate(fullPath);
                                break;
                            case "ENTRY_DELETE":
                                handleDelete(fullPath);
                                break;
                            case "ENTRY_MODIFY":
