            FileAttr attr = getFileAttributes(path);
            if (attr != null) {
                IndexedFile existing = index.get(path.toString());
                if (existing != null) {
                    // Update only if modified time or size changed
                    if (!existing.getLastModified().equals(attr.lastModified) ||
