                        index.put(path.toString(), new IndexedFile(
                                path.toString(),
                                attr.size,
                                attr.lastModified,
                                attr.checksum,
                                attr.isDirectory
                        ));
                        LOG.info("Updated file in index: " + path);
                        saveIndex();
                    }
                }
            }
        } catch (Exception e) {
            LOG.log(Level.WARNING, "Failed to handle modify: " + path, e);
        }
    }

