import com.sun.net.httpserver.HttpsConfigurator;
import com.sun.net.httpserver.HttpsServer;

import javax.net.ssl.*;
import java.io.*;
import java.net.InetSocketAddress;
import java.security.KeyStore;
import java.security.SecureRandom;

public class BasicHttpsServer {

    public static void main(String[] args) {
        // Server port
        int port = 8443;

        try {
            // Create HTTPS server
            HttpsServer server = HttpsServer.create(new InetSocketAddress(port), 0);

            // Set up SSL context
            SSLContext sslContext = SSLContext.getDefault(); // Use default (or configure manually below)

            // Load key store
            KeyStore keyStore = KeyStore.getInstance("PKCS12");
            try (FileInputStream fis = new FileInputStream("keystore.p12")) {
                keyStore.load(fis, "changeit".toCharArray());
            }

            // Create key manager factory
            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(keyStore, "changeit".toCharArray());

            // Create trust manager (optional: use default)
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(keyStore);

            // Initialize SSL context
            sslContext = SSLContext.getInstance("TLS");
            sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());

            // Set SSL configuration
            server.setHttpsConfigurator(new HttpsConfigurator(sslContext) {
                @Override
                public void configure(HttpsParameters params) {
                    try {
                        SSLContext ctx = getSSLContext();
                        SSLSocketFactory factory = ctx.getSocketFactory();
                        params.setSSLParameters(factory.getSupportedSSLParameters());
                    } catch (Exception e) {
                        System.err.println("SSL configuration failed: " + e.getMessage());
                    }
                }
            });

            // Create a simple handler
            server.createContext("/", exchange -> {
                String response = "<h1>Hello from HTTPS Server!</h1>\n";
                exchange.sendResponseHeaders(200, response.length());
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(response.getBytes());
                }
            });

            // Set up SSL support (optional: use default or specify ciphers)
            server.setExecutor(null); // Use default shared executor

            // Start server
            server.start();
            System.out.println("HTTPS server started on port " + port + " (https://localhost:" + port + ")");

            // Keep the server running
            System.in.read(); // Wait for input to stop

        } catch (Exception e) {
            System.err.println("Server error: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
