            server.setExecutor(null); // 使用默认线程池
            server.start();

            System.out.println("✅ 图片上传服务启动，监听端口: " + PORT);
            System.out.println("📁 上传目录: " + new File(UPLOAD_DIR).getAbsolutePath());

        } catch (Exception e) {
            System.err.println("❌ 服务启动失败: " + e.getMessage());
            e.printStackTrace();
        }
    }

    static class UploadHandler implements HttpHandler {

        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if ("POST".equals(exchange.getRequestMethod())) {
                String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
                if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                    sendResponse(exchange, 400, "Content-Type must be multipart/form-data");
                    return;
                }

                // 解析 boundary（用于分隔多部分数据）
                String boundary = contentType.substring(contentType.indexOf("boundary=") + 9);
                // 简化处理：直接读取整个请求体
                ByteArrayOutputStream buffer = new ByteArrayOutputStream();
                try (InputStream inputStream = exchange.getRequestBody()) {
                    byte[] chunk = new byte[1024];
                    int len;
                    while ((len = inputStream.read(chunk)) != -1) {
                        buffer.write(chunk, 0, len);
                    }
                }

                byte[] requestBody = buffer.toByteArray();

                // 解析 multipart 数据
                String bodyStr = new String(requestBody, "UTF-8");
                String[] parts = bodyStr.split("--" + boundary);

                // 查找文件部分
                String filename = null;
                byte[] fileData = null;

                for (String part : parts) {
                    if (part.trim().isEmpty() || part.startsWith("--")) continue;

                    // 检查是否包含文件字段
                    int contentDispositionIndex = part.indexOf("Content-Disposition: form-data;");
                    if (contentDispositionIndex == -1) continue;

                    // 提取文件名
                    int nameIndex = part.indexOf("name=\"file\"");
                    if (nameIndex == -1) continue;

                    int filenameStart = part.indexOf("filename=\"", nameIndex);
                    if (filenameStart == -1) continue;
                    int filenameEnd = part.indexOf("\"", filenameStart + 10);
                    if (filenameEnd == -1) continue;
                    filename = part.substring(filenameStart + 10, filenameEnd);

                    // 提取文件数据（从 "Content-Type: ..." 后开始）
                    int bodyStart = part.indexOf("\r\n\r\n");
                    if (bodyStart == -1) continue;
                    bodyStart += 4; // 跳过 \r\n\r\n

                    fileData = part.substring(bodyStart).getBytes("UTF-8");
                    break;
                }

                if (filename == null || fileData == null) {
                    sendResponse(exchange, 400, "Missing file in request");
                    return;
                }

                // 提取扩展名并验证
                String ext = getExtension(filename);
                if (ext == null) {
                    sendResponse(exchange, 400, "Unsupported file type");
                    return;
                }

                String mimeType = MIME_TYPES.get(ext.toLowerCase());
                if (mimeType == null || !mimeType.startsWith(CONTENT_TYPE_IMAGE)) {
                    sendResponse(exchange, 400, "Only image files are allowed");
                    return;
                }

                // 保存文件
                String savePath = UPLOAD_DIR + "/" + filename;
                try (OutputStream out = new FileOutputStream(savePath)) {
                    out.write(fileData);
                }

                sendResponse(exchange, 200, "OK, image saved as: " + filename);
                System.out.println("✅ 图片已保存: " + savePath);

            } else {
                sendResponse(exchange, 405, "Method Not Allowed");
            }
        }

        private void sendResponse(HttpExchange exchange, int statusCode, String responseText) throws IOException {
            exchange.sendResponseHeaders(statusCode, responseText.length());
            try (OutputStream os = exchange.getResponseBody()) {
                os.write(responseText.getBytes());
            }
        }

        private String getExtension(String filename) {
            int lastDot = filename.lastIndexOf('.');
            if (lastDot == -1 || lastDot >= filename.length() - 1) return null;
            return filename.substring(lastDot + 1).toLowerCase();
        }
    }
}
```

