```java
// SecureTaskSerializer.java
package com.cluster.security;

import com.cluster.tasks.Task;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class SecureTaskSerializer {

    private final SecretKey secretKey; // Should be same on client & server
    private final String macAlgorithm = "HmacSHA256";

    public SecureTaskSerializer(byte[] secretKeyBytes) {
        this.secretKey = new SecretKeySpec(secretKeyBytes, macAlgorithm);
    }

    public byte[] serializeAndSign(Task<?> task) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);

        oos.writeObject(task);
        oos.flush();
        byte[] serializedTask = baos.toByteArray();

        // Sign
        Mac mac = Mac.getInstance(macAlgorithm);
        mac.init(secretKey);
        byte[] hmac = mac.doFinal(serializedTask);

        // Append: [HMAC][SERIALIZED_TASK]
        byte[] signed = new byte[hmac.length + serializedTask.length];
        System.arraycopy(hmac, 0, signed, 0, hmac.length);
        System.arraycopy(serializedTask, 0, signed, hmac.length, serializedTask.length);

        return signed;
    }

    public Task<?> deserializeAndVerify(byte[] signedData) throws IOException, ClassNotFoundException {
        if (signedData.length < 32) // HMAC-SHA256 = 32 bytes
            throw new SecurityException("Invalid signed data");

        byte[] receivedHmac = new byte[32];
        byte[] payload = new byte[signedData.length - 32];

        System.arraycopy(signedData, 0, receivedHmac, 0, 32);
        System.arraycopy(signedData, 32, payload, 0, payload.length);

        // Verify HMAC
        Mac mac = Mac.getInstance(macAlgorithm);
        mac.init(secretKey);
        byte[] expectedHmac = mac.doFinal(payload);

        if (!java.util.Arrays.equals(receivedHmac, expectedHmac)) {
            throw new SecurityException("HMAC verification failed: tampered data");
        }

        // Deserialize
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(payload));
        return (Task<?>) ois.readObject();
    }
}
```

