// TaskDistributor.java
package com.cluster.distributor;

import com.cluster.security.SecureTaskSerializer;
import com.cluster.tasks.Task;

import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;
import java.io.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class TaskDistributor {

    private final SecureTaskSerializer serializer;
    private final ExecutorService executor;
    private final SSLSocket socket;

    public TaskDistributor(String remoteHost, int port) throws IOException {
        this.serializer = new SecureTaskSerializer("my-shared-secret-32chars".getBytes());
        this.executor = Executors.newFixedThreadPool(4);
        this.socket = (SSLSocket) SSLSocketFactory.getDefault().createSocket(remoteHost, port);
        socket.startHandshake();
    }

    public <T> void submitTask(Task<T> task, ResultCallback<T> callback) {
        executor.submit(() -> {
            try {
                byte[] signedTask = serializer.serializeAndSign(task);
                try (DataOutputStream dos = new DataOutputStream(socket.getOutputStream())) {
                    dos.writeInt(signedTask.length);
                    dos.write(signedTask);
                    dos.flush();
                }

                // Wait for response
                try (DataInputStream dis = new DataInputStream(socket.getInputStream())) {
                    int len = dis.readInt();
                    byte[] responseBytes = new byte[len];
                    dis.readFully(responseBytes);

                    // Deserialize & verify response
                    SecureTaskSerializer responseSerializer = new SecureTaskSerializer("my-shared-secret-32chars".getBytes());
                    T result = (T) responseSerializer.deserializeAndVerify(responseBytes);

                    callback.onResult(result);
                }

            } catch (Exception e) {
                callback.onError(e);
            }
        });
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    @FunctionalInterface
    public interface ResultCallback<T> {
        void onResult(T result);
        void onError(Exception e);
    }
}
```

> 🔑 **Key Security Measures**:
> - **TLS 1.3** for encryption in transit.
> - **Pre-shared key** (PSK) for HMAC — should be managed securely (e.g., via Android Keystore or secret manager).
> - **Length-prefixing** (write `int len` first) to demux stream.

