import java.io.*;
import java.net.*;
import java.util.*;

public class Server {
    private static final int PORT = 5555;
    private static final List<PrintWriter> clients = new ArrayList<>();
    private static TicTacToeGame game = new TicTacToeGame();

    public static void main(String[] args) {
        System.out.println("Tic Tac Toe Server starting on port " + PORT);
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("Client connected: " + clientSocket);

                PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);
                clients.add(out);

                new Thread(() -> handleClient(clientSocket)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void handleClient(Socket socket) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true)) {

            // Send start message
            out.println("START");

            String message;
            while ((message = in.readLine()) != null) {
                if (message.startsWith("MOVE")) {
                    int index = Integer.parseInt(message.split(" ")[1]);

                    String response = game.makeMove(index);
                    out.println(response);

                    // Broadcast to all clients
                    for (PrintWriter cli : clients) {
                        cli.println("UPDATE " + game.getStatus());
                    }

                    if (response.equals("WIN") || response.equals("DRAW")) {
                        game.reset();
                        for (PrintWriter cli : clients) {
                            cli.println("START");
                        }
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Client disconnected.");
            clients.remove(out);
        }
    }
}
