    public void initialize() {
        setupBoard();
        connectToServer();
    }

    private void setupBoard() {
        for (int i = 0; i < 9; i++) {
            Button btn = new Button();
            btn.setPrefSize(80, 80);
            btn.setFont(Font.font(24));
            btn.setPadding(new Insets(10));
            final int idx = i;
            btn.setOnAction(e -> {
                if (turn && !isButtonEmpty(btn)) {
                    try {
                        out.println("MOVE " + idx);
                        turn = false;
                        btn.setDisable(true);
                    } catch (Exception ex) {
                        ex.printStackTrace();
                    }
                }
            });
            board.add(btn, i % 3, i / 3);
        }
    }

    private void connectToServer() {
        try {
            socket = new Socket("localhost", 5555);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            out = new PrintWriter(socket.getOutputStream(), true);

            new Thread(() -> {
                try {
                    String msg;
                    while ((msg = in.readLine()) != null) {
                        if (msg.startsWith("START")) {
                            Platform.runLater(() -> {
                                for (int i = 0; i < 9; i++) {
                                    ((Button) board.getChildren().get(i)).setText("");
                                    ((Button) board.getChildren().get(i)).setDisable(false);
                                }
                                turn = true;
                            });
                        } else if (msg.startsWith("UPDATE")) {
                            String data = msg.substring(6);
                            Platform.runLater(() -> updateBoard(data));
                        } else if (msg.equals("WIN")) {
                            Platform.runLater(() -> showAlert("You Win!"));
                        } else if (msg.equals("DRAW")) {
                            Platform.runLater(() -> showAlert("Draw!"));
                        }
                        System.out.println("Received: " + msg);
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }).start();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void updateBoard(String data) {
        for (int i = 0; i < 9; i++) {
            Button btn = (Button) board.getChildren().get(i);
            char c = data.charAt(i);
            if (c != ' ') btn.setText(String.valueOf(c));
        }
        turn = data.charAt(9) == 'X';
    }

    private boolean isButtonEmpty(Button btn) {
        return btn.getText().isEmpty();
    }

    private void showAlert(String msg) {
        System.out.println(msg);
