## 三、核心模块实现（含安全加固设计）

### 1. 网络通信层（Socket + 多线程）

#### 客服端（Server.java）

```java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class CustomerServiceServer {
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clientMap = new ConcurrentHashMap<>();
    private final Object lock = new Object();

    public void start(int port) {
        try {
            serverSocket = new ServerSocket(port);
            System.out.println("✅ 服务器启动，监听端口: " + port);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("👤 新用户连接: " + clientSocket.getInetAddress());

                // 启动独立线程处理每个客户端
                ClientHandler handler = new ClientHandler(clientSocket, this);
                new Thread(handler).start();
            }

        } catch (IOException e) {
            System.err.println("❌ 服务器启动失败: " + e.getMessage());
        }
    }

    // 向指定用户发送消息（可加权限判断）
    public void sendMessage(String userId, String msg) {
        ClientHandler handler = clientMap.get(userId);
        if (handler != null && handler.isConnected()) {
            handler.sendMessage(msg);
        } else {
            System.out.println("⚠️  用户 " + userId + " 不在线或已断开。");
        }
    }

    // 接收文件或图片请求
    public void receiveFile(String userId, String fileName, byte[] data) {
        // 安全校验：文件名过滤、路径限制、大小检查
        if (!isSafeFileName(fileName)) {
            System.err.println("❌ 不安全的文件名: " + fileName);
            return;
        }
        File fileDir = new File("received_files/" + userId);
        if (!fileDir.exists()) fileDir.mkdirs();

        File outFile = new File(fileDir, fileName);
        try (FileOutputStream fos = new FileOutputStream(outFile)) {
            fos.write(data);
            System.out.println("📁 文件接收成功: " + outFile.getAbsolutePath());
        } catch (IOException e) {
            System.err.println("❌ 文件保存失败: " + e.getMessage());
        }
    }

    // 安全检查：防路径穿越攻击
    private boolean isSafeFileName(String filename) {
        if (filename == null || filename.isBlank()) return false;
        // 防止 ../ 或 ./ 路径绕过
        return !filename.contains("..") && !filename.contains(".");
    }

    // 通知新连接
    public void notifyNewConnection(String userId) {
        synchronized (lock) {
            clientMap.put(userId, null);
        }
        System.out.println("🔔 新用户申请服务: " + userId);
    }

    public void removeClient(String userId) {
        synchronized (lock) {
            clientMap.remove(userId);
        }
    }

    public static void main(String[] args) {
        new CustomerServiceServer().start(8888);
    }
}
```

#### 客户端（ClientHandler.java）—— 客服端处理线程

```java
import java.io.*;
import java.net.Socket;
import java.util.Scanner;

public class ClientHandler implements Runnable {
    private Socket socket;
    private BufferedReader reader;
    private PrintWriter writer;
    private String userId;
    private CustomerServiceServer server;
    private boolean connected = true;

    public ClientHandler(Socket socket, CustomerServiceServer server) {
        this.socket = socket;
        this.server = server;
    }

    @Override
    public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            writer = new PrintWriter(socket.getOutputStream(), true);

            userId = reader.readLine(); // 接收客户端ID
            System.out.println("👤 用户 " + userId + " 已连接");

            server.notifyNewConnection(userId);

            // 读取消息（线程阻塞）
            String message;
            while ((message = reader.readLine()) != null && connected) {
                if (message.startsWith("FILE::")) {
                    // 解析文件头：FILE::filename::size::data
                    String[] parts = message.split("::", 3);
                    if (parts.length < 3) continue;

                    String filename = parts[1];
                    int size = Integer.parseInt(parts[2]);

                    byte[] fileData = new byte[size];
                    int totalRead = 0;
                    while (totalRead < size && connected) {
                        int len = reader.read(fileData, totalRead, size - totalRead);
                        if (len == -1) break;
                        totalRead += len;
                    }

                    if (totalRead == size) {
                        server.receiveFile(userId, filename, fileData);
                    } else {
                        System.err.println("❌ 文件接收不完整");
                    }

                } else {
                    // 普通消息
                    System.out.println("📩 收到消息: " + message);
                    // 通知前端显示（通过Swing回调）
                    SwingUtilities.invokeLater(() -> {
                        // 这里由聊天界面调用，更新UI
                        ChatUI.updateChat(userId, message);
                    });
                }
            }

        } catch (Exception e) {
            System.err.println("❌ 与用户 " + userId + " 通信异常: " + e.getMessage());
            connected = false;
        } finally {
            try {
                socket.close();
                server.removeClient(userId);
            } catch (IOException e) {
                e.printStackTrace();
            }
            System.out.println("🔌 用户 " + userId + " 已断开连接");
        }
    }

    public void sendMessage(String msg) {
        if (writer != null && connected) {
            writer.println(msg);
        }
    }

    public boolean isConnected() {
        return connected;
    }
}
