## 四、用户端（Client）实现逻辑

### 用户发起连接：`UserClient.java`

```java
import java.io.*;
import java.net.*;

public class UserClient {
    private Socket socket;
    private BufferedReader reader;
    private PrintWriter writer;

    public boolean connect(String host, int port, String userId) {
        try {
            socket = new Socket(host, port);
            reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            writer = new PrintWriter(socket.getOutputStream(), true);

            writer.println(userId); // 发送用户ID
            System.out.println("✅ 已连接客服端，用户ID: " + userId);

            // 启动接收消息线程
            new Thread(this::receiveMessages).start();

            return true;
        } catch (IOException e) {
            System.err.println("❌ 连接失败: " + e.getMessage());
            return false;
        }
    }

    private void receiveMessages() {
        try {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("FILE::")) {
                    // 与客服端同理解析
                    String[] parts = line.split("::", 3);
                    int size = Integer.parseInt(parts[2]);
                    byte[] fileData = new byte[size];
                    int totalRead = 0;
                    while (totalRead < size) {
                        int len = reader.read(fileData, totalRead, size - totalRead);
                        if (len == -1) break;
                        totalRead += len;
                    }

                    // 保存文件
                    String fileName = "downloads/" + parts[1];
                    try (FileOutputStream fos = new FileOutputStream(fileName)) {
                        fos.write(fileData);
                    }
                    SwingUtilities.invokeLater(() -> {
                        ChatUI.showFileReceived(fileName);
                    });

                } else {
                    SwingUtilities.invokeLater(() -> {
                        ChatUI.updateChat("系统", line);
                    });
                }
            }
        } catch (Exception e) {
            System.err.println("❌ 消息接收异常: " + e.getMessage());
        }
    }

    public void sendMessage(String msg) {
        writer.println(msg);
    }

    public void sendFile(String filePath) {
        File file = new File(filePath);
        if (!file.exists()) return;

        try (FileInputStream fis = new FileInputStream(file);
             ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

            byte[] buffer = new byte[1024];
            int len;
            while ((len = fis.read(buffer)) != -1) {
                baos.write(buffer, 0, len);
            }

            byte[] data = baos.toByteArray();
            String fileName = file.getName();
            writer.println("FILE::" + fileName + "::" + data.length);
            writer.write(new String(data)); // 临时传输
            writer.flush();

        } catch (IOException e) {
            System.err.println("❌ 文件发送失败: " + e.getMessage());
        }
    }

    public void disconnect() {
        try {
            if (socket != null) socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
