## 五、聊天界面（Swing UI）—— 重要安全影响点

```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class ChatUI extends JFrame {
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn, fileBtn;
    private String currentUserId;
    private static final String RECORD_DIR = "chat_records/";

    public ChatUI(String userId) {
        this.currentUserId = userId;
        this.setTitle("电商客服系统 - 用户: " + userId);

        // 初始化UI
        chatArea = new JTextArea(20, 50);
        chatArea.setEditable(false);
        chatArea.setFont(new Font("微软雅黑", Font.PLAIN, 14));
        JScrollPane scrollPane = new JScrollPane(chatArea);

        inputField = new JTextField(30);
        sendBtn = new JButton("发送");
        fileBtn = new JButton("发送文件");

        JPanel bottomPanel = new JPanel(new BorderLayout());
        bottomPanel.add(inputField, BorderLayout.CENTER);
        JPanel buttonPanel = new JPanel(new FlowLayout());
        buttonPanel.add(sendBtn);
        buttonPanel.add(fileBtn);
        bottomPanel.add(buttonPanel, BorderLayout.EAST);

        setLayout(new BorderLayout());
        add(scrollPane, BorderLayout.CENTER);
        add(bottomPanel, BorderLayout.SOUTH);

        loadChatHistory(); // 加载历史记录

        // 事件监听
        sendBtn.addActionListener(e -> sendText());
        fileBtn.addActionListener(e -> sendFile());

        inputField.addActionListener(e -> sendText());

        setDefaultCloseOperation(JFrame.DO_NOTHING_ON_CLOSE);
        addWindowListener(new java.awt.event.WindowAdapter() {
            @Override
            public void windowClosing(java.awt.event.WindowEvent windowEvent) {
                if (JOptionPane.showConfirmDialog(null, "是否退出？", "确认", JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION) {
                    System.exit(0);
                }
            }
        });

        pack();
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void sendText() {
        String text = inputField.getText().trim();
        if (text.isEmpty()) return;

        chatArea.append("【我】: " + text + "\n");
        inputField.setText("");

        // 通过Socket发送
        UserClient client = getConnectedClient();
        if (client != null) {
            client.sendMessage(text);
        }
    }

    private void sendFile() {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("选择要发送的文件");
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = chooser.getSelectedFile();
            UserClient client = getConnectedClient();
            if (client != null) {
                client.sendFile(file.getAbsolutePath());
            }
            chatArea.append("📤 发送文件: " + file.getName() + "\n");
        }
    }

    public static void updateChat(String sender, String message) {
        SwingUtilities.invokeLater(() -> {
            // 仅允许显示合法消息（防止注入）
            if (message.contains("<") || message.contains(">")) {
                message = message.replace("<", "&lt;").replace(">", "&gt;");
            }
            ChatUI.currentInstance.chatArea.append("【" + sender + "】: " + message + "\n");
        });
    }

    public static void showFileReceived(String fileName) {
        SwingUtilities.invokeLater(() -> {
            JOptionPane.showMessageDialog(currentInstance,
                    "🎉 文件接收完成：" + fileName,
                    "文件接收",
                    JOptionPane.INFORMATION_MESSAGE);
        });
    }

    private void loadChatHistory() {
        File file = new File(RECORD_DIR + currentUserId + ".log");
        if (!file.exists()) {
            chatArea.append("📝 无历史记录\n");
            return;
        }

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                chatArea.append(line + "\n");
            }
        } catch (IOException e) {
            chatArea.append("⚠️ 加载历史记录失败: " + e.getMessage() + "\n");
        }
    }

    // 每次发送前保存到本地（安全存储）
    public void saveChatMessage(String sender, String text) {
        try (PrintWriter pw = new PrintWriter(new FileWriter(RECORD_DIR + currentUserId + ".log", true))) {
            pw.println("[时间: " + System.currentTimeMillis() + "] " + sender + ": " + text);
        } catch (IOException e) {
            System.err.println("❌ 保存聊天记录失败: " + e.getMessage());
        }
    }

    private static ChatUI currentInstance;
    public static void setInstance(ChatUI instance) {
        currentInstance = instance;
    }
}
```

