import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

public class Utility {

    public static String getHash(String base) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(base.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();

            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (Exception ex) {
            throw new RuntimeException("Failed to generate SHA-256 hash", ex);
        }
    }

    public static void printLine(int num, char pattern) {
        System.out.println(String.valueOf(pattern).repeat(Math.max(0, num)));
    }

    public static void printLine(int num) {
        printLine(num, '-');
    }

    public static void printDoubleLine(int num) {
        printLine(num, '=');
    }
