            String hash = reader.readLine().trim();
            if (hash != null && !hash.isEmpty()) {
                this.adminPasswordHash = hash;
            } else {
                System.out.println("Admin file empty. Setting default password.");
                setDefaultAdminPassword();
            }
        } catch (IOException e) {
            System.out.println("Admin file not found. Creating default.");
            setDefaultAdminPassword();
        }
    }

