```java
import java.io.*;
import java.util.ArrayList;
import java.util.Random;

public class GameModule {
    private static final int NUM_ROUNDS = 4;
    private static final String PLAYERS_FILENAME = "players.bin";

    private ArrayList<Player> players;

    public GameModule() {
        loadPlayers();
        run();
    }

    private void loadPlayers() {
        try (FileInputStream fis = new FileInputStream(PLAYERS_FILENAME);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            players = new ArrayList<>();
            while (true) {
                try {
                    Player p = (Player) ois.readObject();
                    players.add(p);
                } catch (EOFException e) {
                    break;
                }
            }
            System.out.println("Players loaded from " + PLAYERS_FILENAME);
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error loading players: " + e.getMessage());
            System.exit(1);
        }
    }

    public static void main(String[] args) {
        new GameModule();
    }

    private void run() {
        Scanner scanner = new Scanner(System.in);
        String playerName = "";
        String playerPassword = "";
        Player player = null;

        boolean loggedIn = false;

        while (!loggedIn) {
            System.out.print("Enter login name > ");
            playerName = scanner.nextLine().trim();
            System.out.print("Enter password > ");
            playerPassword = scanner.nextLine().trim();

            player = findPlayer(playerName);

            if (player != null && player.checkPassword(playerPassword)) {
                loggedIn = true;
                System.out.println("Login successful!");
            } else {
                System.out.println("Invalid login. Try again.");
            }
        }

        Dealer dealer = new Dealer();
        Deck deck = new Deck();

        boolean nextGame = true;
        int betOnTable = 0;
        boolean playerQuit = false;

        while (nextGame) {
            System.out.println("================================================================================");
            System.out.println("HighSum GAME - " + player.getLoginName() + " has " + player.getChips() + " chips");
            System.out.println("================================================================================");

            deck.shuffle();
            dealer.clearCardsOnHand();
            player.clearCardsOnHand();

            // Deal 2 cards to each (dealer first)
            for (int i = 0; i < 2; i++) {
                dealer.addCard(deck.dealCard());
                player.addCard(deck.dealCard());
            }

            int round = 1;
            while (round <= NUM_ROUNDS) {
                System.out.println("--------------------------------------------------------------------------------");
                System.out.println("Dealer dealing cards - ROUND " + round);
                System.out.println("--------------------------------------------------------------------------------");

                dealer.showCardsOnHand();
                player.showCardsOnHand();
                System.out.println("Total Value: " + player.getTotalCardsValue());

                if (round == 2) {
                    dealer.addCard(deck.dealCard());
                    player.addCard(deck.dealCard());
                }

                if (round > 1) {
                    dealer.addCard(deck.dealCard());
                    player.addCard(deck.dealCard());
                }

                if (round == 4) {
                    dealer.revealHiddenCard();
                }

                if (round >= 2) {
                    if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                        boolean validChoice = false;
                        String prompt = (round == 2) ? "Follow? [Y/N]: " : "Call [C]/Quit [Q]? ";
                        while (!validChoice) {
                            String choice = scanner.nextLine().trim().toLowerCase();
                            if (choice.equals("c") || choice.equals("y")) {
                                System.out.print("Enter your bet > ");
                                int bet = scanner.nextInt();
                                scanner.nextLine();

                                if (bet <= 0 || bet > player.getChips()) {
                                    System.out.println("Invalid bet. Must be > 0 and ≤ your chips.");
                                    continue;
                                }
                                player.deductChips(bet);
                                betOnTable += bet;
                                System.out.println("Player places bet: " + bet);
                                System.out.println("Chips left: " + player.getChips());
                                System.out.println("Bet on table: " + betOnTable);
                                invalidChoice = true;
                                round++;
                            } else if (choice.equals("q") || choice.equals("n")) {
                                playerQuit = true;
                                nextGame = false;
                                round = NUM_ROUNDS + 1;
                                System.out.println("Player quit. Dealer wins all bets.");
                                break;
                            } else {
                                System.out.println("Invalid input. Enter C/Y or Q/N.");
                            }
                        }
                    } else {
                        Random random = new Random();
                        int dealerBet = Math.min(random.nextInt(11), 10);
                        if (dealerBet > player.getChips()) dealerBet = player.getChips();
                        player.deductChips(dealerBet);
                        betOnTable += dealerBet;
                        System.out.println("Dealer bets: " + dealerBet);
                        System.out.println("Chips left: " + player.getChips());
                        System.out.println("Bet on table: " + betOnTable);
                        round++;
                    }
                } else {
                    // Round 1: Dealer makes first call
                    int dealerBet = Math.min(new Random().nextInt(11), 10);
                    if (dealerBet > player.getChips()) dealerBet = player.getChips();
                    player.deductChips(dealerBet);
                    betOnTable += dealerBet;
                    System.out.println("Dealer bets: " + dealerBet);
                    System.out.println("Chips left: " + player.getChips());
                    System.out.println("Bet on table: " + betOnTable);
                    round++;
                }
            }

            // Final reveal
            if (!playerQuit) {
                System.out.println("--------------------------------------------------------------------------------");
                System.out.println("Game End - Final reveal");
                System.out.println("--------------------------------------------------------------------------------");
                dealer.revealHiddenCard();
                dealer.showCardsOnHand();
                System.out.println("Dealer Total: " + dealer.getTotalCardsValue());
                player.showCardsOnHand();
                System.out.println("Player Total: " + player.getTotalCardsValue());

                if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                    System.out.println("🎉 " + player.getLoginName() + " Wins!");
                    player.addChips(betOnTable);
                } else {
                    System.out.println("❌ Dealer Wins.");
                }
                System.out.println("Final chips: " + player.getChips());
            }

            boolean valid = false;
            while (!valid) {
                System.out.print("Next Game? (Y/N) > ");
                String input = scanner.nextLine().trim().toLowerCase();
                if (input.equals("y")) {
                    valid = true;
                    playerQuit = false;
                    nextGame = true;
                } else if (input.equals("n")) {
                    valid = true;
                    nextGame = false;
                } else {
                    System.out.println("*** Please enter Y or N ***");
                }
            }

            // Update player in list after game
            for (int i = 0; i < players.size(); i++) {
                if (players.get(i).getLoginName().equals(player.getLoginName())) {
                    players.set(i, player);
                    break;
                }
            }
        }

        // Save players after game
        try (FileOutputStream fos = new FileOutputStream(PLAYERS_FILENAME);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {

            for (Player p : players) {
                oos.writeObject(p);
            }
            System.out.println("Players updated and saved.");
        } catch (IOException e) {
            System.err.println("Failed to save players: " + e.getMessage());
        }
    }

    private Player findPlayer(String name) {
        return players.stream()
                .filter(p -> p.getLoginName().equals(name))
                .findFirst()
                .orElse(null);
    }
}
