### 📁 1. 服务器端 (`TimeServer.java`)

```java
import java.io.*;
import java.net.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

public class TimeServer {
    private static final int PORT = 8888;

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("⏰ 服务器启动，监听端口 " + PORT + "...");
            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("✅ 客户端已连接: " + clientSocket.getInetAddress());

                new Thread(new ClientHandler(clientSocket)).start();
            }
        } catch (IOException e) {
            System.err.println("⚠️ 服务器启动失败: " + e.getMessage());
            e.printStackTrace();
        }
    }

    static class ClientHandler implements Runnable {
        private Socket socket;
        private BufferedReader in;
        private PrintWriter out;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    System.out.println("📤 收到客户端消息: " + inputLine);

                    // 提取姓名
                    String name = extractName(inputLine);
                    if (name == null) {
                        out.println("To Unknown: Invalid format");
                        continue;
                    }

                    if (inputLine.trim().equals("From 学号 姓名：Exit")) {
                        out.println("To " + name + ": Bye");
                        System.out.println("👋 客户端退出");
                        break;
                    }

                    if (inputLine.contains("what time is it")) {
                        String currentTime = LocalDateTime.now()
                                .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
                        out.println("To " + name + ": " + currentTime);
                        System.out.println("⏱️  返回时间: " + currentTime);
                    } else {
                        out.println("To " + name + ": Unknown command");
                    }
                }
            } catch (IOException e) {
                System.err.println("⚠️ 与客户端通信异常: " + e.getMessage());
            } finally {
                try {
                    if (in != null) in.close();
                    if (out != null) out.close();
                    if (socket != null) socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        // 从消息中提取姓名（正则简化版）
        private String extractName(String msg) {
            // 简化提取：From <学号> <姓名>：...
            String[] parts = msg.split(" ");
            if (parts.length < 3) return null;

            String name = parts[2];
            if (name.length() < 2 || name.length() > 20) return null;

            return name;
        }
    }
}
```

