public class TimeClient {
    private static final String SERVER_HOST = "localhost";
    private static final int PORT = 8888;

    public static void main(String[] args) {
        try (Socket socket = new Socket(SERVER_HOST, PORT);
             BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
             BufferedReader stdIn = new BufferedReader(new InputStreamReader(System.in))) {

            System.out.println("📱 客户端已连接服务器：" + SERVER_HOST + ":" + PORT);

            // 模拟5次运行
            for (int i = 1; i <= 5; i++) {
                System.out.println("\n🔁 第 " + i + " 次测试：");

                // 用户输入
                System.out.print("输入命令（例：From 123456 张三：what time is it 或 Exit）: ");
                String userInput = stdIn.readLine();

                // 发送请求
                out.println(userInput);
                System.out.println("📤 发送: " + userInput);

                // 读取响应
                String response = in.readLine();
                System.out.println("📥 收到: " + response);

                // 判断是否退出
                if (response != null && response.contains("Bye")) {
                    System.out.println("👋 服务器已退出，客户端停止运行。");
                    break;
                }
            }

        } catch (UnknownHostException e) {
            System.err.println("❌ 未知主机：" + SERVER_HOST);
        } catch (IOException e) {
            System.err.println("⚠️ 客户端通信错误: " + e.getMessage());
            e.printStackTrace();
        }
    }
}
