package model;

import java.io.Serializable;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    public enum MessageType { TEXT, IMAGE, FILE }

    private String sender; // 用户名/客服
    private String content; // 文本内容或文件路径/Base64
    private MessageType type;
    private byte[] data; // 图片或文件的二进制数据
    private long timestamp;

    public Message(String sender, String content, MessageType type) {
        this.sender = sender;
        this.content = content;
        this.type = type;
        this.timestamp = System.currentTimeMillis();
    }

    public Message(String sender, byte[] data, MessageType type) {
        this.sender = sender;
        this.data = data;
        this.type = type;
        this.timestamp = System.currentTimeMillis();
    }

    // Getters and Setters
    public String getSender() { return sender; }
    public String getContent() { return content; }
    public MessageType getType() { return type; }
    public byte[] getData() { return data; }
    public long getTimestamp() { return timestamp; }

    public void setContent(String content) { this.content = content; }
    public void setData(byte[] data) { this.data = data; }
}
