### 🔹 `client/ClientHandler.java` —— 客户端通信线程

```java
package client;

import model.Message;
import java.io.*;
import java.net.Socket;

public class ClientHandler implements Runnable {
    private String host;
    private int port;
    private String username;
    private ClientGUI clientGUI;
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private volatile boolean connected = false;

    public ClientHandler(String host, int port, String username) {
        this.host = host;
        this.port = port;
        this.username = username;
    }

    @Override
    public void run() {
        try {
            socket = new Socket(host, port);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());
            connected = true;

            // 发送登录信息
            Message loginMsg = new Message(username, "LOGIN", Message.MessageType.TEXT);
            out.writeObject(loginMsg);

            // 接收客服消息
            while (connected && !Thread.currentThread().isInterrupted()) {
                try {
                    Message msg = (Message) in.readObject();
                    if (msg != null) {
                        clientGUI.receiveMessage(msg);
                    }
                } catch (Exception e) {
                    break;
                }
            }

        } catch (Exception e) {
            System.err.println("客户端连接异常: " + e.getMessage());
        } finally {
            cleanup();
        }
    }

    public void send(Message msg) {
        if (connected) {
            try {
                out.writeObject(msg);
                out.flush();
            } catch (IOException e) {
                System.err.println("发送失败: " + e.getMessage());
                connected = false;
            }
        }
    }

    private void cleanup() {
        connected = false;
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void setClientGUI(ClientGUI gui) {
        this.clientGUI = gui;
    }

    public boolean isConnectionLost() {
        return !connected;
    }
}
