    private ExecutorService executor;
    private ChatLog chatLog;
    private volatile boolean running = true;

    public ServerManager(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        executor = Executors.newFixedThreadPool(10);
        chatLog = new ChatLog();
        System.out.println("客服服务器启动在端口: " + port);
    }

    public void start() {
        while (running) {
            try {
                Socket clientSocket = serverSocket.accept();
                executor.submit(new ChatSession(clientSocket, this));
            } catch (IOException e) {
                if (running) System.err.println("接受连接失败: " + e.getMessage());
            }
        }
    }

    public void stop() {
        running = false;
        try {
            serverSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        executor.shutdown();
    }

    // 获取聊天日志（用于加载历史）
    public ChatLog getChatLog() {
        return chatLog;
    }
}
