```java
package server;

import model.ChatLog;
import model.Message;
import java.io.*;
import java.util.concurrent.atomic.AtomicBoolean;

public class ChatSession implements Runnable {
    private Socket clientSocket;
    private BufferedReader in;
    private PrintWriter out;
    private String username;
    private AtomicBoolean active = new AtomicBoolean(true);

    private ServerManager manager;

    public ChatSession(Socket socket, ServerManager manager) {
        this.clientSocket = socket;
        this.manager = manager;
    }

    @Override
    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            out = new PrintWriter(clientSocket.getOutputStream(), true);

            // 读取消息头
            String line = in.readLine();
            if (line != null && line.startsWith("LOGIN:")) {
                username = line.substring(6).trim();
            }

            // 点击服务通知
            if (manager instanceof ServerGUI) {
                ((ServerGUI) manager).notifyNewConnection(username);
            }

            // 接收消息，转发给客服（或发送回客户）
            while (active.get() && !Thread.currentThread().isInterrupted()) {
                try {
                    Message msg = (Message) new ObjectInputStream(clientSocket.getInputStream()).readObject();
                    // 记录日志
                    manager.getChatLog().addMessage(msg);

                    // 向客服通知消息
                    new Thread(() -> {
                        // 模拟客服收到消息后处理
                        if (msg.getType() == Message.MessageType.TEXT) {
                            ((ServerGUI) manager).receiveFromCustomer(username, msg.getContent());
                        }
                    }).start();

                    // 转发给客户（客服发来的回复）
                    // 示例：回复一条测试消息
                    Message reply = new Message("客服", "已收到您的消息", Message.MessageType.TEXT);
                    new ObjectOutputStream(clientSocket.getOutputStream()).writeObject(reply);
                    new ObjectOutputStream(clientSocket.getOutputStream()).flush();
                } catch (Exception e) {
                    break;
                }
            }

        } catch (IOException e) {
            System.out.println(username + " 断开连接");
        } finally {
            close();
        }
    }

    private void close() {
        active.set(false);
        try {
            in.close();
            out.close();
            clientSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void sendToClient(Message msg) {
        try {
            new ObjectOutputStream(clientSocket.getOutputStream()).writeObject(msg);
            new ObjectOutputStream(clientSocket.getOutputStream()).flush();
        } catch (IOException e) {
            System.err.println("无法发送给客户: " + e.getMessage());
        }
    }

    public String getUsername() {
        return username;
    }
}
