import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

public class MouseRecorder implements ActionListener {
    private static final String RECORDINGS_DIR = "recordings";
    private static final String RECORDING_FILE = "recordings.dat";

    private final AtomicBoolean isRecording = new AtomicBoolean(false);
    private final List<Point> record = new ArrayList<>();
    private long startTime;
    private Timer timer;
    private final Map<String, Recording> recordings = new ConcurrentHashMap<>();

    private final KeyboardFocusManager kfm = KeyboardFocusManager.getCurrentKeyboardFocusManager();
    private final GlobalKeyboardListener listener = new GlobalKeyboardListener();

    private final Path recordingsPath = Paths.get(RECORDINGS_DIR);

    // Constructor
    public MouseRecorder() {
        setupRecordingDir();
        loadRecordings();
        installGlobalKeyListener();
    }

    private void setupRecordingDir() {
        try {
            Files.createDirectories(recordingsPath);
        } catch (IOException e) {
            System.err.println("Failed to create recordings directory: " + e.getMessage());
        }
    }

    private void loadRecordings() {
        Path file = recordingsPath.resolve(RECORDING_FILE);
        if (Files.exists(file)) {
            try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(file))) {
                @SuppressWarnings("unchecked")
                Map<String, Recording> loaded = (Map<String, Recording>) ois.readObject();
                recordings.putAll(loaded);
                System.out.println("Loaded " + loaded.size() + " recordings.");
            } catch (Exception e) {
                System.err.println("Failed to load recordings from file: " + e.getMessage());
            }
        }
    }

    private void saveRecordings() {
        Path file = recordingsPath.resolve(RECORDING_FILE);
        try (ObjectOutputStream oos = new ObjectOutputStream(Files.newOutputStream(file))) {
            oos.writeObject(new HashMap<>(recordings));
            System.out.println("Recordings saved to " + file);
        } catch (IOException e) {
            System.err.println("Failed to save recordings: " + e.getMessage());
        }
    }

    private void installGlobalKeyListener() {
        try {
            // Add global key listener (requires AWT)
            kfm.addKeyEventDispatcher(e -> {
                if (e.getID() == KeyEvent.KEY_PRESSED) {
                    if (e.isShiftDown() && e.getKeyCode() == KeyEvent.VK_P) {
                        startRecording();
                        return true;
                    }
                    if (e.isShiftDown() && e.getKeyCode() == KeyEvent.VK_L) {
                        stopRecording();
                        return true;
                    }
                }
                return false;
            });
        } catch (Exception e) {
            System.err.println("Could not set up global key listener: " + e.getMessage());
        }
    }

    private void startRecording() {
        if (isRecording.getAndSet(true)) return;

        record.clear();
        startTime = System.currentTimeMillis();
        timer = new Timer(10, e -> {
            Point p = MouseInfo.getPointerInfo().getLocation();
            synchronized (record) {
                record.add(new Point(p.x, p.y));
            }
        });
        timer.setRepeats(true);
        timer.start();
        System.out.println("Recording started... (Shift+P)");
    }

