## ✅ 1. Сервер (ChatServer.java)

```java
import java.io.*;
import java.net.*;
import java.util.ArrayList;
import java.util.List;

public class ChatServer {
    private static final int PORT = 8888;
    private static List<ClientHandler> clients = new ArrayList<>();

    public static void main(String[] args) {
        System.out.println("🚀 Запуск чата на порту " + PORT + " ...");

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                System.out.println("🔄 Ожидание подключения клиента...");
                Socket clientSocket = serverSocket.accept();
                System.out.println("✅ Клиент подключился: " + clientSocket.getInetAddress());

                // Создаём обработчик для клиента в отдельном потоке
                ClientHandler clientHandler = new ClientHandler(clientSocket);
                clients.add(clientHandler);
                new Thread(clientHandler).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // Общая метод для рассылки сообщения всем клиентам
    public static void broadcastMessage(String message, ClientHandler sender) {
        for (ClientHandler client : clients) {
            if (client != sender) { // Не отправляем сообщение отправителю
                client.sendMessage(message);
            }
        }
    }

    // Удаление клиента при отключении
    public static void removeClient(ClientHandler client) {
        clients.remove(client);
        System.out.println("❌ Клиент отключился. Всего подключений: " + clients.size());
    }

    // Внутренний класс обработчик клиента
    static class ClientHandler implements Runnable {
        private Socket socket;
        private PrintWriter out;
        private BufferedReader in;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                // Инициализация потоков
                out = new PrintWriter(socket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    System.out.println("📨 Получено от клиента: " + inputLine);
                    broadcastMessage(inputLine, this);
                }
            } catch (IOException e) {
                System.err.println("🔥 Ошибка чтения с клиента: " + e.getMessage());
            } finally {
                try {
                    if (in != null) in.close();
                    if (out != null) out.close();
                    if (socket != null) socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                ChatServer.removeClient(this);
            }
        }

        public void sendMessage(String message) {
            if (out != null) {
                out.println(message);
            }
        }
    }
}
```

