## ✅ 2. Клиент (ChatClient.java)

```java
import java.io.*;
import java.net.*;

public class ChatClient {
    private static final String SERVER_ADDRESS = "localhost";
    private static final int SERVER_PORT = 8888;

    public static void main(String[] args) {
        try (Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT);
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
             BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             BufferedReader stdIn = new BufferedReader(new InputStreamReader(System.in))) {

            System.out.println("💬 Подключён к чату. Начинайте писать (нажмите Enter для отправки):");

            // Поток для чтения сообщений от сервера
            Thread readerThread = new Thread(() -> {
                try {
                    String serverMessage;
                    while ((serverMessage = in.readLine()) != null) {
                        System.out.println("🌐 ОТ СЕРВЕРА: " + serverMessage);
                    }
                } catch (IOException e) {
                    System.err.println("❌ Ошибка чтения с сервера: " + e.getMessage());
                }
            });
            readerThread.start();

            // Поток для отправки сообщений
            String userInput;
            while ((userInput = stdIn.readLine()) != null) {
                out.println(userInput);
            }

        } catch (IOException e) {
            System.err.println("❌ Не удалось подключиться к серверу: " + e.getMessage());
        }
    }
}
