## 🔐 Step 3: Rate Limiting Configuration (Java)

Create a `RateLimitingConfig.java`:

```java
package com.example.ratelimitingapp.config;

import com.github.vladimirbukhtoyarov.bucket4j.redis.DistributedBucket4j;
import com.github.vladimirbukhtoyarov.bucket4j.redis.ReactiveRedisOperations;
import io.lettuce.core.RedisClient;
import io.lettuce.core.api.sync.RedisCommands;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.StringRedisSerializer;

import java.time.Duration;

@Configuration
public class RateLimitingConfig {

    @Value("${spring.redis.host}")
    private String redisHost;

    @Value("${spring.redis.port}")
    private int redisPort;

    // Creates Redis connection factory
    @Bean
    public LettuceConnectionFactory redisConnectionFactory() {
        RedisClient redisClient = RedisClient.create("redis://" + redisHost + ":" + redisPort);
        return new LettuceConnectionFactory(redisClient);
    }

    // Creates RedisTemplate for bucket4j
    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new StringRedisSerializer());
        template.setHashKeySerializer(new StringRedisSerializer());
        template.setHashValueSerializer(new StringRedisSerializer());
        template.afterPropertiesSet();
        return template;
    }

    // Bucket4j Redis backend
    @Bean
    public DistributedBucket4j bucket4jRedisBackend(RedisTemplate<String, Object> redisTemplate) {
        ReactiveRedisOperations<String> operations = new ReactiveRedisOperations<>(redisTemplate);
        return new DistributedBucket4j(operations);
    }

    // Custom Rate Limiter Bean
    @Bean
    public RateLimiter rateLimiter(DistributedBucket4j bucket4jBackend) {
        return new RateLimiter(bucket4jBackend);
    }
}
```

