import com.github.vladimirbukhtoyarov.bucket4j.redis.DistributedBucket4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

@Service
public class RateLimiter {

    private final DistributedBucket4j bucket4jBackend;

    // Cache buckets per key to avoid constant Redis calls
    private final ConcurrentMap<String, Bucket> bucketCache = new ConcurrentHashMap<>();

    @Autowired
    public RateLimiter(DistributedBucket4j bucket4jBackend) {
        this.bucket4jBackend = bucket4jBackend;
    }

    // Define 10 requests per minute per IP
    public boolean tryConsume(String identifier) {
        return bucketCache.computeIfAbsent(identifier, key -> {
            Bandwidth limit = Bandwidth.classic(10, Duration.ofMinutes(1));
            return Bucket4j.builder()
                    .addLimit(limit)
                    .build(bucket4jBackend, key);
        }).tryConsume(1);
    }
}
```

> 🔥 **Note:** `identifier` could be `request.getRemoteAddr()`, or user ID, or API key.

