import javax.mail.*;
import javax.mail.internet.MimeMessage;
import java.io.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class SecureIMAPMailProcessor {

    // Use environment variables for sensitive data
    private static final String USERNAME = System.getenv("IMAP_USERNAME");
    private static final String PASSWORD = System.getenv("IMAP_PASSWORD");
    private static final String HOST = System.getenv("IMAP_HOST"); // e.g., "imap.gmail.com"
    private static final String PORT = System.getenv("IMAP_PORT");   // e.g., "993"
    private static final String STORE_PROTOCOL = "imaps"; // Use SSL

    // Regex pattern to extract numbers (digits only) from strings
    private static final Pattern NUMBER_PATTERN = Pattern.compile("\\d+");

    // Store results: subject_number -> message_body_number
    private static final Hashtable<String, String> numberMap = new Hashtable<>();

    public static void main(String[] args) {
        if (USERNAME == null || PASSWORD == null || HOST == null || PORT == null) {
            System.err.println("Error: Required environment variables (IMAP_USERNAME, IMAP_PASSWORD, IMAP_HOST, IMAP_PORT) are missing.");
            System.exit(1);
        }

        // Configure mail session
        Properties props = new Properties();
        props.setProperty("mail.store.protocol", STORE_PROTOCOL);
        props.setProperty("mail.imaps.host", HOST);
        props.setProperty("mail.imaps.port", PORT);
        props.setProperty("mail.imaps.ssl.enable", "true");
        props.setProperty("mail.imaps.ssl.trust", HOST); // Relax trust only for testing
        props.setProperty("mail.imaps.ssl.checkserveridentity", "true"); // Enable SSL identity check

        // Optional: disable hostname verification only for testing! 🔴 Avoid in production
        // props.setProperty("mail.imaps.ssl.trust", "*"); // NOT recommended

        try (Session session = Session.getInstance(props, null);
             Store store = session.getStore()) {

            // Connect to IMAP server
            System.out.println("Connecting to IMAP server...");
            store.connect(HOST, USERNAME, PASSWORD);

            // Open INBOX folder in read-only mode
            Folder inbox = store.getFolder("INBOX");
            inbox.open(Folder.READ_ONLY);

            Message[] messages = inbox.getMessages();

            System.out.println("Found " + messages.length + " messages.");

            for (Message message : messages) {
                if (message.getFlags().contains(Flags.Flag.SEEN)) {
                    continue; // Skip already read messages
                }

                String subject = message.getSubject();
                String body = extractTextFromMessage(message);

                String subjectNumber = extractNumberFromSubject(subject);
                String bodyNumber = extractNumberFromBody(body);

                if (subjectNumber != null && bodyNumber != null) {
                    System.out.println("Found match: Subject = " + subjectNumber + ", Body = " + bodyNumber);
                    numberMap.put(subjectNumber, bodyNumber);
                } else {
                    System.out.println("Skipping message: Subject='" + subject + "', Body='" + (body != null ? body.substring(0, Math.min(50, body.length())) : "") + "...");
                }
            }

            // Close folders and store
            inbox.close(false); // Do not expunge
            store.close();

            // Display result
            System.out.println("\n--- Stored Numbers ---");
            for (Map.Entry<String, String> entry : numberMap.entrySet()) {
                System.out.println("Subject: " + entry.getKey() + " → Body: " + entry.getValue());
            }

        } catch (MessagingException e) {
            System.err.println("Failed to connect or read emails: " + e.getMessage());
            e.printStackTrace();
        } catch (Exception e) {
            System.err.println("Unexpected error: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Extracts plain text content from a MimeMessage.
     */
    private static String extractTextFromMessage(Message message) throws MessagingException {
        Object content = message.getContent();

        if (content instanceof String) {
            return (String) content;
        } else if (content instanceof Multipart) {
            Multipart multipart = (Multipart) content;
            StringBuilder text = new StringBuilder();

            for (int i = 0; i < multipart.getCount(); i++) {
                BodyPart part = multipart.getBodyPart(i);
                if (part.isMimeType("text/plain")) {
                    text.append(part.getContent());
                } else if (part.isMimeType("text/html")) {
                    String html = (String) part.getContent();
                    text.append(HTMLToPlainText(html)); // Simple HTML to plain text
                }
            }
            return text.toString();
        } else {
            return content != null ? content.toString() : "";
        }
    }

    /**
     * Simple HTML to plain text converter (basic)
     */
    private static String HTMLToPlainText(String html) {
        // Remove HTML tags, preserve line breaks
        return html.replaceAll("<[^>]*>", "").replaceAll("\n", " ").replaceAll(" +", " ");
    }

    /**
     * Extracts number from subject (first sequence of digits)
     */
    private static String extractNumberFromSubject(String subject) {
        if (subject == null || subject.trim().isEmpty()) return null;
        Matcher matcher = NUMBER_PATTERN.matcher(subject);
        if (matcher.find()) {
            return matcher.group();
        }
        return null;
    }

    /**
     * Extracts number from message body (first sequence of digits)
     */
    private static String extractNumberFromBody(String body) {
        if (body == null || body.trim().isEmpty()) return null;
        Matcher matcher = NUMBER_PATTERN.matcher(body);
        if (matcher.find()) {
            return matcher.group();
        }
        return null;
    }
}
