import android.view.View;
import android.widget.Button;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;
import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;
import java.net.URI;

public class MainActivity extends AppCompatActivity {

    private WebSocketClient webSocketClient;
    private Button btnSend;
    private TextView tvStatus;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        btnSend = findViewById(R.id.btnSend);
        tvStatus = findViewById(R.id.tvStatus);

        // Подключение к WebSocket-серверу (замени на свой)
        URI uri = URI.create("ws://192.168.1.100:8080/ws"); // Замени на твой сервер

        webSocketClient = new WebSocketClient(uri) {
            @Override
            public void onOpen(ServerHandshake handshakedata) {
                runOnUiThread(() -> tvStatus.setText("Статус: Подключено"));
            }

            @Override
            public void onMessage(String message) {
                runOnUiThread(() -> tvStatus.setText("Получено: " + message));
            }

            @Override
            public void onClose(int code, String reason, boolean remote) {
                runOnUiThread(() -> tvStatus.setText("Статус: Отключено"));
            }

            @Override
            public void onError(Exception ex) {
                runOnUiThread(() -> tvStatus.setText("Ошибка: " + ex.getMessage()));
            }
        };

        btnSend.setOnClickListener(v -> {
            String msg = "Привет, сервер!";
            if (webSocketClient != null && webSocketClient.isOpen()) {
                webSocketClient.send(msg);
                tvStatus.setText("Отправлено: " + msg);
            } else {
                tvStatus.setText("Соединение закрыто. Попробуйте позже.");
            }
        });

        // Подключаемся при старте
        webSocketClient.connect();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (webSocketClient != null) {
            webSocketClient.close();
        }
    }
}
