    public void onMessage(WebSocket conn, String message) {
        System.out.println("Received: " + message);
    }

    @Override
    public void onError(WebSocket conn, Exception ex) {
        ex.printStackTrace();
    }

    // 启动帧流（每秒 30 帧，模拟真实流）
    private void startFrameStreaming(WebSocket conn) {
        scheduler.scheduleAtFixedRate(() -> {
            File imageFile = findNextFrameFile();
            if (imageFile == null) {
                conn.send("END_OF_STREAM");
                scheduler.shutdown();
                return;
            }

            try {
                // 使用 FFmpeg 将单张图片转为 H.264 帧（并输出到标准输出）
                ProcessBuilder pb = new ProcessBuilder(
                    ffmpegPath,
                    "-framerate", "30",                    // 每秒 30 帧
                    "-i", imageFile.getAbsolutePath(),    // 输入图像
                    "-c:v", "libx264",                    // H.264 编码
                    "-pix_fmt", "yuv420p",               // 兼容性好
                    "-f", "h264",                         // 输出为 H.264 二进制流
                    "-"                                   // 输出到 stdout
                );

                Process process = pb.start();

                // 读取 FFmpeg 输出的 H.264 数据
                try (InputStream is = process.getInputStream()) {
                    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
                    byte[] chunk = new byte[4096];
                    int bytesRead;
                    while ((bytesRead = is.read(chunk)) != -1) {
                        buffer.write(chunk, 0, bytesRead);
                    }

                    byte[] h264Data = buffer.toByteArray();

                    // 安全编码为 Base64（避免原始二进制传输错误）
                    String base64Frame = Base64.getEncoder().encodeToString(h264Data);

                    // 发送到客户端
                    conn.send("{\"type\":\"frame\",\"data\":\"" + base64Frame + "\"}");
                }

                // 等待 FFmpeg 结束
                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    System.err.println("FFmpeg failed with exit code: " + exitCode);
                }

            } catch (Exception e) {
                System.err.println("Error processing frame: " + e.getMessage());
                e.printStackTrace();
            }
        }, 0, 1000 / 30, TimeUnit.MILLISECONDS); // 每 33ms 一帧
    }

    // 查找下一个待处理的帧文件
    private File findNextFrameFile() {
        File[] files = imageDir.listFiles((dir, name) -> name.matches("^frame_\\d{3}\\.jpg$"));
        if (files == null || files.length == 0) return null;

        // 按文件名排序，取最小的（或模拟按顺序读取）
        File next = files[0];
        for (File file : files) {
            if (file.getName().compareTo(next.getName()) < 0) {
                next = file;
            }
        }
        return next;
    }

    public static void main(String[] args) {
        File imageDir = new File("./frames"); // 放图片的目录
        if (!imageDir.exists()) {
            System.err.println("Image directory not found: " + imageDir.getAbsolutePath());
            return;
        }

        int port = 8888;
        VideoFrameWebSocketServer server = new VideoFrameWebSocketServer(new InetSocketAddress(port), imageDir);
        server.start();
        System.out.println("WebSocket server started on ws://localhost:" + port);
    }
}
