// RateLimiterHandlerFilterFunction.java
package com.mediaworld.apimanager.configuration.redis;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.server.HandlerFilterFunction;
import org.springframework.web.reactive.function.server.HandlerFunction;
import org.springframework.web.reactive.function.server.ServerRequest;
import org.springframework.web.reactive.function.server.ServerResponse;
import reactor.core.publisher.Mono;

import java.net.InetSocketAddress;
import java.time.Duration;
import java.time.LocalTime;
import java.util.Optional;

import static org.springframework.http.HttpStatus.TOO_MANY_REQUESTS;

@Component
public class RateLimiterHandlerFilterFunction implements HandlerFilterFunction<ServerResponse, ServerResponse> {

    @Value("${MAX_REQUESTS_PER_MINUTE:20}")
    private Long maxRequestsPerMinute;

    private final ReactiveRedisTemplate<String, Long> redisTemplate;

    public RateLimiterHandlerFilterFunction(ReactiveRedisTemplate<String, Long> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @Override
    public Mono<ServerResponse> filter(ServerRequest request, HandlerFunction<ServerResponse> next) {
        int currentMinute = LocalTime.now().getMinute();
        String key = "rl_" + requestAddress(request.remoteAddress()) + ":" + currentMinute;

        return redisTemplate.opsForValue().get(key)
                .flatMap(count -> {
                    if (count != null && count >= maxRequestsPerMinute) {
                        return ServerResponse.status(TOO_MANY_REQUESTS).bodyValue("Rate limit exceeded");
                    }
                    return incrAndExpireKey(key, request, next);
                })
                .switchIfEmpty(incrAndExpireKey(key, request, next));
    }

    private String requestAddress(Optional<InetSocketAddress> maybeAddress) {
        return maybeAddress.map(InetSocketAddress::getHostName)
                .orElse("unknown");
    }

    private Mono<ServerResponse> incrAndExpireKey(String key, ServerRequest request, HandlerFunction<ServerResponse> next) {
        return redisTemplate.execute(new ReactiveRedisCallback<List<Object>>() {
            @Override
            public Publisher<List<Object>> doInRedis(ReactiveRedisConnection connection) throws DataAccessException {
                // Serialize key
                ByteBuffer bbKey = ByteBuffer.wrap(key.getBytes());

                return connection.numberCommands().incr(bbKey)
                        .then(connection.keyCommands().expire(bbKey, Duration.ofSeconds(59L)))
                        // Chain: After INCR and EXPIRE succeed, continue with next handler
                        .then(Mono.empty());
            }
        }).then(next.handle(request));
    }
}
```

