Here’s a Java program to **check a website’s TLS configuration**, including whether it uses **ephemeral Diffie-Hellman (DHE)** or **Elliptic Curve DHE (ECDHE)**, which are strong key exchange methods.

```java
import javax.net.ssl.*;
import java.io.*;
import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;
import java.util.Arrays;

public class TLSSiteChecker {

    public static void checkSite(String host, int port) {
        try {
            SSLContext context = SSLContext.getInstance("TLS");
            context.init(null, new TrustManager[]{new X509TrustManager() {
                public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {}
                public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {}
                public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
            }}, null);

            SSLSocketFactory factory = context.getSocketFactory();
            SSLSocket socket = (SSLSocket) factory.createSocket(host, port);

            // Enable only strong cipher suites (remove weak ones)
            String[] enabledCiphers = socket.getEnabledCipherSuites();
            socket.setEnabledCipherSuites(enabledCiphers);

            socket.startHandshake();

            // Get session info
            SSLSession session = socket.getSession();
            String cipherSuite = session.getCipherSuite();
            String protocol = session.getProtocol();

            System.out.println("Connected to: " + host + ":" + port);
            System.out.println("Protocol: " + protocol);
            System.out.println("Cipher Suite: " + cipherSuite);

            // Check for use of DHE/ECDHE (strong key exchange)
            boolean usesDHE = cipherSuite.contains("DHE") || cipherSuite.contains("ECDHE");
            if (usesDHE) {
                System.out.println("🔒 Strong key exchange (DHE/ECDHE) detected: " + cipherSuite);
            } else {
                System.out.println("⚠️  Weak or no ephemeral key exchange detected (no DHE/ECDHE).");
            }

            socket.close();

        } catch (Exception e) {
            System.err.println("Error connecting to " + host + ":" + port + " - " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java TLSSiteChecker <hostname> [port]");
            System.exit(1);
        }

        String host = args[0];
        int port = args.length > 1 ? Integer.parseInt(args[1]) : 443;

        checkSite(host, port);
    }
}
```

