```java
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Base64;

public class NfcEncryptor {

    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";
    private static final int IV_LENGTH = 12;
    private static final int TAG_LENGTH = 16;  // GCM tag length

    public static String encryptNfcData(String plaintext, byte[] key) throws Exception {
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, ALGORITHM);
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);

        // Generate random IV
        byte[] iv = new byte[IV_LENGTH];
        new SecureRandom().nextBytes(iv);
        GCMParameterSpec gcmParameterSpec = new GCMParameterSpec(TAG_LENGTH * 8, iv);

        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, gcmParameterSpec);

        byte[] ciphertext = cipher.doFinal(plaintext.getBytes("UTF-8"));

        // Combine: IV + Ciphertext + Auth Tag
        byte[] output = new byte[iv.length + ciphertext.length + TAG_LENGTH];
        System.arraycopy(iv, 0, output, 0, iv.length);
        System.arraycopy(ciphertext, 0, output, iv.length, ciphertext.length);
        System.arraycopy(cipher.getMAC(), 0, output, iv.length + ciphertext.length, TAG_LENGTH);

        return Base64.getEncoder().encodeToString(output);
    }

    public static void main(String[] args) {
        String plaintext = "A0123456|99999|XYZ";
        byte[] key = "0123456789abcdef".getBytes("UTF-8"); // 16 bytes

        try {
            String encryptedBase64 = encryptNfcData(plaintext, key);
            System.out.println("Encrypted data (Base64):");
            System.out.println(encryptedBase64);

            // Check size
            byte[] decoded = Base64.getDecoder().decode(encryptedBase64);
            System.out.println("Total bytes: " + decoded.length + " / 136 (within limit)");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
