import org.bytedeco.ffmpeg.*;
import org.bytedeco.ffmpeg.global.ffmpeg;

import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;

public class ImageToH264StreamServer {

    public static void main(String[] args) {
        final String imagePath = "test.jpg"; // 输入图片路径
        int port = 12345;

        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("服务器启动，等待客户端连接...");
            try (Socket clientSocket = serverSocket.accept();
                 OutputStream out = clientSocket.getOutputStream()) {

                System.out.println("客户端已连接，开始传输H.264流...");

                // Step 1: 初始化 FFmpeg 编码器 (H.264)
                AVFormatContext outputFormatContext = null;
                AVCodec codec = ffmpeg.avcodec_find_encoder(ffmpeg.AV_CODEC_ID_H264);
                if (codec == null) {
                    throw new RuntimeException("无法找到 H.264 编码器");
                }

                AVCodecContext codecContext = ffmpeg.avcodec_alloc_context3(codec);
                codecContext.width(640);
                codecContext.height(480);
                codecContext.time_base(new AVRational(1, 25)); // 25 fps
                codecContext.framerate(new AVRational(25, 1));
                codecContext.pix_fmt(ffmpeg.AV_PIX_FMT_YUV420P);
                codecContext.bit_rate(1000000);
                codecContext.gop_size(25); // I帧间隔

                ffmpeg.avcodec_open2(codecContext, codec, null);

                // Step 2: 读取图片并转换为 AVFrame
                AVFrame frame = ffmpeg.av_frame_alloc();
                AVPicture picture = new AVPicture();
                ffmpeg.avpicture_fill(picture, null, codecContext.pix_fmt(), codecContext.width(), codecContext.height());

                // 用 ImageIO 加载图像并转换为 YUV420P (简化处理，实际需使用 libswscale)
                BufferedImage img = javax.imageio.ImageIO.read(new File(imagePath));
                byte[] yuvData = convertToYUV420P(img, codecContext.width(), codecContext.height());

                // 复制像素数据到 frame
                for (int i = 0; i < yuvData.length; i++) {
                    picture.data(0).put(i, yuvData[i]); // Y plane
                }

                frame.format(codecContext.pix_fmt());
                frame.width(codecContext.width());
                frame.height(codecContext.height());
                frame.linesize(0, codecContext.width());

                // Step 3: 将帧编码为 H.264
                AVPacket packet = new AVPacket();
                ffmpeg.av_new_packet(packet, 1024 * 1024); // 分配缓冲区

                boolean success = ffmpeg.avcodec_send_frame(codecContext, frame) >= 0;

                // 编码循环
                while (success) {
                    int ret = ffmpeg.avcodec_receive_packet(codecContext, packet);
                    if (ret < 0) break;

                    // 发送 H.264 数据包（注意：包头可能需要添加起始码）
                    byte[] h264Data = new byte[packet.size()];
                    for (int i = 0; i < packet.size(); i++) {
                        h264Data[i] = packet.data().get(i);
                    }

                    // 添加 H.264 起始码 (0x00 00 00 01 or 0x00 00 01) —— 通常由编码器自动添加
                    if (h264Data.length > 0 && h264Data[0] != 0x00) {
                        // 有些编码器不自动添加，手动添加
                        byte[] wrapped = new byte[4 + h264Data.length];
                        wrapped[0] = 0x00;
                        wrapped[1] = 0x00;
                        wrapped[2] = 0x00;
                        wrapped[3] = 0x01;
                        System.arraycopy(h264Data, 0, wrapped, 4, h264Data.length);
                        h264Data = wrapped;
                    }

                    out.write(h264Data);
                    out.flush();

                    System.out.println("已发送 H.264 数据包，大小: " + h264Data.length + " 字节");
                    ffmpeg.av_packet_unref(packet);
                }

                // 清理资源
                ffmpeg.av_packet_unref(packet);
                ffmpeg.av_frame_unref(frame);
                ffmpeg.avcodec_free_context(codecContext);
                ffmpeg.av_frame_free(frame);
                ffmpeg.av_packet_unref(packet);

            } catch (Exception e) {
                e.printStackTrace();
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 简化转换：将 BufferedImage 转为 YUV420P (仅用于演示，实际应使用 libswscale)
    private static byte[] convertToYUV420P(BufferedImage image, int width, int height) {
        int size = width * height * 3 / 2;
        byte[] yuv = new byte[size];

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int rgb = image.getRGB(x, y);
                int r = (rgb >> 16) & 0xFF;
                int g = (rgb >> 8) & 0xFF;
                int b = rgb & 0xFF;

                // Y = 0.299R + 0.587G + 0.114B
                int yVal = (int) (0.299 * r + 0.587 * g + 0.114 * b);
                yVal = Math.max(0, Math.min(255, yVal));
                yuv[y * width + x] = (byte) yVal;

                // U = -0.147R - 0.289G + 0.436B + 128
                int uVal = (int) (-0.147 * r - 0.289 * g + 0.436 * b + 128);
                uVal = Math.max(0, Math.min(255, uVal));
                if (y % 2 == 0 && x % 2 == 0) {
                    int uIdx = width * height + (y / 2) * width / 2 + x / 2;
                    yuv[uIdx] = (byte) uVal;
                }

                // V = 0.436R - 0.368G - 0.068B + 128
                int vVal = (int) (0.436 * r - 0.368 * g - 0.068 * b + 128);
                vVal = Math.max(0, Math.min(255, vVal));
                if (y % 2 == 0 && x % 2 == 0) {
                    int vIdx = width * height + width * height / 4 + (y / 2) * width / 2 + x / 2;
                    yuv[vIdx] = (byte) vVal;
                }
            }
        }
        return yuv;
    }
}
```

> ⚠️ 注意：上述 `convertToYUV420P` 为简化版本，**仅用于演示**。生产环境应使用 `libswscale` 进行高效转换。

