import org.bytedeco.javacv.FFmpegFrameRecorder;
import org.bytedeco.javacv.Frame;
import org.bytedeco.javacv.FrameRecorder;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.File;

@Component
public class ImageToH264Stream {

    private final ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

    public byte[] imageToH264(BufferedImage image) throws Exception {
        // 将 BufferedImage 转为 Frame（JavaCV 的 Frame 类）
        Frame frame = new Frame(image);

        // 使用 FFmpeg 编码为 H.264
        FFmpegFrameRecorder recorder = new FFmpegFrameRecorder(outputStream, 640, 480);
        recorder.setFormat("h264");
        recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
        recorder.setVideoQuality(1);
        recorder.setFrameRate(25);
        recorder.setVideoBitrate(1000000); // 1 Mbps
        recorder.setAudioCodec(avcodec.AV_CODEC_ID_NONE);
        recorder.start();

        recorder.record(frame);
        recorder.stop();

        byte[] h264Data = outputStream.toByteArray();
        outputStream.reset(); // 清空 buffer，可复用

        return h264Data;
    }
}
```

> ✅ 说明：
> - `Frame` 是 JavaCV 的核心数据类型。
> - `FFmpegFrameRecorder` 可直接将 `Frame` 编码为 H.264。
> - 输出是原始 H.264 byte stream（可直接通过 Socket 发送）。

