#include <cstdlib>
#include <string>
#include <memory>
#include <cstring>
#include <iostream>
#include <vector>

#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xpath.h>
#include <libxml/xpathInternals.h>

#include "udf.h"
#include "udf_utils.h"

// 安全最大 XML 大小限制（如 1MB）
const size_t MAX_XML_SIZE = 1024 * 1024; // 1MB

/**
 * XML 解析 UDF：将 XML 字符串解析为 JSON 格式字符串（可选）
 * 输入: XML 字符串
 * 输出: JSON 字符串（表示 XML 结构）
 */
extern "C" {
    void xml_parse(const StringValue* input, StringValue* output, FunctionContext* context) {
        // 1. 输入检查
        if (!input || !input->data || input->len == 0) {
            output->len = 0;
            output->data = nullptr;
            return;
        }

        // 2. 防止 DoS：检查输入大小
        if (input->len > MAX_XML_SIZE) {
            context->set_error("XML input too large (> 1MB)");
            output->len = 0;
            output->data = nullptr;
            return;
        }

        // 3. 初始化 libxml2
        xmlDocPtr doc = xmlParseMemory(input->data, input->len);
        if (!doc) {
            context->set_error("Failed to parse XML");
            output->len = 0;
            output->data = nullptr;
            return;
        }

        // 4. 构建 JSON 输出（简易递归结构）
        std::string result = xml_node_to_json(doc->children);

        // 5. 设置输出
        output->data = static_cast<char*>(malloc(result.size() + 1));
        if (!output->data) {
            xmlFreeDoc(doc);
            context->set_error("Memory allocation failed");
            output->len = 0;
            return;
        }

        memcpy(output->data, result.c_str(), result.size());
        output->data[result.size()] = '\0';
        output->len = result.size();

        // 6. 清理
        xmlFreeDoc(doc);
    }

    // 递归将 xmlNode 转为 JSON（简化实现）
    std::string xml_node_to_json(xmlNodePtr node) {
        if (!node) return "null";

        std::string json = "{";
        std::string name = node->name ? reinterpret_cast<const char*>(node->name) : "root";

        // 添加标签名
        json += "\"tag\":\"" + name + "\"";

        // 添加属性
        xmlAttrPtr attr = node->properties;
        if (attr) {
            json += ",\"attributes\":{";
            bool first = true;
            while (attr) {
                std::string attr_name = reinterpret_cast<const char*>(attr->name);
                std::string attr_value = reinterpret_cast<const char*>(attr->children ? attr->children->content : NULL);
                if (!first) json += ",";
                json += "\"" + attr_name + "\":\"" + attr_value + "\"";
                first = false;
                attr = attr->next;
            }
            json += "}";
        }

        // 添加文本内容
        if (node->children && node->children->type == XML_TEXT_NODE) {
            std::string text = reinterpret_cast<const char*>(node->children->content);
            if (!text.empty()) {
                json += ",\"text\":\"" + text + "\"";
            }
        }

        // 添加子节点
        xmlNodePtr child = node->children;
        if (child) {
            std::string children_json = "[";
            bool first_child = true;
            while (child) {
                if (!first_child) children_json += ",";
                children_json += xml_node_to_json(child);
                first_child = false;
                child = child->next;
            }
            children_json += "]";
            json += ",\"children\":" + children_json;
        }

        json += "}";

        return json;
    }
}
```

> 💡 注：此实现为“简化版”JSON 输出，实际生产中应使用 `json11` 或 `nlohmann/json` 更安全地处理。

