```java
// UserClient.java
import javax.swing.*;
import java.io.*;
import java.net.Socket;
import java.nio.file.Files;
import java.util.Base64;

public class UserClient extends JFrame {
    private JTextField txtMessage;
    private JTextArea txtChat;
    private JButton btnSend, btnImage, btnFile;
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String userId = "USR_" + System.currentTimeMillis();
    private String chatFile;

    public UserClient(String serverHost, int port) {
        setupUI();
        connectToServer(serverHost, port);
        startListening();
    }

    private void setupUI() {
        setTitle("用户端 - 电商客服");
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        txtChat = new JTextArea();
        txtChat.setEditable(false);
        JScrollPane scroll = new JScrollPane(txtChat);
        add(scroll, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        txtMessage = new JTextField(30);
        btnSend = new JButton("发送");
        btnImage = new JButton("发送图片");
        btnFile = new JButton("发送文件");

        JPanel inputPanel = new JPanel(new FlowLayout());
        inputPanel.add(txtMessage);
        inputPanel.add(btnSend);
        inputPanel.add(btnImage);
        inputPanel.add(btnFile);

        bottom.add(txtMessage, BorderLayout.CENTER);
        bottom.add(inputPanel, BorderLayout.EAST);

        add(bottom, BorderLayout.SOUTH);

        btnSend.addActionListener(e -> sendMessage());
        btnImage.addActionListener(e -> sendImage());
        btnFile.addActionListener(e -> sendFile());
    }

    private void connectToServer(String host, int port) {
        try {
            socket = new Socket(host, port);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            // 发送连接请求
            Message req = new Message();
            req.setType(Message.Type.CONNECT_REQ);
            req.setSender(userId);
            out.writeObject(req);
            out.flush();

            // 30秒超时等待响应（阻塞）
            socket.setSoTimeout(30000);
            Message resp = (Message) in.readObject();
            if (resp.getType() == Message.Type.CONNECT_ACCEPT) {
                JOptionPane.showMessageDialog(this, "已连接客服！");
                loadChatHistory();
            } else if (resp.getType() == Message.Type.CONNECT_REJECT) {
                JOptionPane.showMessageDialog(this, "客服忙或已拒绝，稍后再试。");
                this.dispose();
            } else {
                JOptionPane.showMessageDialog(this, "连接失败：" + resp.getContent());
                this.dispose();
            }

        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "连接失败：\n" + e.getMessage(), "错误", JOptionPane.ERROR_MESSAGE);
            this.dispose();
        }
    }

    private void startListening() {
        new Thread(() -> {
            try {
                while (!socket.isClosed()) {
                    Message msg = (Message) in.readObject();
                    SwingUtilities.invokeLater(() -> appendMessage(msg));
                }
            } catch (IOException | ClassNotFoundException e) {
                SwingUtilities.invokeLater(() -> {
                    txtChat.append("\n[系统] 连接中断，客服已离线。\n");
                    btnSend.setEnabled(false);
                    btnImage.setEnabled(false);
                    btnFile.setEnabled(false);
                });
            }
        }).start();
    }

    private void sendMessage() {
        String text = txtMessage.getText().trim();
        if (text.isEmpty()) return;

        Message msg = new Message();
        msg.setType(Message.Type.TEXT);
        msg.setSender(userId);
        msg.setContent(text);

        try {
            out.writeObject(msg);
            out.flush();
            txtChat.append("我：" + text + "\n");
            txtMessage.setText("");
            saveMessage(msg); // 保存本地
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this, "发送失败：" + e.getMessage(), "错误", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            try {
                byte[] imageData = Files.readAllBytes(file.toPath());
                String base64 = Base64.getEncoder().encodeToString(imageData);

                Message msg = new Message();
                msg.setType(Message.Type.IMAGE);
                msg.setSender(userId);
                msg.setContent(base64);
                msg.setFilename(file.getName());

                out.writeObject(msg);
                out.flush();

                txtChat.append("我：[图片] " + file.getName() + "\n");
                saveMessage(msg);

            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "图片读取失败：" + e.getMessage());
            }
        }
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(file.toPath());
                Message msg = new Message();
                msg.setType(Message.Type.FILE);
                msg.setSender(userId);
                msg.setData(data);
                msg.setFilename(file.getName());

                out.writeObject(msg);
                out.flush();

                txtChat.append("我：[文件] " + file.getName() + "\n");
                saveMessage(msg);

            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "文件读取失败：" + e.getMessage());
            }
        }
    }

    private void appendMessage(Message msg) {
        // 仅展示文本或图像预览
        switch (msg.getType()) {
            case TEXT -> txtChat.append("客服：" + msg.getContent() + "\n");
            case IMAGE -> {
                String base64 = msg.getContent();
                ImageIcon icon = new ImageIcon(Base64.getDecoder().decode(base64));
                JLabel label = new JLabel(icon);
                label.setBorder(BorderFactory.createLineBorder(Color.GRAY, 1));
                txtChat.append("客服：[图片] " + msg.getFilename() + "\n");
                // 可加入 JDialog 显示大图（简化版：只显示提示）
            }
            case FILE -> txtChat.append("客服：[文件] " + msg.getFilename() + " (已接收)\n");
            case HEARTBEAT -> txtChat.append("系统：[客服在线]\n");
            default -> txtChat.append("系统：收到未知消息\n");
        }
        saveMessage(msg);
    }

    private void loadChatHistory() {
        chatFile = "chats/" + userId + ".log";
        File file = new File(chatFile);
        if (!file.exists()) return;

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                txtChat.append(line + "\n");
            }
        } catch (IOException e) {
            System.err.println("历史记录加载失败：" + e.getMessage());
        }
    }

    private void saveMessage(Message msg) {
        try (PrintWriter pw = new PrintWriter(new FileWriter(chatFile, true))) {
            String line = String.format("[%d] %s: %s", 
                msg.getTimestamp(), msg.getSender(), msg.getContent());
            pw.println(line);
        } catch (IOException e) {
            System.err.println("本地记录保存失败：" + e.getMessage());
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            new UserClient("localhost", 8888).setVisible(true);
        });
    }
}
