### 3. 客服端实现（`AgentServer.java`）

```java
// AgentServer.java
import javax.swing.*;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class AgentServer extends JFrame {
    private JTextArea txtLog;
    private JList<String> userList;
    private DefaultListModel<String> model;
    private ServerSocket serverSocket;
    private Map<String, ObjectOutputStream> userOutMap = new ConcurrentHashMap<>();
    private Map<String, String> userStatus = new ConcurrentHashMap<>();

    private Object lock = new Object();
    private volatile boolean running = true;

    public AgentServer(int port) {
        setupUI();
        startServer(port);
    }

    private void setupUI() {
        setTitle("客服端 - 电商平台");
        setSize(700, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        txtLog = new JTextArea();
        txtLog.setEditable(false);
        JScrollPane logScroll = new JScrollPane(txtLog);
        add(logScroll, BorderLayout.CENTER);

        model = new DefaultListModel<>();
        userList = new JList<>(model);
        JScrollPane listScroll = new JScrollPane(userList);
        add(listScroll, BorderLayout.EAST);

        JButton btnAccept = new JButton("接受");
        JButton btnReject = new JButton("拒绝");
        JButton btnSend = new JButton("发送");

        JPanel actions = new JPanel(new FlowLayout());
        actions.add(btnAccept);
        actions.add(btnReject);
        actions.add(btnSend);

        add(actions, BorderLayout.SOUTH);

        btnAccept.addActionListener(e -> {
            String selected = userList.getSelectedValue();
            if (selected != null && userStatus.containsKey(selected)) {
                String userId = selected.split(" - ")[0];
                acceptConnection(userId);
            }
        });

        btnReject.addActionListener(e -> {
            String selected = userList.getSelectedValue();
            if (selected != null) {
                String userId = selected.split(" - ")[0];
                rejectConnection(userId);
            }
        });

        btnSend.addActionListener(e -> {
            String selected = userList.getSelectedValue();
            if (selected == null) {
                JOptionPane.showMessageDialog(this, "请先选择一个用户");
                return;
            }
            String userId = selected.split(" - ")[0];
            sendText(userId, txtLog.getText());
        });
    }

    private void startServer(int port) {
        new Thread(() -> {
            try {
                serverSocket = new ServerSocket(port);
                log("客服端监听在端口 " + port);

                while (running) {
                    Socket client = serverSocket.accept();

                    // 新用户链接，触发弹窗
                    new Thread(() -> {
                        try (ObjectInputStream in = new ObjectInputStream(client.getInputStream());
                             ObjectOutputStream out = new ObjectOutputStream(client.getOutputStream())) {

                            Message req = (Message) in.readObject();
                            if (req.getType() == Message.Type.CONNECT_REQ) {
                                String userId = req.getSender();
                                log("收到新用户连接请求：" + userId);

                                synchronized (lock) {
                                    userStatus.put(userId, "pending");
                                    model.addElement(userId + " - 等待响应");
                                }

                                // 提示用户确认
                                int choice = JOptionPane.showConfirmDialog(this,
                                    "用户 " + userId + " 请求服务，是否接受？",
                                    "新连接", JOptionPane.YES_NO_OPTION);

                                if (choice == JOptionPane.YES_OPTION) {
                                    acceptConnection(userId);
                                    userOutMap.put(userId, out);
                                    sendToUser(userId, new Message(Message.Type.CONNECT_ACCEPT, "客服已连接"));
                                } else {
                                    rejectConnection(userId);
                                    sendToUser(userId, new Message(Message.Type.CONNECT_REJECT, "客服繁忙"));
                                }
                            }

                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                    }).start();
                }

            } catch (IOException e) {
                log("服务器启动失败：" + e.getMessage());
            }
        }).start();
    }

    private void acceptConnection(String userId) {
        userStatus.put(userId, "active");
        model.setElementAt(userId + " - 服务中", model.indexOf(userId + " - 等待响应"));
        log("已接受用户 " + userId);
        sendHeartbeat(userId);
    }

    private void rejectConnection(String userId) {
        userStatus.put(userId, "rejected");
        model.setElementAt(userId + " - 已拒绝", model.indexOf(userId + " - 等待响应"));
        userStatus.remove(userId);
        log("已拒绝用户 " + userId);
    }

    private void sendToUser(String userId, Message msg) {
        try {
            ObjectOutputStream out = userOutMap.get(userId);
            if (out != null) {
                out.writeObject(msg);
                out.flush();
            }
        } catch (IOException e) {
            log("向 " + userId + " 发送失败：" + e.getMessage());
            userOutMap.remove(userId);
            model.removeElement(userId + " - 服务中");
        }
    }

    private void sendText(String userId, String text) {
        Message msg = new Message();
        msg.setType(Message.Type.TEXT);
        msg.setSender("AGENT");
        msg.setContent(text);
        sendToUser(userId, msg);
    }

    private void sendHeartbeat(String userId) {
        new Thread(() -> {
            while (userStatus.containsKey(userId) && userStatus.get(userId).equals("active")) {
                // 每10秒发送一次心跳
                try {
                    Thread.sleep(10000);
                    sendToUser(userId, new Message(Message.Type.HEARTBEAT, null));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }).start();
    }

    private void log(String text) {
        String timestamp = new java.text.SimpleDateFormat("HH:mm:ss").format(new java.util.Date());
        txtLog.append("[" + timestamp + "] " + text + "\n");
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            new AgentServer(8888).setVisible(true);
        });
    }
}
```

