```java
import java.io.*;
import java.net.*;
import java.util.ArrayList;
import java.util.List;

public class ImageServer {
    private static final int PORT = 8888;
    private List<String> receivedImageFilenames = new ArrayList<>();

    public static void main(String[] args) {
        new ImageServer().start();
    }

    public void start() {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("服务器启动，监听端口 " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("客户端已连接: " + clientSocket.getInetAddress());

                new Thread(() -> handleClient(clientSocket)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void handleClient(Socket clientSocket) {
        try (ObjectInputStream ois = new ObjectInputStream(clientSocket.getInputStream());
             ObjectOutputStream oos = new ObjectOutputStream(clientSocket.getOutputStream())) {

            // 接收图片数量
            int numImages = ois.readInt();
            System.out.println("接收到 " + numImages + " 张图片");

            for (int i = 0; i < numImages; i++) {
                String filename = (String) ois.readObject();
                int fileLength = ois.readInt();

                // 限制单张图片大小（防止 DoS）
                if (fileLength > 10 * 1024 * 1024) { // 10MB
                    System.out.println("图片过大，拒绝接收: " + filename);
                    oos.writeObject("ERROR: File too large");
                    return;
                }

                byte[] imageData = new byte[fileLength];
                int totalRead = 0;
                while (totalRead < fileLength) {
                    int read = ois.read(imageData, totalRead, fileLength - totalRead);
                    if (read == -1) break;
                    totalRead += read;
                }

                if (totalRead != fileLength) {
                    System.out.println("图片传输不完整: " + filename);
                    oos.writeObject("ERROR: Incomplete image");
                    continue;
                }

                // 保存图片（安全路径 + 校验扩展名）
                String safeFilename = sanitizeFilename(filename);
                try (FileOutputStream fos = new FileOutputStream("received/" + safeFilename)) {
                    fos.write(imageData);
                }
                receivedImageFilenames.add(safeFilename);
                System.out.println("成功保存图片: " + safeFilename);
            }

            oos.writeObject("SUCCESS: All images received");
            oos.flush();

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            try {
                clientSocket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    // 安全过滤文件名（防止路径遍历）
    private String sanitizeFilename(String filename) {
        if (filename == null || filename.isEmpty()) return "unknown.jpg";
        String clean = filename.replaceAll("[^a-zA-Z0-9._-]", "_");
        clean = clean.replace("..", "_"); // 防止 .. 路径遍历
        // 限制扩展名
        if (!clean.matches(".*\\.(jpg|jpeg|png|gif|bmp|webp)$")) {
            clean += ".jpg";
        }
        return clean;
    }
}
```

