import java.io.*;
import java.net.*;
import java.util.Arrays;

public class ImageClient {
    private static final String SERVER_IP = "127.0.0.1";
    private static final int PORT = 8888;

    public static void main(String[] args) {
        new ImageClient().sendImages();
    }

    public void sendImages() {
        try (Socket socket = new Socket(SERVER_IP, PORT);
             ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
             ObjectInputStream ois = new ObjectInputStream(socket.getInputStream())) {

            File imagesDir = new File("images");
            File[] imageFiles = imagesDir.listFiles((dir, name) ->
                name.toLowerCase().matches(".*\\.(jpg|jpeg|png|gif|bmp|webp)$"));

            if (imageFiles == null || imageFiles.length == 0) {
                System.out.println("未找到图片文件");
                return;
            }

            // 发送图像数量
            oos.writeInt(imageFiles.length);
            oos.flush();

            for (File file : imageFiles) {
                String filename = file.getName();
                byte[] imageData = readFileToBytes(file);

                oos.writeObject(filename);
                oos.writeInt(imageData.length);
                oos.write(imageData);
                oos.flush();
                System.out.println("已发送: " + filename);
            }

            // 等待服务端响应
            String response = (String) ois.readObject();
            System.out.println("服务器响应: " + response);

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

    private byte[] readFileToBytes(File file) throws IOException {
        try (FileInputStream fis = new FileInputStream(file)) {
            return fis.readAllBytes();
        }
    }
}
