     */
    public synchronized String getDateLastReviewByUser(String username, int idHotel) {
        if (username == null || idHotel <= 0) {
            return "";
        }

        String existingDate = "";
        String existingUsername = "";
        int existingIdHotel = -1;
        String fieldName = "";

        try (JsonReader jsonReader = new JsonReader(new FileReader(REVIEW_FILE_PATH))) {
            jsonReader.beginArray();

            while (jsonReader.hasNext()) {
                jsonReader.beginObject();

                while (jsonReader.hasNext()) {
                    fieldName = jsonReader.nextName();
                    switch (fieldName) {
                        case "username":
                            existingUsername = jsonReader.nextString();
                            break;
                        case "idHotel":
                            existingIdHotel = jsonReader.nextInt();
                            break;
                        case "dateTime":
                            if (existingUsername.equalsIgnoreCase(username) && existingIdHotel == idHotel) {
                                existingDate = jsonReader.nextString();
                            } else {
                                jsonReader.skipValue();
                            }
                            break;
                        default:
                            jsonReader.skipValue();
                            break;
                    }
                }
                jsonReader.endObject();
            }

            jsonReader.endArray();

        } catch (IOException e) {
            System.err.println("Errore di lettura del file: " + e.getMessage());
            return "";
        }

        return existingDate;
    }

    /**
     * Legge un array di 4 valori interi (punteggi singoli) dal reader JSON.
     * Metodo privato utilizzato per gestire il campo {@code singleScores} nel JSON.
     * 
     * <p><strong>Validazione</strong>: non controlla il valore dei punteggi, ma può sollevare
     * {@link IOException} se il JSON non è valido (es. array non numerico, troppi valori).
     * 
     * @param jsonReader reader JSON da cui leggere l'array dei punteggi.
     * @return array di 4 interi.
     * @throws IOException se il JSON non è valido o non contiene 4 valori numerici.
     */
    private int[] readRatingList(JsonReader jsonReader) throws IOException {
        int[] ratings = new int[4];
        jsonReader.beginArray();

        for (int i = 0; i < 4; i++) {
            ratings[i] = jsonReader.nextInt();
        }

        jsonReader.endArray();
        return ratings;
    }
}
