package com.example.socket.netty;

import io.netty.channel.ChannelInitializer;
import io.netty.channel.ChannelPipeline;
import io.netty.channel.socket.SocketChannel;
import io.netty.handler.codec.LengthFieldBasedFrameDecoder;
import io.netty.handler.codec.LengthFieldPrepender;
import io.netty.handler.codec.string.StringDecoder;
import io.netty.handler.codec.string.StringEncoder;
import io.netty.handler.timeout.IdleStateHandler;
import io.netty.util.CharsetUtil;

public class SocketChannelInitializer extends ChannelInitializer<SocketChannel> {

    private final int maxFrameLength;
    private final int readTimeoutSeconds;
    private final int writeTimeoutSeconds;

    public SocketChannelInitializer(int maxFrameLength, int readTimeoutSeconds, int writeTimeoutSeconds) {
        this.maxFrameLength = maxFrameLength;
        this.readTimeoutSeconds = readTimeoutSeconds;
        this.writeTimeoutSeconds = writeTimeoutSeconds;
    }

    @Override
    protected void initChannel(SocketChannel ch) {
        ChannelPipeline pipeline = ch.pipeline();

        // 防止缓冲区溢出：基于长度字段的解码器
        pipeline.addLast(new LengthFieldBasedFrameDecoder(
            maxFrameLength, // max frame length
            0, // length field offset
            4, // length field length (int)
            0, // length adjust
            4  // initial bytes to strip
        ));

        // 加密/编码器
        pipeline.addLast(new StringDecoder(CharsetUtil.UTF_8));
        pipeline.addLast(new StringEncoder(CharsetUtil.UTF_8));

        // 空闲超时（防止僵尸连接）
        pipeline.addLast(new IdleStateHandler(
            readTimeoutSeconds,
            writeTimeoutSeconds,
            0
        ));

        // 自定义处理器
        pipeline.addLast(new SocketHandler());
    }
}
```

