package com.example.socket.netty;

import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInboundHandlerAdapter;
import io.netty.handler.timeout.IdleStateEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class SocketHandler extends ChannelInboundHandlerAdapter {

    private static final Logger logger = LoggerFactory.getLogger(SocketHandler.class);

    // 安全：防止注入、脚本等恶意输入
    private static final String[] BAD_PATTERNS = {
        "eval", "exec", "system", "cmd", "bash", "sh", "java", "<script>", "<iframe>",
        "document", "window", "onload", "onerror", "base64"
    };

    @Override
    public void channelRead(ChannelHandlerContext ctx, Object msg) {
        String received = (String) msg;
        logger.info("Received from {}: {}", ctx.channel().remoteAddress(), received);

        // 🔒 安全检查：检测恶意输入
        if (isMaliciousInput(received)) {
            logger.warn("Blocked malicious input from {}: {}", ctx.channel().remoteAddress(), received);
            ctx.channel().writeAndFlush("ERROR: Malicious input detected.\n");
            ctx.close();
            return;
        }

        // ✅ 正常处理：打印或转发
        ctx.writeAndFlush("RECEIVED: " + received.length() + " bytes -> " + received + "\n");

        // 防止日志泄露敏感信息
        // if (received.contains("password") || received.contains("token")) log.warn("Potential sensitive data");
    }

    private boolean isMaliciousInput(String input) {
        if (input == null || input.isEmpty()) return false;
        String lower = input.toLowerCase();
        for (String bad : BAD_PATTERNS) {
            if (lower.contains(bad)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
        if (evt instanceof IdleStateEvent) {
            logger.warn("Idle timeout from {}: {}", ctx.channel().remoteAddress(), evt);
            ctx.close();
        }
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
        logger.error("Unexpected exception from {}: {}", ctx.channel().remoteAddress(), cause.getMessage(), cause);
        ctx.close();
    }

    @Override
    public void channelInactive(ChannelHandlerContext ctx) {
        logger.info("Client disconnected: {}", ctx.channel().remoteAddress());
    }
}
```

