## 6. `netty/NettyServer.java`（启动类）

```java
package com.example.socket.netty;

import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelOption;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Component
public class NettyServer {

    private static final Logger logger = LoggerFactory.getLogger(NettyServer.class);

    private final int port;
    private final int maxConnections;
    private final int readTimeoutSeconds;
    private final int writeTimeoutSeconds;
    private final int maxFrameLength;

    private ChannelFuture channelFuture;
    private EventLoopGroup bossGroup;
    private EventLoopGroup workerGroup;

    public NettyServer(int port, int maxConnections, int readTimeoutSeconds, int writeTimeoutSeconds, int maxFrameLength) {
        this.port = port;
        this.maxConnections = maxConnections;
        this.readTimeoutSeconds = readTimeoutSeconds;
        this.writeTimeoutSeconds = writeTimeoutSeconds;
        this.maxFrameLength = maxFrameLength;
    }

    public void start() {
        bossGroup = new NioEventLoopGroup(1);
        workerGroup = new NioEventLoopGroup();

        try {
            ServerBootstrap bootstrap = new ServerBootstrap();
            bootstrap.group(bossGroup, workerGroup)
                     .channel(NioServerSocketChannel.class)
                     .childHandler(new SocketChannelInitializer(maxFrameLength, readTimeoutSeconds, writeTimeoutSeconds))
                     .option(ChannelOption.SO_BACKLOG, maxConnections)
                     .childOption(ChannelOption.SO_KEEPALIVE, true)
                     .childOption(ChannelOption.TCP_NODELAY, true)
                     .childOption(ChannelOption.CONNECT_TIMEOUT_MILLIS, 30000);

            channelFuture = bootstrap.bind(port).sync();

            logger.info("Socket server started on port {}", port);
        } catch (Exception e) {
            logger.error("Failed to start Netty server", e);
            stop();
        }
    }

    public void stop() {
        if (channelFuture != null) {
            channelFuture.channel().closeFuture().syncUninterruptibly();
        }

        if (bossGroup != null) bossGroup.shutdownGracefully();
        if (workerGroup != null) workerGroup.shutdownGracefully();

        logger.info("Socket server stopped");
    }
}
```

