   → Prevent information leakage (e.g., stack traces).

4. **Use of Secure HTTP Methods**  
   → Prefer `GET` or `POST` appropriately.

5. **No Hardcoded Credentials or Secrets**  
   → Not applicable here, but good practice.

6. **Avoid Untrusted Libraries**  
   → Use only standard JDK classes.

---

## ✅ **Secure Implementation: Temperature Converter Servlet**

```java
// TemperatureConverterServlet.java
package com.example.security;

import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.regex.Pattern;

@WebServlet("/convert")
public class TemperatureConverterServlet extends HttpServlet {

    // Regex to validate valid floating-point numbers (supports integers, decimals, negatives)
    private static final Pattern VALID_CELSIUS_REGEX = Pattern.compile("^-?\\d+(\\.\\d+)?$");

    private static final int MAX_INPUT_LENGTH = 20; // Prevent buffer overflow or DoS
    private static final double MAX_CELSIUS = 1000.0;
    private static final double MIN_CELSIUS = -1000.0;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // 1. Only allow GET methods (for simplicity and safety)
        // 2. Extract parameter
        String celsiusStr = request.getParameter("celsius");

        if (celsiusStr == null || celsiusStr.isEmpty()) {
            sendError(response, "Missing required parameter: celsius", 400);
            return;
        }

        // 3. Validate input length
        if (celsiusStr.length() > MAX_INPUT_LENGTH) {
            sendError(response, "Input too long", 400);
            return;
        }

        // 4. Validate format with regex (prevent injection, malformed floats)
        if (!VALID_CELSIUS_REGEX.matcher(celsiusStr).matches()) {
            sendError(response, "Invalid temperature format", 400);
            return;
        }

        // 5. Parse and validate numeric range
        double celsius;
        try {
            celsius = Double.parseDouble(celsiusStr);
            if (Double.isInfinite(celsius) || Double.isNaN(celsius)) {
                sendError(response, "Invalid numeric value", 400);
                return;
            }
            if (celsius > MAX_CELSIUS || celsius < MIN_CELSIUS) {
                sendError(response, "Temperature out of valid range (-1000 to 1000)", 400);
                return;
            }
        } catch (NumberFormatException e) {
            sendError(response, "Invalid number format", 400);
            return;
        }

        // 6. Perform conversion safely
        double fahrenheit = (celsius * 9.0 / 5.0) + 32.0;

        // 7. Respond safely with JSON (to avoid XSS)
        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");

        PrintWriter out = response.getWriter();
        out.print("{\"celsius\":" + celsius + ",\"fahrenheit\":" + String.format("%.2f", fahrenheit) + "}");
        out.flush();
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // Forward POST to GET handling for consistency
        // This is secure as long as we validate properly
        doGet(request, response);
    }

    private void sendError(HttpServletResponse response, String message, int statusCode) throws IOException {
        response.setStatus(statusCode);
        response.setContentType("application/json");
        PrintWriter out = response.getWriter();
        out.print("{\"error\":\"" + message + "\"}");
        out.flush();
    }
}
```

