### 💻 Java 代码：JSON 转 XML（安全实现）

```java
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.io.StringWriter;
import java.util.Objects;

/**
 * 安全的 JSON 转 XML 工具类（安全研究员视角）
 *
 * @author Security Researcher
 * @since 2025
 */
public class JsonToXmlConverter {

    private static final Logger logger = LoggerFactory.getLogger(JsonToXmlConverter.class);

    // 安全的 XML Mapper，禁用外部实体和 DTD
    private static final XmlMapper xmlMapper = new XmlMapper();

    static {
        // 🔒 禁用外部实体（防止 XXE 攻击）
        xmlMapper.configure(ToXmlGenerator.Feature.WRITE_XML_DECLARATION, true);
        xmlMapper.configure(ToXmlGenerator.Feature.AUTOMATIC_NS_PREFIXES, true);

        // 🔒 禁用 DOCTYPE 声明和外部实体（关键安全设置）
        xmlMapper.disable(com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator.Feature.WRITE_DOCDECL);
        xmlMapper.disable(com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator.Feature.WRITE_XML_DECLARATION);

        // 更进一步：防止 XXE（XML External Entity）注入
        try {
            javax.xml.parsers.SAXParserFactory.newInstance()
                    .newSAXParser()
                    .getXMLReader()
                    .setEntityResolver((publicId, systemId) -> {
                        logger.warn("Blocked external entity resolution: Public ID={}, System ID={}", publicId, systemId);
                        return null;
                    });
        } catch (Exception e) {
            logger.error("Failed to configure XML entity resolver.", e);
        }

        logger.info("JsonToXmlConverter initialized with XXE protection enabled.");
    }

    /**
     * 将 JSON 字符串转换为 XML 字符串
     *
     * @param json JSON 输入字符串
     * @return 转换后的 XML 字符串，如果失败返回 null
     */
    public static String toJsonXml(String json) {
        if (json == null || json.trim().isEmpty()) {
            logger.warn("Empty or null JSON input received.");
            return null;
        }

        // 🛡️ 输入验证：检查是否是合法 JSON
        if (!isJsonValid(json)) {
            logger.warn("Invalid JSON input: {}", json);
            return null;
        }

        StringWriter writer = new StringWriter();
        try {
            // 使用 Jackson 的 XML 映射器进行转换
            xmlMapper.writeValue(writer, jsonMapper.readValue(json, Object.class));
            String result = writer.toString();

            // ✅ 安全性检查：确保不包含危险内容（如恶意实体）
            if (containsMaliciousXml(result)) {
                logger.error("Detected potentially malicious XML content after conversion.");
                return null;
            }

            logger.debug("Successfully converted JSON to XML.\nOutput:\n{}", result);
            return result;

        } catch (IOException e) {
            logger.error("IO Exception during JSON to XML conversion.", e);
            return null;
        } finally {
            try {
                writer.close();
            } catch (IOException e) {
                logger.warn("Failed to close StringWriter.", e);
            }
        }
    }

    /**
     * 验证 JSON 字符串是否有效（简单检查）
     *
     * @param json JSON 字符串
     * @return true if valid
     */
    private static boolean isJsonValid(String json) {
        try {
            // 仅做语法验证，不处理复杂结构
            ObjectMapper jsonMapper = new ObjectMapper();
            jsonMapper.readTree(json);
            return true;
        } catch (Exception e) {
            logger.debug("JSON invalid: {}", json);
            return false;
        }
    }

    /**
     * 检查生成的 XML 是否可能包含恶意内容（如 ENTITY 声明）
     *
     * @param xml XML 字符串
     * @return true if malicious content detected
     */
    private static boolean containsMaliciousXml(String xml) {
        String upper = xml.toUpperCase();
        return upper.contains("<!ENTITY") || upper.contains("<!DOCTYPE")
                || upper.contains("<!ELEMENT") || upper.contains("SYSTEM");
    }

    /**
     * 主函数：演示使用
     */
    public static void main(String[] args) {
        // 测试用例
        String json1 = "{ \"name\": \"Alice\", \"age\": 30, \"hobbies\": [\"reading\", \"coding\"] }";
        String json2 = "{\"data\":{\"user\":\"admin\",\"token\":\"12345\"}}";

        System.out.println("=== JSON to XML Conversion (Safety-First) ===\n");

        System.out.println("Input: " + json1);
        String xml1 = toJsonXml(json1);
        System.out.println("Output: " + xml1 + "\n");

        System.out.println("Input: " + json2);
        String xml2 = toJsonXml(json2);
        System.out.println("Output: " + xml2 + "\n");

        // 恶意输入测试（用于验证安全防护）
        String maliciousJson = "{ \"name\": \"<script>alert('XSS')</script>\" }";
        System.out.println("Malicious JSON (should be cleaned): " + maliciousJson);
        String maliciousXml = toJsonXml(maliciousJson);
        System.out.println("Output: " + maliciousXml + "\n");

        // 注意：安全措施防止 XML 注入，但 JSON 结构本身仍需验证
    }
}
```

