package com.example.demo.controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.UUID;

@RestController
public class FileUploadController {

    @Value("${upload.dir:uploads}")
    private String uploadDir;

    // Allowed file extensions (whitelist)
    private static final String[] ALLOWED_EXTENSIONS = {
        "jpg", "jpeg", "png", "gif", "pdf", "doc", "docx"
    };

    // Max file size: 10MB
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024;

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        // Check if file is empty
        if (file.isEmpty()) {
            return ResponseEntity.badRequest().body("File is empty.");
        }

        // Check file size
        if (file.getSize() > MAX_FILE_SIZE) {
            return ResponseEntity.status(413).body("File too large. Max size: 10MB.");
        }

        // Validate file extension
        String originalFilename = file.getOriginalFilename();
        if (originalFilename == null) {
            return ResponseEntity.badRequest().body("Invalid file name.");
        }

        String extension = getFileExtension(originalFilename).toLowerCase();
        boolean validExtension = false;
        for (String allowed : ALLOWED_EXTENSIONS) {
            if (allowed.equalsIgnoreCase(extension)) {
                validExtension = true;
                break;
            }
        }

        if (!validExtension) {
            return ResponseEntity.status(400).body("Invalid file type. Only images and documents are allowed.");
        }

        // Generate a unique filename to prevent collisions and tampering
        String uniqueFilename = UUID.randomUUID() + "." + extension;
        Path destination = Paths.get(uploadDir, uniqueFilename);

        // Ensure upload directory exists
        try {
            Files.createDirectories(destination.getParent());
        } catch (IOException e) {
            return ResponseEntity.internalServerError().body("Failed to create upload directory.");
        }

        // Save file securely
        try {
            Files.copy(file.getInputStream(), destination, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            return ResponseEntity.internalServerError().body("Failed to save file: " + e.getMessage());
        }

        return ResponseEntity.ok("File uploaded successfully: " + uniqueFilename);
    }

    private String getFileExtension(String filename) {
        int lastIndexOf = filename.lastIndexOf(".");
        if (lastIndexOf == -1) {
            return ""; // No extension
        }
        return filename.substring(lastIndexOf + 1);
    }
}
```

