import java.util.*;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class Sondage {
    private final List<String> candidats;
    private final Map<String, Integer> votes; // Vote par candidat (String -> int)
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public Sondage(List<String> candidats) {
        this.candidats = new ArrayList<>(candidats);
        this.votes = new HashMap<>();
        candidats.forEach(c -> votes.put(c, 0));
    }

    // Récupérer la liste des candidats
    public synchronized List<String> getCandidats() {
        return new ArrayList<>(candidats);
    }

    // Voter pour un candidat (par index)
    public synchronized boolean voter(int index) {
        if (index < 0 || index >= candidats.size()) {
            return false;
        }
        String candidat = candidats.get(index);
        votes.merge(candidat, 1, Integer::sum);
        return true;
    }

    // Récupérer le gagnant (le plus voté)
    public synchronized String getResultat() {
        return votes.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse("Aucun vote");
    }

    // Pour debug : afficher les votes
    public synchronized void afficherVotes() {
        votes.forEach((c, v) -> System.out.println(c + " : " + v + " voix"));
    }

    // Retourne le nombre de votes par candidat
    public synchronized Map<String, Integer> getVotes() {
        return new HashMap<>(votes);
    }
}
```

> 🔒 **Sécurité appliquée** :
> - `synchronized` sur les méthodes critiques.
> - `ReentrantReadWriteLock` **optionnel**, ici on utilise `synchronized` car simple, mais peut être remplacé par un `ReadWriteLock` pour améliorer les performances en lecture.
> - **Validation des index**.
> - **Pas de modification directe** du `List<String>` ou `Map<String, Integer>` extérieurs.

