import java.io.*;
import java.net.Socket;
import java.util.concurrent.atomic.AtomicBoolean;

public class GestionnaireClient implements Runnable {
    private final Socket clientSocket;
    private final Sondage sondage;

    public GestionnaireClient(Socket clientSocket, Sondage sondage) {
        this.clientSocket = clientSocket;
        this.sondage = sondage;
    }

    @Override
    public void run() {
        try (
            BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
            PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true)
        ) {
            String commande;
            while ((commande = in.readLine()) != null) {
                System.out.println("Commande reçue : " + commande);

                // Traitement des commandes
                if (commande.trim().equalsIgnoreCase("candidats")) {
                    out.println("OK");
                    for (String candidat : sondage.getCandidats()) {
                        out.println(candidat);
                    }
                } else if (commande.startsWith("vote ")) {
                    String[] parts = commande.split(" ", 2);
                    if (parts.length != 2) {
                        out.println("ERR");
                        continue;
                    }

                    try {
                        int index = Integer.parseInt(parts[1]);
                        if (sondage.voter(index)) {
                            out.println("OK");
                        } else {
                            out.println("ERR");
                        }
                    } catch (NumberFormatException e) {
                        out.println("ERR");
                    }
                } else if (commande.trim().equalsIgnoreCase("resultat")) {
                    String gagnant = sondage.getResultat();
                    out.println("OK");
                    out.println(gagnant);
                } else {
                    out.println("ERR");
                }
            }

        } catch (IOException e) {
            System.err.println("Erreur client : " + e.getMessage());
        } finally {
            try {
                clientSocket.close();
            } catch (IOException e) {
                System.err.println("Erreur lors de la fermeture du socket client");
            }
        }
    }
}
```

> 🔒 **Sécurité et robustesse** :
> - Utilisation de `try-with-resources` pour fermer ressources.
> - Vérification des formats de commandes.
> - `NumberFormatException` attrapé pour éviter crash.
> - `AtomicBoolean` non nécessaire ici car mutex interne est suffisant.

