public class Client {
    private final String host;
    private final int port;
    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;

    public Client(String host, int port) {
        this.host = host;
        this.port = port;
    }

    public void connecter() throws IOException {
        socket = new Socket(host, port);
        in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        out = new PrintWriter(socket.getOutputStream(), true);
        System.out.println("Connecté au serveur.");
    }

    public void envoyerCommande(String commande) {
        out.println(commande);
        try {
            String reponse = in.readLine();
            System.out.println("Serveur : " + reponse);

            if (reponse.equals("OK")) {
                if (commande.startsWith("candidats")) {
                    String line;
                    while (!(line = in.readLine()).isEmpty()) {
                        System.out.println("→ " + line);
                    }
                } else if (commande.startsWith("resultat")) {
                    String gagnant = in.readLine();
                    System.out.println("👉 Gagnant : " + gagnant);
                }
            } else if (reponse.equals("ERR")) {
                System.err.println("❌ Erreur serveur.");
            }
        } catch (IOException e) {
            System.err.println("Erreur lecture réponse : " + e.getMessage());
        }
    }

    public void fermer() {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (IOException e) {
            System.err.println("Erreur de fermeture du client : " + e.getMessage());
        }
    }

