        if (context == null) throw new IllegalArgumentException("Context cannot be null");
        if (serverHost == null || serverHost.isEmpty()) throw new IllegalArgumentException("Server host cannot be null or empty");
        if (serverPort <= 0 || serverPort > 65535) throw new IllegalArgumentException("Invalid port: " + serverPort);

        this.context = context.getApplicationContext();
        this.serverHost = serverHost;
        this.serverPort = serverPort;
        this.socketTimeoutMs = socketTimeoutMs;
    }

    /**
     * Establishes a secure SSL/TLS connection to the remote server.
     * @throws IOException if connection fails due to network, timeout, or SSL errors
     */
    public void connect() throws IOException {
        if (sslSocket != null && !sslSocket.isClosed()) {
            throw new IOException("Already connected");
        }

        try {
            // Initialize SSL context with custom trust manager (certificate pinning)
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, new TrustManager[]{new PinnedTrustManager()}, null);

            SSLSocketFactory factory = sslContext.getSocketFactory();
            sslSocket = (SSLSocket) factory.createSocket();

            // Configure socket
            InetSocketAddress address = new InetSocketAddress(serverHost, serverPort);
            sslSocket.connect(address, socketTimeoutMs);
            sslSocket.setSoTimeout(socketTimeoutMs);

            // Enable only secure protocols (disable SSLv3, TLS 1.0, 1.1)
            String[] supportedProtocols = sslSocket.getSupportedProtocols();
            List<String> secureProtocols = Arrays.asList("TLSv1.2", "TLSv1.3");
            List<String> enabledProtocols = secureProtocols.stream()
                    .filter(Arrays.asList(supportedProtocols)::contains)
                    .toList();

            if (enabledProtocols.isEmpty()) {
                throw new IOException("No secure SSL/TLS protocol supported by the server");
            }

            sslSocket.setEnabledProtocols(enabledProtocols.toArray(new String[0]));

            // Verify host
            if (!sslSocket.getEnabledCipherSuites().length > 0) {
                throw new IOException("No cipher suites enabled");
            }

            // Initialize streams
            out = sslSocket.getOutputStream();
            in = new BufferedInputStream(sslSocket.getInputStream());

            Log.d(TAG, "Secure TLS connection established to " + serverHost + ":" + serverPort);
        } catch (GeneralSecurityException e) {
            Log.e(TAG, "SSL/TLS setup failed: ", e);
            throw new IOException("Failed to initialize SSL context", e);
        }
    }

    /**
     * Send data over the secure socket.
     * @param data bytes to send
     * @throws IOException if write fails
     */
    public void send(byte[] data) throws IOException {
        if (out == null) throw new IOException("Not connected");
        out.write(data);
        out.flush();
    }

    /**
     * Receive data from the socket.
     * @return byte array of received data, or null if closed
     * @throws IOException if read fails
     */
    public @Nullable byte[] receive() throws IOException {
        if (in == null) return null;

        byte[] buffer = new byte[1024];
        int bytesRead = in.read(buffer);
        if (bytesRead == -1) {
            return null; // EOF / connection closed
        }
        return Arrays.copyOf(buffer, bytesRead);
    }

    /**
     * Closes the socket and streams.
     */
    @Override
    public void close() {
        try {
            if (in != null) in.close();
        } catch (IOException e) {
            Log.e(TAG, "Error closing input stream", e);
        }

        try {
            if (out != null) out.close();
        } catch (IOException e) {
            Log.e(TAG, "Error closing output stream", e);
        }

        if (sslSocket != null) {
            try {
                sslSocket.close();
            } catch (IOException e) {
                Log.e(TAG, "Error closing SSL socket", e);
            }
            sslSocket = null;
        }

        Log.d(TAG, "Secure socket closed");
    }

    /**
     * Custom TrustManager that performs certificate pinning.
     */
    private static class PinnedTrustManager implements X509TrustManager {

        private final X509Certificate[] trustAnchorCertificates;
        private final CertificatePinner certificatePinner;

        public PinnedTrustManager() throws IOException, GeneralSecurityException {
            // Load pinned certificate(s) from raw resource
            CertificateFactory cf = CertificateFactory.getInstance("X.509");
            InputStream certInputStream = null;
            try {
                certInputStream = new java.io.FileInputStream("/path/to/cert.pem"); // <<<< REPLACE IN REAL USE
                // OR: certInputStream = context.getResources().openRawResource(R.raw.server_cert);
                trustAnchorCertificates = new X509Certificate[]{(X509Certificate) cf.generateCertificate(certInputStream)};
            } finally {
                if (certInputStream != null) certInputStream.close();
            }

            // Initialize pinning
            this.certificatePinner = new CertificatePinner.Builder()
                    .add("example.com", SERVER_PIN) // Match host
                    .build();
        }

        @Override
        public void checkClientTrusted(X509Certificate[] chain, String authType) {
            // Do not trust clients; only server-side validation
        }

        @Override
        public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            if (chain == null || chain.length == 0) {
                throw new CertificateException("No server certificate provided");
            }

            X509Certificate serverCert = chain[0];

            // Verify that the server cert matches at least one pinned public key
            for (String pin : PINNED_PUBLIC_KEYS) {
                if (matchesPinnedKey(serverCert, pin)) {
                    Log.d(TAG, "Certificate pin validated successfully");
                    return;
                }
            }

            throw new CertificateException("Certificate not pinned: " + serverCert.getSubjectX500Principal());
        }

        private boolean matchesPinnedKey(X509Certificate cert, String expectedPin) {
            try {
                java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
                byte[] publicKeyBytes = cert.getPublicKey().getEncoded();
                byte[] hash = md.digest(publicKeyBytes);
                String actualPin = "sha256/" + android.util.Base64.getEncoder().encodeToString(hash);

                // For safety, avoid string comparison attacks
                return MessageDigest.isEqual(actualPin.getBytes(), expectedPin.getBytes());
            } catch (Exception e) {
                Log.e(TAG, "Error during pinning validation", e);
                return false;
            }
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            return new X509Certificate[0]; // No trust anchor (we trust only pinned certs)
        }
    }
}
```

---

### 📁 File Placement in Android Project

- Place your server certificate (`.crt` or `.pem`) in `res/raw/server_cert.pem`
- Use `context.getResources().openRawResource(R.raw.server_cert)` in `PinnedTrustManager`

> ⚠️ **Critical**: Replace `server_cert.pem` with the actual server certificate. Never hardcode private keys!

---

### 🔍 Security Notes (Researcher Perspective)

1. **Avoid Dynamic Pinning via Network**: Hardcoded pins are safer than fetching them remotely (MITM risk).
2. **Use `CertificatePinner` from OkHttp (if allowed)**: For real apps, consider using **OkHttp** which has built-in certificate pinning and is battle-tested.
3. **Pin Multiple Keys** – For key rotation, pin multiple keys at a time.
4. **Use TLS 1.2+ Only** – Disable weak protocols.
5. **Avoid Trust All (No)** – Never use `TrustAllX509TrustManager`.
6. **Monitor Certificate Changes** – Add a fallback mechanism (e.g., logging) if pinning fails.

---

### ✅ Example Usage in Android Activity

```java
