public class StudentManagementSystem {

    // Using ConcurrentHashMap for thread safety in multi-threaded environments
    private final Map<String, Student> studentMap;
    private final List<Student> studentList;
    private final Map<String, List<Student>> indexByName;
    private final Map<String, List<Student>> indexByGrade;

    private final SecurityLogger securityLogger;

    // Constructor
    public StudentManagementSystem() {
        this.studentMap = new ConcurrentHashMap<>();
        this.studentList = new ArrayList<>();
        this.indexByName = new ConcurrentHashMap<>();
        this.indexByGrade = new ConcurrentHashMap<>();
