     * Security-enhanced student addition with input validation
     */
    public boolean addStudent(Student student) {
        if (student == null) {
            securityLogger.log("Attempted to add null student object");
            return false;
        }

        if (student.getId() == null || student.getId().trim().isEmpty()) {
            securityLogger.log("Attempted to add student with null/empty ID");
            return false;
        }

        if (student.getName() == null || student.getName().trim().isEmpty()) {
            securityLogger.log("Attempted to add student with null/empty name");
            return false;
        }

        // Validate grade (0-100)
        if (student.getGrade() < 0 || student.getGrade() > 100) {
            securityLogger.log("Attempted to add student with invalid grade: " + student.getGrade());
            return false;
        }

        // Check for duplicate ID
        if (studentMap.containsKey(student.getId())) {
            securityLogger.log("Attempted to add student with duplicate ID: " + student.getId());
            return false;
        }

        // Add to primary collection
        studentMap.put(student.getId(), student);
        studentList.add(student);

        // Update indexes
        updateIndexes(student);

        securityLogger.log("Successfully added student: " + student.getName() + " (" + student.getId() + ")");
        return true;
    }

    /**
     * Secure student removal with authorization checks
     */
    public boolean removeStudent(String id, String currentUser, boolean isAdmin) {
        if (id == null || id.trim().isEmpty()) {
            securityLogger.log("Attempted to remove student with null/empty ID");
            return false;
        }

        // Validation and authorization
        if (!isAdmin && !currentUser.equals(id)) {
            securityLogger.log("Unauthorized attempt to remove student: " + id + 
                              " by user: " + currentUser);
            return false;
        }

        Student removedStudent = studentMap.remove(id);
        if (removedStudent == null) {
            securityLogger.log("Attempted to remove non-existent student: " + id);
            return false;
        }

        studentList.removeIf(s -> s.getId().equals(id));
        removeFromIndexes(removedStudent);

        securityLogger.log("Successfully removed student: " + removedStudent.getName() + 
                          " (ID: " + id + ") by user: " + currentUser);
        return true;
    }

    /**
     * Secure student update with input validation
     */
    public boolean updateStudent(String id, Student updatedStudent, String currentUser) {
        if (id == null || id.trim().isEmpty()) {
            securityLogger.log("Attempted to update student with null/empty ID");
            return false;
        }

        if (updatedStudent == null) {
            securityLogger.log("Attempted to update student with null student object");
            return false;
        }

        if (!studentMap.containsKey(id)) {
            securityLogger.log("Attempted to update non-existent student: " + id);
            return false;
        }

        // Security: prevent user from changing their own ID
        if (!updatedStudent.getId().equals(id)) {
            securityLogger.log("Unauthorized attempt to change student ID: " + 
                              "from " + id + " to " + updatedStudent.getId());
            return false;
        }

        // Input validation
        if (updatedStudent.getName() == null || updatedStudent.getName().trim().isEmpty()) {
