        studentMap.put(id, updatedStudent);

        // Update list
        int index = studentList.indexOf(oldStudent);
        if (index != -1) {
            studentList.set(index, updatedStudent);
        }

        // Update indexes
        removeFromIndexes(oldStudent);
        updateIndexes(updatedStudent);

        securityLogger.log("Successfully updated student: " + updatedStudent.getName() + 
                          " (ID: " + id + ") by user: " + currentUser);
        return true;
    }

    /**
     * Search students by ID or name with security logging
