        Report report = new Report("Summary Report", new Date());
        report.addData("Total Students", Integer.toString(totalStudents));
        report.addData("Average Grade", String.format("%.2f", averageGrade));
        report.addData("Highest Grade", Integer.toString(highestGrade));
        report.addData("Lowest Grade", Integer.toString(lowestGrade));

        securityLogger.log("Generated summary report");
