        // Remove from grade index
        String gradeKey = String.valueOf((int) student.getGrade());
        if (indexByGrade.containsKey(gradeKey)) {
            indexByGrade.get(gradeKey).remove(student);
            if (indexByGrade.get(gradeKey).isEmpty()) {
                indexByGrade.remove(gradeKey);
            }
        }
    }

