public class SecurityLogger {
    private final List<String> logEntries;
    private final Object lock;

    public SecurityLogger() {
        this.logEntries = new ArrayList<>();
        this.lock = new Object();
    }

    public void log(String message) {
        synchronized (lock) {
            String timestamp = new Date().toString();
            String logEntry = "[" + timestamp + "] " + message;
            logEntries.add(logEntry);

            // Limit log size to prevent memory exhaustion
            if (logEntries.size() > 1000) {
                logEntries.remove(0); // Remove oldest entry
            }
        }
    }

    public List<String> getRecentLogs(int maxCount) {
        synchronized (lock) {
            int fromIndex = Math.max(0, logEntries.size() - maxCount);
            return new ArrayList<>(logEntries.subList(fromIndex, logEntries.size()));
        }
    }
}
