### ✅ 2. 服务端（多线程安全+防护）

#### `ServerSocketManager.java`

```java
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ServerSocketManager {
    private static final int PORT = 8888;
    private final SSLServerSocketFactory sslFactory;
    private final ConcurrentHashMap<String, CustomerServiceHandler> activeSessions = new ConcurrentHashMap<>();
    private final AtomicInteger userCounter = new AtomicInteger(1);

    public ServerSocketManager() throws Exception {
        // 加载信任的服务器证书（PKI认证）
        KeyStore ks = KeyStore.getInstance("JKS");
        try (InputStream is = new FileInputStream("server-keystore.jks")) {
            ks.load(is, "changeit".toCharArray());
        }
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, "changeit".toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ks);

        SSLContext context = SSLContext.getInstance("TLS");
        context.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());
        this.sslFactory = context.getServerSocketFactory();
    }

    public void start() {
        try (SSLServerSocket serverSocket = (SSLServerSocket) sslFactory.createServerSocket(PORT)) {
            serverSocket.setSoTimeout(30000);
            System.out.println("客服服务器启动，监听端口 " + PORT);

            while (true) {
                try {
                    SSLSocket clientSocket = (SSLSocket) serverSocket.accept();

                    // 设置SSL参数
                    clientSocket.setEnabledCipherSuites(clientSocket.getSupportedCipherSuites());

                    // 检查客户端是否为合法用户（可扩展为Token验证）
                    String clientId = "customer_" + userCounter.incrementAndGet();
                    CustomerServiceHandler handler = new CustomerServiceHandler(clientSocket, clientId, this);
                    new Thread(handler).start();

                } catch (IOException e) {
                    System.err.println("客户端连接异常: " + e.getMessage());
                }
            }
        } catch (Exception e) {
            throw new RuntimeException("服务端启动失败", e);
        }
    }

    public void notifyNewConnection(String userId) {
        System.out.println("【新用户申请】用户 " + userId + " 请求连接");
        // 可扩展为通知弹窗或日志记录
    }

    public void removeSession(String userId) {
        activeSessions.remove(userId);
        System.out.println("会话 " + userId + " 已关闭");
    }

    public static void main(String[] args) throws Exception {
        new ServerSocketManager().start();
    }
}
```

