#### `CustomerServiceHandler.java`

```java
import javax.net.ssl.*;
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;

public class CustomerServiceHandler implements Runnable {
    private final SSLSocket socket;
    private final String userId;
    private final ServerSocketManager server;
    private final Object lock = new Object();
    private volatile boolean connected = true;

    private final ConcurrentHashMap<String, String> userFiles = new ConcurrentHashMap<>();
    private final ChatLogManager logManager;

    public CustomerServiceHandler(SSLSocket socket, String userId, ServerSocketManager server) {
        this.socket = socket;
        this.userId = userId;
        this.server = server;
        this.logManager = new ChatLogManager(userId); // 每个用户一个日志文件
        server.notifyNewConnection(userId);
    }

    @Override
    public void run() {
        try (
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
        ) {
            // 初始化消息读取
            String inputLine;
            while ((inputLine = in.readLine()) != null && connected) {
                try {
                    Message msg = parseMessage(inputLine);
                    handleIncomingMessage(msg, out);
                } catch (Exception e) {
                    System.err.println("处理消息异常：" + e.getMessage());
                    sendError(out, "系统错误: " + e.getMessage());
                }
            }
        } catch (IOException e) {
            System.err.println("会话 " + userId + " 断开连接: " + e.getMessage());
        } finally {
            close();
        }
    }

    private Message parseMessage(String json) throws Exception {
        // JSON解析（使用Jackson或Gson）
        // 这里简化为手动处理
        return new MessageParser().parse(json);
    }

    private void handleIncomingMessage(Message msg, PrintWriter out) throws Exception {
        switch (msg.getType()) {
            case "text":
                logManager.appendLog(msg.getSender(), "用户", msg.getContent());
                broadcastToClient(out, msg);
                break;

            case "image":
            case "file":
                String filePath = saveFile(msg.getContent(), msg.getFileName());
                String md5 = calculateMD5(filePath);
                logManager.appendLog(msg.getSender(), "文件", msg.getFileName(), md5);
                String resp = buildResponse("file_received", "文件已接收", message.getFileName(), md5);
                out.println(resp);
                break;

            case "ping":
                out.println(buildResponse("pong", "在线"));
                break;

            default:
                sendError(out, "未知消息类型");
        }
    }

    private String saveFile(String base64Data, String fileName) throws Exception {
        // 防止路径遍历攻击
        Path safePath = Paths.get("uploads", fileName).normalize();
        if (!safePath.startsWith(Paths.get("uploads").toAbsolutePath())) {
            throw new SecurityException("非法文件路径");
        }

        byte[] data = Base64.getDecoder().decode(base64Data);
        Files.write(safePath, data);

        // 只允许指定类型
        if (!isAllowedFileType(fileName)) {
            Files.delete(safePath);
            throw new SecurityException("不支持的文件类型");
        }

        return safePath.toString();
    }

    private boolean isAllowedFileType(String fileName) {
        String ext = fileName.substring(fileName.lastIndexOf('.') + 1).toLowerCase();
        return Set.of("jpg", "jpeg", "png", "pdf", "txt", "docx").contains(ext);
    }

    private String calculateMD5(String filePath) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(Files.readAllBytes(Paths.get(filePath)));
        return bytesToHex(digest);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    private void broadcastToClient(PrintWriter out, Message msg) {
        String response = buildResponse("receive", msg.getContent(), msg.getSender(), msg.getTimestamp());
        out.println(response);
    }

    public void sendError(PrintWriter out, String msg) {
        try {
            out.println(buildResponse("error", msg));
        } catch (Exception ignored) {}
    }

    private String buildResponse(String type, String... args) {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        sb.append("\"type\":\"").append(type).append("\",");
        sb.append("\"timestamp\":").append(System.currentTimeMillis()).append(",");
        sb.append("\"sender\":\"admin\",");
        if (args.length > 0) {
            sb.append("\"content\":\"").append(args[0]).append("\"");
        }
        sb.append("}");
        return sb.toString();
    }

    private void close() {
        synchronized (lock) {
            connected = false;
            try {
                socket.close();
                server.removeSession(userId);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
