public class ChatLogManager {
    private final String userId;
    private final Path logFile;

    public ChatLogManager(String userId) {
        this.userId = userId;
        this.logFile = Paths.get("logs", userId + ".log").normalize();
        try {
            Files.createDirectories(logFile.getParent());
        } catch (IOException e) {
            throw new RuntimeException("无法创建存储目录", e);
        }
    }

    public void appendLog(String sender, String role, String content, String md5) {
        try (PrintWriter pw = new PrintWriter(Files.newBufferedWriter(logFile, StandardOpenOption.APPEND))) {
            long ts = System.currentTimeMillis();
            pw.printf("[%d] %s (%s): %s%s%n", ts, sender, role, content, md5 != null ? " [MD5:" + md5 + "]" : "");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void loadMessages(JTextArea area) {
        try {
            if (Files.exists(logFile)) {
                Files.lines(logFile).forEach(line -> {
                    SwingUtilities.invokeLater(() -> area.append(line + "\n"));
                });
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
