package com.example;

import com.example.model.Employee;
import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.hibernate.cfg.Configuration;

import java.util.List;

public class HibernatePersistenceExample {

    private static SessionFactory sessionFactory;

    static {
        try {
            // Build SessionFactory from hibernate.cfg.xml
            sessionFactory = new Configuration().configure().buildSessionFactory();
        } catch (Throwable ex) {
            System.err.println("Initial SessionFactory creation failed." + ex);
            throw new ExceptionInInitializerError(ex);
        }
    }

    public static void main(String[] args) {
        try (Session session = sessionFactory.openSession()) {
            // Begin transaction
            session.beginTransaction();

            // Create and persist an employee
            Employee employee = new Employee(
                "Alice",
                "Johnson",
                "alice.johnson@company.com",
                "Engineering",
                85000.00
            );

            session.save(employee);
            System.out.println("Employee persisted: " + employee);

            // Optional: Query all employees
            List<Employee> employees = session.createQuery("FROM Employee", Employee.class).list();
            System.out.println("All employees in DB: " + employees);

            // Commit transaction
            session.getTransaction().commit();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (sessionFactory != null && !sessionFactory.isClosed()) {
                sessionFactory.close();
            }
        }
    }
}
