package com.example.servlet;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.RoundingMode;

@WebServlet("/DivideServlet")
public class DivideServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // 设置响应内容类型和字符编码
        response.setContentType("text/html;charset=UTF-8");

        // 获取输入流
        PrintWriter out = response.getWriter();

        // 1. 获取表单参数
        String num1Str = request.getParameter("num1");
        String num2Str = request.getParameter("num2");

        // 2. 输入为空检查
        if (num1Str == null || num1Str.trim().isEmpty()) {
            sendError(out, "错误：被除数不能为空。");
            return;
        }
        if (num2Str == null || num2Str.trim().isEmpty()) {
            sendError(out, "错误：除数不能为空。");
            return;
        }

        // 3. 尝试转换为 BigDecimal（推荐用于精确数学运算）
        BigDecimal num1 = null;
        BigDecimal num2 = null;

        try {
            num1 = new BigDecimal(num1Str.trim());
            num2 = new BigDecimal(num2Str.trim());
        } catch (NumberFormatException e) {
            sendError(out, "错误：输入必须是有效的数字。");
            return;
        }

        // 4. 检查除数是否为零
        if (num2.compareTo(BigDecimal.ZERO) == 0) {
            sendError(out, "错误：除数不能为零。");
            return;
        }

        // 5. 执行除法运算（保留6位小数）
        BigDecimal result = num1.divide(num2, 6, RoundingMode.HALF_UP);

        // 6. 输出结果（关键：防止 XSS，HTML 转义）
        out.println("<!DOCTYPE html>");
        out.println("<html lang=\"zh\">");
        out.println("<head>");
        out.println("    <meta charset=\"UTF-8\">");
        out.println("    <title>计算结果</title>");
        out.println("    <style>");
        out.println("        body { font-family: Arial, sans-serif; margin: 40px; background: #f4f4f4; }");
        out.println("        .result { background: #fff; padding: 30px; border-radius: 8px; box-shadow: 0 0 10px rgba(0,0,0,0.1); max-width: 500px; margin: auto; text-align: center; }");
        out.println("        .result h2 { color: #28a745; }");
        out.println("        .result p { font-size: 18px; margin: 10px 0; }");
        out.println("        .back { margin-top: 20px; display: inline-block; padding: 10px 20px; background: #007BFF; color: white; text-decoration: none; border-radius: 4px; }");
        out.println("    </style>");
        out.println("</head>");
        out.println("<body>");
        out.println("    <div class=\"result\">");
        out.println("        <h2>计算结果</h2>");
        out.println("        <p><strong>" + escapeHtml(num1Str) + "</strong> ÷ <strong>" + escapeHtml(num2Str) + "</strong> = <strong>" + escapeHtml(result.toString()) + "</strong></p>");
        out.println("        <a href=\"divide.html\" class=\"back\">返回</a>");
        out.println("    </div>");
        out.println("</body>");
        out.println("</html>");
    }

    // 7. 错误输出方法（HTML转义，防止XSS）
    private void sendError(PrintWriter out, String message) {
        out.println("<!DOCTYPE html>");
        out.println("<html lang=\"zh\">");
        out.println("<head><meta charset=\"UTF-8\"><title>错误</title></head>");
        out.println("<body>");
        out.println("    <div style=\"text-align:center;margin-top:50px;font-family:Arial; color:red; font-size:18px;\">");
        out.println("        <p>" + escapeHtml(message) + "</p>");
        out.println("        <a href=\"divide.html\" style=\"display:inline-block;padding:10px 20px;background:#007BFF;color:white;text-decoration:none;border-radius:4px;margin-top:10px;\">返回</a>");
        out.println("    </div>");
        out.println("</body>");
        out.println("</html>");
    }

    // 8. HTML 转义方法（防止 XSS）
    private String escapeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;");
    }

    // 防止 GET 请求（可选）
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // 可选：只允许 POST
        response.setStatus(HttpServletResponse.SC_METHOD_NOT_ALLOWED);
        sendError(response.getWriter(), "错误：请使用 POST 方法提交表单。");
    }
}
