import javax.xml.xpath.*;
import org.w3c.dom.Document;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import java.io.StringReader;
import java.io.StringWriter;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;

public class XmlExtractor {

    /**
     * Extracts a specific XML node or subtree from the input XML string using XPath.
     *
     * @param xmlString The full XML string.
     * @param xpathExpression The XPath expression to locate the desired node(s).
     * @return The extracted XML content as a string, or null if not found.
     * @throws Exception if XML parsing or XPath evaluation fails.
     */
    public static String extractXmlPiece(String xmlString, String xpathExpression) throws Exception {
        // Validate inputs
        if (xmlString == null || xmlString.trim().isEmpty()) {
            throw new IllegalArgumentException("XML string must not be null or empty.");
        }
        if (xpathExpression == null || xpathExpression.trim().isEmpty()) {
            throw new IllegalArgumentException("XPath expression must not be null or empty.");
        }

        // Secure XML parser configuration
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true); // Prevents DOCTYPE attacks
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setFeature("http://apache.org/xml/features/validation/schema", false);
        factory.setFeature("http://apache.org/xml/features/validation/schema-full-checking", false);
        factory.setFeature("http://xml.org/sax/features/validation", false);
        factory.setFeature("http://xml.org/sax/features/namespaces", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new org.xml.sax.InputSource(new StringReader(xmlString)));

        // XPath evaluation
        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xpath = xPathFactory.newXPath();

        // Prevent XPath injection via input validation (e.g., disallow certain characters)
        // We’re assuming the XPath is trusted, but in real apps, sanitize it.
        // For now, assume it's from a trusted source (like config).
        XPathExpression expr = xpath.compile(xpathExpression);
        Object result = expr.evaluate(document, XPathConstants.NODESET);

        NodeList nodeList = (NodeList) result;

        if (nodeList.getLength() == 0) {
            System.out.println("No nodes found for XPath: " + xpathExpression);
            return null;
        }

        // Extract the first matched node subtree
        Node firstNode = nodeList.item(0);

        // Convert node to string
        return nodeToString(firstNode);
    }

    /**
     * Converts a DOM Node to its XML string representation.
     *
     * @param node The DOM node to convert.
     * @return XML string of the node and its children.
     */
    private static String nodeToString(Node node) {
        try {
            TransformerFactory tf = TransformerFactory.newInstance();
            tf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            tf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            tf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            tf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            Transformer transformer = tf.newTransformer();
            transformer.setOutputProperty("omit-xml-declaration", "yes"); // Optional
            transformer.setOutputProperty("indent", "no");

            StringWriter writer = new StringWriter();
            transformer.transform(new DOMSource(node), new StreamResult(writer));
            return writer.getBuffer().toString();
        } catch (Exception e) {
            throw new RuntimeException("Failed to convert DOM node to string: " + e.getMessage(), e);
        }
    }

    // Example usage and test
    public static void main(String[] args) {
        String xml = "<root>\n" +
                "  <person id=\"1\">\n" +
                "    <name>John Doe</name>\n" +
                "    <email>john@example.com</email>\n" +
                "  </person>\n" +
                "  <person id=\"2\">\n" +
                "    <name>Jane Smith</name>\n" +
                "    <email>jane@example.com</email>\n" +
                "  </person>\n" +
                "</root>";

        try {
            String extracted = extractXmlPiece(xml, "//person[@id='1']");
            System.out.println("Extracted XML:\n" + extracted);
            // Output:
            // <person id="1">
            //   <name>John Doe</name>
            //   <email>john@example.com</email>
            // </person>
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
```

