import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.*;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

public class HOTELIERServer {

    private List<Hotel> hotels;
    private final String jsonFilePath;
    private final String initialFlagFile = "first_run.flag"; // File di traccia

    public HOTELIERServer(String jsonFilePath) {
        this.jsonFilePath = jsonFilePath;
        loadHotelsFromJson();
    }

    private void loadHotelsFromJson() {
        Gson gson = new Gson();

        File jsonFile = new File(jsonFilePath);
        File flagFile = new File(initialFlagFile);

        // Se il file JSON non esiste (primo avvio), crealo con hotel iniziali a 0
        if (!jsonFile.exists()) {
            System.out.println("Primo avvio: creazione del file Hotels.json con hotel iniziali a 0.");
            hotels = createInitialHotels();
            saveHotelsToJson(jsonFile, hotels);
            // Contrassegna primo avvio
            try (FileWriter fw = new FileWriter(flagFile)) {
                fw.write("first_run_completed");
            } catch (IOException e) {
                System.err.println("Errore durante la scrittura del file di flag: " + e.getMessage());
            }
            return;
        }

        // Se il file JSON esiste, ma il flag non c'è -> primo avvio
        if (!flagFile.exists()) {
            System.out.println("File JSON esiste ma primo avvio rilevato. Azzeramento punteggi.");
            try (FileReader reader = new FileReader(jsonFile)) {
                Type hotelListType = new TypeToken<ArrayList<Hotel>>(){}.getType();
                hotels = gson.fromJson(reader, hotelListType);
                // Azzeramento punteggi
                for (Hotel hotel : hotels) {
                    hotel.rate = 0;
                    if (hotel.ratings != null) {
                        hotel.ratings.cleaning = 0;
                        hotel.ratings.position = 0;
                        hotel.ratings.services = 0;
                        hotel.ratings.quality = 0;
                    }
                }
                // Salva con punteggi azzerati
                saveHotelsToJson(jsonFile, hotels);
                // Scrivi il flag
                try (FileWriter fw = new FileWriter(flagFile)) {
                    fw.write("first_run_completed");
                } catch (IOException e) {
                    System.err.println("Errore durante la scrittura del file di flag: " + e.getMessage());
                }
                return;
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        // Se il flag esiste: caricamento normale dal file JSON
        try (FileReader reader = new FileReader(jsonFile)) {
            Type hotelListType = new TypeToken<ArrayList<Hotel>>(){}.getType();
            hotels = gson.fromJson(reader, hotelListType);
        } catch (IOException e) {
            e.printStackTrace();
            hotels = new ArrayList<>(); // fallback
        }
    }

    // Crea una lista di hotel iniziali con punteggi a 0
    private List<Hotel> createInitialHotels() {
        List<Hotel> initialHotels = new ArrayList<>();

        // Esempio: aggiungi almeno un hotel iniziale
        Hotel hotel = new Hotel();
        hotel.id = 1;
        hotel.name = "Hotel Iniziale";
        hotel.description = "Hotel creato al primo avvio";
        hotel.city = "Città iniziale";
        hotel.phone = "+39000000000";
        hotel.services = new ArrayList<>();
        hotel.services.add("Colazione");
        hotel.rate = 0;
        hotel.ratings = new Hotel.Ratings();
        hotel.ratings.cleaning = 0;
        hotel.ratings.position = 0;
        hotel.ratings.services = 0;
        hotel.ratings.quality = 0;

        initialHotels.add(hotel);
        return initialHotels;
    }

    // Salva la lista di hotel in formato JSON
    private void saveHotelsToJson(File file, List<Hotel> hotels) {
        Gson gson = new Gson();
        try (FileWriter writer = new FileWriter(file)) {
            gson.toJson(hotels, writer);
        } catch (IOException e) {
            System.err.println("Errore durante la scrittura del file JSON: " + e.getMessage());
        }
    }

    // Metodi utili per testare
    public List<Hotel> getHotels() {
        return hotels;
    }

    public static void main(String[] args) {
        String jsonFilePath = "Hotels.json";
        HOTELIERServer server = new HOTELIERServer(jsonFilePath);

        // Esempio: stampa tutti i nomi
        for (Hotel hotel : server.hotels) {
            System.out.println("Hotel: " + hotel.name + ", Punteggio: " + hotel.rate);
        }
    }
}
