```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.net.SocketTimeoutException;

public class PortConnectivityChecker {

    /**
     * 检测指定主机和端口的连通性
     *
     * @param host     目标主机（IP 或域名）
     * @param port     目标端口
     * @param timeout  连接超时时间（毫秒）
     * @return         true 表示端口开放且可连接，false 表示不可达或被拒绝
     */
    public static boolean isPortOpen(String host, int port, int timeout) {
        try (Socket socket = new Socket()) {
            // 设置连接超时时间
            socket.connect(new InetSocketAddress(host, port), timeout);
            socket.close(); // 连接成功后关闭
            return true;
        } catch (SocketTimeoutException e) {
            // 超时，表示连接未在指定时间内建立
            System.out.println("连接超时: " + host + ":" + port);
            return false;
        } catch (IOException e) {
            // 连接被拒绝、主机不可达、DNS 失败等
            System.out.println("连接失败: " + host + ":" + port + " - " + e.getMessage());
            return false;
        }
    }

    public static void main(String[] args) {
        String host = "192.168.1.100";  // 替换为实际目标 IP 或域名
        int port = 80;
        int timeout = 5000; // 5秒超时

        if (isPortOpen(host, port, timeout)) {
            System.out.println("✅ 端口 " + port + " 在 " + host + " 上开放");
        } else {
            System.out.println("❌ 端口 " + port + " 在 " + host + " 上不可达或被防火墙阻止");
        }
    }
}
```

