import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;

public class BankAccountSimulation {

    // 共享变量：账户总汇款金额
    private static int totalAmount = 0;            // 不安全版本
    private static AtomicInteger atomicTotal = new AtomicInteger(0); // 安全版本

    // 模拟顾客的汇款任务
    static class TransferTask implements Runnable {
        private final String customerName;
        private final int numTransfers;
        private final Random random;

        public TransferTask(String customerName, int numTransfers) {
            this.customerName = customerName;
            this.numTransfers = numTransfers;
            this.random = new Random();
        }

        @Override
        public void run() {
            for (int i = 0; i < numTransfers; i++) {
                int amount = random.nextInt(100) + 1;  // 1-100 元
                try {
                    Thread.sleep(random.nextInt(50)); // 模拟不同时间汇款
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                // 版本1：无同步，会导致竞态条件（不安全）
                totalAmount += amount;

                // 版本2 或 3：使用 synchronized 或 AtomicInteger
                // atomicTotal.addAndGet(amount);

                System.out.printf("%s 汇款 %d 元，当前总额: %d%n", customerName, amount, totalAmount);
            }
        }
    }

    // 启动并运行程序一次
    public static void runSimulation() {
        System.out.println("\n================== 开始新一次模拟 ==================");
        // 重置总金额
        totalAmount = 0;

        // 创建多个顾客线程
        List<Thread> threads = new ArrayList<>();
        String[] customers = {"顾客A", "顾客B", "顾客C", "顾客D", "顾客E"};
        int totalTransfers = 0;

        for (int i = 0; i < customers.length; i++) {
            int numTransfers = 2 + random.nextInt(3); // 每人 2~4 次汇款
            Thread t = new Thread(new TransferTask(customers[i], numTransfers));
            threads.add(t);
            totalTransfers += numTransfers;
        }

        // 启动所有线程
        threads.forEach(Thread::start);

        // 等待所有线程完成
        threads.forEach(t -> {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        // 输出最终总额
        System.out.printf("✅ 模拟完成。共 %d 次汇款，账户总金额: %d 元%n", totalTransfers, totalAmount);
    }

    // 验证：在每个线程中使用 Atomic 代替普通变量（更安全）
    public static void runAtomicSimulation() {
        System.out.println("\n================== 使用 AtomicInteger 的模拟 ==================");
        atomicTotal.set(0); // 重置

        List<Thread> threads = new ArrayList<>();
        String[] customers = {"顾客A", "顾客B", "顾客C", "顾客D", "顾客E"};
        int totalTransfers = 0;

        for (int i = 0; i < customers.length; i++) {
            int numTransfers = 2 + random.nextInt(3);
            Thread t = new Thread(new TransferTask(customers[i], numTransfers));
            threads.add(t);
            totalTransfers += numTransfers;
        }

        threads.forEach(Thread::start);
        threads.forEach(t -> {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        System.out.printf("✅ 模拟完成。共 %d 次汇款，账户总金额: %d 元（Atomic）%n", totalTransfers, atomicTotal.get());
    }

    public static void main(String[] args) {
        System.out.println("🏦 银行账户汇款模拟程序 (安全研究员视角)");

        // 运行 5 次，观察结果
        for (int i = 1; i <= 5; i++) {
            System.out.printf("\n🔄 第 %d 次运行 (无同步版本)：%n", i);
            runSimulation();  // 使用不安全的 totalAmount
        }

        System.out.println("\n\n" + "=".repeat(60));

        for (int i = 1; i <= 5; i++) {
            System.out.printf("\n🔄 第 %d 次运行 (使用 AtomicInteger)：%n", i);
            runAtomicSimulation();
        }
    }

    // 静态随机生成器（避免多线程竞争）
    private static final Random random = new Random();
