```java
package com.example.springbootcrud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;

import javax.servlet.http.HttpServletRequest;

@SpringBootApplication
public class SpringbootcrudApplication {

    public static void main(String[] args) {
        SpringApplication.run(SpringbootcrudApplication.class, args);
    }
}

/**
 * Custom Error Controller to handle all error responses
 */
@Controller
public class CustomErrorController {

    /**
     * Handle all error requests (Spring Boot's default error path)
     */
    @RequestMapping("/error")
    @ResponseBody
    public ResponseEntity<String> handleError(HttpServletRequest request) {
        // Optional: Log the error (include request URL, status, etc.)
        String path = (String) request.getAttribute("javax.servlet.error.request_uri");
        Integer status = (Integer) request.getAttribute("javax.servlet.error.status_code");

        // Log error details (in production, log to audit/monitoring system)
        System.err.println("Error occurred at: " + path + " with status: " + status);

        // Return a secure, generic response to avoid leaking internal details
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("{\"error\": \"An unexpected error occurred. Please try again later.\"}");
    }
}
```

