### 🔹 Krok 3: Backend – zapis do bazy, generacja tokena potwierdzającego

**Backend: `routes/auth.js`**

```javascript
const express = require('express');
const router = express.Router();
const bcrypt = require('bcrypt');
const { v4: uuidv4 } = require('uuid');
const { pool } = require('../db'); // Połączenie z PostgreSQL
const nodemailer = require('nodemailer');
const crypto = require('crypto');

// Zabezpieczenie: nie zapisujemy hasła jako plaintext
// Zapiszemy hashowane

router.post('/register', async (req, res) => {
    const { email, password } = req.body;

    // Walidacja
    if (!email || !password) {
        return res.status(400).json({ error: 'Email i hasło są wymagane.' });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        return res.status(400).json({ error: 'Niepoprawny adres e-mail.' });
    }

    // Sprawdź czy email już istnieje (dla unikalności)
    const existingUser = await pool.query(
        'SELECT id FROM users WHERE email = $1',
        [email]
    );

    if (existingUser.rows.length > 0) {
        return res.status(409).json({ error: 'Użytkownik z takim e-mailem już istnieje.' });
    }

    // Hash hasła (bcrypt)
    const saltRounds = 12;
    const passwordHash = await bcrypt.hash(password, saltRounds);

    // Generuj token potwierdzający (unikalny, jednorazowy, z czasem ważności)
    const verificationToken = uuidv4();
    const expiresAt = new Date();
    expiresAt.setHours(expiresAt.getHours() + 1); // 1 godzina ważności

    // Zapisz użytkownika z niepotwierdzonym stanem i tokenem
    try {
        await pool.query(
            `INSERT INTO users (email, password_hash, verification_token, verification_token_expires_at)
             VALUES ($1, $2, $3, $4)`,
            [email, passwordHash, verificationToken, expiresAt]
        );

        // Wyślij e-mail z linkiem potwierdzającym
        const verificationLink = `https://yourdomain.com/verify-email?token=${verificationToken}`;

        const transporter = nodemailer.createTransport({
            host: 'smtp.yourmailprovider.com',
            port: 587,
            secure: false,
            auth: {
                user: process.env.EMAIL_USER,
                pass: process.env.EMAIL_PASS
            },
            requireTls: true,
            tls: { rejectUnauthorized: true }
        });

        const mailOptions = {
            from: 'noreply@yourdomain.com',
            to: email,
            subject: 'Potwierdź swoją rejestrację',
            html: `
                <h2>Witaj!</h2>
                <p>Aby potwierdzić konto, kliknij w poniższy link:</p>
                <a href="${verificationLink}" style="color: #007BFF; text-decoration: underline;">
                    Potwierdź adres e-mail
                </a>
                <p>Link wygaśnie za 1 godzinę.</p>
                <p>Jeśli nie zarejestrowałeś się na tej stronie, zignoruj to e-mail.</p>
            `
        };

        await transporter.sendMail(mailOptions);

        res.status(201).json({
            message: 'Użytkownik zarejestrowany. Link do potwierdzenia został wysłany.'
        });

    } catch (err) {
        console.error('Błąd podczas rejestracji:', err);
        res.status(500).json({ error: 'Wewnętrzny błąd serwera.' });
    }
});
```

