### 🔹 Krok 6: Backend – sprawdzenie i aktywacja konta

**Backend: `routes/auth.js` – nowy endpoint**

```javascript
// GET /api/verify-email?token=...
router.get('/verify-email', async (req, res) => {
    const { token } = req.query;

    if (!token) {
        return res.status(400).json({ error: 'Brak tokenu.' });
    }

    try {
        const result = await pool.query(
            `SELECT id, verification_token, verification_token_expires_at, is_verified 
             FROM users 
             WHERE verification_token = $1 AND is_verified = FALSE`,
            [token]
        );

        const user = result.rows[0];

        if (!user) {
            return res.status(400).json({ error: 'Nieprawidłowy lub już użyty token.' });
        }

        // Sprawdź, czy token nie wygasł
        const now = new Date();
        if (now > new Date(user.verification_token_expires_at)) {
            return res.status(400).json({ error: 'Link potwierdzający wygasł.' });
        }

        // ✅ Aktywuj konto
        await pool.query(
            `UPDATE users 
             SET is_verified = TRUE, verification_token = NULL, verification_token_expires_at = NULL, updated_at = NOW()
             WHERE id = $1`,
            [user.id]
        );

        // Możesz teraz: (opcjonalnie) ustanowić sesję / JWT
        res.status(200).json({
            message: 'Konto zostało pomyślnie potwierdzone.',
            redirect: '/login' // Frontend może użyć tego do przekierowania
        });

    } catch (err) {
        console.error('Błąd weryfikacji:', err);
        res.status(500).json({ error: 'Wewnętrzny błąd serwera.' });
    }
});
```

