### ✅ Rozszerz `get()`:

```js
function get() {
    return new Promise((resolve, reject) => {
        fs.readFile(path, 'utf-8', (err, data) => {
            if (err) {
                reject(err);
                return;
            }

            const decodedMap = {}; // 0x1df -> "value"
            const callMap = {};     // _0x1234 -> function(0x1df) { ... }

            // Etap 1: Znajdź wszystkie funkcje a0_xxx = function(0x...)
            const simpleMapRegex = /a0_\w+\s*=\s*function\s*\((0x[0-9a-fA-F]+)\)\s*\{\s*return\s*['"]([^'"]+)['"];\s*\}/gm;
            let match;
            while ((match = simpleMapRegex.exec(data)) !== null) {
                const hexValue = match[1];
                const plainValue = match[2];
                decodedMap[hexValue] = plainValue;
            }

            // Etap 2: Znajdź wszystkie funkcje typu _0x... = function(...) { ... } — czyli dekodery
            const complexMapRegex = /(?:var|function)\s+_0x([0-9a-fA-F]+)\s*=\s*function\s*\(([^)]*)\)\s*\{\s*(.*?)\s*\}/gms;
            const processedCalls = new Set();

            while ((match = complexMapRegex.exec(data)) !== null) {
                const callId = match[1]; // np. 1234
                const args = match[2].trim();
                const body = match[3].trim();

                // Sprawdź: czy to funkcja z jednym argumentem, który jest liczbą szesnastkową?
                // Załóżmy: _0x1234(0x1df) → zwraca coś
                if (args === '0x[0-9a-fA-F]+' || args.startsWith('0x')) {
                    // Użyj regex dla ciał do wyłapania: return ...
                    const returnMatch = /return\s*(?:_0x[0-9a-fA-F]+\s*\([^)]*\)|['"]([^'"]+)['"]|(\w+))/g.exec(body);
                    if (returnMatch) {
                        const returnValue = returnMatch[1] || returnMatch[2] || '';
                        callMap[`_0x${callId}`] = returnValue; // np. '_0x1234' -> '0x1df'
                    }
                }
            }

            // Teraz — rozwiąż łańcuchy:
            // Jeśli _0x1234() → zwraca 0x1df, a 0x1df → "hello", to:
            // `decodeMap['0x1df']` = "hello", a `callMap['_0x1234']` = '0x1df'
            // Zatem `_0x1234()` → "hello"

            // Przetwórz połączenia
            const finalDecoded = {};
            for (const [key, value] of Object.entries(callMap)) {
                // Jeśli `value` to coś typu `0x1df`, to przekształć
                if (value.startsWith('0x') && decodedMap[value]) {
                    finalDecoded[key] = decodedMap[value];
                }
            }

            // Dodaj też proste mapowania
            Object.assign(finalDecoded, decodedMap);

            // Teraz zwracamy całość
            resolve({
                decodeMap: finalDecoded,
                callMap: callMap,
                allMappings: Object.keys(finalDecoded).reduce((acc, k) => {
                    acc[k] = finalDecoded[k];
                    return acc;
                }, {})
            });
        });
    });
}
```

