// middleware/validate.js
const { body, validationResult } = require('express-validator');
const sanitize = require('sanitize-html');

// Validate and sanitize message
const validateMessage = (data) => {
  const errors = [];
  const text = data?.text;

  if (!text || typeof text !== 'string') {
    errors.push('Message text is required');
    return null;
  }

  if (text.length < 1 || text.length > 500) {
    errors.push('Message must be between 1 and 500 characters');
    return null;
  }

  const cleanText = sanitize(text, {
    allowedTags: [],
    allowedAttributes: {},
    allowedIframeHostnames: [],
    allowedSchemes: []
  });

  if (cleanText !== text) {
    errors.push('Message contains forbidden content');
    return null;
  }

  return { text: cleanText };
};

// Express validator middleware (optional)
const validateMessageValidator = [
  body('text')
    .trim()
    .isLength({ min: 1, max: 500 })
    .withMessage('Message must be 1–500 chars')
    .isString()
    .withMessage('Text must be a string'),
];

module.exports = { validateMessage, validateMessageValidator };
```

