    this.scriptNode = null;
    this.buffers = [];
    this.bufferSize = 2048;
    this.sampleRate = 44100;
    this.minBPM = 40;
    this.maxBPM = 200;
    this.bpm = 0;
    this.isListening = false;
    this.lastBeatTime = 0;
    this.beatInterval = 0;
    this.peaks = 0;
    this.visualizer = null;
    this.ctx = null;
    this.timer = null;

