    this.startButton.addEventListener('click', () => this.startListening());
    this.stopButton.addEventListener('click', () => this.stopListening());

    // Resize visualizer
    this.resizeCanvas();
    window.addEventListener('resize', () => this.resizeCanvas());
  }

  resizeCanvas() {
    const width = this.visualizer.clientWidth;
    const height = this.visualizer.clientHeight;
    this.visualizer.width = width;
    this.visualizer.height = height;
    this.ctx.clearRect(0, 0, width, height);
  }

  async initAudio() {
    try {
      // Request microphone access
      this.microphoneStream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Create audio context
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();

      // Create analyzer node
      this.audioAnalyser = this.audioContext.createAnalyser();
      this.audioAnalyser.fftSize = 2048;

      // Create script processor node
      this.scriptNode = this.audioContext.createScriptProcessor(2048, 1, 1);

      // Connect nodes
      this.microphoneStream.getAudioTracks()[0].connect(this.audioContext.destination);
      this.microphoneStream.getAudioTracks()[0].connect(this.audioContext.destination);

      // Connect microphone stream to analyzer and script node
      this.microphoneStream.getAudioTracks()[0].connect(this.audioContext.destination);
      const source = this.audioContext.createMediaStreamSource(this.microphoneStream);
      source.connect(this.audioAnalyser);
      source.connect(this.scriptNode);

      // Set up script processor to analyze audio
      this.scriptNode.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        this.analyzeAudio(inputData);
      };

      this.status.textContent = "Listening... Please play rhythmic audio.";
      this.startButton.disabled = true;
      this.stopButton.disabled = false;
      this.isListening = true;
      this.reset();

      // Draw visualizer
      this.drawVisualizer();
    } catch (err) {
      console.error('Error accessing microphone:', err);
      this.status.textContent = `Error: ${err.message}`;
      this.startButton.disabled = false;
      this.stopButton.disabled = true;
      alert(`Microphone access denied or error: ${err.message}`);
    }
