  analyzeAudio(inputData) {
    // Keep last few audio chunks
    if (this.buffers.length > 50) {
      this.buffers.shift();
    }
    this.buffers.push(inputData.slice()); // Copy the data

    // Calculate average amplitude
    let sum = 0;
    for (let i = 0; i < inputData.length; i++) {
      sum += Math.abs(inputData[i]);
    }
    const avgAmplitude = sum / inputData.length;

    // Detect beat based on amplitude (thresholding)
    const threshold = 0.08; // Adjust based on environment
    const isBeat = avgAmplitude > threshold;

    if (isBeat) {
      const now = Date.now();
      const interval = now - this.lastBeatTime;

      // Calculate BPM only after at least 2 beats
      if (this.peaks >= 1) {
        this.beatInterval = (interval + this.beatInterval) / 2;
        this.bpm = 60000 / this.beatInterval; // BPM = 60000 ms / interval in ms

        // Smooth the BPM value
        if (this.bpm < this.minBPM) this.bpm = this.minBPM;
        if (this.bpm > this.maxBPM) this.bpm = this.maxBPM;
      }

      this.lastBeatTime = now;
      this.peaks += 1;

      // Update display
      this.updateDisplay(this.bpm);
    }
