  updateDisplay(bpm) {
    const formattedBPM = bpm.toFixed(1);
    this.bpmDisplay.textContent = formattedBPM;

    // Update BPM info text based on tempo
    if (bpm < 80) {
      this.bpmInfo.textContent = "Slow tempo (Ballad)";
    } else if (bpm < 100) {
      this.bpmInfo.textContent = "Medium tempo (Pop)";
    } else if (bpm < 120) {
      this.bpmInfo.textContent = "Moderate tempo (Rock)";
    } else if (bpm < 140) {
      this.bpmInfo.textContent = "Fast tempo (House)";
    } else {
      this.bpmInfo.textContent = "Very fast tempo (Dubstep)";
    }
  }

  drawVisualizer() {
    // Clear canvas
    this.ctx.clearRect(0, 0, this.visualizer.width, this.visualizer.height);

    if (!this.audioAnalyser) return;

    // Get frequency data
    const bufferLength = this.audioAnalyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    this.audioAnalyser.getByteFrequencyData(dataArray);

    // Draw frequency bars
    const barWidth = (this.visualizer.width / bufferLength) * 2.5;
    let x = 0;

    for (let i = 0; i < bufferLength; i++) {
      const barHeight = dataArray[i] / 255 * this.visualizer.height;

      // Use gradient color
      const gradient = this.ctx.createLinearGradient(0, 0, 0, this.visualizer.height);
      gradient.addColorStop(0, '#3498db');
      gradient.addColorStop(1, '#2980b9');

      this.ctx.fillStyle = gradient;
      this.ctx.fillRect(x, this.visualizer.height - barHeight, barWidth, barHeight);

      x += barWidth + 1;
    }

    // Continue animation loop
    requestAnimationFrame(() => this.drawVisualizer());
  }

  startListening() {
    this.reset();
    this.status.textContent = "Starting microphone access...";
    this.startButton.disabled = true;
    this.stopButton.disabled = false;

    // Try to initialize audio again in case of permission
    this.initAudio();
  }

  stopListening() {
    // Stop streaming
    if (this.microphoneStream) {
      this.microphoneStream.getTracks().forEach(track => track.stop());
      this.microphoneStream = null;
    }

    // Close audio context
    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
    }

    // Clear visualizer
    this.ctx.clearRect(0, 0, this.visualizer.width, this.visualizer.height);

    // Reset UI
    this.startButton.disabled = false;
    this.stopButton.disabled = true;
    this.status.textContent = "Listening stopped. Ready to detect BPM.";
    this.bpmDisplay.textContent = "--";
    this.bpmInfo.textContent = "Current BPM";
    this.isListening = false;
  }
}

