export class PersonalDataForm {
  private state: FormState;

  constructor(initialState: FormState = initialFormState) {
    this.state = initialState;
  }

  // Update field value
  public updateField(field: keyof PersonalData, value: string): void {
    this.state.data[field] = value;
    // Clear error when user starts typing
    if (this.state.errors[field]) {
      this.state.errors[field] = undefined;
    }
  }

  // Validate form and return errors
  public validate(): FormErrors {
    const errors = validateForm(this.state.data);
    this.state.errors = errors;
    return errors;
  }

  // Submit form (simulated)
  public async submit(): Promise<boolean> {
    if (this.state.isSubmitting) return false;

    this.state.isSubmitting = true;

    // Validation
    const errors = this.validate();

    if (Object.keys(errors).length > 0) {
      this.state.isSubmitting = false;
      return false;
    }

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      this.state.isSubmitted = true;
      this.state.isSubmitting = false;

      return true;
    } catch (error) {
      this.state.isSubmitting = false;
      console.error('Ошибка при отправке данных:', error);
      return false;
    }
  }

  // Reset form
  public reset(): void {
    this.state.data = { lastName: '', firstName: '', middleName: '' };
    this.state.errors = {};
    this.state.isSubmitting = false;
    this.state.isSubmitted = false;
  }

  // Getters
  public get getState(): FormState {
    return { ...this.state };
  }

  public get isValid(): boolean {
    return Object.keys(this.validate()).length === 0;
  }
}
