      fetchStatusOnceAgain();
    }
  };

  document.addEventListener('visibilitychange', handleVisibilityChange);

  return () => {
    document.removeEventListener('visibilitychange', handleVisibilityChange);
  };
}, []);
```

> ⚠️ Use sparingly — this can trigger unwanted reloads, but may help in niche cases.

---

### ✅ Recommended Fix Summary

| Approach | Why It Works | When to Use |
|--------|--------------|-------------|
| `useEffect` with `location` dependency | Runs on **every route change**, even tab re-use | Most projects |
| `useLoader` + `useLoaderData` | Runs on **every route navigation**, including new tabs | React Router v6.4+ preferred |
| `useEffect` with `location` + `statusEvent` | Reliable, reactive, minimal cost | Quick fix |
| `visibilitychange` + focus detection | Edge-case fallback | Only if you observe inconsistent tab behavior |

---

### 💡 Final Recommendation

👉 **Use `loader` and `useLoaderData`** if you’re in React Router v6.4+. It’s made precisely for this: **fetch data on route entry**, no matter how the user navigates (link click, mouse wheel, history.push, reload, etc.).

If you’re not using `loader`, then at minimum:

```js
