// server.js
const express = require('express');
const multer = require('multer');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const crypto = require('crypto');
const path = require('path');
const fs = require('fs');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security headers
app.use(helmet());

// CORS
app.use(cors({ origin: 'https://your-app.com' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10, // limit each IP to 10 requests per windowMs
  message: { error: 'Too many uploads from this IP' }
});
app.use('/api/upload', limiter);

// File upload memory configuration
const storage = multer.memoryStorage();
const upload = multer({ storage: storage, limits: { fileSize: 10 * 1024 * 1024 * 1024 } }); // 10GB max

// AWS S3 Client
const s3Client = new S3Client({
  region: process.env.AWS_REGION,
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },
});

// Unique filename (prevent collisions)
const generateFileName = (originalName) => {
  const ext = path.extname(originalName);
  const uniqueSuffix = crypto.randomBytes(6).toString('hex');
  return `uploads/${Date.now()}-${uniqueSuffix}${ext}`;
};

// Endpoint: Get Pre-signed URL (client calls this first)
app.get('/api/upload/sign', async (req, res) => {
  const { filename, size, contentType } = req.query;

  if (!filename || !size || !contentType) {
    return res.status(400).json({ error: 'Missing filename, size, or contentType' });
  }

  const filePath = generateFileName(filename);
  const expiration = 15 * 60; // 15 minutes

  try {
    const command = new PutObjectCommand({
      Bucket: process.env.S3_BUCKET,
      Key: filePath,
      ContentType: contentType,
      ContentLength: parseInt(size),
      Metadata: { filename, size },
    });

    const url = await s3Client.getSignedUrl('putObject', {
      ...command.input,
      expiresIn: expiration,
    });

    return res.json({
      url,
      key: filePath,
      expiresAt: Date.now() + (expiration * 1000),
    });
  } catch (error) {
    console.error('Error generating pre-signed URL:', error);
    return res.status(500).json({ error: 'Failed to generate pre-signed URL' });
  }
});
```

