const textarea = document.getElementById('textarea');
let animationFrameId = null; // Track current animation frame
let resizeObserver = null;  // For responsive updates

function insertLine() {
    const selection = window.getSelection();
    if (selection.rangeCount === 0) return;

    const range = selection.getRangeAt(0);
    const textNode = range.startContainer;

    if (textNode.nodeType !== Node.TEXT_NODE) return;

    const currentPosition = range.startOffset;
    const lineText = textNode.textContent.trim().slice(currentPosition);

    // Remove existing highlight line if any
    const existingHighlight = document.querySelector('.highlight-line');
    if (existingHighlight) {
        // Safely remove the old highlight (will be re-created below)
        existingHighlight.remove();
    }

    // Create the new line and insert it at the right spot
    const highlightedLine = document.createElement('span');
    highlightedLine.className = 'highlight-line';
    highlightedLine.textContent = '█';

    const lineBreak = document.createElement('br');
    const newLineContainer = document.createElement('span');
    newLineContainer.appendChild(lineBreak);
    newLineContainer.appendChild(highlightedLine);

    // Split text node if needed
    const nextNode = currentPosition > 0 ? textNode.splitText(currentPosition) : textNode;

    // Insert the new line container after the split point
    nextNode.parentNode.insertBefore(newLineContainer, nextNode.nextSibling);

    // Update the selection
    range.deleteContents();
    range.insertNode(lineBreak);
    range.collapse(false); // Move caret after the line break

    // Schedule animation via rAF — only one at a time
    if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
    }

    animationFrameId = requestAnimationFrame(() => {
        // Only run if the DOM is stable and line is present
        const highlightedLineEl = document.querySelector('.highlight-line');
        if (!highlightedLineEl) {
            animationFrameId = null;
            return;
        }

        const container = document.querySelector('.container');
        if (!container) {
            animationFrameId = null;
            return;
        }

        const containerRect = container.getBoundingClientRect();
        const highlightRect = highlightedLineEl.getBoundingClientRect();

        // Estimate available space (approximate from container width)
        const emptySpace = containerRect.width - highlightRect.right;

        if (emptySpace <= 1) {
            // Already visible or too close to the edge — finalize early
            onAnimationEnd();
            return;
        }

        // Apply animation duration based on empty space
        const durationMs = Math.max(100, emptySpace * 3); // Min 100ms
        highlightedLineEl.style.animationDuration = durationMs + 'ms';

        // Schedule final cleanup after animation
        setTimeout(() => {
            onAnimationEnd();
        }, durationMs);
    });
}

function onAnimationEnd() {
    // Remove the highlight line
    const highlightedLineEl = document.querySelector('.highlight-line');
    if (highlightedLineEl) {
        highlightedLineEl.remove();
    }

    // Clear active frame
    animationFrameId = null;
}

function handleKeyPress(event) {
    if (event.key === 'Enter' || event.key === 'Enter') {
        event.preventDefault();

        const lineBreak = document.createElement('br');
        insertLine(); // This will insert and animate new block

        // Update selection
        const range = window.getSelection().getRangeAt(0);
        range.deleteContents();
        range.insertNode(lineBreak);
        range.collapse(true); // Collapse to end for next input
    }
}

// Debounce resize to avoid thrashing
let resizeTimeout = null;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimeout);
    resizeTimeout = setTimeout(() => {
        // Re-trigger update if visible
        if (document.querySelector('.highlight-line')) {
            // We re-queue animation to re-check positioning
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
