    parts.push(contents.slice(token.start, token.end));

    lastEnd = token.end;
    lastTagEnd = token.end;
  }

  // Push remaining text
  if (lastEnd < contents.length) {
    parts.push(contents.slice(lastEnd));
  }

  // Now reconstruct the string, collapsing newlines between tags
  let result = '';
  let i = 0;

  while (i < parts.length) {
    const part = parts[i];

    if (part.startsWith('[')) {
      // It's a tag: [ul], [li], [/ul], etc.
      result += part;

      // Skip to next piece
      i++;

      // Look ahead: after this tag, do we have text?
      // But we want to remove extra newlines after the tag if next thing is a tag
      let next = i;
      while (next < parts.length && parts[next].startsWith('[')) {
        next++;
      }

      // If next item is another tag, then skip over any newlines before it
      if (next < parts.length && parts[next].startsWith('[')) {
        const afterTagText = parts.slice(i, next).join('');
        // Remove any newlines between this tag and next
        // But preserve the content
        const cleanText = afterTagText.replace(/\n+/g, ' '); // Just collapse newlines
        result += cleanText;

        i = next;
      } else {
        // No next tag, so keep original
        result += parts.slice(i, next).join('');
        i = next;
      }
    } else {
      // Regular text
      result += part;
      i++;
    }
  }

  // Cleanup extra spacing from the above process
  return result.replace(/\n+/g, '\n'); // Preserve single newlines
}
```

