```javascript
function sanitizeAndStyleText(elementOrText) {
    // Helper: Create a temporary div to safely parse and manipulate content
    const tempDiv = document.createElement('div');

    // If input is a string, set it as text; if it's an element, clone its innerHTML
    if (typeof elementOrText === 'string') {
        tempDiv.innerHTML = elementOrText;
    } else if (elementOrText instanceof Element) {
        // Clone the element to avoid modifying the original
        tempDiv.appendChild(elementOrText.cloneNode(true));
    } else {
        console.error('Invalid input: expected string or Element');
        return '';
    }

    // Get all text nodes that are inside <b>, <i>, <u> tags
    const targetTags = ['b', 'i', 'u'];
    const relevantNodes = [];

    const walker = document.createTreeWalker(
        tempDiv,
        NodeFilter.SHOW_ELEMENT,
        {
            acceptNode: function(node) {
                if (targetTags.includes(node.tagName.toLowerCase())) {
                    return NodeFilter.FILTER_ACCEPT;
                }
                return NodeFilter.FILTER_REJECT;
            }
        }
    );

    let node;
    while ((node = walker.nextNode())) {
        relevantNodes.push(node);
    }

    // Now process each node to extract styles and apply them to the text
    const extractedTexts = [];
    relevantNodes.forEach(node => {
        const textContent = node.textContent || '';
        const computedStyle = window.getComputedStyle(node);

        // Create a span to hold the styled text
        const styledSpan = document.createElement('span');
        styledSpan.textContent = textContent;

        // Apply only the styles we care about (and are safe)
        if (computedStyle.fontWeight && computedStyle.fontWeight !== 'normal') {
            styledSpan.style.fontWeight = computedStyle.fontWeight;
        }
        if (computedStyle.fontStyle && computedStyle.fontStyle !== 'normal') {
            styledSpan.style.fontStyle = computedStyle.fontStyle;
        }
        if (computedStyle.textDecoration && computedStyle.textDecoration !== 'none') {
            styledSpan.style.textDecoration = computedStyle.textDecoration;
        }

        // Optional: Add `display: inline` to ensure spacing is preserved
        styledSpan.style.display = 'inline';

        extractedTexts.push(styledSpan);
    });

    // Remove original styled elements and replace with styled spans
    // But if you want just plain styled text, just return the styled content
    const fragment = document.createDocumentFragment();
    extractedTexts.forEach(span => {
        fragment.appendChild(span);
