        var $option = $(this),
            optionValue = $option.attr("value"),
            optionText = $option.html(),
            optionClass = $option.attr("class") || "";

        // Проверка: совпадает ли value опции с placeholder-значением?
        if (optionValue === placeholder) {
            // Отметить как selected в оригинальном select
            $option.prop("selected", true);
            foundMatch = true;
        }

        template += '<span class="custom-option ' + optionClass + '" data-value="' + optionValue + '">' + optionText + '</span>';
    });

    template += '</div></div>';

    // Вставка и скрытие оригинального select
    $select.wrap('<div class="custom-select-wrapper"></div>');
    $select.hide();
    $select.after(template);

    // Обработка hover
    $(".custom-option:first-of-type").hover(
        function () {
            $(this).parents(".custom-options").addClass("option-hover");
        },
        function () {
            $(this).parents(".custom-options").removeClass("option-hover");
        }
    );

    // Открытие/закрытие dropdown
    $(".custom-select-trigger").on("click", function (e) {
        $("html").one("click", function () {
            $(".custom-select").removeClass("opened");
        });
        $(this).parents(".custom-select").toggleClass("opened");
        e.stopPropagation();
    });

    // Выбор опции
    $(".custom-option").on("click", function () {
        var $this = $(this),
            value = $this.data("value"),
            $customSelect = $this.parents(".custom-select-wrapper"),
            $originalSelect = $customSelect.find("select");

        // Обновляем значение в оригинальном select
        $originalSelect.val(value).trigger("change");

        // Обновляем UI: снимаем выделение у всех
        $customSelect.find(".custom-option").removeClass("selection");
        $this.addClass("selection");

        // Обновляем текст в trigger
        $customSelect.find(".custom-select-trigger").text($this.text());

        // Закрываем dropdown
        $customSelect.find(".custom-select").removeClass("opened");
    });

