            var $trigger = $select.siblings(".custom-select").find(".custom-select-trigger");
            var $optionElement = $select.siblings(".custom-select").find(".custom-option[data-value='" + placeholder + "']");
            $optionElement.addClass("selection");
            $trigger.text($matchedOption.text());
        }
    }

    // Также, если у select уже есть selected-опция — используем её вместо placeholder
    // Это важно, если placeholder не используется и select заранее имеет выбранный элемент
    var $selectedOption = $select.find("option[selected], option:checked").first();
    if ($selectedOption.length && !$selectedOption.val().toString().trim() === '') {
        var selectedValue = $selectedOption.val();
        var selectedText = $selectedOption.text();

        // Если не совпадает с placeholder — не нужно использовать его
