            $select.siblings(".custom-select").find(".custom-select-trigger").text(selectedText);
        } else if (!placeholder) {
            // Если placeholder вообще отсутствует — используем selected
            $select.siblings(".custom-select").find(".custom-select-trigger").text(selectedText);
            $select.find(".custom-option[data-value='" + selectedValue + "']")
                  .addClass("selection");
        }
    }
});
