const express = require("express");
const cors = require("cors");
const axios = require("axios");
require("dotenv").config();

const app = express();

// === Security & Performance Middleware ===

// Limit JSON payload size (prevent DoS via large payloads)
app.use(express.json({ limit: "10mb" }));

// Enable CORS with specific origin (avoid wildcards in production)
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(",") || "*", // e.g., "https://app.com"
    credentials: true,
  })
);

// === Configuration & Sanity Checks ===

const API_KEY = process.env.APIKEY;

if (!API_KEY) {
  console.error("❌ APIKEY is not set in environment variables!");
  process.exit(1);
}

const BASE_URL = "https://open-weather13.p.rapidapi.com";
const MAX_CITIES = 10; // Prevent abuse / excessive load
const REQUEST_TIMEOUT = 5000; // 5 seconds timeout

// === Input Validation Helper ===
function isValidCity(city) {
  if (typeof city !== "string" || !city.trim()) return false;
  return /^[a-zA-Z0-9\s\-_]{1,50}$/.test(city.trim()); // Alphanumeric, spaces, hyphens, underscores
}

// === Safe Weather Fetch Function (with timeout & retry logic) ===
async function getWeather(city) {
  // Skip invalid cities immediately
  if (!isValidCity(city)) {
    return {
      city: city,
      temperature: "Invalid input",
      error: "Invalid city name",
    };
  }

  const options = {
    method: "GET",
    url: `${BASE_URL}/city/${encodeURIComponent(city.trim())}`,
    headers: {
      "X-RapidAPI-Key": API_KEY,
      "X-RapidAPI-Host": "open-weather13.p.rapidapi.com",
    },
    timeout: REQUEST_TIMEOUT, // Prevent hanging requests
  };

  try {
    const response = await axios.request(options);

    const temp = response.data?.main?.temp;
    if (typeof temp === "number") {
      return {
        city: city,
        temperature: temp,
        unit: "kelvin", // or add Celsius: temp - 273.15
      };
    }

    return {
      city: city,
      temperature: "N/A",
      error: "Unexpected response format",
    };
  } catch (error) {
    if (error.code === "ECONNABORTED") {
      return {
        city: city,
        temperature: "N/A",
        error: "Request timed out",
      };
    }

    if (error.response?.status === 403) {
      return {
        city: city,
        temperature: "N/A",
        error: "Access forbidden: check API key",
      };
    }

    if (error.response?.status === 404) {
      return {
        city: city,
        temperature: "N/A",
        error: "City not found",
      };
    }

    // Other errors (network, DNS, etc.)
    return {
      city: city,
      temperature: "N/A",
      error: "Internal error",
    };
  }
}

// === Rate Limiter (via express-rate-limit) ===
const rateLimit = require("express-rate-limit");

app.use(
  "/weather",
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // max 100 requests per 15 minutes
    message: {
      error: "Too many requests from this IP, please try again later.",
    },
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// === Main Endpoint ===
app.post("/weather", async (req, res) => {
  try {
    const { cities } = req.body;

    // Validate input
    if (!Array.isArray(cities)) {
      return res.status(400).json({
        error: "Invalid input: 'cities' must be an array",
      });
    }

    if (cities.length === 0) {
      return res.status(400).json({
        error: "At least one city is required",
      });
    }

    if (cities.length > MAX_CITIES) {
      return res.status(400).json({
        error: `Too many cities. Max allowed: ${MAX_CITIES}`,
      });
    }

    // Validate all cities
    const validCities = cities.filter((city) => isValidCity(city));
    if (validCities.length === 0) {
      return res.status(400).json({
        error: "No valid cities provided",
      });
    }

    // Fetch weather data in parallel with timeout + error resilience
    const weatherPromises = validCities.map((city) => getWeather(city));

    // Use Promise.allSettled() to handle partial failures gracefully
    const results = await Promise.allSettled(weatherPromises);

    const formattedResults = results.map((result) => {
      if (result.status === "fulfilled") {
        return result.value;
      } else {
        return {
          city: "unknown",
          temperature: "N/A",
          error: "Unhandled error",
        };
      }
    });

    // Return results even if some fail — more useful than rejecting all
    res.status(200).json(formattedResults);

  } catch (error) {
    console.error("Unexpected server error:", error);
    res.status(500).json({
      error: "Internal server error",
      // Avoid exposing stack traces in production
      // Optional: log full error only in debug mode
    });
  }
});

// === Health Check Endpoint (Security Best Practice) ===
app.get("/health", (req, res) => {
  res.status(200).json({
    status: "UP",
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// === Error Handling Middleware (Global) ===
app.use((err, req, res, next) => {
  console.error("Unhandled error:", err);
