- 可扩展用于扫描整个项目目录。

---

### ✅ 1. 安装依赖

```bash
npm install @babel/parser @babel/types
```

---

### ✅ 2. Node.js 函数：分析 TSX 文件中的依赖

```js
const fs = require('fs');
const path = require('path');
const parser = require('@babel/parser');
const t = require('@babel/types');

/**
 * 分析 TSX 文件中引入的第三方依赖
 * @param {string} filePath - TSX 文件路径
 * @returns {Array<string>} 第三方依赖包名数组
 */
function analyzeTsxImports(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');

  try {
    // 使用 Babel 解析代码
    const ast = parser.parse(content, {
      sourceType: 'module',
      plugins: [
        'typescript',
        'jsx',
        'classProperties',
        'optionalChaining',
        'nullishCoalescingOperator'
      ]
    });

    const dependencies = new Set();

    // 遍历 AST 中的 ImportDeclaration 节点
    function traverse(node) {
      if (t.isImportDeclaration(node)) {
        const source = node.source.value;

        // 跳过相对路径、绝对路径、node 内置模块
        if (
          source.startsWith('.') ||
          source.startsWith('/') ||
          source.startsWith('node:') ||
          !source.includes('/')
        ) {
          // 相对路径或内置模块，跳过
          return;
        }

        // 提取包名（通常是第一个路径段，如 'lodash', 'react-router'）
        const packageName = source.split('/')[0];
        if (packageName && packageName !== 'node_modules') {
          dependencies.add(packageName);
        }
      }

      // 递归遍历子节点
      t.traverse(node, {
        enter: (childNode) => traverse(childNode)
      });
    }

    traverse(ast);

    return Array.from(dependencies).sort();
  } catch (error) {
    console.error(`Error parsing ${filePath}:`, error.message);
    return [];
  }
}

// === 示例用法 ===
const filePath = path.resolve(__dirname, 'components/MyComponent.tsx');
const deps = analyzeTsxImports(filePath);

console.log('Detected third-party dependencies:', deps);
```

---

### ✅ 3. 扩展功能（安全研究员向）

#### ✅ 扫描整个项目中的所有 `.tsx` 文件
```js
const glob = require('glob');

function analyzeProjectTsxImports(rootDir) {
  const tsxFiles = glob.sync(path.join(rootDir, '**/*.tsx'));

  const allDeps = new Set();

  tsxFiles.forEach(file => {
    const deps = analyzeTsxImports(file);
    deps.forEach(dep => allDeps.add(dep));
  });

  return Array.from(allDeps).sort();
}

// 使用
const projectDeps = analyzeProjectTsxImports('./src');
console.log('All dependencies in project:', projectDeps);
```

> 🛠 你可将 `glob` 也安装：`npm install glob`

---

### ✅ 4. 安全审计建议（研究员视角）

- 🔍 **发现可疑依赖**：如 `react-async`, `lodash-something`，可能是恶意包。
- 🚩 **检查已知漏洞依赖**：结合 `npm audit`, `snyk`, `dependabot` 等工具进行比对。
- 🧩 **识别隐式依赖**：某些库通过 `import` 间接引入多个包，需注意供应链攻击。
- 🔒 **检测不安全导入模式**：如 `import('some-user-input')`，可能有动态导入风险。

---

### ✅ 5. 输出示例

假设 `MyComponent.tsx`：

```tsx
