import axios, { AxiosInstance } from 'axios'
import { AuthResponse, ApiError } from '../types/auth'

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL

const apiClient: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
    'X-Requested-With': 'XMLHttpRequest',
  },
  withCredentials: true, // Critical for sending cookies (CSRF + session)
})

// Request interceptor for logging and error handling (optional)
apiClient.interceptors.request.use(
  (config) => {
    // Optionally attach CSRF token if needed (via cookie)
    return config
  },
  (error) => Promise.reject(error)
)

apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    const apiError: ApiError = error.response?.data || {
      message: 'An unexpected error occurred',
      statusCode: error.response?.status || 500,
    }

    return Promise.reject(apiError)
  }
)

export default apiClient
```

