        if (max_tokens > 4096) {
            return res.status(400).json({ error: 'max_tokens não pode ultrapassar 4096.' });
        }

        // 📦 Preparar a requisição para OpenAI
        const openaiRequest = {
            model,
            messages,
            max_tokens,
            temperature,
            stream: false, // Pode ser habilitado se quiser streaming
        };

        // 🔑 Chamar a OpenAI via Proxy
        const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
            },
            body: JSON.stringify(openaiRequest),
        });

        const responseData = await response.json();

        // 📝 Auditoria: log sem dados sensíveis
        console.log(`[LOG] Requisição bem-sucedida: ${messages[0].content.substring(0, 50)}...`);

        // ✅ Responder com dados da OpenAI
        res.json(responseData);

    } catch (error) {
        console.error('Erro ao chamar a API da OpenAI:', error);

        // Garantir que não expomos a chave ou detalhes sensíveis
        if (error.response?.data?.error) {
            return res.status(error.response.status).json({ error: error.response.data.error.message });
        }

        res.status(500).json({ error: 'Erro interno ao processar a requisição.' });
    }
});

// Rota de saúde (health check)
app.get('/health', (req, res) => {
    res.status(200).json({ status: 'OK', timestamp: new Date().toISOString() });
});

// Servir arquivos estáticos (opcional)
app.use('/', express.static(path.join(__dirname, 'public')));

// 404 para rotas não encontradas
app.use('*', (req, res) => {
    res.status(404).json({ error: 'Rota não encontrada.' });
});

// Iniciar servidor
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`🚀 Servidor rodando na porta ${PORT}`);
    console.log(`🔗 Health Check: http://localhost:${PORT}/health`);
});
