## 🛠️ Как использовать в контроллерах (с примерами на Node.js + Express)

```js
// controllers/postController.js
const User = require('../models/User');
const Post = require('../models/Post');

// Создать новый пост (связь: 1 ко многим)
exports.createPost = async (req, res) => {
  const { title, content, authorId } = req.body;

  // ✅ 1. Валидация
  if (!title || !content || !authorId) {
    return res.status(400).json({ error: 'Все поля обязательны' });
  }

  // ✅ 2. Проверка валидности ObjectId
  if (!mongoose.Types.ObjectId.isValid(authorId)) {
    return res.status(400).json({ error: 'Неверный ID пользователя' });
  }

  try {
    // ✅ 3. Убедиться, что пользователь существует
    const user = await User.findById(authorId);
    if (!user) {
      return res.status(404).json({ error: 'Пользователь не найден' });
    }

    // ✅ 4. Создаем пост с ссылкой на пользователя
    const post = new Post({
      title,
      content,
      author: authorId
    });

    await post.save();

    res.status(201).json(post);

  } catch (err) {
    // Не логируй исходные ошибки базы — это уязвимость!
    console.error(err); // только в логах
    res.status(500).json({ error: 'Ошибка при создании поста' });
  }
};

// Получить все посты одного пользователя
exports.getUserPosts = async (req, res) => {
  const { userId } = req.params;

  if (!mongoose.Types.ObjectId.isValid(userId)) {
    return res.status(400).json({ error: 'Неверный ID пользователя' });
  }

  try {
    const user = await User.findById(userId);
    if (!user) {
      return res.status(404).json({ error: 'Пользователь не найден' });
    }

    const posts = await Post.find({ author: userId }).sort({ createdAt: -1 });
    res.json(posts);

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Ошибка получения постов' });
  }
};
```

