## ✅ `script.js` — Логика JavaScript

```javascript
// Корзина
let cart = JSON.parse(localStorage.getItem('cart')) || [];
const cartItemsEl = document.getElementById('cart-items');
const cartTotalEl = document.getElementById('cart-total');
const checkoutBtn = document.getElementById('checkout-btn');
const clearCartBtn = document.getElementById('clear-cart');
const cartCounter = document.querySelector('.navbar a[href="cart.html"] span');

// Обновление счётчика корзины
function updateCartCounter() {
  const total = cart.reduce((sum, item) => sum + item.quantity, 0);
  cartCounter.textContent = total;
}

// Добавление в корзину
function addToCart(name, price) {
  const existing = cart.find(item => item.name === name);
  if (existing) {
    existing.quantity++;
  } else {
    cart.push({ name, price, quantity: 1 });
  }
  localStorage.setItem('cart', JSON.stringify(cart));
  updateCartCounter();
  alert(`Товар "${name}" добавлен в корзину!`);
}

// Отображение корзины
function renderCart() {
  if (cart.length === 0) {
    cartItemsEl.innerHTML = '<p>Корзина пуста.</p>';
    cartTotalEl.innerHTML = '<p>Всего: <strong>0 ₽</strong></p>';
    checkoutBtn.disabled = true;
    return;
  }

  let html = '';
  let total = 0;
  cart.forEach((item, index) => {
    const itemTotal = item.price * item.quantity;
    total += itemTotal;
    html += `
      <div class="cart-item">
        <p><strong>${item.name}</strong> (x${item.quantity}) — ${item.price} ₽</p>
        <button onclick="removeFromCart(${index})" class="btn-clear">Удалить</button>
      </div>
    `;
  });
  cartItemsEl.innerHTML = html;
  cartTotalEl.innerHTML = `<p>Всего: <strong>${total} ₽</strong></p>`;
  checkoutBtn.disabled = false;
}

// Удаление из корзины
function removeFromCart(index) {
  cart.splice(index, 1);
  localStorage.setItem('cart', JSON.stringify(cart));
  renderCart();
  updateCartCounter();
}

// Очистка корзины
clearCartBtn.addEventListener('click', () => {
  cart = [];
  localStorage.removeItem('cart');
  renderCart();
  updateCartCounter();
});

// Загрузка карзины при открытии страницы
if (document.getElementById('cart-items')) {
  updateCartCounter();
  renderCart();
}

// Валидация регистрации
function validateRegistration(event) {
  event.preventDefault();

  const username = document.getElementById('username').value.trim();
  const email = document.getElementById('email').value.trim();
  const password = document.getElementById('password').value;
  const confirmPassword = document.getElementById('confirmPassword').value;

  let valid = true;

  // Логин
  if (username.length < 3) {
    document.getElementById('username-error').textContent = 'Логин должен быть минимум 3 символа';
    valid = false;
  } else {
    document.getElementById('username-error').textContent = '';
  }

  // Email
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    document.getElementById('email-error').textContent = 'Введите корректный email';
    valid = false;
  } else {
    document.getElementById('email-error').textContent = '';
  }

  // Пароль
  if (password.length < 6) {
    document.getElementById('password-error').textContent = 'Пароль должен быть минимум 6 символов';
    valid = false;
  } else {
    document.getElementById('password-error').textContent = '';
  }

  // Подтверждение пароля
  if (password !== confirmPassword) {
    document.getElementById('confirm-error').textContent = 'Пароли не совпадают';
    valid = false;
  } else {
    document.getElementById('confirm-error').textContent = '';
  }

  if (valid) {
    alert('Регистрация успешна! Теперь вы можете войти в магазин.');
    document.getElementById('registerForm').reset();
  }
}

// Инициализация
document.addEventListener('DOMContentLoaded', () => {
  if (document.getElementById('cart-items')) {
    updateCartCounter();
    renderCart();
  }
});
```

