logout() {
  window.postMessage({ type: 'CLEAR_USER_INFO' }, '*');
  this.$store.commit('SET_USER_INFO', null);
  this.$store.commit('SET_TOKEN_HASH', null);
  this.$refs.iframeEl.src = '' // 清空 iframe
  // 可选：延迟重新加载 iframe
  setTimeout(() => {
    this.$refs.iframeEl.src = 'https://trusted.com/login';
  }, 500);
}

// 2. 父页面监听 message，允许强制更新
window.addEventListener('message', (event) => {
  if (!isValidOrigin(event.origin)) return;

  if (event.data.type === 'USER_INFO') {
    const newTokenHash = event.data.tokenHash;
    const currentTokenHash = this.$store.state.tokenHash;

    if (newTokenHash !== currentTokenHash) {
      // 强制更新用户信息，避免旧数据残留
      this.$store.commit('SET_USER_INFO', event.data.user);
      this.$store.commit('SET_TOKEN_HASH', newTokenHash);
    }
  }
});
```

---

## ✅ 总结

| 方案 | 推荐度 | 适用场景 |
|------|--------|----------|
| ✅ 主动发送 `CLEAR_USER_INFO` + 重置缓存 | ⭐⭐⭐⭐⭐ | 通用、最佳实践 |
| ✅ 重新加载 iframe + 强制重新请求 | ⭐⭐⭐⭐ | 高安全性需求 |
| ✅ 结合 tokenHash 判断是否更新 | ⭐⭐⭐⭐ | 长期运行、多账号场景 |
| ❌ 仅缓存一次 | ⭐ | 不推荐，有安全缺陷 |

---

## 📢 最终建议

> **不要在 Vuex 中“永久缓存” iframe 发送的用户信息**。  
> 状态必须与用户登录生命周期一致。  
> 任何跨域通信都要考虑：**谁在说话？说了什么？是否可信？是否已过期？**

