```js
const fs = require('fs');
const crypto = require('crypto');

// Konfiguracja
const inputFile = 'plik.js';        // Plik do szyfrowania
const outputFile = 'plik.js.enc';   // Wyjściowy plik zaszyfrowany
const password = 'moje_silne_haslo_123!'; // Hasło – **ZMIEN TO NA SŁUŻBOWE**

const algorithm = 'aes-256-gcm';
const keyLength = 32; // 256-bit

// Funkcja do generowania klucza z hasła
function getEncryptionKey(password, salt = Buffer.from('s3cr3t-s4lt')) {
  return crypto.pbkdf2Sync(password, salt, 100000, keyLength, 'sha256');
}

// Szyfrowanie pliku
function encryptFile(inputPath, outputPath, password) {
  const data = fs.readFileSync(inputPath);
  const key = getEncryptionKey(password);
  const iv = crypto.randomBytes(12); // AES-GCM używa 96-bitowego IV

  const cipher = crypto.createCipheriv(algorithm, key, iv);

  let encrypted = cipher.update(data);
  let tag = cipher.final();
  encrypted = Buffer.concat([encrypted, tag]);

  // Zapisz: IV (12B) + tag (16B) + zaszyfrowane dane
  const result = Buffer.concat([iv, tag, encrypted]);

  fs.writeFileSync(outputPath, result);
  console.log(`✅ Plik został zaszyfrowany: ${outputPath}`);
}

// Uruchom szyfrowanie
encryptFile(inputFile, outputFile, password);
```

