### 🔓 `decrypt.js` – Odszyfrowywanie pliku

```js
const fs = require('fs');
const crypto = require('crypto');

const encryptedFile = 'plik.js.enc'; // Plik zaszyfrowany
const decryptedFile = 'plik.js.dec'; // Plik odszyfrowany
const password = 'moje_silne_haslo_123!'; // To samo hasło co do szyfrowania

const algorithm = 'aes-256-gcm';
const keyLength = 32;
const ivLength = 12;
const tagLength = 16;

function getDecryptionKey(password, salt = Buffer.from('s3cr3t-s4lt')) {
  return crypto.pbkdf2Sync(password, salt, 100000, keyLength, 'sha256');
}

function decryptFile(encryptedPath, outputPath, password) {
  const data = fs.readFileSync(encryptedPath);
  const key = getDecryptionKey(password);

  // Pobierz IV (12 bajtów), tag (16 bajtów), dane (pozostałe)
  const iv = data.slice(0, ivLength);
  const tag = data.slice(ivLength, ivLength + tagLength);
  const ciphertext = data.slice(ivLength + tagLength);

  const decipher = crypto.createDecipheriv(algorithm, key, iv);
  decipher.setAuthTag(tag);

  try {
    let decrypted = decipher.update(ciphertext);
    decrypted = Buffer.concat([decrypted, decipher.final()]);
    fs.writeFileSync(outputPath, decrypted);
    console.log(`✅ Plik został odszyfrowany: ${outputPath}`);
  } catch (err) {
    console.error('❌ Błąd odszyfrowywania – nieprawidłowe hasło lub uszkodzony plik');
  }
}

decryptFile(encryptedFile, decryptedFile, password);
```

