import time
from collections import defaultdict

# Простой механизм блокировки (по IP)
rate_limit = defaultdict(list)

@app.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket):
    client_ip = websocket.scope["client"][0]
    now = time.time()

    # Удалить старые запросы (последние 10 сек)
    requests = [t for t in rate_limit[client_ip] if t > now - 10]
    if len(requests) >= 5:
        await websocket.close(code=1008)  # Too many requests
        return

    rate_limit[client_ip] = requests + [now]

    global message_counter
    await websocket.accept()
    try:
        while True:
            data = await websocket.receive_text()
            message = json.loads(data)
            if len(message) > 500:  # Ограничение на длину
                await websocket.send_text(json.dumps({"error": "Message too long"}))
                continue

            message_counter += 1
            message_with_number = f"{message_counter}. {message}"
            message_list.append(message_with_number)
            await websocket.send_text(json.dumps(message_list))
    except WebSocketDisconnect:
        pass
```

