### 1. Создание базы данных и таблицы (`database.sqlite` + `users.sql`)

Инициализируем базу:

**`data/users.sql`**:
```sql
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL UNIQUE,
    email TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Вставим тестового пользователя
INSERT OR IGNORE INTO users (username, email) VALUES ('alice', 'alice@example.com');
```

Создание базы через `sqlite3` с помощью JS:

**`server.js` (с инициализацией базы)**:

```js
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const app = express();
const PORT = 3000;

// Подключение к базе данных (в памяти — для примера)
// Для продакшена лучше использовать файловую БД
const dbPath = path.join(__dirname, 'database.sqlite');
const db = new sqlite3.Database(dbPath);

// Применяем миграции/инициализацию
function initializeDatabase() {
  const createTableSQL = `
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      email TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const insertSampleUser = `
    INSERT OR IGNORE INTO users (username, email) VALUES ('alice', 'alice@example.com');
  `;

  db.run(createTableSQL, (err) => {
    if (err) {
      console.error('Ошибка при создании таблицы:', err);
      return;
    }
    console.log('Таблица users создана (или уже существует).');

    db.run(insertSampleUser, (err) => {
      if (err) {
        console.error('Ошибка при вставке тестового пользователя:', err);
      } else {
        console.log('Тестовый пользователь добавлен.');
      }
    });
  });
}

// Запуск сервера и инициализация базы
app.use(express.json()); // Для парсинга JSON тел

app.get('/users/:id', (req, res) => {
  const userId = req.params.id;

  // Проверка на валидность id (должно быть числом)
  if (!Number.isInteger(Number(userId)) || userId <= 0) {
    return res.status(400).json({
      error: 'Неверный ID пользователя. Должно быть положительное целое число.'
    });
  }

  // Параметризованный запрос — ключевая мера безопасности!
  const query = 'SELECT id, username, email, created_at FROM users WHERE id = ?';

  db.get(query, [userId], (err, row) => {
    if (err) {
      console.error('Ошибка при выполнении запроса:', err);
      return res.status(500).json({
        error: 'Ошибка сервера'
      });
    }

    if (!row) {
      return res.status(404).json({
        error: 'Пользователь не найден'
      });
    }

    res.status(200).json({
      message: 'Пользователь найден',
      user: row
    });
  });
});

// Запуск сервера
app.listen(PORT, () => {
  console.log(`Сервер запущен на http://localhost:${PORT}`);
});

// Инициализация базы при запуске
initializeDatabase();

module.exports = app;
```

---

### 🔐 Почему это безопасно?

- ✅ **Параметризованные запросы** (`?` вместо конкатенации) — полностью защищены от SQL-инъекций.
- ✅ **Валидация входных данных** (`Number.isInteger` и `userId > 0`) — исключает поддельные/опасные ID.
- ✅ **Отсутствие прямой передачи данных из запроса в SQL**.
- ✅ **Логирование ошибок** — с отладочными сообщениями **без раскрытия деталей клиенту**.

---

### 🧪 Пример запроса:

```bash
curl http://localhost:3000/users/1
```

**Ответ:**
```json
{
  "message": "Пользователь найден",
  "user": {
    "id": 1,
    "username": "alice",
    "email": "alice@example.com",
    "created_at": "2025-04-05 12:00:00"
  }
}
```

Если `id = 999`, вернёт `404 Not Found`.

Если `id = 'abc'`, вернёт `400 Bad Request`.

---

### 🛡️ Дополнительные меры (для продакшена):

- Использовать **подключение к БД через пул** (`sqlite3` не поддерживает пул, можно заменить на `better-sqlite3`).
- Запросы в `Promise`-базе (или `async/await`).
- Пагинация и ограничение доступа.
- Логирование запросов (через `morgan`).
- Аутентификация (JWT, cookies и т.д.).

