### ✅ Финальная функция:

```js
function transformArrayToTree(arr) {
    const result = {};

    const buildTree = (array, currentObj, index = 0) => {
        if (index >= array.length) return;

        const item = array[index];

        // Если текущий элемент — строка, создаём новый уровень
        if (typeof item === 'string') {
            // Проверка на ключи, которые задают контекст
            if (item === 'Read' || item === 'Write') {
                // Текущий блок — это операция: Read/Write
                const operation = item;
                const nextItem = array[index + 1];

                // Дальше идёт массив — это действия
                if (Array.isArray(nextItem)) {
                    // Определяем группу: Read → Positive, Write → Instantaneous
                    const group = operation === 'Read' ? 'Positive' : 'Instantaneous';

                    // Создаём подуровень в зависимости от текущего объекта
                    if (!currentObj[group]) {
                        currentObj[group] = {};
                    }

                    // Присваиваем массив в качестве значения
                    currentObj[group][operation] = nextItem;

                    // Продолжаем с индексом после массива
                    buildTree(array, currentObj, index + 2);
                } else {
                    // Если после Read/Write не массив — ошибка или неожиданно
                    console.warn(`Expected array after "${operation}", got ${typeof nextItem}`, nextItem);
                    buildTree(array, currentObj, index + 1);
                }
            } else {
                // Это просто ключ: DCU_DLMS, Parameters, General и т.п.
                if (!currentObj[item]) {
                    currentObj[item] = {};
                }
                buildTree(array, currentObj[item], index + 1);
            }
        }
        // Если элемент — массив (не строка), то он уже обработан как значение
        // (например, как Read/Write)
        else {
            // Это массив — ожидается, что он следует после Read/Write
            console.warn("Unexpected array at top level");
            buildTree(array, currentObj, index + 1);
        }
    };

    buildTree(arr, result);
    return result;
}
```

