/* Slide-up animation - Safe & Lightweight */
.slide-up {
  /* 总是定义基础属性 */
  position: relative;
  display: block;
  overflow: hidden;

  /* 动画属性 */
  animation: slideUp 0.4s ease-out forwards;

  /* 初始状态：完全隐藏，位置在上方 */
  opacity: 0;
  transform: translateY(20px); /* 从下方滑入 */
}

/* 定义动画关键帧 */
@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
