// Валидация Host заголовка (на уровне Nginx или в Node.js)
const isValidHost = (host) => {
  const validDomains = ['yourapp.com', 'yourapp.dev'];
  return validDomains.some(domain => host.endsWith(domain));
};

app.use((req, res, next) => {
  const host = req.get('Host');
  if (!isValidHost(host)) {
    return res.status(400).send('Bad Host header');
  }
  next();
});
