app.get('/users', (req, res) => {
  const { limit, offset } = req.query;

  // ❌ НЕ ДЕЛАЙ ТАК:
  // const limit = parseInt(req.query.limit);

  // ✅ ЛУЧШЕ: Валидация параметров
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  if (isNaN(limit) || limit < 1 || limit > 100) {
    return res.status(400).json({ error: 'Invalid limit (1-100)' });
  }

  if (isNaN(offset) || offset < 0) {
    return res.status(400).json({ error: 'Invalid offset' });
  }

  // Теперь можно использовать
  res.json({ limit, offset });
});
```

---

### ✅ 3. Валидация `req.body` — критически важно!

#### Пример: POST /user

```js
app.post('/users', (req, res) => {
  const { name, email, age } = req.body;

  // ❌ Опасно: без валидации
  // const user = new User(name, email, age);

  // ✅ Правильно: валидация с помощью библиотеки

  // Используй `joi` или `zod` — это лучший способ

  const schema = Joi.object({
    name: Joi.string().min(2).max(50).required(),
    email: Joi.string().email().required(),
    age: Joi.number().integer().min(18).max(120).optional()
  });

  const { error } = schema.validate(req.body);

  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }

  // Теперь безопасно
  const user = new User(name, email, age);
  user.save();

  res.status(201).json(user);
});
```

> 💡 **Библиотеки для валидации**:
> - [`Joi`](https://joi.dev/) — популярная, надёжная
> - [`Zod`](https://zod.dev/) — типобезопасная, очень мощная
