```

#### 2. **JavaScript (Client-Side)**

```javascript
const trigger = document.getElementById('preview-trigger');
const overlay = document.getElementById('preview-overlay');

// Fetch the preview data from a different page
async function fetchPreview() {
  try {
    // Use your trusted backend proxy to fetch the external page
    const response = await fetch('/api/preview?url=https://your-website.com/target-page#target-element', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
