    const targetElement = doc.querySelector('#preview-target'); // e.g., a product card
    if (targetElement) {
      overlay.innerHTML = targetElement.outerHTML;
    } else {
      overlay.innerHTML = '<p>Target element not found.</p>';
    }

  } catch (err) {
    overlay.innerHTML = `<p>Error: ${err.message}</p>`;
  }
}

