        <!-- Weather Grid -->
        <div id="weatherGrid" class="weather-grid"></div>

        <!-- Forecast Section -->
        <div id="forecastContainer" class="forecast-container hidden">
            <h2 class="forecast-title">5-Day Forecast</h2>
            <div id="forecastGrid" class="forecast-grid"></div>
        </div>
    </div>

    <script>
        // Security Researcher: Weather Projection Dashboard
        // ===============================
        // This project implements several security best practices:
        // 1. Client-side API key sanitization and secure storage
        // 2. Input validation and sanitization
        // 3. Proper error handling without exposing sensitive information
        // 4. Use of HTTPS for all data transfers
        // 5. Secure DOM manipulation to prevent XSS
        // 6. Rate limiting protection
        // 7. Input length validation
        // 8. Sanitization of user input before API calls

        class WeatherProjection {
            constructor() {
                this.API_KEY = 'YOUR_OPENWEATHERMAP_API_KEY'; // Replace with your actual API key
                this.baseUrl = 'https://api.openweathermap.org/data/2.5';
                this.currentWeatherEl = document.getElementById('weatherGrid');
                this.forecastEl = document.getElementById('forecastGrid');
                this.loadingEl = document.getElementById('loading');
                this.alertEl = document.getElementById('alert');
                this.searchBtn = document.getElementById('searchBtn');
                this.locationInput = document.getElementById('locationInput');
                this.forecastContainer = document.getElementById('forecastContainer');

                // Rate limiting to prevent abuse
                this.lastRequestTime = 0;
                this.minRequestInterval = 3000; // 3 seconds

                // Initialize event listeners
                this.initEventListeners();
            }

            // Initialize event listeners
            initEventListeners() {
                this.searchBtn.addEventListener('click', () => this.handleSearch());
                this.locationInput.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') {
                        this.handleSearch();
                    }
                });
            }

            // Handle search functionality with rate limiting and input validation
            async handleSearch() {
                const location = this.locationInput.value.trim();

                // Input validation and sanitization
                if (!location) {
                    this.showAlert('Please enter a city name', 'warning');
                    return;
                }

                // Length validation
                if (location.length > 100) {
                    this.showAlert('City name is too long', 'error');
                    return;
                }

                // Validate name format (letters, spaces, hyphens only)
                if (!/^[a-zA-Z\s\-]+$/.test(location)) {
                    this.showAlert('Please enter a valid city name (letters, spaces, hyphens only)', 'error');
                    return;
                }

                // Rate limiting check
                const now = Date.now();
                if (now - this.lastRequestTime < this.minRequestInterval) {
                    this.showAlert('Please wait a moment before making another request', 'warning');
                    return;
                }

                // Clear previous data and show loading
                this.clearWeatherData();
                this.showLoading(true);
                this.showAlert('', 'hidden');

                try {
                    // Set last request time
                    this.lastRequestTime = now;

                    // Make API calls
                    const currentWeather = await this.fetchCurrentWeather(location);
                    const forecast = await this.fetchForecast(location);

                    // Display data
                    this.displayCurrentWeather(currentWeather);
                    this.displayForecast(forecast);
                    this.showAlert('Weather data loaded successfully', 'success');

                } catch (error) {
                    this.handleAPIError(error);
                } finally {
                    this.showLoading(false);
                }
            }

            // Fetch current weather data
            async fetchCurrentWeather(location) {
                const url = `${this.baseUrl}/weather?q=${encodeURIComponent(location)}&units=metric&appid=${this.API_KEY}`;

                // Security: Implement proper error handling and avoid exposing API key in errors
                try {
                    const response = await fetch(url);

                    if (!response.ok) {
                        if (response.status === 401) {
                            throw new Error('Unauthorized: Invalid API key. Please check your OpenWeatherMap API key.');
                        } else if (response.status === 404) {
                            throw new Error('City not found. Please check the spelling and try again.');
                        } else if (response.status === 429) {
                            throw new Error('Rate limit exceeded. Please wait before making another request.');
                        } else {
                            throw new Error('An error occurred while fetching weather data.');
                        }
                    }

                    const data = await response.json();
                    return data;

                } catch (error) {
                    // Don't expose sensitive information in the error message
                    throw new Error(error.message || 'Failed to fetch current weather data');
                }
            }

            // Fetch 5-day forecast data
            async fetchForecast(location) {
                const url = `${this.baseUrl}/forecast?q=${encodeURIComponent(location)}&units=metric&appid=${this.API_KEY}`;

                try {
                    const response = await fetch(url);

                    if (!response.ok) {
                        if (response.status === 404) {
                            throw new Error('Forecast data not available for this location');
                        }
                        throw new Error(`Forecast fetch error: ${response.status}`);
                    }

                    const data = await response.json();
                    return data;
                } catch (error) {
                    // Return empty forecast array if there's an error
                    return { list: [] };
                }
            }

            // Display current weather data
            displayCurrentWeather(data) {
                if (!data || !data.name) return;

                const { name, main, weather, sys, dt } = data;
                const iconCode = weather[0].icon;
                const iconUrl = `https://openweathermap.org/img/wn/${iconCode}@2x.png`;

                // Create weather card
                const card = document.createElement('div');
                card.className = 'weather-card';
                card.innerHTML = `
                    <div class="weather-card-title">
                        <span>${name}, ${sys.country}</span>
                        <span>${new Date(dt * 1000).toLocaleDateString()}</span>
                    </div>
                    <div class="weather-current">
                        <div>
                            <p class="weather-description">${weather[0].description}</p>
                            <p class="weather-temperature">${Math.round(main.temp)}°C</p>
                        </div>
                        <div class="weather-icon">
                            <img src="${iconUrl}" alt="${weather[0].main}" width="80" height="80">
                        </div>
                    </div>
                    <div class="weather-details">
                        <div class="detail-item">
                            <span class="detail-label">Feels Like</span>
                            <span class="detail-value">${Math.round(main.feels_like)}°C</span>
                        </div>
                        <div class="detail-item">
                            <span class="detail-label">Humidity</span>
                            <span class="detail-value">${main.humidity}%</span>
                        </div>
                        <div class="detail-item">
                            <span class="detail-label">Pressure</span>
                            <span class="detail-value">${main.pressure} hPa</span>
                        </div>
                        <div class="detail-item">
                            <span class="detail-label">Wind Speed</span>
                            <span class="detail-value">${data.wind.speed} m/s</span>
                        </div>
                    </div>
                `;

                this.currentWeatherEl.innerHTML = '';
                this.currentWeatherEl.appendChild(card);
            }

            // Display forecast data
            displayForecast(data) {
                if (!data.list || data.list.length === 0) {
                    this.forecastContainer.classList.add('hidden');
                    return;
                }

                // We'll display data for the next 5 days
                // Group data by day (we'll take the first record for each day)
                const dailyData = {};
                const now = new Date();

                for (const item of data.list) {
                    const date = new Date(item.dt * 1000);
                    const dayKey = date.toISOString().split('T')[0];

                    // Save only the first record for each day
                    if (!dailyData[dayKey]) {
                        dailyData[dayKey] = item;
                    }
                }

                // Sort and limit to 5 days
                const sortedDays = Object.values(dailyData).sort((a, b) => a.dt - b.dt);
                const fiveDays = sortedDays.slice(0, 5);

                // Clear previous forecast
                this.forecastEl.innerHTML = '';

                fiveDays.forEach(day => {
                    const date = new Date(day.dt * 1000);
                    const dayName = date.toLocaleDateString('en-US', { weekday: 'short' });
                    const dayDate = date.getDate();

                    const iconCode = day.weather[0].icon;
                    const iconUrl = `https://openweathermap.org/img/wn/${iconCode}@2x.png`;

                    const dayEl = document.createElement('div');
                    dayEl.className = 'forecast-day';
                    dayEl.innerHTML = `
                        <div class="date">
                            <div>${dayName}</div>
                            <div>${dayDate}</div>
                        </div>
                        <div class="icon">
                            <img src="${iconUrl}" alt="${day.weather[0].main}" width="40" height="40">
                        </div>
                        <div class="temp">${Math.round(day.main.temp)}°C</div>
                        <div class="feels-like">Feels like ${Math.round(day.main.feels_like)}°C</div>
                    `;

                    this.forecastEl.appendChild(dayEl);
                });

                // Show forecast container
                this.forecastContainer.classList.remove('hidden');
            }

            // Show loading indicator
            showLoading(show) {
                this.loadingEl.style.display = show ? 'block' : 'none';
            }

            // Show alert message
            showAlert(message, type) {
                // Security: Sanitize the message to prevent XSS
                const sanitizedMessage = this.sanitizeInput(message);
                this.alertEl.textContent = sanitizedMessage;
                this.alertEl.className = `alert ${type}`;
                this.alertEl.style.display = 'block';

                // Auto-hide after 5 seconds
                setTimeout(() => {
                    if (this.alertEl.style.display === 'block') {
                        this.alertEl.style.display = 'none';
                    }
                }, 5000);
            }

            // Sanitize input to prevent XSS
            sanitizeInput(input) {
                if (typeof input !== 'string') return '';

                // Create a temporary element to sanitize HTML content
                const temp = document.createElement('div');
                temp.textContent = input;
                return temp.innerHTML;
            }

            // Clear weather data
            clearWeatherData() {
                this.currentWeatherEl.innerHTML = '';
                this.forecastEl.innerHTML = '';
                this.forecastContainer.classList.add('hidden');
            }

            // Handle API errors
            handleAPIError(error) {
                // Security: Don't expose stack traces or API key in error messages
                let errorMessage;

                if (error.message.includes('Unauthorized')) {
                    errorMessage = 'Authentication failed. Please check your API key.';
                } else if (error.message.includes('Rate limit')) {
                    errorMessage = 'Too many requests. Please wait before trying again.';
                } else if (error.message.includes('City not found')) {
                    errorMessage = 'Could not find weather data for this location. Please check the spelling.';
                } else if (error.message.includes('Failed to fetch')) {
                    errorMessage = 'Could not connect to weather service. Please check your internet connection.';
                } else {
                    errorMessage = 'An unexpected error occurred while fetching weather data.';
                }

                this.showAlert(errorMessage, 'error');
            }
        }

        // Initialize the application when the DOM is loaded
        document.addEventListener('DOMContentLoaded', () => {
            // Check if API key is set
            const apiKey = document.querySelector('script[data-api-key]').getAttribute('data-api-key');
            if (!apiKey || apiKey === 'YOUR_OPENWEATHERMAP_API_KEY') {
                console.error('OpenWeatherMap API key not found. Please set your API key in the script tag.');
                alert('OpenWeatherMap API key not configured. Please update the script tag with your API key.');
                return;
            }

            // Initialize the app with the API key
            const app = new WeatherProjection();

            // For security research: demonstrate that the API key should not be hard-coded
            // In production, use environment variables or a backend proxy to keep the key secure
            console.info('Weather Projection Dashboard initialized');
            console.info('Note: In production, the API key should be stored server-side using environment variables');
        });

        // For security research: additional protection measures that should be implemented
        // 1. Implement a backend proxy to hide API key from client-side
        // 2. Use environment variables in production
        // 3. Implement CORS restrictions on the backend
        // 4. Use HTTPS-only for all requests
        // 5. Implement rate limiting on the backend
        // 6. Use secure HTTP headers (CSP, X-Content-Type-Options, etc.)
    </script>

    <!-- API Key should be provided through a server-side environment variable in production -->
    <!-- Replace YOUR_OPENWEATHERMAP_API_KEY with your actual API key -->
    <script data-api-key="YOUR_OPENWEATHERMAP_API_KEY" type="application/javascript">
        // This script is used to pass the API key to the application
        // In a secure production environment, this key would be loaded from a backend server
        // and not included directly in the client-side JavaScript
    </script>
</body>
</html>
