// server.js
const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();
const PORT = 3000;

// Serve static files (your HTML game)
app.use(express.static(path.join(__dirname)));

// Middleware to parse JSON
app.use(express.json());

// File to store scores
const SCORES_FILE = path.join(__dirname, 'scores.txt');

// Route to get top scores
app.get('/scores', (req, res) => {
  try {
    const data = fs.readFileSync(SCORES_FILE, 'utf8');
    const scores = data.split('\n').map(line => line.trim()).filter(line => line);
    res.json(scores);
  } catch (err) {
    res.json([]);
  }
});

// Route to save a new score
app.post('/submit-score', (req, res) => {
  const { name, score } = req.body;
  const timestamp = new Date().toLocaleString();

  const line = `Name: ${name}, Score: ${score}, Date: ${timestamp}`;

  try {
    fs.appendFileSync(SCORES_FILE, line + '\n');
    res.status(200).json({ success: true });
  } catch (err) {
    res.status(500).json({ success: false, error: 'Could not save score.' });
  }
});

// Start server
