exports.login = async (req, res) => {
  const { email, password } = req.body;

  // 1. Проверка входных данных
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  // 2. Поиск пользователя по email
  try {
    const user = await UserModel.findByEmail(email);

    if (!user) {
      // Важно: не говорить, что email не найден — уязвимость для "user enumeration"
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    // 3. Сравнение хэша пароля
    const isPasswordValid = await bcrypt.compare(password, user.password_hash);

    if (!isPasswordValid) {
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    // 4. Генерация JWT токена
    const token = jwt.sign(
      { id: user.id, email: user.email, role: user.role },
      JWT_SECRET,
      { expiresIn: '1h' }
    );

    // 5. Создание secure-сессии (если используется cookie)
    res.cookie('auth_token', token, {
      httpOnly: true, // Предотвращает XSS
      secure: process.env.NODE_ENV === 'production', // HTTPS только в проде
      sameSite: 'strict', // Защита от CSRF
      maxAge: 60 * 60 * 1000 // 1 час
    });

    return res.status(200).json({
      message: 'Login successful',
      user: { id: user.id, email: user.email, role: user.role }
    });

  } catch (err) {
    console.error('Login error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
};

// POST /register
exports.register = async (req, res) => {
  const { email, password, role } = req.body;

  // Проверка входных данных
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  // Убедимся, что email валиден
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // Проверка длины пароля
  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  try {
    // Проверка, существует ли пользователь
    const existing = await UserModel.findByEmail(email);
    if (existing) {
      return res.status(409).json({ error: 'User already exists' });
    }

    // Хэширование пароля (bcrypt)
    const saltRounds = 12;
    const password_hash = await bcrypt.hash(password, saltRounds);

    // Создание пользователя
    const userId = await UserModel.create({
      email,
      password_hash,
      role: role || 'user'
    });

    return res.status(201).json({ message: 'User registered successfully', userId });

  } catch (err) {
    console.error('Registration error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
};
```

### 🔐 Ключевые моменты безопасности в Controller:
- ❌ **Нет уязвимостей** к "user enumeration" (один ответ на все ошибки).
- ✅ Используется **bcrypt** для хранения паролей.
- ✅ Используется **JWT** с `httpOnly`, `secure`, `sameSite` cookie.
- ✅ Все данные проверяются (валидация формы, длина пароля).
- ✅ Нет `req.body` без проверки.

