    // DOM Elements
    const costPriceInput = document.getElementById('costPrice');
    const sellingPriceInput = document.getElementById('sellingPrice');
    const desiredMarkupInput = document.getElementById('desiredMarkup');
    const calculateBtn = document.getElementById('calculateBtn');

    // Chart canvases
    const barChartCtx = document.getElementById('barChart').getContext('2d');
    const pieChartCtx = document.getElementById('pieChart').getContext('2d');

    // Global charts (initialized later)
    let barChart = null;
    let pieChart = null;

    // Initialize charts (empty)
    function initCharts() {
      barChart = new Chart(barChartCtx, {
        type: 'bar',
        data: {
          labels: ['Cost', 'Markup', 'Profit'],
          datasets: [{
            label: 'Amount ($)',
            data: [0, 0, 0],
            backgroundColor: ['#e74c3c', '#f39c12', '#27ae60'],
          }]
        },
        options: {
          responsive: true,
          plugins: {
            legend: { display: true }
          }
        }
      });

      pieChart = new Chart(pieChartCtx, {
        type: 'doughnut',
        data: {
          labels: ['Cost', 'Profit'],
          datasets: [{
            data: [0, 0],
            backgroundColor: ['#e74c3c', '#27ae60'],
          }]
        },
        options: {
          responsive: true,
          plugins: {
            legend: { position: 'top' }
          }
        }
      });
    }

    // Calculate markup logic
    function calculate() {
      const cost = parseFloat(costPriceInput.value) || 0;
      const selling = parseFloat(sellingPriceInput.value) || 0;
      const desiredMarkup = parseFloat(desiredMarkupInput.value) || 0;

      let markupPercent = 0;
      let profit = 0;
      let markupAmount = 0;

      // If selling price is provided, calculate all derived metrics
      if (selling > 0) {
        profit = selling - cost;
        markupAmount = selling - cost;
        markupPercent = (markupAmount / cost) * 100;
      }

      // If desired markup is provided, calculate required selling price
      const requiredSelling = desiredMarkup > 0 ? cost * (1 + desiredMarkup / 100) : 0;

      // Update UI results
      const results = {
        cost,
        selling,
        desiredMarkup,
        markupPercent,
        profit,
        markupAmount,
        requiredSelling
      };

      // Update Charts
      updateCharts(results);

      return results;
    }

    // Update charts with new data
    function updateCharts(results) {
      const { cost, profit, markupAmount } = results;

      // BAR CHART: Cost, Markup, Profit
      barChart.data.datasets[0].data = [cost, markupAmount, profit];
      barChart.update();

      // PIE CHART: Cost vs. Profit
      pieChart.data.datasets[0].data = [cost, profit];
      pieChart.update();

      // Optional: log results for developers
      console.log('Updated Charts with:', results);
    }

    // Calculate button event
    calculateBtn.addEventListener('click', () => {
      const results = calculate();
      // Optional: Display summary
      console.log('Calculated:', results);
    });

