### ✅ 2. **Corrige `remplirQuestions()` pour afficher les questions avec leurs détails**

```js
function remplirQuestions(data) {
    const questions = data.questions;
    $('#questions').empty();
    const ul = $('<ul>');

    questions.forEach(question => {
        const li = $('<li>').addClass('question-item');

        // Titre
        const title = $('<h4>').text(question.title);

        // Question Type et réponses
        let content = $('<p>').text("Type: " + question.questionType);
        if (question.questionType === "multiple") {
            content.append(
                $('<br>')
                .append("Choix 1: ").append($('<span>').text(question.proposition1))
                .append(' / Choix 2: ').append($('<span>').text(question.proposition2))
                .append('<br>')
                .append("Réponse = ").append(question.reponse === 1 ? question.proposition1 : question.proposition2)
            );
        } else if (question.questionType === "simple") {
            content.append($('<br>').text("Réponse = " + question.reponse));
        }

        // Liens de modification/suppression
        const editBtn = $('<button>').text("Modifier").on("click", () => formQuestionnaire(false, question));
        const delBtn = $('<button>').text("Supprimer").on("click", () => delQuestion(question.url));

        // Ajout au li
        li.append(title)
          .append(content)
          .append($('<br>'))
          .append(editBtn)
          .append(' ')
          .append(delBtn);

        ul.append(li);
    });

    $('#questions').append(ul);
}
```

> ✅ On affiche **l’ID**, **le type**, **les réponses**, et **des boutons** pour modifier/supprimer.

