### ✅ 4. **Corrige `SaveNewQuestion()` pour envoyer les bons champs**

```js
function SaveNewQuestion() {
    const isMultiple = $("#isMultiple").is(":checked");
    const title = $("#title").val();
    const questionnaire_id = $("#questionnaire_id").val();

    if (!title || !questionnaire_id) {
        alert("Veuillez remplir le titre et le questionnaire");
        return;
    }

    let payload = {
        title: title,
        questionType: isMultiple ? "multiple" : "simple",
        questionnaire_id: parseInt(questionnaire_id)
    };

    if (isMultiple) {
        const prop1 = $("#textChoix1").val();
        const prop2 = $("#textChoix2").val();
        const reponse = $("#choix1").is(":checked") ? 1 : 2;
        if (!prop1 || !prop2) {
            alert("Les choix doivent être remplis !");
            return;
        }
        payload.proposition1 = prop1;
        payload.proposition2 = prop2;
        payload.reponse = reponse;
    } else {
        const reponse = $("#reponse").val();
        if (!reponse) {
            alert("La réponse est obligatoire");
            return;
        }
        payload.reponse = reponse;
    }

    fetch("http://localhost:5000/quiz/api/v1.0/questions", {
        method: "POST",
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
    })
    .then(res => {
        if (res.ok) {
            console.log('Question ajoutée avec succès');
            refreshQuestionnaireList(); // Rafraîchit la liste
            $("#currenttask").empty(); // Efface le formulaire
        } else {
            throw new Error('Échec de l\'ajout');
        }
    })
    .catch(err => {
        console.error("Erreur : ", err);
        alert("Erreur lors de l'ajout : " + err.message);
    });
}
```

