// 安全地给 table 的每行添加序号
function addTableRowNumbers(tableSelector) {
  // 输入验证：确保 selector 是字符串且非空
  if (typeof tableSelector !== 'string' || !tableSelector.trim()) {
    console.error('Invalid table selector provided.');
    return;
  }

  const table = document.querySelector(tableSelector);
  if (!table) {
    console.warn(`Table not found: ${tableSelector}`);
    return;
  }

  // 确保是 table 元素
  if (table.tagName !== 'TABLE') {
    console.error('Selected element is not a <table> element.');
    return;
  }

  // 获取所有 <tr> 元素
  const rows = table.querySelectorAll('tbody tr, tfoot tr, thead tr');
  const headerRow = table.querySelector('thead tr');

  // 安全地遍历每行
  rows.forEach((row, index) => {
    // 避免重复添加序号（防止多次运行出错）
    if (row.querySelector('[data-row-index]')) {
      console.debug('Row already has a row index. Skipping.');
      return;
    }

    // 创建新的 th 或 td 元素用于序号
    const cell = document.createElement('td');
    cell.textContent = index + 1; // 从1开始编号
    cell.setAttribute('data-row-index', index + 1);
    cell.style.textAlign = 'center';
    cell.style.width = '2rem';
    cell.style.padding = '0.5em';
    cell.style.border = '1px solid #ccc';

    // 插入到行首
    const firstChild = row.firstElementChild || row;
    row.insertBefore(cell, firstChild);

    // 可选：添加 class 标记以方便后续 CSS 或 JS 识别
    row.classList.add('has-row-number');
  });

  console.info(`Added row numbers to table: ${tableSelector}`);
}

