## 8. Order Controller (server/controllers/orderController.js)

```javascript
// server/controllers/orderController.js
const Order = require('../models/Order');
const User = require('../models/User');

// @desc    Create new order
// @route   POST /api/orders
// @access  Private
const createOrder = async (req, res) => {
  try {
    const { items, total, notes, deliveryAddress, phoneNumber } = req.body;
    const userId = req.user._id;

    // Validate required fields
    if (!items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ error: 'Items are required' });
    }

    if (!total || total <= 0) {
      return res.status(400).json({ error: 'Valid total is required' });
    }

    if (!deliveryAddress) {
      return res.status(400).json({ error: 'Delivery address is required' });
    }

    if (!phoneNumber) {
      return res.status(400).json({ error: 'Phone number is required' });
    }

    // Validate each item
    for (const item of items) {
      if (!item.name || !item.quantity || !item.price) {
        return res.status(400).json({ error: 'Each item must have name, quantity, and price' });
      }

      if (item.quantity < 1 || item.price < 0) {
        return res.status(400).json({ error: 'Invalid quantity or price for item' });
      }
    }

    // Create the order
    const order = await Order.create({
      user: userId,
      items,
      total,
      notes,
      deliveryAddress,
      phoneNumber
    });

    res.status(201).json(order);

  } catch (error) {
    console.error('Create order error:', error);
    res.status(500).json({ error: 'Server error creating order' });
  }
};

// @desc    Get all user orders
// @route   GET /api/orders
// @access  Private
const getMyOrders = async (req, res) => {
  try {
    const orders = await Order.find({ user: req.user._id }).sort({ createdAt: -1 });

    res.status(200).json(orders);
  } catch (error) {
    console.error('Get orders error:', error);
    res.status(500).json({ error: 'Server error retrieving orders' });
  }
};

// @desc    Get order by ID (for user)
// @route   GET /api/orders/:id
// @access  Private
const getOrderById = async (req, res) => {
  try {
    const order = await Order.findOne({ _id: req.params.id, user: req.user._id });

    if (!order) {
      return res.status(404).json({ error: 'Order not found' });
    }

    res.status(200).json(order);
  } catch (error) {
    console.error('Get order by ID error:', error);
    res.status(500).json({ error: 'Server error retrieving order' });
  }
};

// @desc    Get all orders (admin only)
// @route   GET /api/orders/admin
// @access  Private (admin)
const getAllOrders = async (req, res) => {
  try {
    const orders = await Order.find().sort({ createdAt: -1 });

    res.status(200).json(orders);
  } catch (error) {
    console.error('Get all orders error:', error);
    res.status(500).json({ error: 'Server error retrieving orders' });
  }
};

module.exports = {
  createOrder,
  getMyOrders,
  getOrderById,
  getAllOrders
};
