  <div id="weather-output"></div>
</div>
```

### JavaScript: Update the DOM

```javascript
function displayWeather(data) {
  const outputDiv = document.getElementById('weather-output');

  const city = data.name;
  const temp = Math.round(data.main.temp - 273.15); // Convert from Kelvin to Celsius
  const description = data.weather[0].description;
  const country = data.sys.country;

  outputDiv.innerHTML = `
    <h2>${city}, ${country}</h2>
    <p>🌡️ Temperature: ${temp}°C</p>
    <p>🌤️ Condition: ${description}</p>
  `;
}
```

### Add Event Listener

```javascript
document.getElementById('fetch-btn').addEventListener('click', () => {
  const city = document.getElementById('city-input').value.trim();
  if (!city) {
    alert('Please enter a city name!');
    return;
  }

  const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=YOUR_API_KEY`;

  fetch(url)
    .then(response => {
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return response.json();
    })
    .then(data => displayWeather(data))
    .catch(error => {
      console.error('Fetch error:', error);
      alert(`Oops! Couldn't fetch weather for "${city}". Try again.`);
    });
});
```

> ⚠️ **Security Tip**: We use `encodeURIComponent()` on the city name to prevent malformed URLs and potential injection attacks (like `city=Paris%2F%3Cscript%3Ealert(%27XSS%27)%3C/script%3E`).

