```js
import { fromEvent, of } from 'rxjs';
import { map, switchMap, filter, tap, catchError } from 'rxjs/operators';
import { ajax } from 'rxjs/ajax';

// URL для загрузки JSON (файл из лаб.7)
const DATA_URL = 'data.json';

// DOM элементы
const showBtn = document.getElementById('showBtn');
const deleteBtn = document.getElementById('deleteBtn');
const container = document.getElementById('data-container');
const emptyMsg = container.querySelector('.empty');

// Флаг, чтобы отследить, загружены ли данные
let dataRows = [];

// Инициализация RxJS: отслеживание события "click" на кнопке "Показать данные"
fromEvent(showBtn, 'click')
  .pipe(
    // Отключаем кнопку на время загрузки
    tap(() => {
      showBtn.disabled = true;
      showBtn.textContent = 'Загрузка...';
    }),

    // Попытка загрузки JSON
    switchMap(() =>
      ajax
        .getJSON(DATA_URL)
        .pipe(
          // Обработка успешного ответа
          map((responseData) => {
            // Превращаем объект в массив строк для отображения
            return Object.entries(responseData).map(([key, value]) => ({
              key,
              value: typeof value === 'object' ? JSON.stringify(value) : value
            }));
          }),

          // Обработка ошибок
          catchError((error) => {
            console.error('Ошибка загрузки данных:', error);
            alert('Не удалось загрузить данные. Проверьте, доступен ли файл data.json.');
            return of([]); // возвращаем пустой массив
          })
        )
    ),

    // Обновление DOM
    tap((newData) => {
      dataRows = newData; // Сохраняем данные

      // Очищаем контейнер и добавляем строки
      container.innerHTML = '';

      if (newData.length === 0) {
        container.innerHTML = '<p class="empty">Данные не найдены</p>';
      } else {
        newData.forEach(row => {
          const div = document.createElement('div');
          div.className = 'data-row';
          div.innerHTML = `<span><strong>${row.key}</strong></span><span>${row.value}</span>`;
          container.appendChild(div);
        });
      }

      // Включаем кнопку "Удалить"
      deleteBtn.disabled = false;

      // Восстановление кнопки "Показать данные"
      showBtn.disabled = false;
      showBtn.textContent = 'Показать данные';
    })
  )
  .subscribe();

// Отслеживание события "click" на кнопке "Удалить"
fromEvent(deleteBtn, 'click')
  .pipe(
    filter(() => dataRows.length > 0),
    tap(() => {
      // Удаляем последнюю строку из `dataRows`
      dataRows.pop();

      // Обновляем DOM
      container.innerHTML = '';

      if (dataRows.length === 0) {
        container.innerHTML = '<p class="empty">Данные не загружены</p>';
        deleteBtn.disabled = true;
      } else {
        dataRows.forEach(row => {
          const div = document.createElement('div');
          div.className = 'data-row';
          div.innerHTML = `<span><strong>${row.key}</strong></span><span>${row.value}</span>`;
          container.appendChild(div);
        });
      }

      console.log('Последняя строка удалена');
    })
  )
  .subscribe();
```

