// composables/useQueue.ts
import { ref, reactive, watch, onUnmounted, inject } from 'vue';

// Typ für ein Queue-Element
export interface QueueItem {
  type: string;
  [key: string]: any; // beliebige zusätzliche Properties
  fromQueue?: boolean;
  step?: number;
}

// Interface für den EventBus (Typisierung)
export interface EventBus {
  emit(event: string, payload?: any): void;
  on(event: string, callback: (payload?: any) => void): void;
  off(event: string, callback: (payload?: any) => void): void;
}

// Haupt-Composable
export const useQueue = () => {
  // Reaktive Zustände
  const items = ref<QueueItem[]>([]);
  const queueRunning = ref(false);

  // Injection: eventBus mit Typensicherheit
  const $eventBus = inject<EventBus>('eventbus', null);

  if (!$eventBus) {
    console.warn('⚠️ useQueue: eventBus not provided! Queue will not work.');
  }

  // Referenz um Timeout-Timer zu speichern (für cleanup)
  let timeoutId: number | null = null;

  // Hilfsfunktion: EventListener-Handler
  const playQueuedEnded = (event: Event) => {
    // Entferne Listener sofort
    const target = event.target as EventTarget;
    target?.removeEventListener('ended', playQueuedEnded, true);

    if (items.value.length === 0) {
      queueRunning.value = false;
      console.log('✅ Queue: playQueuedEnded - no items left, queue stopped.');
    } else {
      console.log(
        `🔄 Queue: playQueuedEnded - ${items.value.length} items remaining, scheduling next run in ${config.settings.alerts.queueTimeDistance}ms`
      );

      // Timeout für nächste Ausführung
      timeoutId = window.setTimeout(playQueued, config.settings.alerts.queueTimeDistance);
    }
  };

  // Queue-Item ausführen (FIFO)
  const playQueued = () => {
    if (items.value.length === 0) {
      queueRunning.value = false;
      return;
    }

    queueRunning.value = true;
    const item = items.value.shift();

    if (!item) return;

    item.fromQueue = true;
    item.step = 4;

    console.log('🟢 Queue: playing item:', item.type, item);

    // Event auslösen
    if ($eventBus) {
      $eventBus.emit(item.type, item);
    } else {
      console.warn('⚠️ useQueue: eventBus not available, cannot emit event:', item.type);
    }
  };

  // Hinzufügen eines Items zur Queue
  const addToQueue = (item: QueueItem) => {
    const newItem = {
      ...item,
      fromQueue: true,
      step: 3,
    };

    items.value.push(newItem);

    console.log(
      `📦 Queue: added item to queue (${items.value.length} total), queueRunning: ${queueRunning.value}`
    );

    // Starte die Queue, wenn sie nicht läuft
    if (!queueRunning.value) {
      console.log('⚡ Queue: starting playback as queue is idle.');
      playQueued();
    }
  };

  // Prüfen, ob die Queue leer ist
  const isEmpty = (): boolean => items.value.length === 0;

  // Optionale: Konfiguration über `inject` oder lokal konfigurieren
  const config = inject('config', {
    settings: {
      alerts: {
        queueTimeDistance: 5000, // Standard: 5 Sekunden
      },
    },
  });

  // Cleanup-Handler bei Unmount
  onUnmounted(() => {
    if (timeoutId !== null) {
      window.clearTimeout(timeoutId);
      timeoutId = null;
    }
    console.log('🧹 Queue: cleanup completed - timers cleared.');
  });

  // Optional: Watcher für Reaktivität (z. B. bei externem Modifizieren)
  watch(
    () => items.value.length,
    (length) => {
      if (length > 0 && !queueRunning.value) {
        console.log('🔔 Queue: items added but not running, starting play...');
        playQueued();
      }
    }
  );

  // Public API
  return {
    items,
    queueRunning,
    isEmpty,
    addToQueue,
    // Optionale Hilfsmethoden
    playQueued,
    playQueuedEnded,
    config,
  };
};
```

