        trips.push({ rank, cards: group });
      }
    }

    // Must have at least two pairs
    if (pairs.length < 2) return null;

    // Take the two highest pairs
    pairs.sort((a, b) => b.rank - a.rank); // Sort by rank value (higher first)

    const pair1 = pairs[0].cards;
    const pair2 = pairs[1].cards;

    // Find the kicker card (remaining card not in pairs)
    const allRanksInPairs = new Set([pairs[0].rank, pairs[1].rank]);
    let kicker = null;
    for (const card of sortedCards) {
      if (!allRanksInPairs.has(card.rank)) {
        kicker = card;
        break;
      }
    }

    if (!kicker) return null;

    // Construct result cards: highest pair, second pair, kicker
    const resultCards = [
      ...pair1,
      ...pair2,
      kicker
    ].sort((a, b) => b.value - a.value); // Sort by value descending

    return {
      combination: new TwoPairs(),
      cards: resultCards
    };
  }
}

// Main function to determine winners
function determineWinners(playerHands, boardCards) {
  if (!Array.isArray(playerHands) || !Array.isArray(boardCards)) {
    throw new Error("Invalid input: playerHands and boardCards must be arrays");
  }

  const allHands = playerHands.map((hand) => [...hand, ...boardCards]);
  const bestHands = allHands.map((hand) => getBestHand(hand));
  const maxRank = Math.max(...bestHands.map((hand) => hand?.rank || 0));

  return bestHands.reduce((winners, hand, index) => {
    if (hand && hand.rank === maxRank) {
      winners.push({
        playerId: index,
        winningCombinationId: hand.combination.id,
        winningCards: hand.cards
      });
    }
    return winners;
  }, []);
}

// Function to evaluate best 5-card hand from 7 cards
function getBestHand(cards) {
  if (cards.length < 5) return null;

  const combinations = [
    RoyalFlush,
    StraightFlush,
    FourOfAKind,
    FullHouse,
    Flush,
    Straight,
    ThreeOfAKind,
    TwoPairs,
    Pair
  ];

  // Try each combination in descending order of rank
  for (const combination of combinations) {
    const result = combination.test(cards);
    if (result !== null) {
      return { rank: combination.rank, combination: combination, cards: result.cards };
    }
  }

  // If no combination found, return "High Card" as lowest
  return { rank: 1, combination: new Combination("High Card", 1, 1), cards: cards.sort((a, b) => b.value - a.value).slice(0, 5) };
}

