## 🚀 2. `server.js`
```js
const express = require('express');
const axios = require('axios');
const app = express();
const PORT = 3000;

// Konfigurasi YouTube API
const YOUTUBE_API_KEY = 'YOUR_YOUTUBE_API_KEY_HERE'; // GANTI DENGAN API KEY ANDA
const CHANNEL_ID = 'UC_x5XG1OV2pXb_3c9vqzj7g'; // GANTI DENGAN CHANNEL ID YANG MAU DIAMBIL
const MAX_RESULTS = 12; // Jumlah video per halaman

app.use(express.static('public'));
app.use(express.json());

// Route utama: ambil video dari YouTube
app.get('/api/videos', async (req, res) => {
  try {
    const pageToken = req.query.pageToken || '';
    const response = await axios.get('https://www.googleapis.com/youtube/v3/search', {
      params: {
        part: 'snippet',
        channelId: CHANNEL_ID,
        order: 'date',
        maxResults: MAX_RESULTS,
        pageToken: pageToken,
        key: YOUTUBE_API_KEY,
        type: 'video',
        videoCategoryId: '10' // Musik (opsional; sesuaikan kategori)
      }
    });

    const items = response.data.items;
    const nextPageToken = response.data.nextPageToken;
    const prevPageToken = response.data.prevPageToken;

    // Ambil ID video dan buat URL iframe
    const videos = items.map(item => ({
      id: item.id.videoId,
      title: item.snippet.title,
      description: item.snippet.description,
      thumbnail: item.snippet.thumbnails.medium.url,
      publishedAt: item.snippet.publishedAt
    }));

    res.json({
      videos,
      nextPageToken,
      prevPageToken,
      totalPages: Math.ceil(response.data.pageInfo.totalResults / MAX_RESULTS)
    });
  } catch (error) {
    console.error('Error fetching YouTube data:', error.response?.data || error.message);
    res.status(500).json({ error: 'Failed to fetch videos' });
  }
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

> 🛠️ Ganti `YOUR_YOUTUBE_API_KEY_HERE` dan `CHANNEL_ID` dengan data Anda.

