## 🔄 5. `public/script.js`
```js
let currentPage = 1;
let nextPageToken = '';
let prevPageToken = '';

async function fetchVideos(page = 1, pageToken = '') {
  try {
    const response = await fetch(`/api/videos?pageToken=${pageToken}`);
    const data = await response.json();

    const container = document.getElementById('video-container');
    container.innerHTML = '';

    const videos = data.videos;
    const totalPages = data.totalPages;

    videos.forEach(video => {
      const col = document.createElement('div');
      col.className = 'col-md-4 mb-4';
      col.innerHTML = `
        <div class="card h-100 bg-white">
          <img src="${video.thumbnail}" class="card-img-top" alt="${video.title}">
          <div class="card-body">
            <h5 class="card-title">${video.title}</h5>
            <p class="card-text">${video.description.substring(0, 100)}...</p>
            <a href="https://www.youtube.com/watch?v=${video.id}" target="_blank" class="btn btn-primary btn-sm">
              Lihat di YouTube
            </a>
          </div>
        </div>
      `;
      container.appendChild(col);
    });

    updatePagination(page, totalPages, data.nextPageToken, data.prevPageToken);
  } catch (error) {
    console.error('Error:', error);
    document.getElementById('video-container').innerHTML = '<p class="text-danger">Gagal memuat video.</p>';
  }
}

function updatePagination(page, totalPages, nextToken, prevToken) {
  const pagination = document.getElementById('pagination');
  pagination.innerHTML = '';

  if (prevToken) {
    const prevLi = document.createElement('li');
    prevLi.className = 'page-item';
    prevLi.innerHTML = `<a class="page-link" href="#" onclick="fetchVideos(${page - 1}, '${prevToken}')">&laquo; Sebelumnya</a>`;
    pagination.appendChild(prevLi);
  }

  for (let i = 1; i <= totalPages; i++) {
    const li = document.createElement('li');
    li.className = `page-item ${i === page ? 'active' : ''}`;
    li.innerHTML = `<a class="page-link" href="#" onclick="fetchVideos(${i}, '')">${i}</a>`;
    pagination.appendChild(li);
  }

  if (nextToken) {
    const nextLi = document.createElement('li');
    nextLi.className = 'page-item';
    nextLi.innerHTML = `<a class="page-link" href="#" onclick="fetchVideos(${page + 1}, '${nextToken}')">Berikutnya &raquo;</a>`;
    pagination.appendChild(nextLi);
  }

  currentPage = page;
  nextPageToken = nextToken;
  prevPageToken = prevToken;
}

// Load halaman pertama saat halaman dibuka
window.onload = () => {
  fetchVideos(1);
};
```

