/**
 * Secure Addition Function
 *
 * Safely adds two numbers with strict validation and type safety.
 * Prevents injection attacks, type juggling, and misuse.
 *
 * @param mixed $a First operand
 * @param mixed $b Second operand
 * @return float|int|false The sum if valid, false otherwise
 */
function secureAdd($a, $b) {
    // Step 1: Validate inputs are numeric (allow integers, floats, strings that represent numbers)
    if (!is_numeric($a) || !is_numeric($b)) {
        error_log("SECURITY ALERT: Invalid input detected - non-numeric values provided to secureAdd. Input A: '$a', Input B: '$b'");
        return false;
    }

    // Step 2: Convert to float to handle decimals and avoid integer overflow issues
    // Use floatval to ensure numeric type and prevent type juggling
    $numA = floatval($a);
    $numB = floatval($b);

    // Step 3: Check for special floating-point values (NaN, Infinity)
    if (is_nan($numA) || is_nan($numB)) {
        error_log("SECURITY ALERT: NaN value detected in inputs to secureAdd.");
        return false;
    }

    if (is_infinite($numA) || is_infinite($numB)) {
        error_log("SECURITY ALERT: Infinite value detected in inputs to secureAdd.");
        return false;
    }

    // Step 4: Optional: Define safe bounds to prevent DoS via extremely large numbers
    $maxSafeValue = 1e15; // Adjust based on your application's needs
    if (abs($numA) > $maxSafeValue || abs($numB) > $maxSafeValue) {
        error_log("SECURITY ALERT: Input value too large in secureAdd. Value: $numA or $numB");
        return false;
    }

    // Step 5: Perform addition
    $result = $numA + $numB;

    // Optional: Check result for overflow (though PHP handles this via float semantics)
    if (is_infinite($result) || is_nan($result)) {
        error_log("SECURITY ALERT: Result of addition is invalid (infinite or NaN).");
        return false;
    }

    // Step 6: Return integer if result is whole number, otherwise float
    return (int)$result == $result ? (int)$result : $result;
}

