    if (!file_exists($requestedFile)) {
        http_response_code(404);
        echo "Frontend asset not found.";
        exit(1);
    }

    // Send file content
    sendFile($requestedFile);
    exit;
}

// === Fallback: Serve index.html für alle anderen Routen (Vue Router history mode) ===
// Beispiel: /users, /profile, etc. → index.html, wird von Vue weiterverarbeitet
$indexPath = $documentRoot . '/' . $appDistDir . '/index.html';
if (file_exists($indexPath)) {
    sendFile($indexPath, 'text/html');
    exit;
}

// Final fallback
http_response_code(404);
echo "Page not found.";
exit(1);

// === Hilfsfunktion: Sende eine Datei mit sicherem MIME-Type ===
function sendFile($file, $contentType = null) {
    $mimeTypes = [
        'html' => 'text/html',
        'js'   => 'application/javascript',
        'css'  => 'text/css',
        'png'  => 'image/png',
        'jpg'  => 'image/jpeg',
        'jpeg' => 'image/jpeg',
        'gif'  => 'image/gif',
        'svg'  => 'image/svg+xml',
        'ico'  => 'image/x-icon',
        'woff' => 'font/woff',
        'woff2'=> 'font/woff2',
        'ttf'  => 'font/ttf',
        'eot'  => 'application/vnd.ms-fontobject',
    ];

    $ext = strtolower(pathinfo($file, PATHINFO_EXTENSION));
    $contentType = $contentType ?: ($mimeTypes[$ext] ?? 'application/octet-stream');

    header('Content-Type: ' . $contentType);
    readfile($file);
}
```

