    {
        // Si c’est un tableau, on vérifie que tous les corrects sont présents
        if (!is_array($userAnswer)) {
            return false;
        }

        $userAnswerSet = array_flip($userAnswer);
        $correctAnswerSet = array_flip($this->correct); // Supposons que "correct" est un tableau

        if (count($userAnswerSet) !== count($correctAnswerSet)) {
            return false;
        }

        foreach ($correctAnswerSet as $val => $bool) {
            if (!isset($userAnswerSet[$val])) {
                return false;
            }
        }

        return true;
    }
