```php
<?php
abstract class Question
{
    protected string $uuid;
    protected string $type;
    protected string $label;
    protected array $choices;
    protected mixed $correct;

    public function __construct(array $data)
    {
        $this->uuid = $data['uuid'] ?? '';
        $this->type = $data['type'] ?? '';
        $this->label = $data['label'] ?? '';
        $this->choices = $data['choices'] ?? [];
        $this->correct = $data['correct'] ?? null;
    }

    abstract public function afficheQuestion(): void;

    abstract public function checkReponse(mixed $userAnswer): bool;

    // Getters
    public function getUuid(): string
    {
        return $this->uuid;
    }

    public function getType(): string
    {
        return $this->type;
    }

    public function getLabel(): string
    {
        return htmlspecialchars($this->label, ENT_QUOTES, 'UTF-8');
    }

    public function getChoices(): array
    {
        return array_map('htmlspecialchars', $this->choices, ENT_QUOTES, 'UTF-8');
    }
}
```

