<?php
class CheckboxQuestion extends Question
{
    public function afficheQuestion(): void
    {
        echo "<div class='question'>\n";
        echo "<p><strong>{$this->getLabel()}</strong></p>\n";
        foreach ($this->getChoices() as $choice) {
            echo "<label>\n";
            echo "<input type='checkbox' name='{$this->getUuid()}[]' value='$choice'> ";
            echo "$choice\n";
            echo "</label><br>\n";
        }
        echo "</div>\n";
    }

    public function checkReponse(mixed $userAnswer): bool
    {
        if (!is_array($userAnswer)) {
            return false;
        }

        $userAnswers = array_map('trim', $userAnswer);
        $correct = (array)$this->correct;
        sort($userAnswers);
        sort($correct);

        return $userAnswers === $correct;
    }
}
