<?php
class Quiz
{
    private array $questions = [];
    private int $score = 0;

    public function addQuestion(Question $question): void
    {
        $this->questions[] = $question;
    }

    public function getQuestions(): array
    {
        return $this->questions;
    }

    public function afficheQuiz(): void
    {
        echo "<form method='POST' action='Action/submit.php'>\n";
        echo "<div class='quiz-container'>\n";

        foreach ($this->questions as $question) {
            $question->afficheQuestion();
        }

        echo "<button type='submit' name='submit'>Soumettre</button>\n";
        echo "</div>\n";
        echo "</form>\n";
    }

    public function checkReponse(array $userAnswers): int
    {
        $this->score = 0;

        foreach ($this->questions as $question) {
            $questionId = $question->getUuid();
            $userAnswer = $userAnswers[$questionId] ?? null;

            if ($question->checkReponse($userAnswer)) {
                $this->score++;
            }
        }

        return $this->score;
    }

    public function getScore(): int
    {
        return $this->score;
    }
}
```

