}

// Validate CSRF on submission
if ($_POST) {
    $token = $_POST['csrf_token'] ?? '';
    if (!hash_equals($_SESSION['csrf_token'], $token)) {
        $errors[] = 'Invalid CSRF token.';
    }
    // ... continue validation
}
?>

