```php
<?php
// backup.php

require_once 'config.php';

// --- 1. Vérification des prérequis ---
if (!is_dir(BACKUP_DIR)) {
    die("Error: Backup directory does not exist.\n");
}
if (!is_writable(BACKUP_DIR)) {
    die("Error: Backup directory is not writable.\n");
}

// --- 2. Génération du nom du fichier ---
$timestamp = date('Ymd_His');
$filename = sprintf('%s/%s_%s.sql', BACKUP_DIR, DB_NAME, $timestamp);
$final_file = $filename;

// --- 3. Utilisation de mysqldump via shell_exec (le plus sûr)
// Important : échapper les valeurs
$cmd = sprintf(
    'mysqldump --host=%s --user=%s --password=%s %s | gzip > %s',
    escapeshellarg(DB_HOST),
    escapeshellarg(DB_USER),
    escapeshellarg(DB_PASS),
    escapeshellarg(DB_NAME),
    escapeshellarg($final_file)
);

// Exécuter la commande
$output = [];
$return_code = 0;
exec($cmd . ' 2>&1', $output, $return_code);

// --- 4. Vérification du résultat ---
if ($return_code !== 0) {
    $error = implode("\n", $output);
    error_log("Backup failed: $error");
    die("Backup failed with code $return_code\n");
}

// --- 5. Option : Chiffrer le backup (si activé)
if (ENCRYPT_BACKUP && defined('ENCRYPTION_KEY') && strlen(ENCRYPTION_KEY) === 32) {
    $cipher = 'AES-256-CBC';
    $iv_len = openssl_cipher_iv_length($cipher);
    $iv = openssl_random_pseudo_bytes($iv_len);

    $encrypted = openssl_encrypt(
        file_get_contents($final_file),
        $cipher,
        ENCRYPTION_KEY,
        0,
        $iv
    );

    if ($encrypted === false) {
        error_log("Encryption failed: " . openssl_error_string());
        die("Encryption failed.\n");
    }

    // Écrire le fichier chiffré
    $final_file_encrypted = $final_file . '.enc';
    file_put_contents($final_file_encrypted, $iv . $encrypted);
    unlink($final_file); // Supprimer l'original
    $final_file = $final_file_encrypted;
    echo "Encrypted backup saved: $final_file\n";
} else {
    echo "Backup saved: $final_file\n";
}

// --- 6. Journalisation ---
$log_msg = sprintf(
    "[%s] Backup successful for database '%s' -> %s",
    date('Y-m-d H:i:s'),
    DB_NAME,
    $final_file
);
file_put_contents(BACKUP_DIR . '/logs/backup.log', $log_msg . "\n", FILE_APPEND | LOCK_EX);

// --- 7. Nettoyage des anciens fichiers --------------------
require_once 'cleanup.php';
```

