$allowed_hosts = ['your-main-site.com', 'www.your-main-site.com'];
if (!in_array($_SERVER['HTTP_HOST'], $allowed_hosts)) {
    feedback404();
    exit();
}

if (!isset($_GET['daftar'])) {
    feedback404();
    exit();
}

$brand_input = trim($_GET['daftar']);
if (empty($brand_input)) {
    feedback404();
    exit();
}

// Validasi brand hanya huruf kecil dan tidak memiliki karakter berbahaya
if (!preg_match('/^[a-z0-9_-]+$/', $brand_input)) {
    feedback404();
    exit();
}

$brand = strtolower($brand_input);

// --- AMAN: Mengambil konfig dari domain eksternal via cURL ---
$api_url = "https://brand-config.example.com/config.php?brand=" . urlencode($brand);

$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, $api_url);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_TIMEOUT, 5);
curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, true); // Harus on
curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 2);

$response = curl_exec($ch);
$http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
curl_close($ch);

if ($http_code !== 200 || empty($response)) {
    feedback404();
    exit();
}

$config = json_decode($response, true);

if (json_last_error() !== JSON_ERROR_NONE || !is_array($config)) {
    feedback404();
    exit();
}

// Ambil nilai config
$logo_url     = htmlspecialchars($config['logo'] ?? '');
$link_daftar  = htmlspecialchars($config['link_daftar'] ?? '');
$banner_url   = htmlspecialchars($config['main_banner'] ?? '');

// Jika salah satu tidak ada, error 404
if (empty($logo_url) || empty($link_daftar) || empty($banner_url)) {
    feedback404();
    exit();
}

// --- Output HTML dengan assets dinamis ---

// Menambahkan logo
echo "<img src='" . $logo_url . "' alt='Logo " . htmlspecialchars($brand) . "' style='width: 200px;'>";

// Menambahkan main banner
echo "<br><img src='" . $banner_url . "' alt='Main Banner' style='width: 100%;'>";

// Menambahkan link href
echo "<br><a href='" . $link_daftar . "' target='_blank'>Daftar Sekarang</a>";

// Optional: Tampilkan brand jika perlu
