### 🛠️ 1. 前端代码（HTML + JavaScript）

```html
<!-- index.html -->
<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8" />
    <title>博客文章</title>
    <style>
        .comment { border: 1px solid #ccc; margin: 10px 0; padding: 10px; }
        #commentForm { margin: 20px 0; }
        #commentList { margin-top: 20px; }
    </style>
</head>
<body>
    <h1>我的第一篇博客</h1>

    <!-- 评论表单 -->
    <form id="commentForm">
        <input type="text" id="commentText" placeholder="输入你的评论..." required />
        <button type="submit">提交评论</button>
    </form>

    <!-- 动态显示评论列表 -->
    <div id="commentList">
        <p>加载中...</p>
    </div>

    <!-- 加载Ajax脚本 -->
    <script>
        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', function () {
            const form = document.getElementById('commentForm');
            const commentInput = document.getElementById('commentText');
            const commentList = document.getElementById('commentList');

            // 1. 初始化：加载已有评论
            loadComments();

            // 2. 提交评论
            form.addEventListener('submit', async function (e) {
                e.preventDefault(); // 阻止默认提交行为

                const commentText = commentInput.value.trim();
                if (!commentText) return;

                try {
                    const response = await fetch('/api/comments', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-Token': getCookie('csrf_token') // 跨站请求伪造防护
                        },
                        body: JSON.stringify({ text: commentText })
                    });

                    if (response.ok) {
                        commentInput.value = ''; // 清空输入框
                        loadComments(); // 重新加载评论列表
                        alert('评论提交成功！');
                    } else {
                        alert('提交失败：' + await response.text());
                    }
                } catch (error) {
                    console.error('请求失败:', error);
                    alert('网络错误，请重试');
                }
            });

            // 3. 加载评论列表
            async function loadComments() {
                try {
                    const response = await fetch('/api/comments', {
                        method: 'GET',
                        headers: { 'Accept': 'application/json' }
                    });

                    if (!response.ok) throw new Error('网络错误');

                    const comments = await response.json();

                    // 清空并更新评论列表
                    commentList.innerHTML = '';

                    if (comments.length === 0) {
                        commentList.innerHTML = '<p>暂无评论。</p>';
                        return;
                    }

                    comments.forEach(comment => {
                        const commentDiv = document.createElement('div');
                        commentDiv.className = 'comment';
                        commentDiv.innerHTML = `
                            <strong>${comment.username}</strong>
                            <p>${comment.text}</p>
                            <small>${new Date(comment.timestamp).toLocaleString()}</small>
                        `;
                        commentList.appendChild(commentDiv);
                    });
                } catch (error) {
                    commentList.innerHTML = '<p>加载评论失败，请检查网络。</p>';
                    console.error('加载评论失败:', error);
                }
            }

            // 4. 从 Cookie 中获取 CSRF Token（假设后端使用 CSRF 保护）
            function getCookie(name) {
                let cookieValue = null;
                if (document.cookie && document.cookie !== '') {
                    const cookies = document.cookie.split(';');
                    for (let i = 0; i < cookies.length; i++) {
                        const cookie = cookies[i].trim();
                        if (cookie.substring(0, name.length + 1) === (name + '=')) {
                            cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
                            break;
                        }
                    }
                }
                return cookieValue;
            }

            // 自动刷新评论（可选：每30秒更新一次）
            setInterval(loadComments, 30000);
        });
    </script>
</body>
</html>
