```js
// server.js
const express = require('express');
const bcrypt = require('bcrypt');
const cors = require('cors');
const crypto = require('crypto');
const app = express();

// 中间件
app.use(cors());
app.use(express.json()); // 解析 JSON 请求体
app.use(express.static('public')); // 静态文件（如 HTML）

// 模拟数据库（实际应使用 MongoDB/MySQL）
let comments = [
    { id: 1, username: 'Alice', text: '好文章！', timestamp: Date.now() },
    { id: 2, username: 'Bob', text: '学习了', timestamp: Date.now() - 10000 }
];

// CSRF Token 生成与存储（简化版，生产环境中需使用 session/数据库）
let csrfTokens = new Map(); // key: token, value: { expiresAt }

function generateCSRFToken() {
    const token = crypto.randomBytes(32).toString('hex');
    const expiresAt = Date.now() + 3600000; // 1小时
    csrfTokens.set(token, { expiresAt });
    return token;
}

function isValidCSRFToken(token) {
    const stored = csrfTokens.get(token);
    if (!stored) return false;
    if (Date.now() > stored.expiresAt) {
        csrfTokens.delete(token);
        return false;
    }
    return true;
}

// 获取 CSRF Token
app.get('/api/csrf-token', (req, res) => {
    const token = generateCSRFToken();
    res.json({ csrfToken: token });
});

// 获取评论列表（GET /api/comments）
app.get('/api/comments', (req, res) => {
    // 为前端提供安全响应
    const safeComments = comments.map(c => ({
        id: c.id,
        username: c.username,
        text: c.text,
        timestamp: c.timestamp
    }));
    res.json(safeComments);
});

// 提交评论（POST /api/comments）
app.post('/api/comments', (req, res) => {
    const { text } = req.body;

    // 安全检查
    if (!text || typeof text !== 'string' || text.length < 1 || text.length > 500) {
        return res.status(400).json({ error: '评论长度无效' });
    }

    // 防止 XSS：对输入进行转义或使用模板引擎处理
    const cleanText = sanitizeText(text);

    // 从 headers 获取 CSRF Token
    const csrfToken = req.headers['x-csrf-token'];
    if (!csrfToken || !isValidCSRFToken(csrfToken)) {
        return res.status(403).json({ error: 'CSRF Token 验证失败' });
    }

    // 添加评论
    const newComment = {
        id: comments.length + 1,
        username: 'Anonymous',
        text: cleanText,
        timestamp: Date.now()
    };
    comments.push(newComment);

    res.status(201).json({ message: '评论已提交' });
});

// 简单的 XSS 防护：转义 HTML 字符
function sanitizeText(input) {
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#x27;'
    };
    return input.replace(/[&<>"']/g, match => map[match]);
}

// 启动服务器
app.listen(3000, () => {
    console.log('服务器运行在 http://localhost:3000');
});
```

