## 3. `includes/api-matomo.php` – Wrapper API Matomo
```php
<?php
// includes/api-matomo.php

require_once __DIR__ . '/../config/config.php';

class MatomoAPI {
    private $url;
    private $token;

    public function __construct() {
        $this->url = MATOMO_API_URL;
        $this->token = MATOMO_TOKEN;
    }

    private function get($action, $params = []) {
        $params = array_merge([
            'format' => 'json',
            'token_auth' => $this->token,
        ], $params);

        $url = $this->url . '?module=API&method=' . $action . '&' . http_build_query($params);

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, true);
        curl_setopt($ch, CURLOPT_TIMEOUT, 30);

        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($httpCode !== 200) {
            error_log("API Matomo errore: $httpCode - $response");
            return false;
        }

        $data = json_decode($response, true);
        if (json_last_error() !== JSON_ERROR_NONE) {
            error_log("Errore JSON: " . json_last_error_msg());
            return false;
        }

        return $data;
    }

    public function getSites() {
        return $this->get('SitesManager.getSitesWithAtLeastViewAccess');
    }

    public function getReport($idSite, $dateFrom, $dateTo, $period = 'range') {
        $params = [
            'idSite' => $idSite,
            'date' => $period === 'range' ? $dateFrom . ',' . $dateTo : $dateFrom,
            'period' => $period,
            'segment' => '',
            'format' => 'json',
            'expanded' => '1',
            'apiModule' => 'ReportsExport',
            'apiAction' => 'get',
            'method' => 'API.get',
            'module' => 'CoreHome',
            'format' => 'json',
            'date' => $dateFrom . ',' . $dateTo,
            'period' => 'range',
        ];

        return $this->get('API.get', $params);
    }
}
