## 4. `includes/utils.php` – Funzioni di utilità
```php
<?php
// includes/utils.php

function formatDateString($date) {
    return date('Y-m-d', strtotime($date));
}

function exportToCsv($data, $filename) {
    $filename = preg_replace('/[^A-Za-z0-9\-\_]/', '_', $filename) . '.csv';
    header('Content-Type: text/csv');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Pragma: no-cache');
    header('Expires: 0');

    $fp = fopen('php://output', 'w');
    fputcsv($fp, array_keys($data[0])); // header
    foreach ($data as $row) {
        fputcsv($fp, $row);
    }
    fclose($fp);
    exit;
}

function exportToExcel($data, $filename) {
    $filename = preg_replace('/[^A-Za-z0-9\-\_]/', '_', $filename) . '.xlsx';

    require_once __DIR__ . '/../vendor/autoload.php'; // PHPExcel / PhpSpreadsheet

    $spreadsheet = new PhpOffice\PhpSpreadsheet\Spreadsheet();
    $sheet = $spreadsheet->getActiveSheet();

    $headers = array_keys($data[0]);
    $sheet->fromArray($headers, null, 'A1');
    $sheet->fromArray($data, null, 'A2');

    $writer = new PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
    header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Cache-Control: max-age=0');
    $writer->save('php://output');
    exit;
}

function exportToPdf($data, $filename) {
    $filename = preg_replace('/[^A-Za-z0-9\-\_]/', '_', $filename) . '.pdf';

    require_once __DIR__ . '/../vendor/autoload.php'; // DomPDF

    $html = '<h2>Report Matomo</h2><table border="1" cellspacing="0" cellpadding="5">';
    $html .= '<tr>' . implode('', array_map(fn($h) => "<th>$h</th>", array_keys($data[0]))) . '</tr>';

    foreach ($data as $row) {
        $html .= '<tr>' . implode('', array_map(fn($cell) => "<td>" . htmlspecialchars($cell) . "</td>", $row)) . '</tr>';
    }
    $html .= '</table>';

    $pdf = new Dompdf\Dompdf();
    $pdf->loadHtml($html);
    $pdf->setPaper('A4', 'portrait');
    $pdf->render();

    header('Content-Type: application/pdf');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Cache-Control: max-age=0');
    echo $pdf->stream();
    exit;
}
